printf "  %-26s" "neverallow (presets)..."
if na_out="$(python3 "${REPO_ROOT}/tools/check_neverallow.py" 2>&1)"; then
    ok
else
    bad; printf '%s\n' "$na_out" | sed -n 1,12p | sed 's/^/      /'
fi
printf "  %-26s" "neverallow (canary)..."
if na_out="$(python3 "${REPO_ROOT}/tools/check_neverallow.py" --canary 2>&1)"; then
