printf "  %-26s" "unsafe budget..."
if ub_out="$(python3 "${REPO_ROOT}/tools/unsafe_budget.py" --self-test 2>&1)" \
   && ub_out="$(python3 "${REPO_ROOT}/tools/unsafe_budget.py" 2>&1)"; then
    ok
else
    bad; printf '%s\n' "$ub_out" | sed -n 1,10p | sed 's/^/      /'
fi

# Every row's key has a line in tools/gate_rows.tsv (its tier and the paths it
# depends on, for `make check1`), and no line names a row that is gone. A
# row's deps cover what it demonstrably reads (gate_rows.py --check-deps: its
# host suite and that suite's crates, the scripts and fixtures it names, the
# programs of the image it boots, the optional crates and test-hook files of
# its features, the files that print its markers): a row whose deps missed
# its source was never picked for a change to it (the bench row and
# domains/robot/bench). The row runs the tool's canaries first.
printf "  %-26s" "gate rows manifest..."
if grm_out="$(python3 "${REPO_ROOT}/tools/gate_rows.py" --self-test 2>&1)" \
   && grm_out="$(python3 "${REPO_ROOT}/tools/gate_rows.py" --check 2>&1)"; then
    ok
else
    bad; printf '%s\n' "$grm_out" | sed -n 1,10p | sed 's/^/      /'
fi

# aarch64 boots the Image, never the ELF (wave 15): QEMU `virt` hands the
# device tree, and with it the command line (`init=`, `canary=`), only to an
# arm64 `Image` (`kernel.img`, in x0). Booted as an ELF the kernel gets x0 = 0
# and no DTB (kernel/src/entry/aarch64/asm/boot.S says why), so a row that
# boots the ELF silently loses its boot arguments. This flags a
# `-kernel` within six lines after an aarch64 QEMU command that names the ELF
# (`$A64_KERNEL`, `$kelf`, `$elf`, `$(AARCH64_ELF)`, `.../release/kernel`).
# The row also runs the check on a planted line, which must be flagged.
a64_elf_boot_hits() { # <file>...: one line per aarch64 QEMU boot handed the ELF
    local q="qemu-system-""aarch64"
    awk -v q="$q" '
        index($0, q) { n = 6 }
        /qemu-system-riscv64|"\$QEMU"/ { n = 0 }
        n > 0 {
            if ($0 ~ /-kernel[[:space:]]+"?\$\{?(A64_KERNEL|kelf|elf)\}?"?([[:space:]]|$)/ \
                || $0 ~ /-kernel[[:space:]]+\$\(AARCH64_ELF\)/ \
                || $0 ~ /-kernel[[:space:]]+"?[^[:space:]]*\/release\/kernel"?([[:space:]]|$)/)
                print FILENAME ":" FNR ": " $0
            n--
        }' "$@"
}
printf "  %-26s" "aarch64 boots the Image..."
a64_lint_tmp="$(mktemp)"
builtin printf '%s -M virt -nographic \\\n    -kernel "$%s" >log 2>&1 &\n' "qemu-system-""aarch64" A64_KERNEL >"$a64_lint_tmp"
a64_lint_planted="$(a64_elf_boot_hits "$a64_lint_tmp")"; rm -f "$a64_lint_tmp"
a64_lint_out="$(cd "$REPO_ROOT" && a64_elf_boot_hits tools/ci_check.sh Makefile mk/*.mk tools/vsbench_aarch64.sh)"
if [ -z "$a64_lint_planted" ]; then
    bad; echo "      the check missed a planted ELF boot: it checks nothing"
elif [ -n "$a64_lint_out" ]; then
    bad; echo "      aarch64 QEMU boots handed the ELF (no DTB, no command line); boot kernel.img:"
    printf '%s\n' "$a64_lint_out" | sed -n 1,10p | sed 's/^/        /'
else
    ok
fi

# AzOS-micro (strategic plan, phase 8): the riscv32 M-mode image builds from
# the micro defconfig with the topology signed by the test key, and a warning
# fails the row as it fails the kernel builds. It boots nowhere here (the QEMU
# rv32+PMP row is the testing week's); micro-tests, below, run the kernel's
# decisions on the host.
if ci_row_begin "micro: make micro"; then
printf "  %-26s" "micro: make micro..."
if micro_out="$(make micro 2>&1)"; then
    if printf '%s\n' "$micro_out" | grep -E "^warning:" | qgrep -qvE "^warning: [A-Za-z0-9_-]+@[0-9]"; then
        bad; printf '%s\n' "$micro_out" | grep -E "^warning:" -A4 | sed -n 1,20p | sed 's/^/      /'
    else
        ok
    fi
else
    bad; printf '%s\n' "$micro_out" | grep -A6 '^error' | sed -n 1,40p | sed 's/^/      /'
fi
fi; ci_row_end

echo ""
# The seccomp image table. crates/core/sched/src/seccomp.rs `include!`s
# build/image_hashes.rs, the SHA-256 of every ELF the disk images carry, so no
# kernel build below and no seccomp-tests run compiles without it. Made through
# make, which rebuilds any stale userspace ELF first, so the table and the images
# made later come from the same bytes. A failure aborts the gate: every kernel
# build would fail with it, for one reason.
echo "Generating the seccomp image table ($AZOS_OUT/build/image_hashes.rs)..."
if ! make $AZOS_OUT/build/image_hashes.rs >/dev/null 2>&1; then
    echo "  FATAL: make $AZOS_OUT/build/image_hashes.rs failed: a userspace ELF did not build,"
    echo "         or python3 is missing. Run it by hand to see which."
    exit 1
fi

# Same table, aarch64 ELFs, own file (crates/core/sched/src/seccomp.rs cfg-selects
# between the two — see that include! site). A failure here only aborts the
# aarch64 userspace row below, not the whole gate: unlike the riscv64 table,
# no OTHER row's kernel build `include!`s this file.
echo "Generating the seccomp image table ($AZOS_OUT/build/image_hashes_aarch64.rs)..."
if ! make $AZOS_OUT/build/image_hashes_aarch64.rs >/dev/null 2>&1; then
    echo "  WARNING: make $AZOS_OUT/build/image_hashes_aarch64.rs failed — the aarch64"
    echo "           userspace row below will fail too."
    A64_USERSPACE_TABLE_FAILED=1
fi

ci_phase "[1/4] builds + aarch64/early QEMU rows"
echo "[1/4] Building all feature combinations..."

# The x86_64 skeleton type-checks the kernel through the arch contract only:
# there the facade exports arch-api's traits and `ARCH`, not the ISA modules.
# Shared code that names a module (`azos_arch::cpu::hart_id()`) still builds
# for riscv64 and aarch64, whose facades re-export those modules, and the arch
# cfg lint does not see it (it is not a cfg). Wave 15 integration: the per-hart
# loopback guard did exactly that, and only `make ARCH=x86_64 check` failed.
if ci_row_begin "x86_64: make check"; then
printf "  %-26s" "x86_64: make check..."
# Warnings fail it as they fail every riscv64/aarch64 `build` row below (same
# filter: a build script's `warning: <pkg>@<version>:` line is information).
# It only checked for errors until wave 15 (GR4), and four x86_64-only
# warnings had piled up unseen.
if x86_out="$(make ARCH=x86_64 check 2>&1)"; then
    if printf '%s\n' "$x86_out" | grep -E "^warning:" \
         | qgrep -qvE "^warning: [A-Za-z0-9_-]+@[0-9]"; then
        bad; printf '%s\n' "$x86_out" | grep -E "^warning:" -A4 \
          | grep -vE "^warning: [A-Za-z0-9_-]+@[0-9]" | sed -n 1,20p | sed 's/^/      /'
    else
        ok
    fi
else
    bad; printf '%s\n' "$x86_out" | grep -A6 '^error' | sed -n 1,40p | sed 's/^/      /'
fi
fi; ci_row_end

# No forced recompile here any more. This line used to `touch` every .rs file
# under crates/ domains/ kernel/ because "rustc only emits warnings when it
# compiles": four unused-constant warnings once sat unnoticed on a warm cache.
# The cargo this tree pins (nightly-2026-02-21) REPLAYS a fresh unit's stored
# warnings on every build. Measured 2026-10-03 on this tree: an unused const
# planted in crates/core/abi and, separately, in kernel/src/main.rs printed
# its `warning:` on the compiling build, again on a 0.08 s fresh rebuild, and
# again after building another feature set and coming back; `build` below
# fails on those lines either way. The touch cost every warm gate a rebuild of
# every crate for each of the ~50 feature sets (264 s of cargo in [1/4], gate
# of 2026-10-03). If a cargo upgrade stops replaying, that canary is how to see
# it: plant the const, build twice, and the second build must still warn.

build       "default (QEMU)"      --release
build       "qemu"                --release --features qemu
build       "no-ml"               --release --features no-ml
build       "rvv"                 --release --features rvv
build       "net-smoke"           --release --features qemu,net-smoke
build       "dhcp-smoke"          --release --features qemu,dhcp-smoke
# Secure-boot policy is fixed at compile time, so if this feature
# is not built in CI it can break with nobody noticing — exactly the way
# esp32c3 rotted.
build       "secure-boot-enforced" --release --features qemu,secure-boot-enforced
build       "link-provisioning-enforced" --release --features qemu,link-provisioning-enforced
build       "reflex-smoke"        --release --features qemu,reflex-smoke
build       "envelope-smoke"      --release --features qemu,envelope-smoke
build       "geofence-smoke"      --release --features qemu,geofence-smoke
build       "console-splice-smoke" --release --features qemu,console-splice-smoke
# The refusal canary is its own feature (never part of `qemu`), so it has to be
# built here or it rots unseen: see the "topology: infeasible deadlines" row.
build       "deadline-refusal-canary" --release --features qemu,deadline-refusal-canary
# Same reason as the row above: a canary feature that is never BUILT here rots
# unseen, and this one is the only thing in the gate that observes the frame
# budget refusing anything.
build       "mem-quota-canary"  --release --features qemu,mem-quota-canary
build       "mem-locked-smoke"  --release --features qemu,mem-locked-smoke
build       "mem-locked-canary" --release --features qemu,mem-locked-canary
build       "user-stack-request-canary" --release --features qemu,user-stack-request-canary
build       "mem-locked-refusal-canary" --release --features qemu,mem-locked-refusal-canary
build       "mem-admission-canary" --release --features qemu,mem-admission-canary
build       "disk-part-row"     --release --features qemu,disk-part-row
build       "deadline-hart-canary" --release --features qemu,deadline-hart-canary
build       "dma-contig-canary"   --release --features qemu,dma-contig-canary
build       "brain-lies-smoke"    --release --features qemu,brain-lies-smoke
build       "actuation-smoke"     --release --features qemu,actuation-smoke
build       "reflex+actuation"    --release --features qemu,reflex-smoke,actuation-smoke
# Wave 8 TLB shootdown probe and its canary (see the "tlb: stale access" rows).
build       "tlb-smoke"           --release --features qemu,tlb-smoke
build       "tlb-local-only"      --release --features qemu,tlb-smoke,tlb-local-only
build       "tlb-bound-canary"    --release --features qemu,tlb-smoke,tlb-bound-canary
# The page-table free check's canary (see the "mm: canary" row).
build       "exit-satp-canary"    --release --features qemu,exit-satp-canary
build       "proxy-pi-smoke"      --release --features qemu,proxy-pi-smoke
# The donation canary for the row that boots proxy-pi-smoke: built here so it
# cannot rot; booted by hand (it must fail on `[PROXYPI] FAIL TIMEOUT`).
build       "proxy-donation-canary" --release --features qemu,proxy-donation-canary
build       "sup-smoke"           --release --features qemu,sup-smoke
# The supervisor canary: built here so it cannot rot; booted by
# hand (the restart row must fail on `[SUP] FAIL not restarted after kill 1`).
build       "sup-canary"          --release --features qemu,sup-canary

# Wave 9: the ring-3 donation floor's canary, booted by hand (it must fail on
# `[PROXYPI] FAIL floor: gpio_drv was lent 8, below the ring-3 floor 12`).
build       "donation-floor-canary" --release --features qemu,donation-floor-canary
# ipc-census is load-bearing diagnostics: the userspace-IPC scenario's
# comment prescribes it as the wedge-reproduction recipe (K-C25), so it must
# stay inside the cold-cache warnings gate or it rots silently.
build       "ipc-census"          --release --features qemu,ipc-census
# Wave 14: the motor-command watchdog record row (`rt_watchdog_record_row`)
# and its canary.
build       "rtwd-window-smoke"   --release --features qemu,rtwd-window-smoke
build       "rtwd-record-canary"  --release --features qemu,rtwd-window-smoke,rtwd-record-canary
# Wave 11: the supervisor over what the topology starts (`supall_row`) and its
# canary.
build       "supall-smoke"        --release --features qemu,supall-smoke
build       "supall-canary"       --release --features qemu,supall-smoke,supall-canary
# Wave 10: the "behavior ARP sleeps" rows boot `arp-timing` on both ISAs.
build       "arp-timing"          --release --features qemu,arp-timing
# Wave 11: the display features `make config` offers (DRV_DISPLAY_RAMFB,
# DRV_DISPLAY_HDMI in config/subsys/Kconfig.display). No row boots either; building
# them here is what keeps the options from rotting unseen.
build       "ramfb"               --release --features qemu,ramfb,fb-console,fb-panic-screen
build       "hdmi"                --release --features vf2,hdmi
# Wave 11 (SENSORTS): the acquisition-stamp smoke and its frozen-stamp canary
# (the ktest `sensors_imu_stamped_at_acquisition` boots both, on both ISAs:
# rows `ktest (rv|arm)` and `ktest IMU frozen-stamp canary (rv|arm)`).
build       "sensor-ts-smoke"     --release --features qemu,sensor-ts-smoke
build       "sensor-ts-freeze"    --release --features qemu,sensor-ts-freeze
# ── Per-board ISA extensions, and the guard that keeps them on their board ──
#
# The K1 (SpacemiT X60, RVA22) has Zba/Zbb/Zbs, so its build lets the compiler
# use them ANYWHERE — not only in hand-written `asm!`. The VF2 (JH7110, SiFive
# U74) is rv64gc and has none of them: one such instruction is an illegal
# instruction on its first execution. Both binaries are called `kernel`.
#
# So the flags are checked from both sides, because either check alone is
# worthless: the negative one (VF2 and QEMU carry no B instruction) is what
# stops a mis-set flag bricking the primary board, and the positive one (the K1
# carries thousands) is its control — without it a detector that matched nothing
# at all would report the VF2 clean for ever.
isa_guard() { # isa_guard <label> <expect: none|some>
    local label="$1" expect="$2" n
    ci_tier_skips "$label" && return 0
    printf "  %-26s" "${label}..."
    local tools; tools="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin"
    local kernel="$AZOS_OUT/target/${TARGET:-riscv64imac-unknown-none-elf}/release/kernel"
    if [ ! -f "$kernel" ]; then bad; echo "      no kernel at $kernel"; return; fi
    # The kernel at that path is the board's only if the board row above built
    # it in this run: after a failed board build it is whatever an earlier
    # build left (gate 4d3f71e0 counted 212 bitmanip instructions in such a
    # leftover and blamed the vf2 build that never linked).
    if [ -z "${BOARD_BUILT:-}" ]; then bad
        echo "      the board build row above made no kernel in this run: nothing current to check"
        return; fi
    n=$("$tools/llvm-objdump" -d --mattr=+zba,+zbb,+zbs "$kernel" 2>/dev/null \
        | grep -cE '[[:space:]](sh[123]add|add\.uw|andn|orn|xnor|clz|ctz|cpop|minu|maxu|sext\.b|zext\.h|rev8|orc\.b|bset|bclr|binv|bext)([[:space:]]|$)')
    case "$expect" in
      none) if [ "$n" -eq 0 ]; then ok; else bad
              echo "      $n bitmanip instruction(s) in a binary for a board without them —"
              echo "      this kernel dies with an illegal instruction on its first one."; fi ;;
      some) if [ "$n" -gt 0 ]; then ok; else bad
              echo "      0 bitmanip instructions in the K1 build: either the flags did not"
              echo "      reach the compiler, or the detector above matches nothing."; fi ;;
    esac
}

# ── aarch64: the port stays alive only because these rows exist ─────────────
#
# The parked-architecture notes said it plainly before this crate moved into the
# workspace: "the CI gate entry is what decides whether the work is still alive
# in six months; without a gate, the esp32c3 history repeats" — an architecture
# that rotted parked for months. So: it builds for its real target, and its pure
# halves are tested on the host, on every run.
#
# This crate row builds `aarch64-unknown-none` (hard-float), the KERNEL
# `aarch64-unknown-none-softfloat` (see "The KERNEL on aarch64" below): the
# crate must build warning-free for both. No code of its own depends on NEON
# being in the target (`dot_f32` is the scalar loop).
if ci_row_begin "aarch64 crate (ARMv8.5)"; then
printf "  %-26s" "aarch64 crate (ARMv8.5)..."
if aarch_out="$(RUSTFLAGS="" KCONFIG_CONFIG="$AARCH64_CONFIG" "$CARGO" build --release --target aarch64-unknown-none \
        -p azos_arch_aarch64 --config "build.rustflags=[]" 2>&1)" \
   && ! printf '%s\n' "$aarch_out" | qgrep -qE "^(error|warning)"; then
    ok
else
    bad; printf '%s\n' "$aarch_out" | grep -E "^(error|warning)" | head -5
fi
fi; ci_row_end

# ── The KERNEL on aarch64 ────────────────────────────────────────────────────
# `azos_kernel` built for `aarch64-unknown-none` with its own linker script
# and booted to `kernel_main`, which now (Item 2 Stage 5, memory-parity task)
# does a real FDT handoff, PMM, kernel page tables (W^X) and a heap, on top of
# the earlier banner/hart-id/FP self-check/boot-stack milestone.
#
# Two entry paths, because they differ in exactly the way that broke once:
# entered at EL1 (QEMU without `virtualization=on`) nothing drops from EL2, so
# EL1's FP/SIMD permission (CPACR_EL1.FPEN) must be set by the kernel's own
# boot.S. It was not, until 2026-09-21; the kernel only survived because its
# minimal kernel_main emitted no FP. The self-check line executes FP on
# purpose, so a boot that loses that permission traps (EC=0x07) and fails here.
#
# Stale-binary rule (see "El gate arrancó un kernel obsoleto"): both the ELF
# and the `.img` are deleted before the build, so a failed build cannot be
# booted in its place.
# Soft-float: the aarch64 kernel is FP-free (user FP state is saved lazily,
# kernel/src/entry/aarch64/fp_lazy.rs); userspace stays hard-float.
A64_KERNEL_OUT="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel"
A64_IMG_OUT="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel.img"
# The same two files; `par_ready` points these two at a parallel job's copies.
A64_KERNEL="$A64_KERNEL_OUT"
A64_IMG="$A64_IMG_OUT"
# Build noise every aarch64 KERNEL row tolerates, and nothing more: the prod
# pubkey notice, and cargo's future-incompat notice for `core` ALONE — the
# build-std `core` carries stdarch's `#[target_feature(enable = "neon")]`
# intrinsics, which rustc flags on a soft-float target (lint
# `aarch64_softfloat_neon`, rust-lang/rust#134375; `-A` does not silence the
# report). Anchored at end of line: a notice that names any second package
# is not matched and still fails the row.
A64_KNOWN_NOISE='prod pubkey|packages contain code that will be rejected by a future version of Rust: core v0\.0\.0 \([^,]*\)$'
# The aarch64 kernel builds, defined before the first row that builds one: a
# deferred build (ci_kb_defer) is made by whichever later row flushes it.
a64_kbuild_out() { # a64_kbuild_out <features>: builds into A64_KERNEL_OUT / A64_IMG_OUT
    local feats="$1"
    rm -f "$A64_KERNEL_OUT" "$A64_IMG_OUT" "${A64_IMG_OUT}.features"
    local out
    # KCONFIG_CONFIG pinned to config/defconfigs/${GATE_DEFC_A64}.config (U12-3): without
    # this override every aarch64 build inherited the exported primary-column
    # KCONFIG_CONFIG above (an ARCH_RISCV64 config before this change existed
    # at all), so `azos_limits` built ARCH_RISCV64's constants for an
    # ARCH_AARCH64 kernel.
    if ! out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$AARCH64_CONFIG" "$CARGO" build --release \
            --target aarch64-unknown-none-softfloat -p azos_kernel --features "$feats" \
            --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)"; then
        printf '%s\n' "$out" | grep -E "^(error|warning)" | grep -vE "$A64_KNOWN_NOISE" | head -5
        return 1
    fi
    if printf '%s\n' "$out" | grep -E "^(error|warning)" | qgrep -vqE "$A64_KNOWN_NOISE"; then
        printf '%s\n' "$out" | grep -E "^(error|warning)" | grep -vE "$A64_KNOWN_NOISE" | head -5
        return 1
    fi
    [ -f "$A64_KERNEL_OUT" ] || return 1
    local a64_objcopy
    a64_objcopy="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objcopy"
    [ -x "$a64_objcopy" ] || return 1
    "$a64_objcopy" -O binary "$A64_KERNEL_OUT" "$A64_IMG_OUT" 2>/dev/null
    [ -f "$A64_IMG_OUT" ] || return 1
    # What the image was built with, for `a64_kernel_check` (as `kbuild`
    # writes `${KERNEL}.features`). Written before the FP-free proof's cached
    # early return below; removed again if that proof fails.
    builtin printf '%s\n' "$feats" >"${A64_IMG_OUT}.features"
    # Same FP-free proof as the "aarch64 kernel FP-free" row, on this feature
    # set's own ELF (more crates are linked in than in the no-feature build).
    # The proof is a function of the ELF's bytes and of the checker: an ELF
    # this run already proved (same SHA-256, same checker) is not re-read
    # (3.3 s each; wave 15 measured ~30 repeats of the plain qemu kernel).
    local fpfree fpkey=""
    if [ -n "${CI_LOG_ABS:-}" ]; then
        fpkey="$CI_LOG_ABS/fpfree/$(cat "$A64_KERNEL_OUT" tools/aarch64_fp_free_check.sh | shasum -a 256 | cut -c1-64)"
        [ -f "$fpkey" ] && return 0
    fi
    if ! fpfree="$(bash tools/aarch64_fp_free_check.sh "$A64_KERNEL_OUT" 2>&1)"; then
        printf '%s\n' "$fpfree" | head -8
        rm -f "${A64_IMG_OUT}.features"
        return 1
    fi
    if [ -n "$fpkey" ]; then mkdir -p "${fpkey%/*}"; : >"$fpkey"; fi
}
a64_kbuild() { # a64_kbuild <comma-separated-features>
    if [ -z "${KB_ROBOT_DONE:-}" ] && [ "$AARCH64_CONFIG" = "$GATE_AARCH64_CONFIG" ] && ci_robot_feats "$1"; then
        KB_ROBOT_DONE=1 AARCH64_CONFIG="$ROBOT_AARCH64_CONFIG" a64_kbuild "$@"; return
    fi
    if [ -z "${KB_CFG_DONE:-}" ] && [ $# -eq 1 ]; then
        local _kc; _kc="$(kb_cfg a64 "$1")" || return 1
        if [ -n "$_kc" ]; then KB_CFG_DONE=1 AARCH64_CONFIG="$_kc" a64_kbuild "$1"; return; fi
    fi
    par_shared "a64_kbuild $1" || return 1
    if [ $# -eq 1 ] && ci_kb_defer a64 "$1"; then return 0; fi
    # Built now: it supersedes a pending deferred build, which a later `par`
    # would otherwise flush OVER it (as `kbuild` does for riscv64): the
    # aarch64 secure-boot rows, built with PROD_PUBKEY_PATH and so never
    # deferred, would boot a pending `qemu` kernel instead.
    [ -z "$PAR_JOB" ] && [ -z "${CI_KFLUSHING:-}" ] && unset CI_KPEND_A64
    a64_kbuild_out "$@"
}

rm -f "$A64_KERNEL" "$A64_IMG" "${A64_IMG}.features"
if ci_row_begin "aarch64 kernel (build)"; then
printf "  %-26s" "aarch64 kernel (build)..."
# `env -u RUSTFLAGS`, NOT `RUSTFLAGS=""` like the arch-crate row above: cargo
# gives an environment RUSTFLAGS — even an empty one — precedence over
# `build.rustflags`, so `RUSTFLAGS=""` silently drops the linker script and the
# link fails on `undefined symbol: _stack_end`. (Written that way first, 21 Sep.)
if a64k_out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$AARCH64_CONFIG" "$CARGO" build --release --target aarch64-unknown-none-softfloat \
        -p azos_kernel \
        --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)" \
   && ! printf '%s\n' "$a64k_out" | grep -E "^(error|warning)" | qgrep -vqE "$A64_KNOWN_NOISE" \
   && [ -f "$A64_KERNEL" ]; then
    # ── ELF → arm64 Image (task 1) ──────────────────────────────────────────
    # `boot.S`'s `_start` opens with the 64-byte arm64 Linux boot-protocol
    # header (Documentation/arch/arm64/booting.rst); a flat `objcopy -O
    # binary` of the ELF reproduces that header at file offset 0, which is
    # what QEMU's `-kernel` loader and U-Boot `booti` both recognise as an
    # Image (as opposed to a bare ELF `-kernel` load, where x0 is always 0 —
    # established empirically this task, not assumed).
    A64_OBJCOPY="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objcopy"
    if [ -x "$A64_OBJCOPY" ] \
       && "$A64_OBJCOPY" -O binary "$A64_KERNEL" "$A64_IMG" 2>/dev/null \
       && [ -f "$A64_IMG" ]; then
        # No --features: an empty `.features`, as `kbuild ""` writes.
        builtin printf '\n' >"${A64_IMG}.features"
        # Header sanity, independent of a QEMU boot: magic, code0, image_size
        # and text_offset against the ELF (tools/image_header.py; riscv64's
        # twin is `image_header_row`).
        if a64_hdr="$(python3 tools/image_header.py arm "$A64_KERNEL" "$A64_IMG" 2>&1)"; then
            ok
        else
            bad; printf '%s\n' "$a64_hdr" | sed 's|^|      |'
        fi
    else
        bad; echo "      llvm-objcopy not found or ELF -> .img failed: $A64_OBJCOPY"
    fi
else
    bad; printf '%s\n' "$a64k_out" | grep -E "^(error|warning)" | grep -vE "$A64_KNOWN_NOISE" | head -5
fi
else
    # Skipped (CI_TIER=rows): the rows below still boot this kernel, the
    # default feature set. A deferred build of the same set, made only if one
    # of them is kept (see ci_kb_defer).
    a64_kbuild "" >/dev/null 2>&1 || true
fi; ci_row_end

# ── The aarch64 kernel names no FP/SIMD register outside the lazy-FP code ────
# The trap path no longer saves the interrupted task's V0-V31/FPSR/FPCR (user
# FP state is saved lazily, on context switch — kernel/src/entry/aarch64/
# fp_lazy.rs), so ANY kernel code that touches a V register corrupts whatever
# user task it interrupted. The soft-float target keeps rustc from emitting
# such code; this row proves the linked ELF, inline asm and `.S` included:
# every instruction naming an FP/SIMD register or FPCR/FPSR must sit in one of
# the symbols the script allows by name. Canaries: the gate-186 hard-float
# kernel fails it (144 functions); so does dropping one allowed name.
if ci_row_begin "aarch64 kernel FP-free"; then
printf "  %-26s" "aarch64 kernel FP-free..."
if [ ! -f "$A64_KERNEL" ]; then
    bad; echo "      not built: $A64_KERNEL"
elif fpfree_out="$(bash tools/aarch64_fp_free_check.sh "$A64_KERNEL" 2>&1)"; then
    ok
else
    bad; printf '%s\n' "$fpfree_out" | head -12 | sed 's|^|      |'
fi
fi; ci_row_end

# ── Trap-path code size (wave 14, LOGLEVEL) ─────────────────────────────────
# The first Rust frames of every trap, the syscall path included, pinned to
# their size within TRAP_SIZE_SLACK bytes. What LLVM inlines into them sets
# the registers every syscall saves: an unrelated edit in the kernel crate
# once inlined `handle_exception` into `riscv64_trap_handler` (130 -> 2038 B)
# and every syscall paid 22 instructions (vsbench `syscall-floor` 195 -> 217
# ns/op, -icount). `#[inline(never)]` on `handle_exception` fixes that one;
# this row catches the next. A size that moved on purpose: re-pin it here.
# Read from the linked ELF (llvm-nm), no QEMU. Canaries (wave 14, by hand,
# reverted): `#[inline(always)]` on `handle_exception` turns the riscv64 row
# red at 1912 B. Removing the `#[inline(never)]` alone did NOT on that tree:
# LLVM kept the body out of line (130 B), and that is the point of the
# attribute and of this row, as the decision flips with unrelated edits.
# Symbols are matched by name suffix (the Rust ones are mangled).
TRAP_SIZE_SLACK="${TRAP_SIZE_SLACK:-64}"
trap_size_row() { # trap_size_row <label> <elf> <symbol-suffix>=<bytes>...
    local label="$1" elf="$2"; shift 2
    printf "  %-26s" "${label}..."
    if [ ! -f "$elf" ]; then bad; echo "      not built: $elf"; return; fi
    local nmtool syms pin sym want got fail=0 report=""
    nmtool="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-nm"
    if ! syms="$("$nmtool" -S --defined-only "$elf" 2>/dev/null | awk '$3 ~ /^[tT]$/ {print $4, $2}')" \
       || [ -z "$syms" ]; then
        bad; echo "      no symbols read from $elf ($nmtool)"; return
    fi
    for pin in "$@"; do
        sym="${pin%=*}"; want="${pin#*=}"
        got="$(awk -v s="$sym" \
            '{ n = length($1); m = length(s); if (n >= m && substr($1, n - m + 1) == s) { print $2; exit } }' <<<"$syms")"
        if [ -z "$got" ]; then
            fail=1; report="$report      $sym: no such text symbol\n"; continue
        fi
        got=$((16#$got))
        if [ "$got" -gt $((want + TRAP_SIZE_SLACK)) ] || [ "$got" -lt $((want - TRAP_SIZE_SLACK)) ]; then
            fail=1; report="$report      $sym: $got B, pinned at $want B +/- $TRAP_SIZE_SLACK\n"
        else
            report="$report      $sym: $got B (pinned $want)\n"
        fi
    done
    if [ "$fail" = 0 ]; then ok; else bad; fi
    printf '%b' "$report"
}
# Re-pinned in the wave-15 integration: block A (c44e9b85) moved both trap
# paths and the row was already red on main (aarch64 1356 B; riscv64
# trap_handler 54 B, handle_ecall 568 B, then 582 with NRCPUS). vsbench
# -icount syscall-floor did not move: 180 riscv64, 152 aarch64.
# Re-pinned 1356 -> 1256 (FX4): 4319c92f (N4, QSBR) moved the interrupt arm
# out of line (`irq_arm`, #[inline(never)], so the syscall path's frame does
# not carry the IRQ boundary guard) and added the exception boundary guard
# inline. Measured on 056b16a1: 1256 B as is, 1460 B with `irq_arm` forced
# inline; svc_dispatch unchanged at 488 and both guards still in the path.
# Re-pinned in the trap-generic front: the syscall flow is written once
# (kernel/src/trap/syscall.rs) and `svc_dispatch` is gone; the second pin is
# now `aarch64_native_svc`, the extern wrapper that instantiates the flow for
# this ISA (the generic dispatch is a const-generic symbol with no stable
# suffix). Measured on the `make aarch64` kernel: aarch64_trap_entry 816 B,
# aarch64_native_svc 804 B (aarch64_fast_ipc_svc 740 B).
# Re-pinned in fx-arm (S6) 816 -> 1360 and 804 -> 1172 (aarch64_fast_ipc_svc
# 740 -> 1092, not pinned). Measured on the gate's own kernel (base features of
# qemu-aarch64.config). The syscall flow now counts every entry in the running
# Domain by case, inline (`Kernel::count_entry`: task slot, domain, atomic add):
# compiling it out gives 1200 and 1012, so it is 160 B of each symbol. The rest
# of the growth (208 B / 384 B) was not bisected (the repo is one commit); the
# entry holds the seccomp verdict, the guards and the exec/signal tail inline.
# `dispatch` is still out of line and the frame is 0x90 B.
# Re-pinned at the gate switch (kconfig-f3f4: the gate's kernel is the generic
# cell, generic-sbc-aarch64-dev+qemu+linux+gui) 1360 -> 1032 and 1172 -> 984.
# Measured on the gate's own kernel (base features of that qemu-aarch64.config,
# no --features). The robot cell's kernel (qemu-aarch64-robot.config) measures
# 1384 and 1204, inside the old pins: the difference is what `use-robot`
# compiles into the path (not bisected). This row watches the gate's kernel.
ci_row "aarch64: trap path size" trap_size_row "aarch64: trap path size" "$A64_KERNEL" aarch64_trap_entry=1032 aarch64_native_svc=984

aarch64_kernel_row() { # aarch64_kernel_row <label> <machine-extra> <expected entry EL> <smp> [cpu] [extra marker] [gic version, 3]
    local label="$1" mach="$2" el="$3" smp="${4:-2}" cpu="${5:-max,pauth=on}" extra="${6:-}" gic="${7:-3}"
    # The interrupt-controller lines of the boot: the GICv3's own, or what a
    # GICv2 boot prints in their place (`irqchip_probe`/`irqchip_init`/
    # `irq_routing_init` in kernel/src/entry/aarch64/boot_hooks.rs).
    local gicm=("[GIC] MMIO mapped: GICD=0x8000000 GICR=0x80a0000")
    if [ "$gic" = 2 ]; then
        gicm=("[GIC] device tree names a GICv2: GICD=0x8000000 (+0x10000) GICC=0x8010000 (+0x10000)" \
              "[GIC] GICv2 MMIO mapped: GICD=0x8000000 GICC=0x8010000, GICD_PIDR2 architecture revision 2" \
              "[GIC] GICv2 distributor + CPU interface initialized, PPI 27 + SGI 0 enabled" \
              "[ITS] none: a GICv2 has no ITS")
    fi
    printf "  %-26s" "${label}..."
    a64_kernel_check || return
    local log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log"
    if [ ! -f "$A64_IMG" ]; then bad; echo "      not built: $A64_IMG"; return; fi
    # Boots the `.img` (Image format), NOT the ELF — this is the row that
    # actually exercises task 1's whole point: x0 carries a real FDT only
    # for a recognised Image load.
    par_ready
    qemu-system-aarch64 -M "virt,gic-version=$gic$mach" -cpu "$cpu" -smp "$smp" \
        -nographic -kernel "$A64_IMG" >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 40 ]; do
        # Two verdicts close the boot, in either order: the migration
        # probe's (`aarch64_migrate_probe_task` in
        # kernel/src/smokes/aarch64_sched.rs) and task A/B's (`phase3_task_done`,
        # its pass line or its `[SCHED] FAILED:`). On `-cpu max` the probe
        # usually prints first, so waiting on it alone killed the boot before
        # the A/B lines below were written (measured 2026-10-22: 3 of 3 runs).
        grep -aq "smp-migrate-probe ran on" "$log" 2>/dev/null \
            && grep -aqE "x20 survived every context switch|\[SCHED\] FAILED:" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception during boot:"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    # Any of mm's/SMP's own "FAILED:" lines (W^X, NX, heap range,
    # no-free-pages, a hart that never came online, a hart that never
    # ticked, TPIDR_EL1 not matching its own hart id, an SGI never
    # received) fails this row too — same free-failure-half trick riscv64's
    # QEMU scenarios already lean on (`QEMU_FAIL_RE`), applied here by hand
    # since this row greps its own log rather than going through that path.
    if grep -aq "FAILED:" "$log" 2>/dev/null; then
        bad; echo "      the boot log reported a failure:"
        grep -a "FAILED:" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local missing=""
    for m in "AzOS Rust kernel booted! (aarch64)" "[BOOT] Hart ID:    0" \
             "[BOOT] Entered at: EL$el" \
             "[MM] SCTLR_EL1.M before first spinlock: ON" \
             "[BOOT] FDT at x0: magic=0xd00dfeed" \
             "[BOOT] FP/SIMD at EL1: 1.5*1.5+0.25 = 2.5" \
             "[MM] PMM:" "[MM] W^X ok:" "[MM] NX outside the image:" \
             "[MM] Null pointer guard active (page 0 unmapped)" \
             "[MM] Stack guard pages active" \
             "[MM] Null guard readback: page 0 unmapped" \
             "[MM] Heap test: Vec = [1, 2, 3, 4, 5, 6]" \
             "[MM] Boot stack:" \
             "[TRAP] svc #0 self-test: PASS" \
             "[TRAP] FP/SIMD survives interrupt: PASS" \
             "[AARCH64-IRQSTACK] hart 0 handles interrupts on its own stack" \
             "[AARCH64-TTBR1] kernel runs in the upper half:" \
             "[AARCH64-TTBR1-POST] after a user task's own TTBR0_EL1" \
             "${gicm[@]}" \
             "[SMP] PSCI conduit:" \
             "[SMP] CPU map (logical=hardware): boot CPU 0=0" \
             "[SCHED] Created $smp idle tasks (one per hart)" \
             "[SCHED] task A and task B created" \
             "[SCHED] Created smp-migrate-probe task" \
             "[SMP] UART lock enabled" \
             "[SMP] Starting $((smp - 1)) secondary hart(s) via PSCI CPU_ON" \
             "[SGI] sent by hart 0, received by hart 1: count=" \
             "[SCHED] Starting scheduler on boot CPU" \
             "interleaved" \
             "preemptions observed:" \
             "x20 survived every context switch" \
             "smp-migrate-probe ran on" ${extra:+"$extra"}; do
        grep -aqF "$m" "$log" 2>/dev/null || missing="$missing\n        $m"
    done
    # The GICR frame count itself (item 1 of this task's brief: canary (a) —
    # mapping only one frame — must fail this row). A regex, not a fixed
    # string with today's `MAX_HARTS` (8) baked in: `kernel::MAX_HARTS`
    # changing would otherwise silently stop this check from meaning
    # anything, rather than failing loudly like the marker text itself would.
    if [ "$gic" != 2 ] \
       && ! grep -aqE '\[GIC\] MMIO mapped: GICD=0x8000000 GICR=0x80a0000 \(x[0-9]+ frames\)' "$log" 2>/dev/null; then
        missing="$missing\n        [GIC] MMIO mapped ... (xN frames)"
    fi
    # Stack guard readback (task 1, aarch64 parity program): a regex, not a
    # fixed "64/64" — `MAX_TASKS` changing would otherwise silently stop this
    # meaning anything. The two halves are printed by the SAME `if` branch in
    # `kernel_main` (kernel/src/main.rs, right after `setup_stack_guard_pages`),
    # so this success-shaped line can only appear when `unmapped == total`; a
    # mismatch prints "[MM] FAILED: stack guard readback" instead, which the
    # generic `FAILED:` check above already catches — this regex only needs
    # to confirm the success line was reached at all.
    if ! grep -aqE '\[MM\] Stack guard readback: [0-9]+/[0-9]+ stack bottoms unmapped' "$log" 2>/dev/null; then
        missing="$missing\n        [MM] Stack guard readback: N/N stack bottoms unmapped"
    fi
    # Per-secondary-hart markers, one pair per hart 1..smp-1 — every hart
    # `-smp $smp` gives this kernel must independently prove it took a real
    # PSCI CPU_ON, published its own MPIDR + hart id, and ticked at least
    # once, not just that HART 1 (the SGI target) did.
    local h=1
    while [ "$h" -lt "$smp" ]; do
        grep -aqE "\[SMP\] hart $h online: MPIDR_EL1=0x[0-9a-f]+ current_cpu_id\(\)=$h" "$log" 2>/dev/null \
            || missing="$missing\n        [SMP] hart $h online (current_cpu_id()=$h)"
        grep -aqF "[SMP] hart $h took" "$log" 2>/dev/null \
            || missing="$missing\n        [SMP] hart $h took N ticks"
        h=$((h + 1))
    done
    # Lazy FP resting state, every hart including 0: CPACR_EL1.FPEN read
    # back as 0b01 (EL0 traps) after its last boot-time writer. A hart left
    # at 0b11 runs user FP untrapped, so its state is never saved on a
    # switch. The failure prints `[FP] FAILED:`, caught by the generic check.
    h=0
    while [ "$h" -lt "$smp" ]; do
        grep -aqF "[FP] hart $h CPACR_EL1.FPEN=0b01: EL0 FP traps" "$log" 2>/dev/null \
            || missing="$missing\n        [FP] hart $h CPACR_EL1.FPEN=0b01"
        h=$((h + 1))
    done
    if [ -n "$missing" ]; then
        bad; echo "      the aarch64 kernel boot did not reach:"; printf "%b\n" "$missing"
        echo "      log kept: $log"; return
    fi
    # Timer ticks: the kernel prints `FAILED:` itself when 5 ticks do not land
    # near the time CNTFRQ_EL0 predicts (caught above); this only catches the
    # check not running at all.
    if ! grep -aqE "\[TIMER\] ticks: 5 in [0-9]+ ms" "$log" 2>/dev/null; then
        bad; echo "      no [TIMER] ticks line: the periodic tick never ran"
        echo "      log kept: $log"; return
    fi
    # PMM frame count > 0: read the actual number back rather than trust
    # the marker's mere presence — a `0 total pages` line would still match
    # the "[MM] PMM:" prefix above.
    local a64_total_pages
    a64_total_pages="$(grep -a "\[MM\] PMM:" "$log" | head -1 | sed -E 's/.* ([0-9]+) total.*/\1/')"
    if [ -z "$a64_total_pages" ] || [ "$a64_total_pages" -eq 0 ]; then
        bad; echo "      PMM reported 0 total pages"; echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"
}
par "aarch64 kernel boots (EL1)"        aarch64_kernel_row "aarch64 kernel boots (EL1)"        ""                     1 2 "max,pauth=on" "[PAN] boot patch (pan=probed-present): every site msr"
par "aarch64 kernel boots (EL2)"        aarch64_kernel_row "aarch64 kernel boots (EL2)"        ",virtualization=on"   2 2 "max,pauth=on" "[PAN] boot patch (pan=probed-present): every site msr"
par "aarch64 kernel boots (EL1, -smp 4)" aarch64_kernel_row "aarch64 kernel boots (EL1, -smp 4)" ""                    1 4 "max,pauth=on" "[PAN] boot patch (pan=probed-present): every site msr"

# ── GICv2 (GIC-400, Cortex-A15 GIC): the same kernel on QEMU `virt,gic-version=2` ──
#
# The Raspberry Pi 5's controller is a GIC-400 (GICv2: MMIO distributor and CPU
# interface, no redistributor, no ITS), which QEMU's `gic-version=2` stands in
# for: the same `arm,cortex-a15-gic` binding, the same `arm,gic` interrupt
# cells, but the CPU interface at 0x08010000. The kernel image is the one the
# GICv3 rows boot; the tree alone selects the backend (`azos_drv_irqchip::gic`,
# `irqchip_probe`), so the row wants the GICv2 lines in place of the GICv3's and
# the rest of the boot unchanged: the PSCI secondary, the timer ticks, the
# scheduler's preemption and, the discriminating one, `[SGI] sent by hart 0,
# received by hart 1`: the `GICD_SGIR` write, the `GICC_IAR` sender and the
# `GICC_EOIR` that returns it (a wrong target mask or an EOI without the sender
# never lands or never ends). EL1 entry only: the EL2 drop writes `ICC_SRE_EL2`,
# which a GICv2 machine does not have. Canaries for the testing week (none run
# when this was written): `gicv2::eoir_encode` returning the INTID alone (an
# SGI is never ended for its sender), and `init_distributor` leaving
# `GICD_CTLR` at 0 (nothing is delivered). Each must turn this row red.
# Needs booting (not run when written).
par "aarch64 kernel boots (GICv2)" aarch64_kernel_row "aarch64 kernel boots (GICv2)" "" 1 2 "max,pauth=on" "[PAN] boot patch (pan=probed-present): every site msr" 2
# ── aarch64: per-process PAC keys (Kconfig A64_PAUTH_PROC_KEYS, S6) ──────────
#
# Every process has APIA/APIB/APDA/APDB/APGA keys of its own, the kernel's key
# is back in APIAKey_EL1 on every entry from EL0 and the process's on the way
# out (kernel/src/entry/aarch64/asm/trap_entry.S, PAC_ENTER / PAC_EXIT;
# crates/core/arch-aarch64/src/cpu/cfi.rs). The row boots the default image on
# `-cpu max,pauth=on -smp 4` (so processes migrate and switch across harts) to
# the end of the early boot and the user tasks, and wants the `[CFI]` line to
# say proc-keys=true. What breaks it, by hand (reverted): the user image is
# built with pac-ret, so a wrong key at the `eret` (PAC_EXIT writes the kernel
# key, or nothing) makes the first `autiasp` of a user function fail, and a
# kernel key left in place by a missing PAC_ENTER makes the first signed
# kernel return after a syscall fail; both stop the boot or the user rows long
# before this marker. `CONFIG_A64_PAUTH_PROC_KEYS=n` reads proc-keys=false and
# this row goes red on the marker. Needs booting (not run when written).
par "aarch64 pac: per-process keys" aarch64_kernel_row "aarch64 pac: per-process keys" "" 1 4 "max,pauth=on" "[CFI] aarch64 pac-ret=true proc-keys=true"

# ── Virtual KASLR (Kconfig KASLR, every ISA) ────────────────────────────────
#
# KASLR defaults to probe on every build type, development included, and to
# require on SECURITY_HARDENED and certifiable builds. The rows still build
# their own images so each one states its policy: tools/kaslr_image.sh (the
# defconfig plus CONFIG_KASLR_PROBE=y for `slid`, or CONFIG_KASLR_NEVER=y for
# `plain`, a private config and target directory; the `plain` rows set n by
# hand, as no defconfig does) and boot each four times with
# tools/kaslr_boot_row.sh, which wants a `[KASLR] image slid to 0x..` line, the
# image mapped at that base, the RAM-map alias read-only, the early boot run to
# its end, and the bases of the boots not all equal. The `plain` row is the
# canary: an image built with KASLR n must read as unslid, AND the slid judge
# must REJECT it (a judge that passes an image that does nothing is a row that
# passes without looking). Canary by hand (reverted): `shared::relocate_image`
# in kaslr_boot returning before the walk makes every slid row FAIL (the boot
# stops at the first pointer it follows); a fixed `seed()` makes the
# "bases not all equal" check FAIL.
kaslr_row() { # kaslr_row <riscv64|aarch64|x86_64> <slid|plain>
    local isa="$1" mode="$2" label="kaslr: $2 ($1)" img out
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    out="$CI_LOG_DIR/kaslr-$isa-$mode.out"
    if ! img="$("$REPO_ROOT/tools/kaslr_image.sh" "$isa" "$mode" 2>"$out.build")"; then
        bad; echo "      the $isa $mode image did not build — log kept: $out.build"; return
    fi
    par_ready
    if ! KASLR_LOG_DIR="$CI_LOG_DIR" "$REPO_ROOT/tools/kaslr_boot_row.sh" "$isa" "$img" "$mode" >"$out" 2>&1; then
        bad; sed 's/^/      /' "$out"; return
    fi
    if [ "$mode" = plain ] \
       && KASLR_LOG_DIR="$CI_LOG_DIR" "$REPO_ROOT/tools/kaslr_boot_row.sh" "$isa" "$img" slid 2 >"$out.canary" 2>&1; then
        bad; echo "      canary did not bite: the slid judge accepted an image that does not slide"; return
    fi
    ok; rm -f "$out" "$out.build" "$out.canary"
}
for kaslr_isa in aarch64 riscv64 x86_64; do
    par "kaslr: slid ($kaslr_isa)"  kaslr_row "$kaslr_isa" slid
    par "kaslr: plain ($kaslr_isa)" kaslr_row "$kaslr_isa" plain
done
# ── ramfb on a slid kernel (riscv64, DRV_DISPLAY_RAMFB) ──────────────────
#
# QEMU's ramfb reads guest physical memory: the framebuffer address and the
# fw_cfg DMA descriptor and payload it is handed must be physical addresses,
# and a `.bss` symbol's address is not one once KASLR slid the image into the
# upper half. The row builds the slid riscv64 image (tools/kaslr_image.sh)
# with `ramfb`, boots it once with `-device ramfb` and wants: the image slid,
# `[RAMFB] configured` (the device cleared the descriptor's control word: it
# read the descriptor), and the configured address below the image base (a
# physical address, not an image one), the same address on the `[FB] ramfb`
# line. Canary (`ramfb-va-canary`, built apart): the framebuffer's virtual
# address again; the address check must then fail.
ramfb_slid_row() { # ramfb_slid_row <pass|canary>
    local want="$1" feats=ramfb label="display: ramfb on a slid kernel (rv)" img out log pid i=0 base addr fb why=""
    [ "$want" = canary ] && { feats=ramfb-va-canary; label="display: ramfb slid canary (rv)"; }
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    out="$CI_LOG_DIR/ramfb-slid-$want.out"; log="$CI_LOG_DIR/ramfb-slid-$want.log"
    if ! img="$(KASLR_EXTRA_FEATURES="$feats" "$REPO_ROOT/tools/kaslr_image.sh" riscv64 slid "$AZOS_OUT/build/kaslr-riscv64-$feats" 2>"$out.build")"; then
        bad; echo "      the slid $feats image did not build — log kept: $out.build"; return
    fi
    par_ready
    rm -f "$log"
    "$QEMU" -machine virt -nographic -bios default -m 256M -smp 2 -kernel "$img" -device ramfb </dev/null >"$log" 2>&1 &
    pid=$!
    while [ "$i" -lt 180 ] && kill -0 "$pid" 2>/dev/null; do
        tr -d '\r' <"$log" | grep -aqE '^\[FB\] (ramfb|no framebuffer)|^\[RAMFB\] .*(failed|no DMA|not found)|KERNEL PANIC|\[FATAL\]' && break
        i=$((i + 1)); sleep 0.5
    done
    kill "$pid" 2>/dev/null; sleep 0.2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    base="$(tr -d '\r' <"$log" | sed -n -E 's/^\[KASLR\] image slid to (0x[0-9a-f]+),.*/\1/p' | sed -n 1p)"
    addr="$(tr -d '\r' <"$log" | sed -n -E 's/^\[RAMFB\] configured: [0-9]+x[0-9]+ @ (0x[0-9a-f]+),.*/\1/p' | sed -n 1p)"
    fb="$(tr -d '\r' <"$log" | sed -n -E 's/^\[FB\] ramfb .* at (0x[0-9a-f]+), .*/\1/p' | sed -n 1p)"
    if [ -z "$base" ]; then why="the image did not slide (no \"[KASLR] image slid to\" line)"
    elif [ -z "$addr" ]; then why="ramfb was not configured: $(tr -d '\r' <"$log" | grep -a '^\[RAMFB\]' | sed -n 1p)"
    elif ! python3 -c 'import sys; sys.exit(0 if int(sys.argv[1], 16) < int(sys.argv[2], 16) else 1)' "$addr" "$base"; then
        why="the device was handed $addr, an image address (image at $base), not a physical one"
    elif [ "$fb" != "$addr" ]; then why="the [FB] line names ${fb:-no address}, ramfb was handed $addr"
    fi
    if [ "$want" = canary ]; then
        if [ -n "$why" ] && [ -n "$base" ]; then ok; rm -f "$log" "$out.build"
        else bad; echo "      canary did not bite: the virtual address passed the row${why:+ ($why)} — log kept: $log"; fi
        return
    fi
    if [ -n "$why" ]; then bad; echo "      $why — log kept: $log"; return; fi
    ok; rm -f "$log" "$out.build"
}
par "display: ramfb on a slid kernel (rv)" ramfb_slid_row pass
par "display: ramfb slid canary (rv)" ramfb_slid_row canary
# ── hv (S6): the resident EL2 stub, and the guest entry behind it (aarch64) ───
#
# Two rows on QEMU `virtualization=on,gic-version=3`, which gives a boot an EL2
# to keep. The kernel without the hypervisor (`VIRT` none, the rows above) must
# NOT keep it: `_azos_drop_to_el1` installs the stub only for the cargo feature
# `hv` (Kconfig HV, derived from VIRT), so its boot line says `none (RoleNone)`
# and no vector table is left at EL2. Canary: take the `.if {hv}` guard out of
# the trampoline (mmu/boot.rs) and that line becomes `kept` on this kernel.
# The `hv` kernel (`--features qemu,hv`) keeps it, the probe `HVC` of the stub
# answers, and `Hypervisor::can_enter` is true: the GICv3 virtual CPU interface
# is there (`ID_AA64PFR0_EL1.GIC`), which is the whole of what the entry needs
# of the CPU. Canary: `HvImpl::can_enter` returning false (or the stub's
# `HVC_INFO` unanswered) leaves "no guest entry".
#
# What neither row does is run a guest: that is `tools/run_guest.sh aarch64`
# (the monitor cannot map a whole guest kernel's RAM yet, see the note at
# `hv_guest_judge`), and the entry itself is exercised by it the day it can.
par "aarch64 kernel boots (EL2, no hypervisor)" aarch64_kernel_row "aarch64 kernel boots (EL2, no hypervisor)" ",virtualization=on" 2 2 "max,pauth=on" "[BOOT] EL2:        none (RoleNone)"

aarch64_hv_row() {
    local label="aarch64 hv: guest entry ready"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-hv-entry.log"
    rm -f "$log"
    if ! a64_kbuild "qemu,hv"; then
        bad; echo "      aarch64 kernel (--features qemu,hv) did not build"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-hv.img"
    cp "$A64_IMG" "$img_copy"
    par_ready
    qemu-system-aarch64 -M virt,virtualization=on,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 120 ]; do
        grep -aqE "\[BOOT\] EL2: +(guest entry ready|no guest entry)|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img_copy"
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception at boot:"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed -n '1,4p' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local missing=""
    grep -aqF "[BOOT] EL2:        kept; resident stub answers HVC (abi 2)" "$log" 2>/dev/null \
        || missing="$missing\n        [BOOT] EL2: kept; resident stub answers HVC (abi 2)"
    grep -aqF "[BOOT] EL2:        guest entry ready (GICv3 virtual CPU interface)" "$log" 2>/dev/null \
        || missing="$missing\n        [BOOT] EL2: guest entry ready (GICv3 virtual CPU interface)"
    if grep -aqF "a PE is parked on an unhandled trap" "$log" 2>/dev/null; then
        missing="$missing\n        no PE parked on an unhandled EL2 trap"
    fi
    if [ -n "$missing" ]; then
        bad; echo "      the hv kernel's boot did not reach:"; printf "%b\n" "$missing"
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"
}
par "aarch64 hv: guest entry ready" aarch64_hv_row
# Leave $A64_IMG on an ordinary qemu build for the rows below.
a64_kbuild "qemu" >/dev/null 2>&1 || true

# ── VE (wave 15): the kernel on an Armv8.0 core ─────────────────────────────
#
# Every row above boots `-cpu max`, which is how the kernel once stopped
# booting on every Armv8.0 core without a red row: boot.S set PSTATE.PAN with
# `MSR PAN, #1` (FEAT_PAN is Armv8.1), UNDEFINED on an A53/A72 before
# VBAR_EL1 was set, so the console stayed empty. Now boot.S, the EL2 drop and
# every UserAccess window key on ID_AA64MMFR1_EL1.PAN under Kconfig `A64_PAN`
# (probe at the 8.0 level). Same kernel image, same markers as the EL1/EL2
# rows, plus the [ISA] line naming PAN absent, so the row ties to the probe.
# EL2 too: `_azos_drop_to_el1` writes SCTLR_EL1.SPAN and SPSR_EL2.PAN.
# Canary: `--features a64-pan-unprobed-canary` (the unprobed `MSR PAN` back):
# an empty log, every marker missing.
# The extra marker is the boot-once PAN patch's census (kernel/src/entry/
# aarch64/pan_patch.rs): under A64_PAN=probe every UserAccess site, linked as
# a branch to the runtime test, is rewritten before the secondaries start to
# `msr PAN` (`-cpu max`, the rows above) or `nop` (here), so a window costs
# no load and no branch after boot. Canary: `canary=pan-patch-skip` leaves
# every site a branch; the line then reads "0 of N sites ..., N still branch"
# (and ktest `a64_pan_sites_patched` goes not ok).
par "aarch64 kernel boots on cortex-a53 (8.0)" aarch64_kernel_row "aarch64 kernel boots on cortex-a53 (8.0)" "" 1 2 cortex-a53 "[PAN] boot patch (pan=probed-absent): every site nop"
par "aarch64 kernel boots on cortex-a53 (8.0, EL2)" aarch64_kernel_row "aarch64 kernel boots on cortex-a53 (8.0, EL2)" ",virtualization=on" 2 2 cortex-a53 "[PAN] boot patch (pan=probed-absent): every site nop"

# The same kernel image on the two ends of the extension range, read from the
# `[ISA]` line (kernel/src/boot/isa.rs; every A64_* extension at `probe` in
# qemu-aarch64.config). `cortex-a72` is Armv8.0: the boot must reach the same
# last marker with the Armv8.1 features LSE and PAN reported absent, so no
# extension is a hard requirement. `max,pauth=on` with `mte=on` on the machine
# (tag storage; QEMU 11 reports the MTE ID field without it too, so the marker
# does not prove it) is past Armv8.5: PAuth (8.3), BTI and MTE (8.5) must be
# probed present, so a field decoder reading the wrong four bits, or QEMU
# dropping one, turns the row red. QEMU 11 names no plain 8.5 model
# (cortex-a710 and neoverse-n2 are Armv9.0). Canary (hand-run 2026-10-22):
# each row's marker on the other row's CPU (8.0 marker on `max`, 8.5 marker on
# cortex-a72) goes red, the marker missing.
par "aarch64 boots (ARMv8.0)" aarch64_kernel_row "aarch64 boots (ARMv8.0)" "" 1 2 cortex-a72 "[ISA] baseline=armv8.0 lse=probed-absent pan=probed-absent"
par "aarch64 boots (ARMv8.5)" aarch64_kernel_row "aarch64 boots (ARMv8.5)" ",mte=on" 1 2 "max,pauth=on" "pauth=probed-present bti=probed-present mte=probed-present"
par "aarch64 shell answers help" shell_help_row "aarch64 shell answers help" arm

# ── aarch64 on QEMU raspi3b: the same kernel on a Raspberry Pi 3 B ───────────
#
# BCM2837 (four Cortex-A53, Armv8.0), RAM at 0, no GIC, no PSCI: the board the
# owner tests on. The image is the `virt` rows' kernel from the same profile
# plus the Pi's drivers the gate's base features leave out (the PM block, the
# VideoCore mailbox, the DWC2 host and the CDC class), and without
# `wdt-bcm2835-pm-arm` (Kconfig WDT_BCM2835_PM_ARM, y on a real Pi): QEMU's PM
# model resets the machine on the arming write itself (no countdown), so an
# armed PM watchdog would reboot it at the scheduler's start; the block stays
# the reset handler. Every board fact comes from the device tree the firmware
# would pass: tests/host/dtb-tests/fixtures/qemu-raspi3b.dtb, Linux's
# bcm2837-rpi-3-b.dts (U-Boot 2025.07's dts/upstream) compiled and dumped by
# QEMU (`dumpdtb=`; QEMU patches `/memory` to the same 0x3c000000 again).
# What each part proves, by its marker:
#   - the load address: the firmware's 0x80000 with RAM at 0, the image linked
#     for 0x4008_0000 (boot.S "Where RAM is", KASLR relocating from the link
#     PA): the banner at all;
#   - the console from /chosen/stdout-path (`serial1`, the mini UART): QEMU's
#     second serial is stdio (`-serial null -serial stdio`);
#   - the BCM2836 local controller + armctrl backend: the tick (CNTV through
#     the local block) and `[SGI] sent by hart 0, received by hart 1` (mailbox
#     0 of core 1);
#   - spin-table SMP: three CPUs released into the kernel's pen, all online;
#   - no PSCI: the conduit is None, so no SMC reaches an EL3 with nothing there.
# Mode `usb` adds a CDC-ECM `usb-net` on the DWC2 root port (QEMU has no
# smsc95xx): the firmware powers the USB domain (SET_POWER_STATE, the
# mailbox), the DMA domain moves every address by the VideoCore's 0xc0000000
# (`dma-ranges`), and the device enumerates. Mode `reboot` types `reboot`:
# with no /psci the PM block resets the SoC, so the banner comes twice.
# Canaries (by hand, each turns its row red): boot.S without the DRAM-base
# derivation (`mov x23, #0x40000000`: the bootstrap map covers no RAM, an
# empty log); `bcm2836::iar` returning 1023 for a mailbox (no SGI); the spin
# table release skipped (harts 1..3 never online); `MmioView::bus_of` without
# the offset (the DWC2 DMA lands in the wrong place: no `attached`).
raspi3b_row() { # raspi3b_row <label> <shell|usb|reboot>
    local label="$1" mode="$2"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log fifo kimg dtb="$REPO_ROOT/tests/host/dtb-tests/fixtures/qemu-raspi3b.dtb"
    local feats="qemu,wdt-bcm2835-pm,rpi-firmware,usb-dwc2,usb-cdc"
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; fifo="$CI_LOG_DIR/${slug}.fifo"; kimg="$CI_LOG_DIR/${slug}.img"
    rm -f "$log" "$fifo" "$kimg"
    if [ ! -f "$dtb" ]; then bad; echo "      no device tree: $dtb"; return; fi
    if ! a64_kbuild "$feats"; then
        bad; echo "      aarch64 --features $feats did not build"; return
    fi
    cp "$A64_IMG" "$kimg"
    if ! mkfifo "$fifo"; then bad; echo "      mkfifo failed: $fifo"; rm -f "$kimg"; return; fi
    local usb=()
    [ "$mode" = usb ] && usb=(-device usb-net,netdev=n0 -netdev user,id=n0)
    par_ready
    while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
    qemu-system-aarch64 -M raspi3b -dtb "$dtb" -kernel "$kimg" -nographic -monitor none \
        -serial null -serial stdio ${usb[@]+"${usb[@]}"} <"$fifo" >"$log" 2>&1 &
    local pid=$! i=0 sent=0 done=""
    exec 9>"$fifo"
    while [ "$i" -lt 240 ]; do
        grep -aqiE "KERNEL PANIC|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        case "$mode" in
            shell) grep -aqF "help              - this message" "$log" 2>/dev/null && { done=1; break; } ;;
            usb) grep -aqE '\[USB\] slot [0-9]+ on root port [0-9]+: 0525:a4a2 class 02:00:00 attached' "$log" 2>/dev/null \
                     && { done=1; break; } ;;
            reboot) [ "$(grep -acF 'AzOS Rust kernel booted! (aarch64)' "$log")" -ge 2 ] && { done=1; break; } ;;
        esac
        if [ "$sent" -eq 0 ] && grep -aqF "robot> " "$log" 2>/dev/null; then
            local cmd=help
            [ "$mode" = reboot ] && cmd=reboot
            if [ "$mode" != usb ]; then
                ( printf '%s' "$cmd" | while IFS= read -r -n1 b; do printf '%s' "$b"; sleep 0.05; done; printf '\r' ) >&9 2>/dev/null
            fi
            sent=1
        fi
        i=$((i + 1)); sleep 0.5
    done
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    exec 9>&-
    rm -f "$fifo" "$kimg"
    if grep -aqiE "KERNEL PANIC|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel crashed:"
        grep -a -m3 -iE "KERNEL PANIC|AARCH64-TRAP|  at " "$log" | tr -d '\r' | sed 's/^/        /'
        echo "      log kept: $log"; return
    fi
    if grep -aqF "FAILED:" "$log" 2>/dev/null; then
        bad; echo "      the boot log reported a failure:"
        grep -a "FAILED:" "$log" | tr -d '\r' | head -5 | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local missing="" m
    for m in "AzOS Rust kernel booted! (aarch64)" \
             "[BOOT] Entered at: EL2" \
             "[BOOT] Console:    BCM2835 mini UART at 0x3f215040 (device tree stdout-path)" \
             "[DTB] Parsed FDT — mem=0x0+0x3c000000 (4 CPUs)" \
             "[MM] RAM detected via DTB: 0x0 - 0x3c000000" \
             "[SMP] spin table: 3 CPU(s) released into the kernel's pen" \
             "[IRQ] device tree names no GIC but the BCM2836 pair: local=0x40000000" \
             "[IRQ] BCM2836 local=0x40000000 + armctrl=0x3f00b200 initialized" \
             "[SMP] PSCI conduit: None (from FDT: no /psci node)" \
             "[SMP] hart 1 online" "[SMP] hart 2 online" "[SMP] hart 3 online" \
             "[SMP] hart 3 took" \
             "[SGI] sent by hart 0, received by hart 1: count=" \
             "[HWBUS] watchdog@7e100000 dt:brcm,bcm2835-pm base=0x3f100000" \
             "robot> "; do
        grep -aqF "$m" "$log" 2>/dev/null || missing="$missing\n        $m"
    done
    grep -aqE "\[TIMER\] ticks: 5 in [0-9]+ ms" "$log" 2>/dev/null || missing="$missing\n        [TIMER] ticks: 5 in N ms"
    case "$mode" in
        shell) grep -aqF "help              - this message" "$log" || missing="$missing\n        the help table (typed help)" ;;
        usb)
            for m in "[DMA] devices at 0x3f003000..=0x40000000: bus address = CPU address + 0xc0000000" \
                     "[USB] usb@7e980000: firmware power domain 6 (device 3) on" \
                     "[USB] DWC2 usb@7e980000: 1 port"; do
                grep -aqF "$m" "$log" || missing="$missing\n        $m"
            done
            grep -aqE '\[USB\] slot [0-9]+ on root port [0-9]+: 0525:a4a2 class 02:00:00 attached' "$log" \
                || missing="$missing\n        [USB] ... 0525:a4a2 class 02:00:00 attached (usb-net)" ;;
        reboot)
            grep -aqF "[RECOVERY] System reboot..." "$log" || missing="$missing\n        [RECOVERY] System reboot..."
            [ "$(grep -acF 'AzOS Rust kernel booted! (aarch64)' "$log")" -ge 2 ] \
                || missing="$missing\n        a second banner (the PM block's reset)" ;;
    esac
    if [ -n "$missing" ] || [ -z "$done" ]; then
        bad; echo "      the raspi3b boot did not reach:"; printf "%b\n" "${missing:-        (its end marker: timeout)}"
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"
}
par "aarch64 raspi3b boots to the shell" raspi3b_row "aarch64 raspi3b boots to the shell" shell
par "aarch64 raspi3b USB via DWC2" raspi3b_row "aarch64 raspi3b USB via DWC2" usb
par "aarch64 raspi3b reboots via the PM block" raspi3b_row "aarch64 raspi3b reboots via the PM block" reboot

# ── aarch64: PL011 console RX on interrupts (wave 7) ─────────────────────────
#
# riscv64's UART RX has been interrupt-driven (PLIC/APLIC -> `uart::irq_handler`
# -> ring) for a long time; the aarch64 PL011 was polled. `boot_hooks::console_irq`
# now reads the PL011's `interrupts` from the DTB (QEMU virt: SPI 1 -> INTID
# 33), routes that SPI to the boot hart (GICD_IROUTER from MPIDR_EL1), enables
# it, and unmasks RX/RX-timeout in the PL011; `handle_irq` drains the FIFO into
# the ring and wakes the parked shell. Input is PACED, one byte per 50 ms, as
# in the AIA row (never a flood: one IRQ per byte with no line rate made that
# row's boot bimodal). The number is read back and must be > 0.
#
# Canary (hand-run, wave 7): `--features qemu,pl011-rx-irq-canary` leaves the
# PL011's RX interrupt masked (GIC side still routed and enabled). The shell
# still answers by polling, and this row goes red on the count, "delivered 0
# time(s)".
pl011_rx_irq_row() {
    local label="aarch64 pl011 rx irq count"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/pl011-rx-irq.log" kcopy="$CI_LOG_DIR/pl011-rx-irq-kernel"
    rm -f "$log" "$kcopy"
    if [ ! -f "$A64_IMG" ]; then bad; echo "      not built: $A64_IMG"; return; fi
    cp "$A64_IMG" "$kcopy"
    par_ready
    pl011_paced_input() { while :; do printf x || break; sleep 0.05; done; }
    pl011_paced_input 2>/dev/null | qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 \
        -nographic -kernel "$kcopy" >"$log" 2>&1 &
    local qpid=$! i=0
    while [ "$i" -lt 90 ]; do
        grep -aqE "\[IRQ\] PL011 (INTID [0-9]+ \(uart\) delivered|RX interrupt not wired)" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$qpid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
    rm -f "$kcopy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel crashed — log kept: $log"; return
    fi
    if ! grep -aqE "\[IRQ\] PL011 0x9000000: DTB INTID 33 \(level\) .* enabled=true" "$log"; then
        bad; echo "      the PL011 SPI was not derived/routed/enabled (want DTB INTID 33, level, enabled=true):"
        grep -a "\[IRQ\] PL011\|\[IRQ\] no PL011" "$log" | tr -d '\r' | sed 's/^/      /'
        echo "      log kept: $log"; return
    fi
    if grep -aqE "\[IRQ\] PL011 INTID 33 \(uart\) delivered [1-9][0-9]* time" "$log"; then
        ok; echo "      $(grep -a "\[IRQ\] PL011 INTID" "$log" | tr -d '\r')"; rm -f "$log"
    else
        bad; echo "      paced input, but no PL011 RX interrupt was counted:"
        grep -a "\[IRQ\] PL011" "$log" | tr -d '\r' | sed 's/^/      /'
        echo "      log kept: $log"
    fi
}
par "aarch64 pl011 rx irq count" pl011_rx_irq_row

# ── aarch64 userspace (Phase 6) ──────────────────────────────────────────────
#
# Two boots, one image each (hermetic — the guest WRITES to its FAT32, so
# reusing an image across boots breaks the second run): `disk-aarch64.img`
# autoruns HELLO.ELF (the milestone: EL0 entry, `write`+`exit` through `svc`,
# the kernel prints the line and reaps the task); `disk-aarch64-systest.img`
# autoruns SYSCALL_TEST.ELF (getpid/write/map a page/write-to-new-page).
# `[SCHED] aarch64 reaped tid=N` (`scheduler.rs`, `#[cfg(target_arch =
# "aarch64")]` only — riscv64 prints nothing new here) is printed for EVERY
# reaped task, so the row reads HELLO's own TID from its autorun line
# (`[AUTORUN][MEM] tid=N HELLO.ELF`) and waits for that TID's reap; it used to
# stop at the first `reaped` of any task, which can come before HELLO prints.
# Canary (by hand, 2026-10-03, on synthetic logs through `a64_hello_reaped`):
# another task reaped before HELLO prints -> still waits, passes once HELLO's
# own reap appears; no HELLO autorun line -> never reaped, the row fails.
a64_hello_tid() { # <log>: HELLO.ELF's TID from its autorun line, or nothing
    grep -a "\] tid=[0-9]* HELLO\.ELF " "$1" 2>/dev/null \
        | sed -n 's/.*\] tid=\([0-9][0-9]*\) HELLO\.ELF .*/\1/p' | sed -n '1p'
}
a64_hello_reaped() { # <log>: HELLO's own task was reaped
    local t; t="$(a64_hello_tid "$1")"
    [ -n "$t" ] && grep -aqE "\[SCHED\] aarch64 reaped tid=${t} slot=" "$1" 2>/dev/null
}
aarch64_userspace_row() {
    local label="aarch64 userspace"
    printf "  %-26s" "${label}..."
    local log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log"
    if [ -n "${A64_USERSPACE_TABLE_FAILED:-}" ]; then
        bad; echo "      $AZOS_OUT/build/image_hashes_aarch64.rs was not generated"; return
    fi
    if [ ! -f "$A64_IMG" ]; then bad; echo "      not built: $A64_IMG"; return; fi

    rm -f $AZOS_OUT/build/disk-aarch64.img $AZOS_OUT/build/disk-aarch64-systest.img
    if ! make $AZOS_OUT/build/disk-aarch64.img $AZOS_OUT/build/disk-aarch64-systest.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64.img \
$AZOS_OUT/build/disk-aarch64-systest.img"
        return
    fi

    # Boot a COPY of the kernel image and a COPY of each disk image — the
    # guest writes FAT32 (BOOTMETA/log files), so reusing an image across
    # runs, or across the two boots this row makes, breaks the second one.
    local img_copy="$CI_LOG_DIR/kernel-aarch64-userspace.img"
    cp "$A64_IMG" "$img_copy"

    # ── Boot 1: hello ────────────────────────────────────────────────────
    local hello_disk="$CI_LOG_DIR/disk-aarch64-hello.img"
    cp $AZOS_OUT/build/disk-aarch64.img "$hello_disk"
    local systest_disk="$CI_LOG_DIR/disk-aarch64-systest.img"
    cp $AZOS_OUT/build/disk-aarch64-systest.img "$systest_disk"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$hello_disk",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 60 ]; do
        a64_hello_reaped "$log" && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        grep -aq "FAILED:" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      hello: the kernel took an exception"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if grep -aq "FAILED:" "$log" 2>/dev/null; then
        bad; echo "      hello: the boot log reported a failure:"
        grep -a "FAILED:" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "Hello from user-space!" "$log" 2>/dev/null; then
        bad; echo "      hello: its write() output never appeared"
        echo "      log kept: $log"; return
    fi
    if ! a64_hello_reaped "$log"; then
        bad; echo "      hello (tid=$(a64_hello_tid "$log")): exited but was never \
reaped (do_schedule's Zombie arm never ran)"
        echo "      log kept: $log"; return
    fi
    rm -f "$log"

    # ── Boot 2: syscall_test ────────────────────────────────────────────
    local log2="$CI_LOG_DIR/aarch64-userspace-systest.log"
    rm -f "$log2"
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$systest_disk",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log2" 2>&1 &
    pid=$!; i=0
    while [ "$i" -lt 60 ]; do
        grep -aqF "[SYSCALL_TEST] ALL PASSED" "$log2" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log2" 2>/dev/null && break
        grep -aq "FAILED:" "$log2" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log2" 2>/dev/null; then
        bad; echo "      syscall_test: the kernel took an exception"
        grep -a "AARCH64-TRAP" "$log2" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log2"; return
    fi
    if ! grep -aqF "[SYSCALL_TEST] ALL PASSED" "$log2" 2>/dev/null; then
        bad; echo "      syscall_test: did not print ALL PASSED"
        grep -a "SYSCALL_TEST\]" "$log2" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log2"; return
    fi

    ok; rm -f "$log2"
}
par "aarch64 userspace" aarch64_userspace_row

# ── aarch64 networking (aarch64 parity program, network bring-up task) ──────
#
# riscv64's `kernel_main` brings up `azos_drv_virtio::virtio::net`, applies
# the configured address, and runs a dedicated `net-poll` task; aarch64's own
# `kernel_main` never called any of it (its own comments said so directly —
# "no network bring-up on aarch64"). Both ISAs now go through the SAME shared
# functions (`install_net_config`/`install_net`, `net_poll_task` — see
# `kernel/src/boot/net.rs`'s own doc comments on each), called from each
# `kernel_main` rather than a second copy. These two rows are aarch64's
# twin of riscv64's `-netdev user,...` scenarios, over virtio-mmio (not
# PCI) — `-global virtio-mmio.force-legacy=false` matches the blk row above
# so the NIC negotiates the SAME (modern, v2) transport the driver has
# actually been run against on this ISA, not legacy v1.
#
# Diskless on purpose for the first row (riscv64's own DHCP row boots
# diskless too): device bring-up must not depend on a disk being present.
aarch64_net_probe_row() {
    local label="aarch64 network: NIC found + MAC"
    printf "  %-26s" "${label}..."
    local log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log"
    if [ ! -f "$A64_IMG" ]; then bad; echo "      not built: $A64_IMG"; return; fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-netprobe.img"
    cp "$A64_IMG" "$img_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -netdev user,id=net0 -device virtio-net-device,netdev=net0 \
        >"$log" 2>&1 &
    local pid=$! i=0
    # Wait for the LAST line this row asserts (net-poll actually running),
    # not for its creation: the row used to stop at "Created net-poll task"
    # and then assert "Phase U1 ... started", which is printed ~50 lines
    # later once the scheduler runs it. Wave 5's boot lines moved it past the
    # kill point (gate 187: "created but never actually ran" on a kernel that
    # runs it at boot line 233 when left alone).
    while [ "$i" -lt 60 ]; do
        grep -aqF "[NET-POLL] Phase U1: dedicated network polling task started" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        grep -aq "FAILED:" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if grep -aq "FAILED:" "$log" 2>/dev/null; then
        bad; echo "      the boot log reported a failure:"
        grep -a "FAILED:" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    # The MAC is read back off the device (2 aligned 32-bit config-space
    # words, unpacked) and asserted against the EXACT value QEMU's SLIRP NIC
    # gives this scenario's `-netdev user` on this command line
    # (52:54:00:12:34:56 — its fixed default, no `mac=` override above).
    #
    # A generic "six hex-pair octets" regex was tried first and does NOT
    # discriminate: hand-verified this task by reverting `net.rs`'s MAC read
    # to the historical per-byte low-byte-of-word bug that read-back
    # function's own doc comment describes (offsets 1/2/3 of the config
    # space are unaligned, so `mmio_read` rounds them down to offset 0 and
    # every one of those three bytes reads back as MAC[0]) — the generic
    # regex still matched the resulting `52:52:52:52:34:34`, a MAC this
    # guest does not own. The exact-string check below fails on that same
    # binary; reverting the bug makes it pass again.
    if ! grep -aqF "[NET] VirtIO net: MAC 52:54:00:12:34:56" "$log" 2>/dev/null; then
        bad; echo "      no MAC read back from the device (or the wrong one)"
        grep -a "VirtIO net: MAC" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[NET] VirtIO net OK" "$log" 2>/dev/null; then
        bad; echo "      NIC probe did not report OK"
        echo "      log kept: $log"; return
    fi
    # Address configuration: `install_net_config` ran and `net_init` brought
    # the stack up (both shared with riscv64 — see their own doc comments).
    if ! grep -aqE '\[CFG\] net: [0-9]+\.[0-9]+\.[0-9]+\.[0-9]+ gw [0-9]+\.[0-9]+\.[0-9]+\.[0-9]+' "$log" 2>/dev/null; then
        bad; echo "      no [CFG] net: address line"
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[NET] Stack ready" "$log" 2>/dev/null; then
        bad; echo "      net_init() never reported the stack ready"
        echo "      log kept: $log"; return
    fi
    # net-poll: shared with riscv64, but pinned to the LAST ONLINE hart here
    # (this board's -smp varies across rows) rather than a literal 3 — see
    # `net_poll_task`'s own call site in `kernel_main` for why. -smp 2 above
    # means hart 1.
    if ! grep -aqF "[SCHED] Created net-poll task (IO-wait, <= sched_hz=100 Hz) [hart 1]" "$log" 2>/dev/null; then
        bad; echo "      net-poll task was not created on the expected hart"
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[NET-POLL] Phase U1: dedicated network polling task started" "$log" 2>/dev/null; then
        bad; echo "      net-poll task was created but never actually ran"
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"
}
par "aarch64 network: NIC found + MAC" aarch64_net_probe_row

# aarch64's twin of riscv64's `network: DHCP lease` row (`run_dhcp_smoke` —
# shared code, see its own doc comment). Needs its OWN build+image: the
# `dhcp-smoke` feature changes `kernel_main`'s boot sequence, so reusing
# `$A64_IMG` here would be exactly the stale-binary trap this project's own
# notes warn about (a build failure leaving the PREVIOUS image for this row
# to boot and report a verdict for). Deleted before rebuilding for the same
# reason `$A64_IMG` itself is.
aarch64_dhcp_row() {
    local label="aarch64 network: DHCP lease"
    printf "  %-26s" "${label}..."
    local log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log"
    local dhcp_kernel="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel"
    local dhcp_img="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel-dhcp-smoke.img"
    rm -f "$dhcp_kernel" "$dhcp_img"
    local build_out
    if ! build_out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$AARCH64_CONFIG" "$CARGO" build --release \
            --target aarch64-unknown-none-softfloat -p azos_kernel --features qemu,dhcp-smoke \
            --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)" \
       || printf '%s\n' "$build_out" | grep -E "^(error|warning)" | qgrep -vqE "$A64_KNOWN_NOISE" \
       || [ ! -f "$dhcp_kernel" ]; then
        bad; echo "      dhcp-smoke aarch64 kernel did NOT build:"
        printf '%s\n' "$build_out" | grep -E "^(error|warning)" | grep -vE "$A64_KNOWN_NOISE" | head -5
        return
    fi
    local a64_objcopy
    a64_objcopy="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objcopy"
    if [ ! -x "$a64_objcopy" ] || ! "$a64_objcopy" -O binary "$dhcp_kernel" "$dhcp_img" \
       || [ ! -f "$dhcp_img" ]; then
        bad; echo "      llvm-objcopy not found or ELF -> .img failed"
        return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-dhcp.img"
    cp "$dhcp_img" "$img_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -netdev user,id=net0 -device virtio-net-device,netdev=net0 \
        >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 60 ]; do
        grep -aqE "\[DHCPSMOKE\] (PASS|FAIL)" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[DHCPSMOKE] PASS" "$log" 2>/dev/null; then
        bad; echo "      DHCP smoke did not PASS:"
        grep -a "DHCPSMOKE\]" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log" "$dhcp_kernel" "$dhcp_img"
}
par "aarch64 network: DHCP lease" aarch64_dhcp_row

# IO-QUEUES N1 (wave 15): virtio-net TX doorbell batching. The boot self-check
# (Kconfig NET_TX_BATCH_SELFCHECK, kernel/src/boot/net.rs) queues three frames
# inside one TX batch and counts doorbell decisions (rung, or skipped on the
# device's NO_NOTIFY): none inside the batch, one at its end. Decisions, not
# doorbells, so the device's timing cannot move the line. Canary row: the
# runtime canary `canary=net-kick-per-frame` (a doorbell per frame) must turn
# it to "in batch 3, at flush 0: FAIL". Defined here, used for arm below and
# for rv in the network block.
net_tx_batch_row() { # net_tx_batch_row <label> <rv|arm> <PASS|FAIL> [kernel command line]
    local label="$1" isa="$2" want="$3" app="${4:-}"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log img
    log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    rm -f "$log"
    if [ "$isa" = rv ]; then
        kbuild "qemu" || { bad; echo "      riscv64 --features qemu did not build"; return; }
        img="$CI_LOG_DIR/kernel-txbatch-${want}-rv.elf"; cp "$KERNEL" "$img"
    else
        [ -f "$A64_IMG" ] || { bad; echo "      not built: $A64_IMG"; return; }
        img="$CI_LOG_DIR/kernel-txbatch-${want}-arm.img"; cp "$A64_IMG" "$img"
    fi
    par_ready
    if [ "$isa" = rv ]; then
        "$QEMU" -machine virt -nographic -bios default -kernel "$img" ${app:+-append "$app"} \
            -netdev user,id=net0 -device virtio-net-device,netdev=net0 </dev/null >"$log" 2>&1 &
    else
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$img" ${app:+-append "$app"} -global virtio-mmio.force-legacy=false \
            -netdev user,id=net0 -device virtio-net-device,netdev=net0 </dev/null >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 120 ]; do
        grep -aqE "\[NET\] TX batch self-check: .*(PASS|FAIL)" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill "$pid" 2>/dev/null; sleep 1; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img"
    local line
    line="$(tr -d '\r' < "$log" | grep -a '\[NET\] TX batch self-check:' | sed -n 1p)"
    if [ "$want" = PASS ] \
       && printf '%s\n' "$line" | grep -qE ': 3 frames, doorbell decisions in batch 0, at flush 1: PASS$'; then
        ok; rm -f "$log"
    elif [ "$want" = FAIL ] && grep -aqF "[CANARY] net-kick-per-frame: one doorbell per frame" "$log" \
       && printf '%s\n' "$line" | grep -qE ': 3 frames, doorbell decisions in batch 3, at flush 0: FAIL$'; then
        ok; rm -f "$log"
    else
        bad; echo "      expected the TX batch self-check to $want, got: ${line:-no self-check line}"
        echo "      log kept: $log"
    fi
}
par "aarch64 network: TX doorbell batching" net_tx_batch_row "aarch64 network: TX doorbell batching" arm PASS
par "aarch64 network: TX batch canary" net_tx_batch_row "aarch64 network: TX batch canary" arm FAIL "canary=net-kick-per-frame"

# ── aarch64: flight recorder + e-stop latch (aarch64 parity task S2) ────────
#
# `install_flight_recorder` (kernel/src/boot/robot.rs) is the shared function both
# `kernel_main`s call to arm the FAT32-backed flight recorder AND replay the
# durable e-stop latch — riscv64 had this inline in its own FAT32-mount arm;
# aarch64 called none of it, so "was the e-stop latched when we last shut
# down?" silently answered "not latched" on every boot there, regardless of
# what was on disk. riscv64 has a gate row for this property (`safety: latch
# survives reboot`, driven by a real brain-link peer + kill-switch GPIO); this
# is its aarch64 twin, using `estop-latch-smoke`'s direct durable-write call
# (`domains/robot/behavior::logger::log_safety_violation_durable`) instead of that
# whole apparatus — same on-disk record, same replay code, same ISA-neutral
# `domains/robot/behavior`/`domains/robot/safety-core`, a smaller trigger.
#
# Two boots, ONE image (hermetic per boot — the SECOND boot reads what the
# FIRST wrote, so reusing the image across the pair is the point, not a bug;
# see feedback-hermetic-qemu-scenarios for why that rule is usually the
# opposite way round).
aarch64_flight_recorder_row() {
    local label="aarch64: flight recorder"
    printf "  %-26s" "${label}..."
    local log1="$CI_LOG_DIR/aarch64-flight-recorder-boot1.log"
    local log2="$CI_LOG_DIR/aarch64-flight-recorder-boot2.log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log1" "$log2"
    local fr_kernel="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel"
    local fr_img="$AZOS_OUT/target/aarch64-unknown-none-softfloat/release/kernel-flight-recorder-smoke.img"
    rm -f "$fr_kernel" "$fr_img"
    local build_out
    if ! build_out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$ROBOT_AARCH64_CONFIG" "$CARGO" build --release \
            --target aarch64-unknown-none-softfloat -p azos_kernel \
            --features qemu,use-robot,estop-latch-smoke \
            --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)" \
       || printf '%s\n' "$build_out" | grep -E "^(error|warning)" | qgrep -vqE "$A64_KNOWN_NOISE" \
       || [ ! -f "$fr_kernel" ]; then
        bad; echo "      estop-latch-smoke aarch64 kernel did NOT build:"
        printf '%s\n' "$build_out" | grep -E "^(error|warning)" | grep -vE "$A64_KNOWN_NOISE" | head -5
        return
    fi
    local a64_objcopy
    a64_objcopy="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objcopy"
    if [ ! -x "$a64_objcopy" ] || ! "$a64_objcopy" -O binary "$fr_kernel" "$fr_img" \
       || [ ! -f "$fr_img" ]; then
        bad; echo "      llvm-objcopy not found or ELF -> .img failed"
        return
    fi
    rm -f $AZOS_OUT/build/disk-aarch64.img
    make_disk $AZOS_OUT/build/disk-aarch64.img
    local img_copy="$CI_LOG_DIR/kernel-aarch64-flight-recorder.img"
    cp "$fr_img" "$img_copy"

    # Boot 1: fresh disk, writes the durable latching record.
    qemu-system-aarch64 -M "virt,gic-version=3" -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-aarch64.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 \
        >"$log1" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 60 ]; do
        grep -aq "ESTOPLATCHSMOKE\]" "$log1" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log1" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log1" 2>/dev/null; then
        bad; echo "      boot 1: the kernel took an exception:"
        grep -a "AARCH64-TRAP" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi
    if ! grep -aqF "ESTOPLATCHSMOKE] wrote durable SAFETY_ESTOP record" "$log1" 2>/dev/null; then
        bad; echo "      boot 1: never wrote the durable SAFETY_ESTOP record:"
        grep -a "ESTOPLATCHSMOKE\]\|LOG\]" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi

    # Boot 2: SAME image. Replay must read boot 1's record back.
    qemu-system-aarch64 -M "virt,gic-version=3" -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-aarch64.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 \
        >"$log2" 2>&1 &
    pid=$!; i=0
    while [ "$i" -lt 60 ]; do
        grep -aq "ESTOPLATCHSMOKE\]" "$log2" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log2" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log2" 2>/dev/null; then
        bad; echo "      boot 2: the kernel took an exception:"
        grep -a "AARCH64-TRAP" "$log2" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log2"; return
    fi
    # The actual proof: boot 2 replayed what boot 1 wrote. Exact text, same
    # line `boot_latch::apply` prints on riscv64's own gate row.
    if ! grep -aqF "SAFETY] ESTOP restored: the last session ended latched (action 2)" \
            "$log2" 2>/dev/null; then
        bad; echo "      boot 2 did NOT restore the latch boot 1 wrote:"
        grep -a "SAFETY\]\|LOG\]" "$log2" | tr -d '\r' | sed 's|^|        |'
        echo "      logs kept: $log1 $log2"; return
    fi
    ok; rm -f "$log1" "$log2" "$fr_kernel" "$fr_img" $AZOS_OUT/build/disk-aarch64.img
}
par "aarch64: flight recorder" aarch64_flight_recorder_row

# ── OTA: the boot is marked good, a signed update lands, a bad one rolls back ─
#
# Four rows per ISA (aarch64 and riscv64, the same function each), in the order
# a device meets them:
#
#   <isa>: OTA boot good          the boot is CONFIRMED, and the confirmation is
#                                 on the volume (below)
#   <isa>: OTA update, B confirmed  a signed update arrives over the network on a
#                                 healthy system, B boots on trial, is confirmed,
#                                 and a third boot still runs B
#   <isa>: OTA forged update refused  the same transfer with one bit of the
#                                 signature flipped: nothing is installed
#   <isa>: OTA bad update rolls back  an update whose slot cannot confirm
#                                 exhausts its attempts and the device boots A
#
# **Boot good.** Two properties, one row, and the second is the one that matters.
#
# `sys-wdt` was riscv64-only until the aarch64 row existed: aarch64's `kernel_main`
# created no such task, so nothing on that ISA ever called
# `ota_mark_boot_good`. `ota_boot_validate` still INCREMENTED `boot_count` on
# every boot, so every aarch64 boot printed a higher `count=N/3` than the last
# and, on a board with a second slot installed, the third boot would have
# rolled back to `last_good` — and then done it again, forever, because the
# slot it rolled back to could not mark itself good either. riscv64 had the task
# and a row that proves the mark only after a crash (`boot count: survives a
# crash`); this one proves it on a plain boot, on both ISAs, with the same code.
#
# WHY TWO BOOTS, AND WHY THE SAME DISK. A row that asserted only "[WDT] Phase
# 16 system watchdog running" and "[OTA] Boot marked good" would have passed
# the moment the task was spawned, whether or not the mark reached the
# volume — and a row asserting only the log line would have passed against a
# `BOOTMETA` write that silently failed. The property is a STATE: `boot_count`
# stops climbing. Only a second boot off the volume the first one wrote can
# see it. So both boots share ONE disk copy — that sharing IS the test — while
# the copy itself keeps this row hermetic from every other row, which matters
# because the guest writes this volume.
#
# Measured before the fix (aarch64), on this exact pair of boots: `count=1/3`
# then `count=2/3`, with no `[WDT]` line in either log.
#
# THE WAIT IS 30 SECONDS OF REAL UPTIME and is not negotiable down: the delay
# is `azos_ota::OTA_BOOT_GOOD_DELAY_S`, and shortening it under a test
# feature would prove a delay production never ships. Boot 1 reached the mark
# at 32 s wall (measured), so the bound is 90 s — three times the delay, not
# a value tuned to the one run that passed.
#
# Canary (20-10, by hand, reverted; the function is shared, the kernel code is
# too): the `ota_write_boot_meta` of `ota_mark_boot_good` removed -> boot 1
# still prints "[OTA] Boot marked good" and boot 2 reads `count=2/3`: the last
# check goes red on both ISAs ("boot_count CLIMBED", measured). The update and
# rollback rows below go red on the same edit. Bucket (a): discriminates.
boot_good_row() { # boot_good_row <riscv64|aarch64>
    local isa="$1" label="$1: OTA boot good"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log1="$CI_LOG_DIR/$isa-boot-good-1.log"
    local log2="$CI_LOG_DIR/$isa-boot-good-2.log"
    rm -f "$log1" "$log2"
    local dsrc img_copy disk_copy trap_re='!!! KERNEL PANIC !!!|AARCH64-TRAP\] unhandled'
    if [ "$isa" = riscv64 ]; then
        if ! kbuild "qemu"; then
            bad; echo "      riscv64 kernel (--features qemu) did not build"; return
        fi
        dsrc=$AZOS_OUT/build/disk.img
        img_copy="$CI_LOG_DIR/kernel-riscv64-boot-good.elf"
        cp "$KERNEL" "$img_copy"
    else
        if ! a64_kbuild "qemu"; then
            bad; echo "      aarch64 kernel (--features qemu) did not build"; return
        fi
        dsrc=$AZOS_OUT/build/disk-aarch64.img
        img_copy="$CI_LOG_DIR/kernel-aarch64-boot-good.img"
        cp "$A64_IMG" "$img_copy"
    fi
    # Fresh from the Makefile each run (`boot_count=0` in its BOOTMETA), so
    # boot 1 always starts from 0 whatever a previous gate left behind.
    rm -f "$dsrc"
    if ! make_disk "$dsrc"; then
        bad; echo "      disk image build failed: make $dsrc"; return
    fi
    # ONE disk copy, deliberately shared by both boots below — see this row's
    # header.
    disk_copy="$CI_LOG_DIR/disk-$isa-boot-good-run.img"
    cp "$dsrc" "$disk_copy"

    boot_good_boot() { # boot_good_boot <log> <marker> <max-seconds>
        par_ready
        if [ "$isa" = riscv64 ]; then
            "$QEMU" -machine virt -nographic -bios default -kernel "$img_copy" -smp 4 \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk_copy",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$1" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                -kernel "$img_copy" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk_copy",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$1" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt "$3" ]; do
            grep -aqF "$2" "$1" 2>/dev/null && break
            grep -aqE "$trap_re" "$1" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    }

    # Boot 1: fresh BOOTMETA. The task must run, and it must mark the boot.
    # `ota_mark_boot_good` writes BOOTMETA and THEN prints, so breaking on the
    # print cannot race the write.
    boot_good_boot "$log1" "[OTA] Boot marked good" 90
    if grep -aqE "$trap_re" "$log1" 2>/dev/null; then
        bad; echo "      boot 1: the kernel panicked or took an exception:"
        grep -aE "KERNEL PANIC|AARCH64-TRAP" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi
    # Half one: the task is not merely created, it ENTERED. This line is
    # `system_wdt_task`'s own first statement.
    if ! grep -aqF "[WDT] Phase 16 system watchdog running" "$log1" 2>/dev/null; then
        bad; echo "      boot 1: sys-wdt never entered — the task was not created,"
        echo "      or was created on a hart nothing drains (check the pin against"
        echo "      this row's -smp):"
        grep -a "SCHED\] Created sys-wdt\|WDT\]" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi
    if ! grep -aqF "[OTA] Boot: slot=A count=1/3" "$log1" 2>/dev/null; then
        bad; echo "      boot 1 did not start from a fresh BOOTMETA (expected count=1/3)"
        echo "      — the disk copy is stale, so boot 2 below would prove nothing:"
        grep -a "OTA] Boot:" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi
    # Half two, part one: the mark was reached at all (the hook is installed
    # AND sys-wdt iterated for 30 s, not just entered and died).
    if ! grep -aqF "[OTA] Boot marked good (slot=A)" "$log1" 2>/dev/null; then
        bad; echo "      boot 1: sys-wdt ran but never marked the boot good within 90 s."
        echo "      Either install_ota_boot_good_hook was not called (disk-gated block"
        echo "      in kernel_main), or the task stopped iterating:"
        grep -a "WDT\]\|OTA\]" "$log1" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log1"; return
    fi

    # Boot 2: the SAME volume boot 1 wrote. This is the whole row.
    boot_good_boot "$log2" "[OTA] Boot: slot=" 40
    if grep -aqE "$trap_re" "$log2" 2>/dev/null; then
        bad; echo "      boot 2: the kernel panicked or took an exception:"
        grep -aE "KERNEL PANIC|AARCH64-TRAP" "$log2" | tr -d '\r' | sed 's|^|        |'
        echo "      logs kept: $log1 $log2"; return
    fi
    # Half two, part two: `boot_count` did NOT climb. Without the mark this
    # reads count=2/3, and at 3/3 a board with a second slot rolls back.
    if ! grep -aqF "[OTA] Boot: slot=A count=1/3" "$log2" 2>/dev/null; then
        bad; echo "      boot 2: boot_count CLIMBED — the mark boot 1 printed did not"
        echo "      reach the volume, so OTA would still roll this board back:"
        echo "        boot 1: $(grep -a 'OTA] Boot: slot=' "$log1" | tr -d '\r' | sed -n '1p')"
        echo "        boot 2: $(grep -a 'OTA] Boot: slot=' "$log2" | tr -d '\r' | sed -n '1p')"
        echo "      logs kept: $log1 $log2"; return
    fi
    ok; rm -f "$log1" "$log2" "$img_copy" "$disk_copy"
}
# NOT invoked here. The aarch64 call needs `a64_kbuild`, defined further down;
# a function must be defined before the line that calls it RUNS, and every
# `a64_kbuild` caller is itself invoked below its definition. Called after the
# guard rows instead; see there. (Gate 169 went red exactly here:
# `a64_kbuild: command not found`.)

# ── OTA end to end: update, forged update, bad update ────────────────────────
#
# What is on the network path today, and what is not. `ota recv` (the listener
# `ota_auto_recv_port` starts; `tools/ota_send.py` is its sender) takes ONE
# kernel: a 24-byte ROTA header and the raw bytes, installed into the inactive
# slot's `KERN_<slot>.BIN`, authenticated by the `KERN_<slot>.SIG` sidecar the
# volume holds, and recorded in BOOTMETA (`active_slot` moves, `boot_count`
# 0). It is the update these rows send. The whole-system bundle (AZUM: kernel,
# topology, configuration, images, one signed manifest) has its own rows below
# (`ota_bundle_row`): the installer fetches it over the network (`pkg
# fetch-update`), stages it and `ota switch` makes it the one that boots. Four
# things stood in the way of those rows on 20-10 and are fixed: `pkg` could not
# open a bundle past ~30 KB (its frame budget now holds the largest file the
# installer takes), `pkgd` took the `.` and `..` of a set directory's listing
# for entries and failed to clear it, the VFS's FAT32 created files in the root
# directory only (`/fat/PKG/SYS_B/KERN.BIN`, the installer's journal, the
# shell's `echo > /fat/D1/A.TXT`), and nothing carried a bundle to the
# installer from the network.
#
# The three scenarios share one shape: a QEMU boots the volume, the host sends
# the update through SLIRP (`hostfwd` on a host port the row picks for itself,
# so no two rows or runs share one), and later boots of the SAME volume read
# what the earlier ones wrote. QEMU boots the `-kernel` it is given whatever
# BOOTMETA says: the loader that picks the slot (U-Boot's `boot.cmd` on a
# board) does not exist here, so the row IS the loader and boots, for a boot of
# slot B, the kernel B holds. `KERN_B.BIN` carries a stand-in payload (the
# kernel ELF is 77 MB, over the 8 MiB the listener takes), the way the
# secure-boot fixtures' `KERN_A.BIN` is a stand-in.
OTAE2E_KEY="$REPO_ROOT/tools/keys/test_pub.bin"
OTAE2E_PRIV="$REPO_ROOT/tools/keys/test_priv.bin"
OTAE2E_PID=""
OTAE2E_PORT=""
otae2e_free_port() { python3 -c 'import socket; s = socket.socket(); s.bind(("127.0.0.1", 0)); print(s.getsockname()[1])'; }

# otae2e_qemu <riscv64|aarch64> <kernel> <disk> <log> [net]: one boot of the
# volume in the background (OTAE2E_PID). `net` gives it a NIC with the guest's
# 8080 forwarded to a free host port (OTAE2E_PORT); a port taken between the
# probe and QEMU's bind ends QEMU at once, and the boot is started again on
# another. -no-reboot: a panic ends QEMU, which is how a crashed boot reads.
otae2e_qemu() {
    local isa="$1" kernel="$2" disk="$3" log="$4" net="${5:-}" try netargs
    for try in 1 2 3; do
        netargs=()
        if [ -n "$net" ]; then
            OTAE2E_PORT="$(otae2e_free_port)"
            netargs=(-netdev "user,id=net0,hostfwd=tcp:127.0.0.1:${OTAE2E_PORT}-:8080" -device virtio-net-device,netdev=net0)
        fi
        if [ "$isa" = riscv64 ]; then
            "$QEMU" -machine virt -nographic -bios default -kernel "$kernel" -no-reboot -smp 4 \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 -device virtio-blk-device,drive=hd0 \
                ${netargs[@]+"${netargs[@]}"} </dev/null >"$log" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic -kernel "$kernel" -no-reboot \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 -device virtio-blk-device,drive=hd0 \
                ${netargs[@]+"${netargs[@]}"} </dev/null >"$log" 2>&1 &
        fi
        OTAE2E_PID=$!
        sleep 1
        kill -0 "$OTAE2E_PID" 2>/dev/null && return 0
        wait "$OTAE2E_PID" 2>/dev/null
        # Gone already: for want of the port, start again; for any other
        # reason (a guest that died in its first second) the boot did start,
        # and the row's own checks say what its log holds.
        grep -aq "host forwarding" "$log" 2>/dev/null || return 0
    done
    return 1
}
# otae2e_wait <log> <ERE> <seconds>: 0 once the ERE is in the log; 1 when it is
# not and QEMU is gone or the time is out.
otae2e_wait() {
    local i=0 max=$(( $3 * 2 ))
    while [ "$i" -lt "$max" ]; do
        grep -aqE "$2" "$1" 2>/dev/null && return 0
        kill -0 "$OTAE2E_PID" 2>/dev/null || { grep -aqE "$2" "$1" 2>/dev/null; return; }
        i=$((i + 1)); sleep 0.5
    done
    return 1
}
# otae2e_send <log> <ERE> <payload> <version>: send the payload to the guest's
# listener (OTAE2E_PORT) and wait for the guest to say <ERE> in <log>. A
# transfer the guest does not finish in 90 s (measured under a loaded host, 17 on
# 10 cores: the receive window stuck at 222 KB of 256) is dropped and sent
# again, three times. Kept: the cause is not TCP (`tcp_rx_stall` in
# tests/host/net-tests: the window reopens on the first read) but the OTA task
# stuck in the block layer under a host stall; see `net_rx_bulk_row`. The sender's own output is OTAE2E_SENT.
otae2e_send() {
    local log="$1" ere="$2" payload="$3" ver="$4" try spid
    OTAE2E_SENT=""
    for try in 1 2 3; do
        python3 tools/ota_send.py "$payload" 127.0.0.1 --port "$OTAE2E_PORT" --version "$ver" >"$log.sender" 2>&1 &
        spid=$!
        otae2e_wait "$log" "$ere" 90
        local rc=$?
        kill "$spid" 2>/dev/null; wait "$spid" 2>/dev/null
        OTAE2E_SENT="$(cat "$log.sender" 2>/dev/null)"
        [ "$rc" -eq 0 ] && return 0
    done
    return 1
}
# The marker the row waited for is printed AFTER the write it speaks of; the
# second is for the lines printed right behind it.
otae2e_stop() { sleep 1; kill -9 "$OTAE2E_PID" 2>/dev/null; wait "$OTAE2E_PID" 2>/dev/null; OTAE2E_PID=""; }
# otae2e_field <disk> <key>: a field of the plain BOOTMETA the volume holds
# (the mirror of the dual record, read from the host: the guest is stopped).
otae2e_field() { mtype -i "$1" ::BOOTMETA 2>/dev/null | tr -d '\r' | sed -n "s/^$2=//p" | sed -n 1p; }
# otae2e_listen <disk>: the OTA listener on, no brain link (host port 9000
# belongs to the network rows), CONFIG.SIG signed again for this disk.
# `cfg_get` answers the FIRST line with a key, so the listener's key goes first.
otae2e_listen() {
    local disk="$1" ini="$1.cfg.ini" rc=0
    mcopy -n -i "$disk" ::CONFIG.INI "$ini.in" 2>/dev/null \
      && { printf 'ota_auto_recv_port=8080\n'; sed -e 's/^behavior_server_port=.*/behavior_server_port=0/' "$ini.in"; } >"$ini" \
      && grep -q '^behavior_server_port=0' "$ini" \
      && mcopy -o -i "$disk" "$ini" ::CONFIG.INI 2>/dev/null \
      && python3 tools/gen_config_sig.py "$ini" --config-v2 --counter 1 --image "$disk" --out "$ini.sig" >/dev/null 2>&1 \
      && mcopy -o -i "$disk" "$ini.sig" ::CONFIG.SIG 2>/dev/null || rc=1
    rm -f "$ini" "$ini.in" "$ini.sig"
    return $rc
}
# otae2e_trap <log>...: a panic or an exception in a log that is not a crash
# the row asked for.
otae2e_trap() { grep -aqE '!!! KERNEL PANIC !!!|AARCH64-TRAP\] unhandled|\[FATAL\]' "$@" 2>/dev/null; }

# ── TCP receive: a bulk transfer into a reader that is slower than the link ──
#
# `<isa>: TCP receive 1 MiB, slow reader`. The host sends 1 MiB (eight times the
# 128 KiB receive ring) through SLIRP into the OTA listener, the way
# `tools/ota_send.py` sends an update, and the transfer must FINISH: the CRC is
# right, the 1 MiB is on the volume byte for byte, and nothing is resent (the
# `otae2e_send` retry is not used here).
#
# The reader is the OTA task writing 4 KiB at a time through the FAT32 volume to
# a virtio-blk disk: about 290 KB/s on a quiet host (3.6 s for the 1 MiB,
# measured by hand, riscv64), against a link that moves it in milliseconds. So
# the ring is full and the advertised window zero over and over; the window
# reopening each time the reader drains is what the row waits on. The unit of
# that rule is `tests/host/net-tests` (tcp_rx_stall: slow, paused and lost-update
# readers against a BSD-style sender).
#
# What this row does NOT cover, and why it exists anyway: a transfer into which
# the HOST inserts a stall (`kill -STOP` of the QEMU for 1-2 s, a few times
# during the 1 MiB; 20-10, riscv64) fails in about one run in three, and not in
# TCP. Two block-layer outcomes, read over the QEMU gdbstub:
#   * the virtio-blk request in flight when the guest's clock jumped has used up
#     its 500 ms budget (`BLK_TIMEOUT_US`) and the driver latches itself dead
#     ("[VIRTIO-BLK] Error: request timeout - device reset, block I/O disabled");
#     the install then fails;
#   * rarer (2 of ~20): the OTA task sits blocked for good with the ring full
#     and SLIRP sending 1-byte probes at a zero window. It is parked in
#     `ReqQueue::sleep`'s non-reaper arm (`crates/drivers/block/src/queue.rs`,
#     `self.done.wait_if`, called from a FAT directory-scan sector read under
#     `vfs_write`), state Blocked/WaitQueue, no wake stamp, while `GLOBAL.done`
#     holds no waiter (count 0: the pop happened), `reaper` is clear, no slot is
#     in flight, and `done_epoch` has moved 300 signals past the epoch the task
#     went to sleep on. A lost wake-up of a WaitQueue waiter, in
#     `wq_wake_by_tid` / `wake_transition` (`crates/core/sched`), with no
#     timeout behind it. The system is otherwise alive (NTP syncs, the ring-3
#     GPIO driver runs), which is the "zero window and AQ3 failing together" of
#     the 20-10 ota-e2e run.
# This row is the quiet-host baseline those stalls are measured against.
net_rx_bulk_row() { # net_rx_bulk_row <riscv64|aarch64>
    local isa="$1" label="$1: TCP receive 1 MiB, slow reader"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local work="$CI_LOG_DIR/netrx-$isa" kimg disk payload got spid t0
    rm -rf "$work"; mkdir -p "$work"
    kimg="$work/kernel"; disk="$work/disk.img"; payload="$work/payload.bin"; got="$work/KERN_B.BIN"
    if [ "$isa" = riscv64 ]; then
        if ! kbuild "qemu"; then
            bad; echo "      riscv64 kernel (--features qemu) did not build"; return
        fi
        cp "$KERNEL" "$kimg"
        rm -f $AZOS_OUT/build/disk.img
        make_disk $AZOS_OUT/build/disk.img
        cp $AZOS_OUT/build/disk.img "$disk"
    else
        if ! a64_kbuild "qemu"; then
            bad; echo "      aarch64 kernel (--features qemu) did not build"; return
        fi
        cp "$A64_IMG" "$kimg"
        rm -f $AZOS_OUT/build/disk-aarch64.img
        make_disk $AZOS_OUT/build/disk-aarch64.img
        cp $AZOS_OUT/build/disk-aarch64.img "$disk"
    fi
    if ! python3 -c "import random; random.seed(0x52583150); open('$payload', 'wb').write(random.randbytes(1 << 20))" \
       || ! otae2e_listen "$disk"; then
        bad; echo "      could not prepare the payload and the volume $disk"; return
    fi
    par_ready

    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$work/boot.log" net; then
        bad; echo "      QEMU did not start (log: $work/boot.log)"; return
    fi
    if ! otae2e_wait "$work/boot.log" '\[OTA\] Listening on port 8080' 150; then
        otae2e_stop; bad; echo "      the OTA listener never came up:"
        grep -a "OTA\]\|NET\]\|PANIC" "$work/boot.log" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $work/boot.log"; return
    fi
    python3 tools/ota_send.py "$payload" 127.0.0.1 --port "$OTAE2E_PORT" --version 2 >"$work/sender.log" 2>&1 &
    spid=$!
    t0=$SECONDS
    # Once, no resend: 600 s is far past a quiet host's seconds, and a loaded
    # one's tens of seconds (24 s measured at a load of 90 on 10 cores).
    otae2e_wait "$work/boot.log" '\[OTA\] (CRC OK|CRC MISMATCH|INCOMPLETE|Connection lost|Payload idle)' 600
    kill "$spid" 2>/dev/null; wait "$spid" 2>/dev/null
    otae2e_stop
    if ! grep -aqF "[OTA] CRC OK — 1048576 bytes written to slot B" "$work/boot.log" \
       || otae2e_trap "$work/boot.log" \
       || ! mcopy -n -i "$disk" ::KERN_B.BIN "$got" 2>/dev/null \
       || ! cmp -s "$payload" "$got"; then
        bad; echo "      the 1 MiB transfer did not finish intact ($((SECONDS - t0)) s after the send began):"
        sed 's/^/        sender: /' "$work/sender.log"
        grep -a "\[OTA\]" "$work/boot.log" | tr -d '\r' | grep -av '#####' | sed -n '1,14p' | sed 's/^/        /'
        grep -a "VIRTIO-BLK\] Error\|BLK\] device is dead" "$work/boot.log" | tr -d '\r' | sed -n '1,3p' | sed 's/^/        /'
        echo "      log kept: $work/boot.log"; return
    fi
    ok; rm -rf "$work"
}

# ── A signed update on a healthy system, and its forgery ────────────────────
#
# The kernel is built `secure-boot-enforced` against the TEST key (pinned the
# way the secure-boot rows pin it: an absolute `PROD_PUBKEY_PATH`, or the build
# falls back to the all-zero key and verifies nothing), on the volume with a
# signed slot A (`disk-signed`). So every slot that boots here was verified, and
# the transfer is judged by the same key.
#
# good (`<isa>: OTA update, B confirmed`), three boots of one volume:
#   1. A boots, listens, and marks itself good (30 s of real uptime,
#      OTA_BOOT_GOOD_DELAY_S, not shortened). The host sends a 64 KiB payload,
#      version 2, whose `KERN_B.SIG` sidecar is on the volume. The kernel says
#      the signature is VERIFIED for fw=2, writes slot B, and moves BOOTMETA:
#      `active_slot=b`, `boot_count=0`.
#   2. B boots on trial: `count=1/3 last_good=A`, its CRC and signature are
#      verified at the boot gate, and after 30 s it is confirmed (`slot=B`).
#   3. A third boot is B again, `count=1/3 last_good=B`: the confirmation
#      reached the volume, `boot_count` did not climb, and the signature still
#      verifies. `last_good=b` and `boot_count=0` on the host's readback.
# forged (`<isa>: OTA forged update refused`): boot 1 only, with one bit of the
# sidecar's scalar flipped (tools/corrupt_sig.py): the kernel REFUSES the
# staged image, `KERN_B.BIN` is not on the volume and BOOTMETA still says A.
# It is the control of the first: a verdict observed only accepting is
# indistinguishable from a verifier that is not there.
#
# Canaries (20-10, by hand, reverted), all bucket (a): good with the sidecar
# corrupted (forged's input) -> red at "the signed update was not installed"
# (BOOTMETA active_slot=a); good with the `ota_write_boot_meta` of
# `ota_mark_boot_good` removed -> red at the last check (boot 3 reads
# `count=2/3 last_good=A`), both ISAs. forged with the sidecar left VALID (an
# installer that accepts the transfer) -> red, "the forged update was not
# refused cleanly" with BOOTMETA `active_slot=b` (riscv64).
ota_update_row() { # ota_update_row <riscv64|aarch64> <good|forged>
    local isa="$1" mode="$2" label
    if [ "$mode" = good ]; then label="$isa: OTA update, B confirmed"; else label="$isa: OTA forged update refused"; fi
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local work="$CI_LOG_DIR/otae2e-$isa-$mode" kimg disk payload sidecar sent
    rm -rf "$work"; mkdir -p "$work"
    kimg="$work/kernel"; disk="$work/disk.img"; payload="$work/kern_b.bin"; sidecar="$work/KERN_B.SIG"
    if [ "$isa" = riscv64 ]; then
        if ! PROD_PUBKEY_PATH="$OTAE2E_KEY" kbuild "qemu,secure-boot-enforced"; then
            bad; echo "      riscv64 kernel (--features qemu,secure-boot-enforced) did not build"; return
        fi
        cp "$KERNEL" "$kimg"
        rm -f $AZOS_OUT/build/disk.img $AZOS_OUT/build/disk-signed.img
        make_disk $AZOS_OUT/build/disk.img $AZOS_OUT/build/disk-signed.img
        cp $AZOS_OUT/build/disk-signed.img "$disk"
    else
        if ! PROD_PUBKEY_PATH="$OTAE2E_KEY" a64_kbuild "qemu,secure-boot-enforced"; then
            bad; echo "      aarch64 kernel (--features qemu,secure-boot-enforced) did not build"; return
        fi
        cp "$A64_IMG" "$kimg"
        rm -f $AZOS_OUT/build/disk-aarch64.img $AZOS_OUT/build/disk-aarch64-signed.img
        make_disk $AZOS_OUT/build/disk-aarch64.img $AZOS_OUT/build/disk-aarch64-signed.img
        cp $AZOS_OUT/build/disk-aarch64-signed.img "$disk"
    fi
    # The payload is not KERN_A.BIN's (other seed), and its version, 2, is above
    # slot A's 1: an update, not a replay.
    if ! python3 -c "import random; random.seed(0x4F544132); open('$payload', 'wb').write(random.randbytes(65536))" \
       || ! python3 tools/sign_ota.py "$payload" --fw-version 2 --priv "$OTAE2E_PRIV" --out "$sidecar" >/dev/null 2>&1; then
        bad; echo "      could not make and sign the update payload"; return
    fi
    if [ "$mode" = forged ] && ! python3 tools/corrupt_sig.py "$sidecar" "$sidecar.bad" >/dev/null 2>&1; then
        bad; echo "      could not corrupt the sidecar"; return
    fi
    if ! otae2e_listen "$disk" \
       || ! mcopy -o -i "$disk" "$( [ "$mode" = forged ] && echo "$sidecar.bad" || echo "$sidecar" )" ::KERN_B.SIG 2>/dev/null; then
        bad; echo "      could not prepare the volume $disk (listener, sidecar)"; return
    fi
    par_ready

    # Boot 1: A, healthy, receives the update.
    local log1="$work/boot1.log" log2="$work/boot2.log" log3="$work/boot3.log"
    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$log1" net; then
        bad; echo "      QEMU did not start (log: $log1)"; return
    fi
    if ! otae2e_wait "$log1" '\[OTA\] Listening on port 8080' 150; then
        otae2e_stop; bad; echo "      boot 1: the OTA listener never came up:"
        grep -a "OTA\]\|NET\]\|SECURE-BOOT\]\|PANIC" "$log1" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $log1"; return
    fi
    if [ "$mode" = good ] && ! otae2e_wait "$log1" '\[OTA\] Boot marked good \(slot=A\)' 150; then
        otae2e_stop; bad; echo "      boot 1: slot A never confirmed itself, so the system is not healthy:"
        grep -a "OTA\]\|WDT\]" "$log1" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $log1"; return
    fi
    if [ "$mode" = forged ]; then
        otae2e_send "$log1" '\[OTA\] REFUSED: staged image for slot B' "$payload" 2
        sent="$OTAE2E_SENT"
        otae2e_stop
        if ! grep -aqE '\[OTA\] REFUSED: staged image for slot B is .*signature' "$log1" \
           || grep -aqE '\[OTA\] (CRC OK|Active slot|Signature VERIFIED)' "$log1" \
           || [ "$(otae2e_field "$disk" active_slot)" != a ] \
           || mdir -i "$disk" ::KERN_B.BIN >/dev/null 2>&1; then
            bad; echo "      the forged update was not refused cleanly (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot)):"
            printf '%s\n' "$sent" | sed 's/^/        sender: /'
            grep -a "\[OTA\]" "$log1" | tr -d '\r' | sed -n '1,14p' | sed 's/^/        /'
            echo "      log kept: $log1 (volume: $disk)"; return
        fi
        ok; rm -rf "$work"; return
    fi
    otae2e_send "$log1" '\[OTA\] Active slot .* B \(fw=2\)' "$payload" 2
    sent="$OTAE2E_SENT"
    otae2e_stop
    if ! grep -aqF "[OTA] Signature VERIFIED for staged slot B image (fw=2)" "$log1" \
       || ! grep -aqF "[OTA] CRC OK — 65536 bytes written to slot B" "$log1" \
       || ! grep -aqE '\[OTA\] Active slot .* B \(fw=2\)' "$log1" \
       || [ "$(otae2e_field "$disk" active_slot)" != b ] || [ "$(otae2e_field "$disk" boot_count)" != 0 ]; then
        bad; echo "      the signed update was not installed (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot) boot_count=$(otae2e_field "$disk" boot_count)):"
        printf '%s\n' "$sent" | sed 's/^/        sender: /'
        grep -a "\[OTA\]" "$log1" | tr -d '\r' | sed -n '1,14p' | sed 's/^/        /'
        echo "      log kept: $log1 (volume: $disk)"; return
    fi

    # Boot 2: B on trial; it must verify, and after 30 s be confirmed.
    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$log2"; then
        bad; echo "      QEMU did not start (log: $log2)"; return
    fi
    otae2e_wait "$log2" '\[OTA\] Boot marked good|!!! KERNEL PANIC !!!|\[FATAL\]' 150
    otae2e_stop
    if otae2e_trap "$log2" \
       || ! grep -aqF "[OTA] Boot: slot=B count=1/3 last_good=A" "$log2" \
       || ! grep -aqF "[OTA] Slot B CRC OK (fw=2, size=65536)" "$log2" \
       || ! grep -aqE '\[SECURE-BOOT\] Slot B signature: verified' "$log2" \
       || ! grep -aqF "[OTA] Boot marked good (slot=B)" "$log2"; then
        bad; echo "      slot B did not boot on trial and confirm itself:"
        grep -a "OTA\] Boot\|OTA\] Slot\|SECURE-BOOT\] Slot\|PANIC\|FATAL" "$log2" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      logs kept: $log1 $log2"; return
    fi

    # Boot 3: the confirmation is on the volume, and B is what boots.
    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$log3"; then
        bad; echo "      QEMU did not start (log: $log3)"; return
    fi
    otae2e_wait "$log3" '\[SECURE-BOOT\] Slot B signature|!!! KERNEL PANIC !!!|\[FATAL\]' 150
    otae2e_stop
    if otae2e_trap "$log3" \
       || ! grep -aqF "[OTA] Boot: slot=B count=1/3 last_good=B" "$log3" \
       || ! grep -aqF "[OTA] Slot B CRC OK (fw=2, size=65536)" "$log3" \
       || ! grep -aqE '\[SECURE-BOOT\] Slot B signature: verified' "$log3" \
       || [ "$(otae2e_field "$disk" last_good)" != b ]; then
        bad; echo "      the third boot is not a confirmed B (last_good=$(otae2e_field "$disk" last_good)):"
        echo "        boot 2: $(grep -a 'OTA\] Boot: slot=' "$log2" | tr -d '\r' | sed -n '1p')"
        echo "        boot 3: $(grep -a 'OTA\] Boot: slot=' "$log3" | tr -d '\r' | sed -n '1p')"
        echo "      logs kept: $log1 $log2 $log3"; return
    fi
    ok; rm -rf "$work"
}

# ── An update whose slot cannot confirm: the attempts run out, A boots again ──
#
# `<isa>: OTA bad update rolls back`. The same transfer, unsigned (the dev
# path: "INSTALLING AN UNAUTHENTICATED IMAGE", the way the safe-mode row
# installs), and slot B's kernel is one that crashes before it can confirm:
# `safe-mode-smoke` panics right after `ota_boot_validate` wrote the boot's
# unconfirmed mark, in every boot that is not safe mode. The row is the loader,
# so slot A boots the plain kernel and slot B the smoke one; that is the whole
# difference between the slots, and what BOOTMETA says picks which.
#
#   1. A (plain kernel) takes the update: `active_slot=b`.
#   2-4. B (smoke kernel) boots: `count=1/3`, `2/3`, `3/3`, each ends in the
#      deliberate panic, none is confirmed.
#   5. B's fourth boot finds `boot_count` above the 3 attempts: "Boot loop
#      detected ... rolling back to slot A", `count=1/3 last_good=A` (the
#      count restarts for A) and `3 unconfirmed boot(s) before this one`. The
#      kernel that runs this boot is still B's, and it dies of the same panic
#      (a rollback does not reboot into A; it records A for the next boot).
#   6. The loader reads `active_slot=a`: A (plain kernel) boots, `count=2/3`
#      (the rolled-back boot's own mark is still unconfirmed), is confirmed after
#      30 s, and the volume ends `active_slot=a last_good=a boot_count=0`.
# The record of why is on the volume, not only in the logs: BOOTMETA still holds
# slot B's image (fw=2) beside `last_good=a`, and `/fat/CRASH.LOG` holds the
# panics of boots 2-5.
#
# Canaries (20-10, by hand, reverted), bucket (a): boots 2-5 given the PLAIN
# kernel (B as good as A) -> boot 2 confirms itself and the row is red at
# "slot B boot 1 did not count itself 1 and crash before confirming"; the
# `ota_write_boot_meta` of `ota_mark_boot_good` removed -> red at the last
# check (`boot_count=2`, A never zeroes it), both ISAs.
ota_rollback_row() { # ota_rollback_row <riscv64|aarch64>
    local isa="$1" label="$1: OTA bad update rolls back"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local work="$CI_LOG_DIR/otae2e-$isa-rollback" kok kbad disk payload n log sent
    rm -rf "$work"; mkdir -p "$work"
    kok="$work/kernel-a"; kbad="$work/kernel-b"; disk="$work/disk.img"; payload="$work/kern_b.bin"
    if [ "$isa" = riscv64 ]; then
        if ! kbuild "qemu"; then bad; echo "      riscv64 kernel (--features qemu) did not build"; return; fi
        cp "$KERNEL" "$kok"
        if ! kbuild "qemu,safe-mode-smoke"; then bad; echo "      riscv64 kernel (--features qemu,safe-mode-smoke) did not build"; return; fi
        cp "$KERNEL" "$kbad"
        rm -f $AZOS_OUT/build/disk.img
        make_disk $AZOS_OUT/build/disk.img
        cp $AZOS_OUT/build/disk.img "$disk"
    else
        if ! a64_kbuild "qemu"; then bad; echo "      aarch64 kernel (--features qemu) did not build"; return; fi
        cp "$A64_IMG" "$kok"
        if ! a64_kbuild "qemu,safe-mode-smoke"; then bad; echo "      aarch64 kernel (--features qemu,safe-mode-smoke) did not build"; return; fi
        cp "$A64_IMG" "$kbad"
        rm -f $AZOS_OUT/build/disk-aarch64.img
        make_disk $AZOS_OUT/build/disk-aarch64.img
        cp $AZOS_OUT/build/disk-aarch64.img "$disk"
    fi
    if ! python3 -c "import random; random.seed(0x4F544133); open('$payload', 'wb').write(random.randbytes(65536))" \
       || ! otae2e_listen "$disk"; then
        bad; echo "      could not prepare the payload and the volume $disk"; return
    fi
    par_ready

    # 1. A takes the update.
    if ! otae2e_qemu "$isa" "$kok" "$disk" "$work/boot1.log" net; then
        bad; echo "      QEMU did not start (log: $work/boot1.log)"; return
    fi
    if ! otae2e_wait "$work/boot1.log" '\[OTA\] Listening on port 8080' 150; then
        otae2e_stop; bad; echo "      boot 1: the OTA listener never came up:"
        grep -a "OTA\]\|NET\]\|PANIC" "$work/boot1.log" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $work/boot1.log"; return
    fi
    otae2e_send "$work/boot1.log" '\[OTA\] Active slot .* B \(fw=2\)' "$payload" 2
    sent="$OTAE2E_SENT"
    otae2e_stop
    if [ "$(otae2e_field "$disk" active_slot)" != b ]; then
        bad; echo "      the update was not installed (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot)):"
        printf '%s\n' "$sent" | sed 's/^/        sender: /'
        grep -a "\[OTA\]" "$work/boot1.log" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $work/boot1.log (volume: $disk)"; return
    fi

    # 2-4. B boots three times and crashes each time before it can confirm.
    for n in 1 2 3; do
        log="$work/boot-b$n.log"
        if ! otae2e_qemu "$isa" "$kbad" "$disk" "$log"; then bad; echo "      QEMU did not start (log: $log)"; return; fi
        otae2e_wait "$log" 'safe-mode-smoke: deliberate crash|OTA\] Boot marked good' 120
        otae2e_stop
        if ! grep -aqF "[OTA] Boot: slot=B count=$n/3 last_good=A" "$log" \
           || ! grep -aqF "safe-mode-smoke: deliberate crash before the boot is confirmed" "$log" \
           || grep -aqF "[OTA] Boot marked good" "$log"; then
            bad; echo "      slot B boot $n did not count itself $n and crash before confirming:"
            grep -a "OTA\] Boot\|safe-mode-smoke\|PANIC" "$log" | tr -d '\r' | sed -n '1,10p' | sed 's/^/        /'
            echo "      log kept: $log"; return
        fi
    done

    # 5. The fourth boot of B: the attempts are out, BOOTMETA goes back to A.
    log="$work/boot-b4.log"
    if ! otae2e_qemu "$isa" "$kbad" "$disk" "$log"; then bad; echo "      QEMU did not start (log: $log)"; return; fi
    otae2e_wait "$log" 'safe-mode-smoke: deliberate crash|OTA\] Boot marked good' 120
    otae2e_stop
    if ! grep -aqE '\[OTA\] Boot loop detected \(max=3\).*rolling back to slot A' "$log" \
       || ! grep -aqF "[OTA] Boot: slot=A count=1/3 last_good=A" "$log" \
       || ! grep -aqF "[BOOTCNT] 3 unconfirmed boot(s) before this one" "$log" \
       || [ "$(otae2e_field "$disk" active_slot)" != a ]; then
        bad; echo "      B's fourth boot did not roll the volume back to A (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot)):"
        grep -a "OTA\] Boot\|BOOTCNT\]\|safe-mode-smoke\|PANIC" "$log" | tr -d '\r' | sed -n '1,10p' | sed 's/^/        /'
        echo "      log kept: $log (volume: $disk)"; return
    fi

    # 6. The loader reads `a`: A boots, counts 2 (the rolled-back boot's mark
    # is still unconfirmed), and confirms itself.
    log="$work/boot-a.log"
    if ! otae2e_qemu "$isa" "$kok" "$disk" "$log"; then bad; echo "      QEMU did not start (log: $log)"; return; fi
    otae2e_wait "$log" '\[OTA\] Boot marked good|!!! KERNEL PANIC !!!|\[FATAL\]' 150
    otae2e_stop
    if otae2e_trap "$log" \
       || ! grep -aqF "[OTA] Boot: slot=A count=2/3 last_good=A" "$log" \
       || ! grep -aqF "[OTA] Boot marked good (slot=A)" "$log" \
       || [ "$(otae2e_field "$disk" active_slot)" != a ] || [ "$(otae2e_field "$disk" last_good)" != a ] \
       || [ "$(otae2e_field "$disk" boot_count)" != 0 ] || [ "$(otae2e_field "$disk" fw_version_b)" != 2 ] \
       || [ "$(mtype -i "$disk" ::CRASH.LOG 2>/dev/null | grep -ac 'safe-mode-smoke: deliberate crash')" -lt 4 ]; then
        bad; echo "      A did not boot again and confirm, with the record of B's failure on the volume:"
        echo "        BOOTMETA: active_slot=$(otae2e_field "$disk" active_slot) last_good=$(otae2e_field "$disk" last_good) boot_count=$(otae2e_field "$disk" boot_count) fw_version_b=$(otae2e_field "$disk" fw_version_b)"
        echo "        CRASH.LOG entries: $(mtype -i "$disk" ::CRASH.LOG 2>/dev/null | grep -ac 'safe-mode-smoke: deliberate crash')"
        grep -a "OTA\] Boot\|PANIC\|FATAL" "$log" | tr -d '\r' | sed -n '1,8p' | sed 's/^/        /'
        echo "      log kept: $log (volume: $disk)"; return
    fi
    ok; rm -rf "$work"
}

# ── A whole-system update bundle over the network, to a booted B ─────────────
#
# Two rows per ISA (riscv64 and aarch64, the same function each):
#
#   <isa>: OTA bundle over the network, B confirmed  a signed AZUM bundle (kernel,
#                          topology, configuration) reaches the installer over
#                          TFTP, is staged, `ota switch` makes it the boot, and B
#                          boots on trial and confirms itself after the real 30 s
#   <isa>: OTA tampered bundle refused  the same bundle with one byte of the
#                          kernel part changed: staging refuses it, nothing is
#                          switched, and A stays the boot
#
# What the rows put together: `pkg fetch-update` (the installer gets the bundle
# from the source /fat/PKG/SOURCE.CFG names: QEMU's `-netdev user,tftp=DIR`
# gateway, the development source of Kconfig PKG_FETCH_TFTP), the installer's
# journal and the slot's set directory written in subdirectories of the FAT
# volume, `ota switch` (the kernel verifies the staged set again and moves the
# boot record), and the boot of the new slot with the set in force. The kernel
# is built `secure-boot-enforced` against the TEST key (pinned as the other OTA
# rows pin it) on the shell volume with a signed slot A (`disk-sh-signed`), so
# the bundle's manifest is judged by the key the installer and the switch hold.
# The row is the loader (as `ota_update_row`): a boot of slot B boots the kernel
# B holds, here the same image, and the bundle's kernel part is a stand-in
# payload with the sidecar signature the secure-boot gate reads.
#
# The set is the device's own: the topology the volume's device binding allows
# (`make topo-volume`), its configuration as the volume holds it. Boot 2 prints
# `System set of slot B ... in force`.
#
# good, three boots of one volume:
#   1. A boots; in its shell `pkg fetch-update` answers `staged: update ...,
#      epoch 2, into slot B` and `ota switch` `switched to the staged system
#      set`; the volume's BOOTMETA says `active_slot=b`, `boot_count=0`, the
#      set's marker and the installer's journal are on it.
#   2. B boots on trial: `count=1/3 last_good=A`, the set in force, the signature
#      of B verified, and after 30 s `Boot marked good (slot=B)`.
#   3. A third boot is B again, `last_good=B`.
# tampered: boot 1 only. `pkg fetch-update` answers `refused: update part hash`,
# the slot holds no marker, `ota switch` switches nothing, BOOTMETA stays on A.
#
# The tampered row is the control of the good one: a verdict observed only
# accepting is indistinguishable from a stager that is not there. The canaries
# of the stager itself (signature and part hash off) are the host rows
# `network: TFTP forged bundle canary` / `network: TFTP tampered bundle canary`,
# which run the same pair (tests/host/pkg-tests `tftp_source`) without a boot.
OTABUN_LOG=""
# otabun_type <text>: the line typed into the guest's shell on fd 9, a byte at a
# time (the aarch64 PL011 loses a burst), then Enter.
otabun_type() { local i; for ((i = 0; i < ${#1}; i++)); do printf '%s' "${1:i:1}" >&9; sleep 0.05; done; printf '\r' >&9; }
# otabun_cmd <line> <ERE> <seconds>: type the line, then wait for one more match
# of ERE in the log than it held before.
otabun_cmd() {
    local before i=0 max=$(( $3 * 2 ))
    before="$(grep -acE "$2" "$OTABUN_LOG" 2>/dev/null)"
    otabun_type "$1" 2>/dev/null
    while [ "$i" -lt "$max" ]; do
        [ "$(grep -acE "$2" "$OTABUN_LOG" 2>/dev/null)" -gt "${before:-0}" ] && return 0
        kill -0 "$OTAE2E_PID" 2>/dev/null || return 1
        i=$((i + 1)); sleep 0.5
    done
    return 1
}
# otabun_qemu <isa> <kernel> <disk> <log> <stdin> <tftp dir>: one boot in the
# background (OTAE2E_PID) with a NIC and QEMU's TFTP server serving <tftp dir>
# at 10.0.2.2. <stdin> is a fifo the row holds open on fd 9. virtio-rng seeds
# the entropy pool: pkgd (and sshd) read it at start and refuse to run unseeded.
otabun_qemu() {
    local isa="$1" kernel="$2" disk="$3" log="$4" in="$5" tftp="$6"
    if [ "$isa" = riscv64 ]; then
        "$QEMU" -machine virt -nographic -bios default -kernel "$kernel" -no-reboot -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$disk",if=none,format=raw,id=hd0 -device virtio-blk-device,drive=hd0 \
            -netdev "user,id=net0,tftp=$tftp" -device virtio-net-device,netdev=net0 -device virtio-rng-device <"$in" >"$log" 2>&1 &
    else
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic -kernel "$kernel" -no-reboot \
            -global virtio-mmio.force-legacy=false \
            -drive file="$disk",if=none,format=raw,id=hd0 -device virtio-blk-device,drive=hd0 \
            -netdev "user,id=net0,tftp=$tftp" -device virtio-net-device,netdev=net0 -device virtio-rng-device <"$in" >"$log" 2>&1 &
    fi
    OTAE2E_PID=$!
    sleep 1
    kill -0 "$OTAE2E_PID" 2>/dev/null
}
# otabun_volume <isa> <disk> <work> <mode>: the volume and the bundle of a row,
# before the row lets the gate run on: the topology bound to the volume's
# device, the configuration without the brain link (host port 9000 belongs to
# the network rows) signed again for the volume, the source rows, and the
# bundle in the TFTP directory.
otabun_volume() {
    local isa="$1" disk="$2" work="$3" mode="$4" tisa=riscv64 ini="$2.cfg.ini" bun="$3/tftp/SYS.AZU"
    [ "$isa" = aarch64 ] && tisa=aarch64
    par_shared "make topo-volume" || return 1
    make topo-volume TOPO_IMAGE="$disk" TOPO_ISA="$tisa" TOPO_KCONFIG_RISCV64="$PRIMARY_CONFIG" \
        TOPO_KCONFIG_AARCH64="$AARCH64_CONFIG" TOPO_KERNEL_FEATURES="qemu,secure-boot-enforced" >"$work/topo.log" 2>&1 || return 1
    mcopy -n -i "$disk" ::CONFIG.INI "$ini.in" 2>/dev/null \
      && sed -e 's/^behavior_server_port=.*/behavior_server_port=0/' "$ini.in" >"$ini" \
      && grep -q '^behavior_server_port=0' "$ini" \
      && mcopy -o -i "$disk" "$ini" ::CONFIG.INI 2>/dev/null \
      && python3 tools/gen_config_sig.py "$ini" --config-v2 --counter 1 --image "$disk" --out "$ini.sig" >/dev/null 2>&1 \
      && mcopy -o -i "$disk" "$ini.sig" ::CONFIG.SIG 2>/dev/null || return 1
    printf 'tftp=10.0.2.2\nfile=SYS.AZU\n' >"$work/SOURCE.CFG"
    mcopy -o -i "$disk" "$work/SOURCE.CFG" ::PKG/SOURCE.CFG 2>/dev/null || return 1
    # The set: the topology and the configuration as the volume holds them; the
    # kernel part a stand-in payload (the kernel ELF is far over the 8 MiB the
    # kernel image slot takes), version 2, signed by the sidecar the tool makes.
    local f
    for f in CAPS.TOM CAPS.SIG SCHED.TOM CONFIG.SIG; do mcopy -n -i "$disk" "::$f" "$work/$f" 2>/dev/null || return 1; done
    cp "$ini" "$work/CONFIG.INI"
    python3 -c "import random; random.seed(0x4F544134); open('$work/kern_b.bin', 'wb').write(random.randbytes(65536))" \
      && python3 tools/sign_ota.py bundle "$bun" --epoch 2 --fw-version 2 --platform qemu --kernel "$work/kern_b.bin" \
           --caps "$work/CAPS.TOM" --caps-sig "$work/CAPS.SIG" --sched "$work/SCHED.TOM" \
           --config "$work/CONFIG.INI" --config-sig "$work/CONFIG.SIG" --priv "$OTAE2E_PRIV" >/dev/null 2>&1 || return 1
    rm -f "$ini" "$ini.in" "$ini.sig"
    [ "$mode" = tampered ] || return 0
    # One byte of the kernel part, past the manifest (24 B, 52 B a part, the
    # 64 B signature): the manifest is genuine, the kernel is not.
    python3 - "$bun" <<'PY'
import struct, sys
p = sys.argv[1]
b = bytearray(open(p, 'rb').read())
mlen = 24 + 52 * struct.unpack_from('<H', b, 20)[0] + 64
b[mlen + 100] ^= 0x80
open(p, 'wb').write(b)
PY
}
ota_bundle_row() { # ota_bundle_row <riscv64|aarch64> <good|tampered>
    local isa="$1" mode="$2" label
    if [ "$mode" = good ]; then label="$isa: OTA bundle over the network, B confirmed"; else label="$isa: OTA tampered bundle refused"; fi
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local work="$CI_LOG_DIR/otabun-$isa-$mode" kimg disk fifo log1 log2 log3 res try
    rm -rf "$work"; mkdir -p "$work/tftp"
    kimg="$work/kernel"; disk="$work/disk.img"; fifo="$work/in.fifo"
    log1="$work/boot1.log"; log2="$work/boot2.log"; log3="$work/boot3.log"
    if [ "$isa" = riscv64 ]; then
        if ! PROD_PUBKEY_PATH="$OTAE2E_KEY" kbuild "qemu,secure-boot-enforced"; then
            bad; echo "      riscv64 kernel (--features qemu,secure-boot-enforced) did not build"; return
        fi
        cp "$KERNEL" "$kimg"
        rm -f $AZOS_OUT/build/disk-sh.img $AZOS_OUT/build/disk-sh-signed.img
        make_disk $AZOS_OUT/build/disk-sh-signed.img
        cp $AZOS_OUT/build/disk-sh-signed.img "$disk"
    else
        if ! PROD_PUBKEY_PATH="$OTAE2E_KEY" a64_kbuild "qemu,secure-boot-enforced"; then
            bad; echo "      aarch64 kernel (--features qemu,secure-boot-enforced) did not build"; return
        fi
        cp "$A64_IMG" "$kimg"
        rm -f $AZOS_OUT/build/disk-aarch64-sh.img $AZOS_OUT/build/disk-aarch64-sh-signed.img
        make_disk $AZOS_OUT/build/disk-aarch64-sh-signed.img
        cp $AZOS_OUT/build/disk-aarch64-sh-signed.img "$disk"
    fi
    if ! otabun_volume "$isa" "$disk" "$work" "$mode"; then
        bad; echo "      could not prepare the volume and the bundle (topology: $work/topo.log)"; return
    fi
    if ! mkfifo "$fifo"; then bad; echo "      mkfifo failed: $fifo"; return; fi
    par_ready
    OTABUN_LOG="$log1"

    # Boot 1: A, with the shell. The installer gets the bundle, `ota switch`.
    if ! otabun_qemu "$isa" "$kimg" "$disk" "$log1" "$fifo" "$work/tftp"; then
        bad; echo "      QEMU did not start (log: $log1)"; return
    fi
    exec 9>"$fifo"
    if ! otae2e_wait "$log1" 'azos\$ ' 150 || ! otae2e_wait "$log1" '\[pkgd\] AzOS package installer' 90; then
        exec 9>&-; otae2e_stop; bad; echo "      boot 1: the shell or the installer never came up:"
        grep -a "pkgd\]\|compmgr\]\|CONSOLE\]\|PANIC" "$log1" | tr -d '\r' | sed -n '1,16p' | sed 's/^/        /'
        echo "      log kept: $log1"; return
    fi
    # The switch is refused while this boot is unconfirmed (the system that is
    # running has not proven itself): A confirms after 30 s of real uptime, and
    # the tampered row waits too, so the refusal it sees is the stager's and not
    # that one.
    if ! otae2e_wait "$log1" '\[OTA\] Boot marked good \(slot=A\)' 150; then
        exec 9>&-; otae2e_stop; bad; echo "      boot 1: slot A never confirmed itself, so the system is not healthy:"
        grep -a "OTA\]\|WDT\]" "$log1" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $log1"; return
    fi
    # The network may come up after the prompt: the fetch is asked again (at
    # most four times) while it says it could not reach the source.
    res=""
    for try in 1 2 3 4; do
        otabun_cmd "pkg fetch-update" 'staged: update|refused: ' 60
        res="$(grep -aE 'staged: update|refused: ' "$log1" | tr -d '\r' | sed -n '$p')"
        case "$res" in *"refused: update"*|*"staged: update"*) break ;; esac
        sleep 5
    done
    if [ "$mode" = tampered ]; then
        otabun_cmd "ota switch" 'azos\$ ' 30
        exec 9>&-; otae2e_stop
        if ! printf '%s' "$res" | grep -q 'refused: update part hash' \
           || grep -aqE 'ota: switched|\[OTA\] System update:' "$log1" \
           || [ "$(otae2e_field "$disk" active_slot)" != a ] \
           || mdir -i "$disk" ::PKG/SYS_B/UPDATE.MAN >/dev/null 2>&1; then
            bad; echo "      the tampered bundle was staged or switched (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot)):"
            echo "        pkg fetch-update: ${res:-<no answer>}"
            grep -a "ota:\|OTA\] System\|pkgd\]" "$log1" | tr -d '\r' | sed -n '1,10p' | sed 's/^/        /'
            echo "      log kept: $log1 (volume: $disk)"; return
        fi
        ok; rm -rf "$work"; return
    fi
    if ! printf '%s' "$res" | grep -qE 'staged: update [0-9a-f]+, epoch 2, into slot B' \
       || ! otabun_cmd "ota switch" 'ota: switched to the staged system set, epoch 2' 60; then
        exec 9>&-; otae2e_stop; bad; echo "      the bundle was not staged and switched:"
        echo "        pkg fetch-update: ${res:-<no answer>}"
        grep -a "ota:\|OTA\] System\|pkgd\]\|NET\]" "$log1" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      log kept: $log1 (volume: $disk)"; return
    fi
    exec 9>&-; otae2e_stop
    if ! grep -aqF "[OTA] System update: slot B (epoch 2, fw 2) switched to" "$log1" \
       || [ "$(otae2e_field "$disk" active_slot)" != b ] || [ "$(otae2e_field "$disk" boot_count)" != 0 ] \
       || ! mdir -i "$disk" ::PKG/SYS_B/UPDATE.MAN >/dev/null 2>&1 \
       || ! mdir -i "$disk" ::PKG/JOURNAL.BIN >/dev/null 2>&1; then
        bad; echo "      the switch is not on the volume (BOOTMETA active_slot=$(otae2e_field "$disk" active_slot) boot_count=$(otae2e_field "$disk" boot_count)):"
        grep -a "OTA\]" "$log1" | tr -d '\r' | sed -n '1,10p' | sed 's/^/        /'
        echo "      log kept: $log1 (volume: $disk)"; return
    fi

    # Boot 2: B on trial with its set in force; after 30 s it is confirmed.
    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$log2"; then
        bad; echo "      QEMU did not start (log: $log2)"; return
    fi
    otae2e_wait "$log2" '\[OTA\] Boot marked good|!!! KERNEL PANIC !!!|\[FATAL\]' 150
    otae2e_stop
    if otae2e_trap "$log2" \
       || ! grep -aqF "[OTA] Boot: slot=B count=1/3 last_good=A" "$log2" \
       || ! grep -aqF "[OTA] System set of slot B (epoch 2) in force" "$log2" \
       || ! grep -aqE '\[SECURE-BOOT\] Slot B signature: verified' "$log2" \
       || ! grep -aqF "[OTA] Boot marked good (slot=B)" "$log2"; then
        bad; echo "      slot B did not boot on trial with its set and confirm itself:"
        grep -a "OTA\] Boot\|OTA\] System\|SECURE-BOOT\] Slot\|PANIC\|FATAL" "$log2" | tr -d '\r' | sed -n '1,12p' | sed 's/^/        /'
        echo "      logs kept: $log1 $log2"; return
    fi

    # Boot 3: the confirmation is on the volume, and B is what boots.
    if ! otae2e_qemu "$isa" "$kimg" "$disk" "$log3"; then
        bad; echo "      QEMU did not start (log: $log3)"; return
    fi
    otae2e_wait "$log3" '\[SECURE-BOOT\] Slot B signature|!!! KERNEL PANIC !!!|\[FATAL\]' 150
    otae2e_stop
    if otae2e_trap "$log3" \
       || ! grep -aqF "[OTA] Boot: slot=B count=1/3 last_good=B" "$log3" \
       || [ "$(otae2e_field "$disk" last_good)" != b ]; then
        bad; echo "      the third boot is not a confirmed B (last_good=$(otae2e_field "$disk" last_good)):"
        echo "        boot 2: $(grep -a 'OTA\] Boot: slot=' "$log2" | tr -d '\r' | sed -n '1p')"
        echo "        boot 3: $(grep -a 'OTA\] Boot: slot=' "$log3" | tr -d '\r' | sed -n '1p')"
        echo "      logs kept: $log1 $log2 $log3"; return
    fi
    ok; rm -rf "$work"
}

# ── aarch64: file-open / captest / ipctest parity (aarch64 parity program) ──
#
# `aarch64_kernel_row`/`aarch64_userspace_row` above build the aarch64 kernel
# with NO cargo features — proof the port compiles and boots hello/systest at
# all. These three rows need `qemu` (`crates/core/topology/src/builder.rs`'s
# `cap-refusal-canary`: `RESOURCE_MMIO_RTC`/`RESOURCE_PWM_MOTOR`/
# `RESOURCE_GPIO_MOTOR`, and `gpio-aq3-smoke`), the same feature riscv64's own
# `kbuild "qemu"` scenarios below build with — so they rebuild their own
# kernel image rather than reuse `$A64_IMG`, mirroring riscv64's `kbuild`.
#
# Root cause this task found and fixed: `crates/core/syscall::file_ops::
# set_file_ops` — the seam behind `SYS_OPEN`/`NODE_OPENAT`/
# `SYS_SPAWN_EX` — was installed only from riscv64's `kernel_main`; aarch64's own
# never called it, so every file-open syscall returned -1 regardless of
# whether FAT32 was mounted underneath it. `install_ring3_seams`
# (`kernel/src/boot/seams.rs`) is now the ONE function both ISAs call — see that
# function's own doc for the full reasoning, and `install_robot_hw` alongside
# it for the matching gap in the GPIO/PWM/I2C/motor-binding boot step
# `captest`'s cap-refusal checks needed.
#
# "child processes (spawn+wait identity)": covered here, not as a separate
# row — abitest's own `spawn_ex()`/`wait()`/`wait_status()`/`waitpid()` checks
# are part of the "all checks" row below, the same as on riscv64.

# aarch64 abitest: mirrors riscv64's "userspace: ABI conformance" row —
# every check the binary runs, read back rather than counted here (the
# total drifts as `userspace/tests/abitest` grows; do not hardcode it). One KNOWN
# gap, not silenced: `vdso flags bit 0: rdtime native`
# is riscv64-only BY DESIGN (`install_vdso`'s own doc — aarch64 has no
# `rdtime`-from-U-mode fast path yet). Any OTHER failure, or a different
# failure count, fails the row: the count and the failing line(s) are read
# back, not just ALL PASSED's absence.
aarch64_abitest_row() {
    local label="aarch64 abitest"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-abitest.log"
    rm -f "$log"
    if ! a64_kbuild "qemu"; then
        bad; echo "      aarch64 kernel (--features qemu) did not build"; return
    fi
    if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-abitest.img"
    local disk_copy="$CI_LOG_DIR/disk-aarch64-abitest-run.img"
    cp "$A64_IMG" "$img_copy"
    cp $AZOS_OUT/build/disk-aarch64-abitest.img "$disk_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$disk_copy",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    # `[0-9]+ check(s) run` is NOT the last line abitest prints — `FAILED: N
    # check(s)` (when N>0) follows it. Killing on the FIRST match races that
    # second line: caught once, empty `fail_lines` on a run that genuinely
    # failed. Waited out with one extra settle poll below instead of trusted.
    while [ "$i" -lt 90 ]; do
        grep -aqE "ABITEST\] [0-9]+ check\(s\) run" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    sleep 1
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception:"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqE "\[ABITEST\] [0-9]+ check\(s\) run" "$log" 2>/dev/null; then
        bad; echo "      abitest never printed its own summary line"
        echo "      log kept: $log"; return
    fi
    # The page-table free check (riscv64's "mem quota lets real work through"
    # row carries it too): on this ISA it sees the freeing PE's own TTBR0_EL1.
    # Canary, run by hand: `qemu,exit-satp-canary` prints it at every exit.
    if grep -aq "\[MM\] page-table root" "$log" 2>/dev/null; then
        bad; echo "      a teardown found its root still live:"
        grep -a -m3 "\[MM\] page-table root" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    # `fails` comes from COUNTING the `  FAIL  ` lines themselves, the same
    # readback `aarch64_ipctest_row` uses — not from parsing the `FAILED: N`
    # summary line, which is one more print after the trigger this loop
    # breaks on and can still be mid-flush when the settle sleep above ends.
    local fail_lines
    fail_lines="$(grep -a '\[ABITEST\]  FAIL  ' "$log" | sed 's/^\[ABITEST\]  FAIL  //')"
    local fails
    fails="$(printf '%s\n' "$fail_lines" | grep -c .)"
    if [ "$fails" -eq 0 ]; then
        ok; rm -f "$log"; return
    fi
    if [ "$fails" -eq 1 ] && printf '%s\n' "$fail_lines" | qgrep -qF "vdso flags bit 0: rdtime native"; then
        ok; rm -f "$log"; return
    fi
    bad; echo "      abitest reported $fails failure(s), not the one known aarch64 gap:"
    printf '%s\n' "$fail_lines" | sed 's|^|        |'
    echo "      log kept: $log"
}
par "aarch64 abitest" aarch64_abitest_row

# aarch64 twin of `userspace: a crashed ring-3 driver is restarted` (`kernel/src/drv_supervisor.rs`): the kernel stops gpio_drv four times;
# three restarts must answer again and the fourth death must stay down, with
# 3 restarts + 1 give-up added to the flight recorder. `[SUP] FAIL` is a
# verdict; `sup-canary` (supervisor off) fails on `[SUP] FAIL not restarted
# after kill 1`; a supervisor wake before the dead driver's address-space
# teardown fails on `[SUP] FAIL the supervisor was woken` (wave 12, see the
# riscv64 row). Only `[SUP] FAIL`, the driver's own FAILED line and an
# unhandled trap are judged here: this ISA's `--features qemu` boot prints the
# known `[SCHED] FAILED: task A and B did not interleave` (front INV), which is
# not this row's property. `-smp 2`: the autorun hart (3) does not exist, so
# the successor must follow the dead driver's live hart, not the constant.
aarch64_sup_row() {
    local label="aarch64 driver restarted"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-sup.log"
    rm -f "$log"
    if ! a64_kbuild "qemu,sup-smoke"; then
        bad; echo "      aarch64 kernel (--features qemu,sup-smoke) did not build"; return
    fi
    if ! make $AZOS_OUT/build/disk-aarch64-gpiodrv.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-gpiodrv.img"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-sup.img"
    local disk_copy="$CI_LOG_DIR/disk-aarch64-gpiodrv-sup.img"
    cp "$A64_IMG" "$img_copy"
    cp $AZOS_OUT/build/disk-aarch64-gpiodrv.img "$disk_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$disk_copy",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 240 ]; do
        grep -aqE "\[SUP\] (PASS|FAIL)|\[gpio_drv\] .*FAILED|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img_copy" "$disk_copy"
    if grep -aqE "\[SUP\] FAIL|\[gpio_drv\] .*FAILED|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      scenario reported failure:"
        grep -aE "\[SUP\] FAIL|\[gpio_drv\] .*FAILED|AARCH64-TRAP" "$log" | tr -d '\r' | sed -n '1,4p' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aq "\[SUP\] PASS" "$log" 2>/dev/null; then
        bad; echo "      no '[SUP] PASS' within 240 s — last lines:"
        tr -d '\r' < "$log" | tail -5 | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"
}
par "aarch64 driver restarted" aarch64_sup_row
# Leave $A64_IMG on an ordinary qemu build for the rows below.
a64_kbuild "qemu" >/dev/null 2>&1 || true

# aarch64 ipctest: mirrors riscv64's ipctest phase A (1600 of 1600 fast-IPC
# round trips). **No tolerated failure — a clean run or nothing.**
#
# This row used to tolerate exactly one failure named `B/client reported at
# all`, blamed on an aarch64 cross-hart WAKE defect. **That diagnosis was
# wrong and cost a week.** The real cause, found 2026-09-25, was a per-board
# constant in shared userspace test code: `userspace/tests/ipctest` hardcoded
# `TICKS_PER_MS = 10_000`, right for riscv64's fixed 10 MHz CLINT and wrong
# for aarch64, whose `CNTVCT_EL0` ticks at the live `CNTFRQ_EL0` — 1 GHz in
# this QEMU. Every `WAIT_MS` deadline in the file was therefore enforced at
# 1/100th of its intended real time: a nominal 20,000 ms budget became ~200 ms,
# which phase B's own deliberate sleeps (650 ms) blow through. The waiter gave
# up before the waker could plausibly have run. No task ever failed to wake.
#
# Fixed by reading the kernel's own live `vdso_timebase_hz()`. Measured: 5/5
# failures before, 10/10 clean after, canary 2/2. Same CLASS the project had
# already named — a tick count is a per-board number — one instance nobody
# had converted.
#
# The row is host-load sensitive in a DIFFERENT, pre-existing way (phase A not
# finishing 1600 calls inside the 200 s ceiling when run right after another
# freshly rebuilt aarch64 row). That shows up as `PHASE_A_INCOMPLETE`, which
# the old tolerance never covered either, so removing it does not make this
# row more fragile.
#
# KNOWN FLAKE, measured, not guessed: eight forked children each hammer one
# server with real `sys::sleep`-paced calls and a 20 s wall-clock stall
# detector (`WAIT_MS`, `userspace/tests/ipctest`). Run alone, right after a cold
# build, this row completed 1600/1600 twice; run immediately after another
# freshly rebuilt-and-booted aarch64 row on this same host it read 1400 and
# then 1200 of 1600 on two more attempts — a real host-load sensitivity, not
# a logic bug in this row (it correctly reported FAIL both times, which is
# what a genuinely incomplete run must do). Same class of finding as "two
# concurrent QEMUs turn a passing phase A into 4/8 stalled children" above:
# a wall-clock deadline inside the guest is only as reliable as the host is
# idle. Give this row room — do not run it back-to-back with another
# freshly-building aarch64 row without a short settle, and do not run it
# beside a second concurrent QEMU.
aarch64_ipctest_row() {
    local label="aarch64 ipctest"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-ipctest.log"
    rm -f "$log"
    if ! a64_kbuild "qemu"; then
        bad; echo "      aarch64 kernel (--features qemu) did not build"; return
    fi
    if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-ipctest.img"
    local disk_copy="$CI_LOG_DIR/disk-aarch64-ipctest-run.img"
    cp "$A64_IMG" "$img_copy"
    cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$disk_copy",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    # 200, not 60: ipctest's own stall detector gives a client 20 s of guest
    # wall clock (userspace/tests/ipctest/src/main.rs, WAIT_MS) before it reports
    # `server stalled`, and phase A's 1600 calls take longer than 60 s under
    # TCG on a loaded host. The ceiling sits above the guest's own budget so
    # that the TEST decides the verdict, not this loop's patience.
    #
    # This row is STRICT on purpose (1600 of 1600). It went red once in three
    # hand runs with two cargo builds hammering the host, and the log says why:
    # `server stalled: no call served for 20000 ms`, one client of eight silent
    # for twenty seconds of GUEST time on `-smp 2`. That is a lost wake-up, not
    # a slow machine -- raising the budget to 45 s was tried and the same run
    # failed the same way. Under investigation; the row must keep failing until
    # it is fixed rather than be relaxed to accept 1400 of 1600.
    while [ "$i" -lt 200 ]; do
        grep -aqE "IPCTEST\] [0-9]+ check\(s\) run" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception:"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[IPCTEST] all=1600 of 1600 OK" "$log" 2>/dev/null; then
        bad; echo "      phase A did not complete all 1600 calls:"
        grep -a "IPCTEST\] all=" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local fail_lines
    fail_lines="$(grep -a '\[IPCTEST\]  FAIL  ' "$log" | sed 's/^\[IPCTEST\]  FAIL  //')"
    local fails
    fails="$(printf '%s\n' "$fail_lines" | grep -c .)"
    if [ "$fails" -eq 0 ]; then
        ok; rm -f "$log"; return
    fi
    # TOLERANCE REMOVED 2026-09-25. It used to pass a run whose only failure was
    # named `B/client reported at all`, on the belief that this was an aarch64
    # cross-hart WAKE defect. It was not a wake defect at all — see the comment
    # above the row. The row now demands a clean run, like riscv64's.
    bad; echo "      ipctest reported $fails failure(s):"
    printf '%s\n' "$fail_lines" | sed 's|^|        |'
    echo "      log kept: $log"
}
par "aarch64 ipctest" aarch64_ipctest_row

# aarch64 phase 3 under `--features qemu`: two equal-priority kernel tasks on
# ONE hart must take turns because the tick preempts them. The boot rows above
# assert the same "interleaved" line, but they build without `qemu`, and that
# is the only reason they passed: unpinned, the two tasks landed on different
# harts and never shared one. Every `--features qemu` boot printed "[SCHED]
# FAILED: task A and B did not interleave" (8/8 with the ipctest disk, 2/2
# without), and no row read that line. Now both pinned to hart 0
# (`PHASE3_HART` in kernel/src/smokes/aarch64_sched.rs): 9/9 interleaved (5 without a disk,
# 4 with), and the build without `qemu` still interleaves at -smp 1/2/4. No disk here: phase 3
# runs before anything reads one. Canary, by hand: pin phase3-b to hart 1 and
# this row prints the FAILED line (2/2).
aarch64_phase3_qemu_row() {
    local label="aarch64 preemption (qemu)"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-phase3-qemu.log"
    rm -f "$log"
    if ! a64_kbuild "qemu"; then
        bad; echo "      aarch64 kernel (--features qemu) did not build"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-phase3-qemu.img"
    cp "$A64_IMG" "$img_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
        -kernel "$img_copy" >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 120 ]; do
        grep -aqE "\[SCHED\] (FAILED: task A|task A ran [0-9]+ times, task B ran [0-9]+ times, interleaved)" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aqE "\[SCHED\] task A ran [0-9]+ times, task B ran [0-9]+ times, interleaved" "$log" 2>/dev/null \
       && ! grep -aq "\[SCHED\] FAILED:" "$log" 2>/dev/null; then
        ok; rm -f "$log" "$img_copy"; return
    fi
    bad; echo "      phase 3 did not interleave on --features qemu:"
    grep -a "\[SCHED\] FAILED:\|AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
    echo "      log kept: $log"
}
par "aarch64 preemption (qemu)" aarch64_phase3_qemu_row

# aarch64 captest: mirrors riscv64's "userspace: capabilities" row — the
# device-name and device-handle fixes from this task (ISA-neutral
# munmap-refused check: GICD/GICR/UART, not CLINT/PLIC/UART; the MMIO section
# maps the hardware-bus devices the topology grants by selector, the PL031 RTC
# and the PL061 GPIO, found by their identity in the introspection tree's `devices/`), plus
# `install_robot_hw`'s GPIO/PWM/I2C + motor-binding boot step. Full parity:
# ALL PASSED, same as riscv64 — no known gap on this one.
aarch64_captest_row() {
    local label="aarch64 captest"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-captest.log"
    rm -f "$log"
    if ! a64_kbuild "qemu,captest-row"; then
        bad; echo "      aarch64 kernel (--features qemu,captest-row) did not build"; return
    fi
    if ! make $AZOS_OUT/build/disk-aarch64-captest.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-captest.img"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-captest.img"
    local disk_copy="$CI_LOG_DIR/disk-aarch64-captest-run.img"
    cp "$A64_IMG" "$img_copy"
    cp $AZOS_OUT/build/disk-aarch64-captest.img "$disk_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$disk_copy",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 60 ]; do
        grep -aqF "CAPTEST] ALL PASSED" "$log" 2>/dev/null && break
        grep -aqE "CAPTEST\]  FAIL" "$log" 2>/dev/null && break
        grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    if grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel took an exception:"
        grep -a "AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if grep -aqE "CAPTEST\]  FAIL" "$log" 2>/dev/null; then
        bad; echo "      captest reported a failure:"
        grep -a "CAPTEST\]  FAIL" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[CAPTEST] ALL PASSED" "$log" 2>/dev/null; then
        bad; echo "      captest never printed ALL PASSED"
        echo "      log kept: $log"; return
    fi
    ok
}

# Wave 11 (SENSORTS), both ISAs: read from the captest boot of the row above
# (riscv64: "userspace: capabilities"). captest reads each granted sensor
# through its `sensor` endpoint between two vDSO clock reads and prints
# its summary line only when every stamp held: on the reader's clock, inside
# the call for a value read during it (IMU, encoder, rangefinder, battery),
# under 1 s before it for odometry (cached by the 50 Hz `odom` task), never
# backwards; plus a too-short buffer that still reports the whole record. Invoked before the IRQ
# rows, which delete the shared log. Canary (hand-run): the `sensor-ts-freeze`
# kernel on the same disk -> `FAIL  sensor_read_ts(IMU): acquired inside the
# call` and no summary line.
sensor_ts_captest_row() { # sensor_ts_captest_row <label> <log>
    local label="$1" log="$2"
    printf "  %-26s" "${label}..."
    if [ ! -s "$log" ]; then
        bad; echo "      no captest log to read (the captest row did not keep one)"; return
    fi
    if grep -aqE "CAPTEST\]  FAIL  sensor_read_ts" "$log"; then
        bad; echo "      a stamped read failed:"
        grep -aE "CAPTEST\]  FAIL  sensor_read_ts|CAPTEST\] sensorts" "$log" | tr -d '\r' | sed 's|^|        |'
        return
    fi
    if ! grep -aqF "[CAPTEST] sensorts: 5 sensors stamped on the vDSO clock, inside the call (IMU ENCODER RANGE BATTERY) or < 1 s before it (ODOM), monotonic" "$log" \
        || ! grep -aqF "[CAPTEST]   ok   sensor read(IMU, 23-byte buffer) reports the 24-byte record" "$log"; then
        bad; echo "      captest never printed the stamped-read summary and the short-buffer report:"
        grep -a "sensorts\|sensor_read_ts" "$log" | tr -d '\r' | sed 's|^|        |'
        return
    fi
    ok; grep -a "CAPTEST\] sensorts: IMU" "$log" | tr -d '\r' | sed 's|^|      |'
}

# Wave 10 IRQ5, both ISAs: captest binds a line the capability range admits
# and QEMU `virt`'s controller does not implement (riscv64 source 100: PLIC
# 1..=95, APLIC 1..=96; aarch64 SPI 1000: past GICD_TYPER.ITLinesNumber) with
# 510 and with 575. Both must answer -ENODEV, and the kernel reads back, after
# its undo, how many bindings of the line are left: 0. Before, both answered
# 0 and kept a binding no interrupt could reach. Prints the reason and
# returns 1 when the evidence is missing. Canary (hand-run): drop the
# `irq_unbind` in `handlers::route_stored_binding_with` -> "bindings left on
# the line: 1" and this check fails on it.
irq_refusal_evidence() { # irq_refusal_evidence <log> <line>
    local log="$1" line="$2" n
    if ! grep -aqF "[CAPTEST]   ok   irq: irq_bind(absent line) -> -ENODEV" "$log"; then
        echo "      captest did not see the bind of the absent line $line refused with -ENODEV:"
        grep -a "absent line" "$log" | tr -d '\r' | sed 's|^|        |'
        return 1
    fi
    n="$(grep -a "\[IRQ\] ring-3 line $line refused by the interrupt controller" "$log" \
        | tr -d '\r' | grep -c "bindings left on the line: 0$")"
    if [ "$n" != "1" ]; then
        echo "      the kernel did not read back 0 bindings of line $line after the undo:"
        grep -a "ring-3 line $line refused" "$log" | tr -d '\r' | sed 's|^|        |'
        return 1
    fi
    return 0
}

# aarch64 ring-3 IRQ (wave 8, IRQ3; wave 9 IRQ4): read from the SAME boot as
# the captest row above — captest's `irq_section` binds the PL031's line
# (INTID 34, `irq.34` + `mmio.dt:arm,pl031` in the qemu topology) to a port, raises the
# alarm, and must see: the interrupt delivered to the port; the line held
# MASKED while the device still asserts and nobody ACKed (no second event in
# 100 ms); after RTCICR + `DEVICE_IRQ_ACK`, a second alarm delivered. Then an
# alarm raised BEFORE the poll must be waiting on the port (a delivery is
# queued, never lost). Also the boot line of the DTB trigger map
# `gic::user_spi_bind` programs ICFGR from: QEMU `virt` describes the PL031 as
# level (`<0 2 4>`) and the first virtio-mmio slot as edge (`<0 16 1>`).
# The kernel side: `handle_irq`'s ring-3 arm (mask via GICD_ICENABLER, EOI,
# `irq_dispatch`) and the ACK's unmask (GICD_ISENABLER).
#
# Canaries (hand-run): `--features qemu,irq-ack-canary` makes the ACK leave
# the line masked -> `[CAPTEST]  FAIL  irq: second interrupt delivered after
# ACK`; `irq-mask-canary` (no mask on delivery) -> `FAIL  irq: line held
# masked until ACK`.
aarch64_ring3_irq_row() {
    local label="aarch64 ring-3 irq"
    printf "  %-26s" "${label}..."
    local log="$CI_LOG_DIR/aarch64-captest.log"
    if [ ! -s "$log" ]; then
        bad; echo "      no captest log to read (the captest row did not boot)"; return
    fi
    if grep -aqE "CAPTEST\]  FAIL  irq: " "$log"; then
        bad; echo "      captest's IRQ section failed:"
        grep -aE "CAPTEST\]  FAIL  irq: " "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "[CAPTEST] irq: line 34 delivered twice, masked in between, re-armed by ACK" "$log" \
        || ! grep -aqF "[CAPTEST]   ok   irq: line held masked until ACK" "$log" \
        || ! grep -aqF "[CAPTEST] irq: line 34 delivered before the poll was kept on the port" "$log"; then
        bad; echo "      captest never reported the two deliveries, the mask and the delivery kept on the port"
        grep -a "CAPTEST\].*irq" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqE "\[IRQ\] DTB triggers \(GICv3\): [0-9]+ SPIs, [1-9][0-9]* edge; INTID 34 level, INTID 48 edge" "$log"; then
        bad; echo "      the DTB trigger map did not read PL031 level and virtio-mmio edge:"
        grep -a "DTB triggers" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local why
    if ! why="$(irq_refusal_evidence "$log" 1000)"; then
        bad; echo "$why"; echo "      log kept: $log"; return
    fi
    ok; echo "      $(grep -a "irq: line 34 delivered twice" "$log" | tr -d '\r')"
    rm -f "$log"
}
# The captest boot, and the two rows that read its log: one job.
aarch64_captest_group() {
    aarch64_captest_row
    sensor_ts_captest_row "aarch64 sensors: stamped read" "$CI_LOG_DIR/aarch64-captest.log"
    aarch64_ring3_irq_row
    # The rows after this one boot the plain kernel, not the one with captest's
    # row (it needs four CPUs).
    a64_kbuild "qemu"
}
par "aarch64 captest" aarch64_captest_group

# aarch64 DRV1 (wave 9): the buzzer and INA219 ring-3 drivers on this ISA.
# The riscv64 rows `drivers: buzzer` / `drivers: INA219 power monitor` state
# the test; this is the same kernel smoke (`ring3-drv-smoke`) on the aarch64
# `build/disk-aarch64-drv.img` (the one aarch64 image carrying the two driver
# images; their rows say `start = true`), one boot, both verdicts read from
# its log. Rebuilds the plain `qemu` kernel after,
# so no later aarch64 row boots the smoke kernel.
aarch64_ring3_drivers_row() {
    local label="aarch64 ring-3 drivers"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/aarch64-ring3-drivers.log"
    rm -f "$log"
    if ! a64_kbuild "qemu,ring3-drv-smoke"; then
        bad; echo "      aarch64 kernel (--features qemu,ring3-drv-smoke) did not build"; return
    fi
    rm -f $AZOS_OUT/build/disk-aarch64-drvbase.img $AZOS_OUT/build/disk-aarch64-drv.img
    if ! make $AZOS_OUT/build/disk-aarch64-drv.img >/dev/null 2>&1; then
        bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-drv.img"; return
    fi
    local img_copy="$CI_LOG_DIR/kernel-aarch64-drv.img"
    local disk_copy="$CI_LOG_DIR/disk-aarch64-drv-run.img"
    cp "$A64_IMG" "$img_copy"
    cp $AZOS_OUT/build/disk-aarch64-drv.img "$disk_copy"
    par_ready
    qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic \
        -kernel "$img_copy" \
        -global virtio-mmio.force-legacy=false \
        -drive file="$disk_copy",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    while [ "$i" -lt 240 ]; do
        grep -aqE "DRV1\] ina219 (PASS|FAIL)" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img_copy" "$disk_copy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel crashed — log kept: $log"; return
    fi
    if grep -aqE "DRV1\] (buzzer|ina219) FAIL" "$log"; then
        bad; grep -aE "DRV1\] (buzzer|ina219) FAIL" "$log" | tr -d '\r' | sed 's|^|      |'
        echo "      log kept: $log"; return
    fi
    if grep -aqF "[DRV1] buzzer PASS" "$log" && grep -aqF "[DRV1] ina219 PASS" "$log"; then
        ok; rm -f "$log"
    else
        bad; echo "      no verdict for both drivers — log kept: $log"
    fi
}
par "aarch64 ring-3 drivers" aarch64_ring3_drivers_row
a64_kbuild "qemu" || true

# ── Wave 11: what the kernel itself starts is supervised (both ISAs) ────────
#
# Before wave 11 only the autorun image was supervised; the images the kernel
# spawns because the system declares them died once, unsupervised and
# unrecorded. They go through `drv_supervisor::spawn_supervised` and are
# supervised from their start, under the same policy (SUP_RESTART_BURST
# restarts within SUP_RESTART_INTERVAL_S, on failure only). The `start = true`
# rows are the component manager's now (`userspace/services/compmgr`, its
# policy host-tested in `tests/host/compmgr-tests`), the ring-3 host of the
# buzzer included; the kernel keeps the manager itself and the ML service.
# `supall-smoke` (`drv_supervisor::supall`): the buzzer is stopped (137) and
# the component manager must restart it: a new task must own
# `endpoint.buzzer` and answer `buzzer_off`. `[SUPALL] FAIL` is a verdict.
# Canary: `supall-canary` (the manager is shown every row as `restart = no`)
# fails on `[SUPALL] FAIL buzzer not restarted`, which only a driver that
# never came back prints. Boots a copy of
# the drv disk as built (`.pristine` on riscv64; rebuilt on aarch64), so
# earlier boots of that disk cannot push this one into safe mode.
supall_row() { # <label> <isa: rv|arm> <extra features, comma-led or empty> <expect: PASS|FAIL>
    local label="$1" isa="$2" extra="$3" expect="$4"
    printf "  %-26s" "${label}..."
    local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
    local log="$CI_LOG_DIR/${tag}.log" img="$CI_LOG_DIR/${tag}.img" kimg=""
    mkdir -p "$CI_LOG_DIR"; rm -f "$log" "$img"
    if [ "$isa" = "rv" ]; then
        if ! kbuild "qemu,supall-smoke$extra"; then
            bad; echo "      riscv64 kernel (qemu,supall-smoke$extra) did not build"; return
        fi
        if [ ! -f $AZOS_OUT/build/disk-drv.img.pristine ]; then
            rm -f $AZOS_OUT/build/disk-drvbase.img $AZOS_OUT/build/disk-drv.img
            make_disk $AZOS_OUT/build/disk-drv.img
        fi
        cp $AZOS_OUT/build/disk-drv.img.pristine "$img"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$img",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu,supall-smoke$extra"; then
            bad; echo "      aarch64 kernel (qemu,supall-smoke$extra) did not build"; return
        fi
        rm -f $AZOS_OUT/build/disk-aarch64-drvbase.img $AZOS_OUT/build/disk-aarch64-drv.img
        if ! make $AZOS_OUT/build/disk-aarch64-drv.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-drv.img"; return
        fi
        cp $AZOS_OUT/build/disk-aarch64-drv.img "$img"
        kimg="$CI_LOG_DIR/${tag}-kernel.img"
        cp "$A64_IMG" "$kimg"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic \
            -kernel "$kimg" \
            -global virtio-mmio.force-legacy=false \
            -drive file="$img",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 480 ]; do
        grep -aqE "\[SUPALL\] (PASS|FAIL)" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img"; [ -n "$kimg" ] && rm -f "$kimg"

    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      kernel panic or fatal exception:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local verdict
    verdict="$(grep -a "\[SUPALL\] \(PASS\|FAIL\)" "$log" | tr -d '\r' | sed -n '1p')"
    if [ "$expect" = "FAIL" ]; then
        case "$verdict" in
            "[SUPALL] FAIL buzzer not restarted"*) ok; rm -f "$log" ;;
            *) bad; echo "      the canary did not fail on the not-restarted line: '${verdict:-no verdict}'"
               echo "      log kept: $log" ;;
        esac
        return
    fi
    case "$verdict" in
        "[SUPALL] PASS"*) ok; rm -f "$log" ;;
        *) bad; echo "      ${verdict:-no [SUPALL] verdict within 240 s}"
           grep -a "\[SUPALL\]\|\[SUP\]\|DRVLAUNCH" "$log" | tr -d '\r' | sed -n '1,14p' \
               | sed 's|^|        |'
           echo "      log kept: $log" ;;
    esac
}
par "aarch64 moving driver supervised" supall_row "aarch64 moving driver supervised" arm "" PASS
a64_kbuild "qemu" || true

# ── Wave 11 (DRVPLACE): driver placement and the `restart` row key ──────────
#
# `drvplace_row` boots the drivers disk (a copy of the `.pristine` image on
# riscv64; rebuilt on aarch64) on a kernel built with `<features>` and reads
# one verdict. Kinds:
#   ina-kernel   `ring3-drv-smoke` with `ina219-kernel` (Kconfig
#                DRV_INA219_PLACEMENT = kernel): `[DRV1] ina219 PASS` with
#                the same simulated readings (7400 mV, 1500 mA) as the ring-3
#                row, and `(kernel tid=`: the kernel host answered, the
#                topology declared no INADRV.ELF and no ring-3 task owned
#                DRV_KIND_POWER_MON (`placement_check`).
#   ina-canary   `ina219-placement-canary`: the kernel placement with the
#                INADRV.ELF row kept and the link-time check skipped. Must
#                fail on `placement is kernel but the topology declares`,
#                which only the boot check prints.
#   restart      `restart-smoke`: BUZZDRV.ELF `restart = no` (CAPS.TOML format
#                2), read by the component manager (its reading of the key,
#                `always` included, is host-tested in
#                `tests/host/compmgr-tests`). The buzzer killed must stay
#                down.
#   restart-canary  `restart-canary` (the manager is shown every row as
#                `on-failure`): must print `FAIL buzzer restarted under
#                restart = no`.
#   buzz-kernel  wave 12: `ring3-drv-smoke` with `buzzer-kernel` (Kconfig
#                DRV_BUZZER_PLACEMENT = kernel): `[DRV1] buzzer PASS` with the
#                same PWM checks as the ring-3 row, from `(kernel tid=` (the
#                row says `place = "kernel"` and the driver runs there:
#                `buzzer_placement_check`), and the kernel
#                ELF carries the tree's buzzer source marker
#                (tools/chip_source_check.py; the ring-3 ELFs are checked by
#                the Makefile when built). Canaries by hand (2026-10-03):
#                gpio_drv.elf -> "carries no marker"; the chip source edited
#                after the build -> "carries marker <old>"; buzz_drv without
#                its marker print -> `make build/buzz_drv.elf` fails.
# The build bucket is `drvplace_build_canary_row`: the drivers crate told
# "kernel" and the topology not must not compile.
drvplace_row() { # drvplace_row <label> <isa: rv|arm> <features> <kind>
    local label="$1" isa="$2" feats="$3" kind="$4"
    printf "  %-26s" "${label}..."
    local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
    local log="$CI_LOG_DIR/${tag}.log" img="$CI_LOG_DIR/${tag}.img" kimg=""
    mkdir -p "$CI_LOG_DIR"; rm -f "$log" "$img"
    local until="DRV1\] ina219 (PASS|FAIL)"
    case "$kind" in
        restart) until="\[RESTART\] (PASS|FAIL)" ;;
        restart-canary) until="\[RESTART\] (PASS|FAIL)" ;;
    esac
    local src_why=""
    if [ "$isa" = "rv" ]; then
        if ! kbuild "$feats"; then
            bad; echo "      riscv64 kernel ($feats) did not build"; return
        fi
        if [ "$kind" = buzz-kernel ]; then
            src_why="$(python3 tools/chip_source_check.py buzzer "$KERNEL" 2>&1)"
        fi
        if [ ! -f $AZOS_OUT/build/disk-drv.img.pristine ]; then
            rm -f $AZOS_OUT/build/disk-drvbase.img $AZOS_OUT/build/disk-drv.img
            make_disk $AZOS_OUT/build/disk-drv.img
        fi
        cp $AZOS_OUT/build/disk-drv.img.pristine "$img"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$img",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "$feats"; then
            bad; echo "      aarch64 kernel ($feats) did not build"; return
        fi
        if [ "$kind" = buzz-kernel ]; then
            src_why="$(python3 tools/chip_source_check.py buzzer "$A64_KERNEL" 2>&1)"
        fi
        rm -f $AZOS_OUT/build/disk-aarch64-drvbase.img $AZOS_OUT/build/disk-aarch64-drv.img
        if ! make $AZOS_OUT/build/disk-aarch64-drv.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-drv.img"; return
        fi
        cp $AZOS_OUT/build/disk-aarch64-drv.img "$img"
        kimg="$CI_LOG_DIR/${tag}-kernel.img"
        cp "$A64_IMG" "$kimg"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic \
            -kernel "$kimg" \
            -global virtio-mmio.force-legacy=false \
            -drive file="$img",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 480 ]; do
        grep -aqE "$until" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    sleep 1
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$img"; [ -n "$kimg" ] && rm -f "$kimg"

    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      kernel panic or fatal exception:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local why=""
    case "$kind" in
        ina-kernel)
            grep -aqE "\[DRV1\] ina219 PASS 7400 mV 1500 mA [0-9]+% \(kernel tid=" "$log" \
                || why="no '[DRV1] ina219 PASS 7400 mV 1500 mA .. (kernel tid=' line"
            grep -aqF "[DRV1] ina219 FAIL" "$log" && why="an ina219 FAIL line"
            ;;
        ina-canary)
            grep -aqF "[DRV1] ina219 FAIL: placement is kernel but the topology declares" "$log" \
                || why="the canary did not fail on the placement check"
            ;;
        restart)
            grep -aqF "[RESTART] PASS" "$log" || why="no [RESTART] PASS"
            grep -aqF "[RESTART] FAIL" "$log" && why="a [RESTART] FAIL line"
            ;;
        restart-canary)
            grep -aqF "[RESTART] FAIL buzzer restarted under restart = no" "$log" \
                || why="the canary did not fail on the restarted buzzer"
            ;;
        buzz-kernel)
            grep -aqE "\[DRV1\] buzzer PASS .*\(kernel tid=" "$log" \
                || why="no '[DRV1] buzzer PASS ... (kernel tid=' line"
            grep -aqF "[DRV1] buzzer FAIL" "$log" && why="a buzzer FAIL line"
            grep -aqF "[DRV1] ina219 FAIL" "$log" && why="an ina219 FAIL line"
            [ -n "$src_why" ] && why="$src_why"
            ;;
    esac
    if [ -z "$why" ]; then
        ok
        # The read path's cost in this placement (wall clock under TCG;
        # informational, the instruction counts are an -icount boot's).
        grep -a "ina219 read path" "$log" | tr -d '\r' | sed -n '1s|^|      |p'
        rm -f "$log"
    else
        bad; echo "      $why"
        grep -aE "\[DRV1\] (ina219|buzzer)|\[RESTART\]|\[INA219\]|\[BUZZER\]|\[SUP\]" "$log" | tr -d '\r' \
            | sed -n '1,12p' | sed 's|^|        |'
        echo "      log kept: $log"
    fi
}

# The build bucket: the drivers crate told "kernel" (`azos_drv_sensor/
# ina219-kernel`) while the topology still declares INADRV.ELF must not link
# (`kernel/src/tasks/ina219_host.rs`); green only on that assertion's text.
drvplace_build_canary_row() { # <label> <isa: rv|arm|x86>
    local label="$1" isa="$2" out
    local feat="ina219-placement-build-canary"
    local text="DRV_INA219_PLACEMENT: the drivers crate and the topology disagree"
    printf "  %-26s" "${label}..."
    if [ "$isa" = "rv" ]; then
        out="$("$CARGO" build --release --features "qemu,$feat" 2>&1)"
    elif [ "$isa" = "x86" ]; then
        # The x86_64 kernel's own build (`make x86_64`): its features come
        # from the Kconfig expansion, the canary's on top.
        out="$(make x86_64 X86_64_FEATURES="$feat" 2>&1)"
    else
        out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$AARCH64_CONFIG" "$CARGO" build \
            --release --target aarch64-unknown-none-softfloat -p azos_kernel \
            --features "qemu,$feat" \
            --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)"
    fi
    if printf '%s\n' "$out" | qgrep -qF "$text"; then
        ok
    else
        bad; echo "      the mismatched placement built, or failed on something else:"
        printf '%s\n' "$out" | grep -E "^error" | head -3 | sed 's|^|        |'
    fi
    if [ "$isa" = "arm" ]; then a64_kbuild "qemu" || true; fi
}

par "aarch64 INA219 placed in kernel" drvplace_row "aarch64 INA219 placed in kernel" arm "qemu,ring3-drv-smoke,ina219-kernel" ina-kernel
a64_kbuild "qemu" || true
par "aarch64 INA219 placement canary" drvplace_row "aarch64 INA219 placement canary" arm "qemu,ring3-drv-smoke,ina219-placement-canary" ina-canary
a64_kbuild "qemu" || true
ci_row "aarch64 INA219 placement build canary" drvplace_build_canary_row "aarch64 INA219 placement build canary" arm
par "aarch64 restart = no" drvplace_row "aarch64 restart = no" arm "qemu,restart-smoke" restart
a64_kbuild "qemu" || true
par "aarch64 restart key canary" drvplace_row "aarch64 restart key canary" arm "qemu,restart-canary" restart-canary
a64_kbuild "qemu" || true
par "aarch64 buzzer placed in kernel" drvplace_row "aarch64 buzzer placed in kernel" arm "qemu,ring3-drv-smoke,buzzer-kernel" buzz-kernel
a64_kbuild "qemu" || true

# ── Guard-page fault proof (aarch64 parity program, task 1) ─────────────────
#
# `aarch64_kernel_row` above proves the guard PTEs are gone (readback) — it
# does NOT prove a real access actually traps there instead of, say, reading
# stale data from a TLB entry `unmap()` forgot to flush. These two rows each
# rebuild the kernel with ONE opt-in feature (`kernel/Cargo.toml`) that makes
# `kernel_main` deliberately write to the guard it just installed and never
# return — the boot is expected to die in the SAME "[FATAL] aarch64 kernel
# page fault" path an accidental kernel-mode overflow/null-deref would hit
# (`entry::aarch64::handle_page_fault`); this is not new fault-handling
# policy, just a scripted trigger for the policy already there. The address
# is read back from THIS boot's own log twice — once from the probe's own
# announcement, once from the FATAL line — and compared, rather than pinned
# to a literal: the guard address depends on where `TASK_STACKS` lands in
# .bss, which can shift with unrelated code changes.
# ── mem quota: the KERNEL's own refusal counter, read as a number ──────────
#
# The existing `mem-quota-canary` row infers the refusal from abitest's own
# report (`map granted N of 256`, 0 < N < 256). This one reads `mm_quota_refusals()` —
# printed by the ipc-census dump as `mem quota refused=N` — and requires
# N >= 1. A counter stuck at its initial value still prints a line matching
# the text, so only the NUMBER distinguishes a wired quota from a dead one.
#
# It also builds `mem-quota-canary` + `ipc-census` in one boot, a combination
# the suite had never run. Relevant now because 2026-09-25 moved this exact
# arithmetic out of `scheduler.rs`'s inline fields into
# `crates/core/mm::budget::PageBudget` — the host tests cover the struct, this row
# covers the kernel that ships it.
#
# Hand-rolled, not `qemu_run`: that helper deletes its log on success and this
# row must read the log AFTER the marker to parse the count out of it.
#
# Helpers: `kbuild`, `make_disk`, `ok`, `bad`, `$QEMU`, `$KERNEL`,
# `$CI_LOG_DIR` — all defined near the top of this file.
mm_quota_refused_row() {
    if ! kbuild "qemu,mem-quota-canary,ipc-census"; then return; fi

    printf "  %-26s" "mem quota: refusals>0 (N)..."
    mkdir -p "$CI_LOG_DIR"
    local log="$CI_LOG_DIR/mm-quota-refusals-numeric.log"
    rm -f "$log"

    rm -f $AZOS_OUT/build/disk-abitest.img
    make_disk $AZOS_OUT/build/disk-abitest.img
    job_disk $AZOS_OUT/build/disk-abitest.img

    par_ready
    "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file="$JDISK",if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    local pid=$! i=0
    # Two positive waits, each anchored on its own cause, no count:
    #   1. the refusal must have actually happened (abitest's own report).
    #   2. AFTER that, a census dump must have printed the counter non-zero
    #      (the counter only counts up, so once non-zero it stays non-zero —
    #      this is not a race, it is "wait for the next dump to have fired").
    # Kept as two loops rather than one combined regex so a boot that never
    # reaches step 1 reports THAT, not a generic timeout.
    while [ "$i" -lt 360 ]; do
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
            bad; echo "      kernel panic or fatal exception:"
            grep -aiE -m3 "panic|\[FATAL\]" "$log" | sed 's/^/      /'
            return
        fi
        if grep -aqE "map granted (0|256) of 256 pages" "$log" 2>/dev/null; then
            kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
            bad; echo "      canary build did not bind as intended: map granted 0 or 256 of 256"
            return
        fi
        grep -aqE "map granted [1-9][0-9]* of 256 pages" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    while [ "$i" -lt 360 ]; do
        grep -aqE 'mem quota refused=[1-9]' "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null

    # Read the NUMBER back rather than matching a line: a counter stuck at
    # its initial value (0) still prints a line matching
    # "mem quota refused=[0-9]+", so a text match alone cannot tell a wired
    # quota from a dead one. Last occurrence via `sed -n '$p'`
    # (no `tail` — SHELL RULES), since the counter is monotonically
    # non-decreasing across the boot.
    local n
    n="$(grep -aoE 'mem quota refused=[0-9]+' "$log" 2>/dev/null | sed -n '$p' | grep -oE '[0-9]+$')"

    if [ -n "$n" ] && [ "$n" -ge 1 ] 2>/dev/null; then
        ok; rm -f "$log"
    else
        bad
        echo "      mm_quota_refusals() never read back non-zero (got: '${n:-<no line found>}')"
        echo "      a quota that never refuses is indistinguishable from one that is not wired"
        echo "      full log kept: $log"
    fi
}
par "mem quota: refusals>0 (N)" mm_quota_refused_row
# Leave $KERNEL on the ordinary qemu build for anything below that forgets.
kbuild "qemu"

# ── fork refusals name themselves, on BOTH ISAs ────────────────────────────
#
# `sys_fork_impl` refuses from SIX distinct sites and every one of them
# returned a bare `-1` until 2026-09-25. That ambiguity cost a week: an
# aarch64 `fork+exit` `rc=-1` was mis-filed as a known gap because a `-1` in a
# log cannot say WHICH site fired (30 runs across 5 committed trees later
# produced no failure at all — it had been a measurement artefact).
#
# Each site now bumps its own counter and prints `[FORK] refusal site first
# hit: <name>` once, on the 0→1 transition, unconditionally and on both ISAs.
# **A counter no row observes is indistinguishable from one that is not
# wired**, and a FEATURE no scenario runs is the `rvv` trap all over again, so
# these two rows make site 1 fire and read the result back.
#
# The probe (`kernel/src/main.rs`, `--features fork-refusal-probe`) calls fork
# from kernel context just before the scheduler starts, where
# `current_user_pt()` is 0 — site 1's exact test. It allocates nothing and
# cannot reach the five later sites; see the probe's own comment.
#
# Hand-rolled, not `qemu_run`: `-1` here is the PROPERTY, and `qemu_run`'s
# failure set is not the right judge of a boot whose point is a refusal.
#
# Helpers: `kbuild` / `a64_kbuild`, `ok`, `bad`, `$QEMU`, `$KERNEL`,
# `$A64_IMG`, `$CI_LOG_DIR`.
fork_refusal_probe_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2"
    printf "  %-26s" "${label}..."
    local log="$CI_LOG_DIR/$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-').log"
    mkdir -p "$CI_LOG_DIR"; rm -f "$log"
    local img_copy=""
    if [ "$isa" = "rv" ]; then
        if ! kbuild "qemu,fork-refusal-probe"; then
            bad; echo "      riscv64 kernel (qemu,fork-refusal-probe) did not build"; return
        fi
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 4 \
            >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu,fork-refusal-probe"; then
            bad; echo "      aarch64 kernel (qemu,fork-refusal-probe) did not build"; return
        fi
        img_copy="$CI_LOG_DIR/kernel-fork-probe.img"
        cp "$A64_IMG" "$img_copy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$img_copy" >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 60 ]; do
        grep -aqF "[FORK] refusal probe: rc=" "$log" 2>/dev/null && break
        grep -aqF "AARCH64-TRAP] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 0.5
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null

    # 1. The probe ran at all.
    if ! grep -aqF "[FORK] refusal probe: calling fork from kernel context" "$log" 2>/dev/null; then
        bad; echo "      the probe never ran — the feature did not reach the boot:"
        grep -a "FORK" "$log" | tr -d '\r' | sed -n '1,4p' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    # 2. The diagnostic NAMED the site. This is the whole point of the change:
    #    before it, this boot would have produced a bare -1 and nothing else.
    #    The literal is the SITE NAME as `fork_refusal_site_name` prints it
    #    (`kernel-task`), not the enum variant — hand-running this row is what
    #    caught the difference before the gate did.
    if ! grep -aqF "[FORK] refusal site first hit: kernel-task" "$log" 2>/dev/null; then
        bad; echo "      fork refused but the diagnostic did not name the site:"
        grep -a "FORK" "$log" | tr -d '\r' | sed -n '1,6p' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    # 3. Read the RETURN VALUE back, not just the line. A probe that printed
    #    its banner and then returned 0 would satisfy 1 and 2 on a kernel that
    #    had stopped refusing.
    local rc
    rc="$(grep -a "\[FORK\] refusal probe: rc=" "$log" | tr -d '\r' \
          | sed -n '1s/.*rc=\(-\{0,1\}[0-9][0-9]*\).*/\1/p')"
    if [ "${rc:-unset}" != "-1" ]; then
        bad; echo "      fork from kernel context returned '${rc:-<no rc line>}', not -1"
        grep -a "FORK" "$log" | tr -d '\r' | sed -n '1,4p' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    ok; rm -f "$log"; [ -n "$img_copy" ] && rm -f "$img_copy"
    return 0
}
par "fork refusal names its site" fork_refusal_probe_row "fork refusal names its site" rv
par "aarch64 fork refusal site" fork_refusal_probe_row "aarch64 fork refusal site"  arm

# ── exit: the parent's wait returns after the child's teardown, BOTH ISAs ───
#
# Wave 11 (EXIT2). `task_exit_with_code` publishes the exit notice AFTER the
# exit hook and the address-space teardown (Linux's `exit_mm` before
# `exit_notify`), so a parent that reaps and forks again never races a
# half-torn-down child. abitest's `check_exit_storm` starts 64 children one at
# a time (`SYS_SPAWN_EX`), reaps each with `waitpid` (sleeping between looks),
# reads the free pages AT the reap, and prints the kernel's exit-path counters
# (the domain's `DOMAIN_EXIT_STATS` op) around the storm on one line:
#
#   exit storm: spawns=64 reaped=64 exit_teardowns=+N reuse=0 early=0 short=0
#
# Every number is read back: N >= 64 (each child freed its own address space
# on its exit path), `reuse` 0 (no slot claim found a previous tenant's
# address space: the K-C22(B) fallback), `early` 0 (no notice published while
# its task still held its address space), `short` 0 (free pages back when
# `waitpid` returned).
#
# Canaries, run by hand on both ISAs: `note_exit` moved back
# above the exit hook -> `early=64` (and `short` > 0 in some runs, both ISAs); an early
# `return` in `release_address_space_at_exit` -> `exit_teardowns=+0 reuse=64`.
exit_storm_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "qemu"; then bad; echo "      riscv64 kernel (qemu) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu"; then bad; echo "      aarch64 kernel (qemu) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 180 ]; do
        grep -aqF "[ABITEST] exit storm: spawns=" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if grep -aq "\[MM\] page-table root" "$log" 2>/dev/null; then
        bad; echo "      a teardown found its root still live:"
        grep -a -m3 "\[MM\] page-table root" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local line
    line="$(grep -a "\[ABITEST\] exit storm: spawns=" "$log" | tr -d '\r' | sed -n '1p')"
    if [ -z "$line" ]; then
        bad; echo "      abitest never printed its exit-storm line"
        echo "      log kept: $log"; return
    fi
    num() { printf '%s\n' "$line" | sed -n "s/.* $1=+\{0,1\}\([0-9][0-9]*\).*/\1/p"; }
    local spawns reaped exits reuse early short
    spawns="$(num spawns)"; reaped="$(num reaped)"; exits="$(num exit_teardowns)"
    reuse="$(num reuse)"; early="$(num early)"; short="$(num short)"
    if [ "${spawns:-x}" = 64 ] && [ "${reaped:-x}" = 64 ] && [ "${exits:-0}" -ge 64 ] 2>/dev/null \
        && [ "${reuse:-x}" = 0 ] && [ "${early:-x}" = 0 ] && [ "${short:-x}" = 0 ]; then
        ok; rm -f "$log"; return
    fi
    bad; echo "      want spawns=64 reaped=64 exit_teardowns>=+64 reuse=0 early=0 short=0, read:"
    echo "        $line"
    echo "      log kept: $log"
}
par "exit: notice after teardown" exit_storm_row "exit: notice after teardown" rv
par "aarch64 exit notice order" exit_storm_row "aarch64 exit notice order"  arm

# Wave 12 (EXIT2): an unreaped child's exit notice is kept until its parent
# reaps it or exits, as Linux keeps a zombie. The notice table has one entry
# per task slot and a child with a parent is created only while the queued
# notices leave a slot for it (`exit_note::admits`), so no notice is dropped:
# a parent that never waits gets its next child refused. abitest's
# `check_unreaped_children_are_kept` starts children that exit at once, reaps
# none until a spawn is refused, then reaps each by name:
#
#   zombies: spawned=N refused=yes reaped=N drops=0 refusals=+K
#
# Read back: refused, reaped = spawned > 0, drops (`EXIT_STAT_NOTICE_DROPS`) 0,
# refusals (`EXIT_STAT_NOTICE_REFUSALS`) >= 1. Canary, by hand on both ISAs
# (2026-10-03): `exit_note::admits` answering true -> refused=no, spawned=512,
# reaped < 512, drops > 0.
zombie_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "qemu"; then bad; echo "      riscv64 kernel (qemu) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu"; then bad; echo "      aarch64 kernel (qemu) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 240 ]; do
        grep -aqF "[ABITEST] zombies: spawned=" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local line
    line="$(grep -a "\[ABITEST\] zombies: spawned=" "$log" | tr -d '\r' | sed -n '1p')"
    if [ -z "$line" ]; then
        bad; echo "      abitest never printed its zombies line"
        echo "      log kept: $log"; return
    fi
    znum() { printf '%s\n' "$line" | sed -n "s/.* $1=+\{0,1\}\([0-9][0-9]*\).*/\1/p"; }
    local spawned reaped drops refusals
    spawned="$(znum spawned)"; reaped="$(znum reaped)"; drops="$(znum drops)"; refusals="$(znum refusals)"
    if printf '%s\n' "$line" | qgrep -qF " refused=yes " \
        && [ "${spawned:-0}" -ge 1 ] 2>/dev/null && [ "${reaped:-x}" = "$spawned" ] \
        && [ "${drops:-x}" = 0 ] && [ "${refusals:-0}" -ge 1 ] 2>/dev/null; then
        ok; rm -f "$log"; return
    fi
    bad; echo "      want refused=yes reaped=spawned>0 drops=0 refusals>=+1, read:"
    echo "        $line"
    echo "      log kept: $log"
}
par_row zombie_row "exit: unreaped notices kept" rv
par_row zombie_row "aarch64 unreaped notices"    arm

# ── plan item 7: a killed client reaches its exit path, BOTH ISAs ───────────
#
# Every per-client release (ports, shm, fast-IPC slots, sockets, fds)
# runs from the exit hook, so a forced kill that leaves its target blocked
# releases nothing. ipctest's phase K forks children that block where nothing
# will wake them (a futex wait with no deadline, a port wait, an idle
# fast-IPC accept, a 30 s sleep), force-kills each with signal 9, and reads
# the status it is reaped with within 3 s:
#
#   [IPCTEST] killed waits: notify=137 port=137 accept=137 sleep=137
#
# -1 is a child the kill never ended. The row reads the line, not the run's
# verdict: phase A after it has a stall detector of its own (`userspace: IPC`).
#
# Canaries, run by hand (plan item 7 report; on riscv64 the unfixed kernel
# read -1 for all four, the same children run from abitest):
# `--features qemu,kill-wake-timer-only-canary` -> port=-1 accept=-1 (rv);
# `kill-reblock-canary` -> all four -1 (rv, arm).
dead_client_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "qemu"; then bad; echo "      riscv64 kernel (qemu) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-ipctest.img
        make_disk $AZOS_OUT/build/disk-ipctest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-ipctest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu"; then bad; echo "      aarch64 kernel (qemu) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0
    while [ "$i" -lt 240 ]; do
        grep -aqF "[IPCTEST] killed waits: notify=" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local line
    line="$(grep -a "\[IPCTEST\] killed waits: notify=" "$log" | tr -d '\r' | sed -n '1p')"
    if [ -z "$line" ]; then
        bad; echo "      ipctest never printed its killed-waits line"
        echo "      log kept: $log"; return
    fi
    num() { printf '%s\n' "$line" | sed -n "s/.* $1=\(-\{0,1\}[0-9][0-9]*\).*/\1/p"; }
    if [ "$(num notify)" = 137 ] && [ "$(num port)" = 137 ] && [ "$(num accept)" = 137 ] \
        && [ "$(num sleep)" = 137 ]; then
        ok; rm -f "$log"; return
    fi
    bad; echo "      want notify=137 port=137 accept=137 sleep=137, read:"
    echo "        $line"
    echo "      log kept: $log"
}
par "kill: dead client released" dead_client_row "kill: dead client released" rv
par "aarch64 dead client"        dead_client_row "aarch64 dead client"        arm

# ── fork: a parent's runtime handles are stale in its child, BOTH ISAs ──────
#
# A fork child (`SYS_FOREIGN_FORK`, `crates/core/syscall/src/natfork.rs`)
# inherits its parent's descriptors and is seeded from its own row; every
# other parent handle (a port, an unmapped region, an io_ring) is installed as
# a placeholder while the table is built and removed at the end, so it is
# stale in the child. ipctest's phase C forks a stranger that sweeps the
# parent's own port, region and ring handles and must get `-ECAPSTALE` from
# each (the pass half is `userspace: IPC` and `aarch64 ipctest`). Canary
# `native-fork-copy-canary` keeps the placeholders, as the reverted
# 2026-09-21 copy kept the parent's table: the stranger resolves them, and
# this row requires ipctest's own failure line for it. (The hosted runtime's
# lxhello cannot see this: its parent holds only its row and descriptors, so
# no placeholder is left to keep.)
fork_stale_canary_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "qemu,native-fork-copy-canary"; then bad; echo "      riscv64 kernel (native-fork-copy-canary) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-ipctest.img
        make_disk $AZOS_OUT/build/disk-ipctest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-ipctest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "qemu,native-fork-copy-canary"; then bad; echo "      aarch64 kernel (native-fork-copy-canary) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    # The sweep's verdicts come after the guesser posts (or after ipctest
    # stops waiting for it: a wait on a resolved port can block), then the
    # owner's checks; the row stops at the owner's first one.
    local pid=$! i=0 want='\[IPCTEST\]  FAIL  C/(stranger resolved no|guesser reported) '
    while [ "$i" -lt 240 ]; do
        grep -aqF "C/owner port_poll_typed still resolves" "$log" 2>/dev/null && break
        grep -aqE "IPCTEST\] (ALL PASSED|FAILED)" "$log" 2>/dev/null && break
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "panic|\[FATAL\]|AARCH64-TRAP" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if grep -aqE "$want" "$log" 2>/dev/null; then
        ok; rm -f "$log"; return
    fi
    bad; echo "      the stranger resolved none of its parent's handles: the row does not discriminate"
    grep -aE "C/(stranger|guesser)" "$log" | tr -d '\r' | sed -n '1,3p' | sed 's|^|        |'
    echo "      log kept: $log"
}
par "fork: stale parent handles canary (rv)"  fork_stale_canary_row "fork: stale parent handles canary (rv)"  rv
par "fork: stale parent handles canary (arm)" fork_stale_canary_row "fork: stale parent handles canary (arm)" arm

# ── inspect: a view region needs its grant, BOTH ISAs ───────────────────────
#
# The kernel keeps no /proc: the topology wiring a service reads is in a view
# region of the introspection tree (`inspect.names`, `.rpc`, `.mcp`,
# `.components`, `.logins`, `.clock`), granted only to the rows that declare
# it. abitest's `check_views` (the autorun row: the task view, the public and
# the admin regions, no view) prints
#
#   views: public=1 admin=1 views=0
#
# and its fourteen `views:` checks: the public and the admin region granted,
# each of the six view keys finding no capability, the public region naming
# no task, and a child it starts listed under it in the admin task list when
# the spawn returns, off the list when its reap returns, and reaped. The list
# is read with no wait: the kernel writes a task's row where the task changes.
# Read back: views=0, fourteen `ok` lines, no `FAIL`. The canary row boots
# `inspect-view-canary` (every published view granted with the public region)
# and must see views>0 and a `... is not granted` check fail; the stale row
# boots `task-view-stale-canary` (a task's row written at the next refresh,
# not where it changes) and must see a task-list check about the child fail.
views_row() { # <label> <isa: rv|arm> <features> <held|canary|stale>
    local label="$1" isa="$2" feats="$3" want="$4"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "$feats"; then bad; echo "      riscv64 kernel ($feats) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "$feats"; then bad; echo "      aarch64 kernel ($feats) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0 fault='panic|\[FATAL\]|AARCH64-TRAP\] unhandled'
    while [ "$i" -lt 180 ]; do
        grep -aqF "views: the child is reaped" "$log" 2>/dev/null && break
        grep -aqiE "$fault" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    if grep -aqiE "$fault" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "$fault" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    local line views oks fails
    line="$(grep -a "\[ABITEST\] views: public=" "$log" | tr -d '\r' | sed -n '1p')"
    if [ -z "$line" ] || ! grep -aqF "views: the child is reaped" "$log"; then
        bad; echo "      abitest never finished its view check"
        echo "      log kept: $log"; return
    fi
    views="$(printf '%s\n' "$line" | sed -n 's/.* views=\([0-9][0-9]*\).*/\1/p')"
    oks="$(grep -a "\[ABITEST\]   ok   views: " "$log" | wc -l | tr -d ' ')"
    fails="$(grep -a "\[ABITEST\]  FAIL  views: " "$log" | tr -d '\r')"
    if [ "$want" = held ]; then
        if [ "${views:-x}" = 0 ] && [ "$oks" = 14 ] && [ -z "$fails" ]; then
            ok; rm -f "$log"; return
        fi
        bad; echo "      want views=0, 14 ok and no FAIL views lines; read ($oks ok):"
    elif [ "$want" = stale ]; then
        if printf '%s\n' "$fails" | qgrep -qE "task list shows the child|reaped child is off the task list"; then
            ok; rm -f "$log"; return
        fi
        bad; echo "      the canary (task rows written at the next refresh) failed no task-list check; read ($oks ok):"
    else
        if [ "${views:-0}" -gt 0 ] 2>/dev/null && printf '%s\n' "$fails" | qgrep -qF "is not granted"; then
            ok; rm -f "$log"; return
        fi
        bad; echo "      the canary (views granted with the public region) granted none; read ($oks ok):"
    fi
    echo "        $line"
    [ -n "$fails" ] && printf '%s\n' "$fails" | sed -n '1,6s|^|        |p'
    echo "      log kept: $log"
}
par_row views_row "inspect: views need their grant"          rv  qemu held
par_row views_row "aarch64 inspect: views need their grant"  arm qemu held
par_row views_row "inspect: views canary"                    rv  qemu,inspect-view-canary canary
par_row views_row "aarch64 inspect: views canary"            arm qemu,inspect-view-canary canary
par_row views_row "inspect: task list stale canary"          rv  qemu,task-view-stale-canary stale
par_row views_row "aarch64 inspect: task list stale canary"  arm qemu,task-view-stale-canary stale

# ── sysabi: the native syscall register contract (Chain E commit 8) ─────────
#
# Every native syscall preserves the callee-saved registers, sp/gp/tp and its
# outputs, and nothing else (crates/core/abi/src/syscall_nr.rs, "Register
# contract"); Kconfig SYSCALL_LEAN_ENTRY takes a native task's syscall on a
# trap path that stores only those and returns the clobbered registers zero.
# abitest's `sysabi:` checks fill the callee-saved file and the clobbered
# registers with patterns around getpid, yield and cap_info and read them
# back: the three `survive` checks and `clobbered registers come back zero or
# as passed` run in every abitest row (rv "userspace: ABI conformance",
# "aarch64 abitest", "x86_64 abitest"). The canary rows boot
# `syscall-abi-canary`: the native exit flips bit 0 of one callee-saved
# register (s3, x20, rbx) when the call's second argument register holds
# SYSCALL_ABI_CANARY_A1, which only those probes pass. The three `survive`
# checks of calls that return through that exit must FAIL; the
# clobbered-register check must still pass. x86_64's twin is
# `x86_64 abitest sysabi canary` (x86_autorun_row).
sysabi_canary_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2" feats="qemu,syscall-abi-canary"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "$feats"; then bad; echo "      riscv64 kernel ($feats) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "$feats"; then bad; echo "      aarch64 kernel ($feats) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0 fault='panic|\[FATAL\]|AARCH64-TRAP\] unhandled'
    while [ "$i" -lt 180 ]; do
        grep -aqF "sysabi: clobbered registers come back" "$log" 2>/dev/null && break
        grep -aqiE "$fault" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    sysabi_canary_judge "$log"
}
# sysabi_canary_judge <log>: the canary's verdict, shared with x86_64's row.
sysabi_canary_judge() {
    local log="$1" why="" w fails oks
    if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled|KERNEL PANIC' "$log" 2>/dev/null; then
        why="the kernel faulted: $(grep -aiE -m1 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" | tr -d '\r')"
    elif ! grep -aqF "sysabi: clobbered registers come back" "$log"; then
        why="abitest never finished its sysabi checks"
    else
        fails="$(grep -a '\[ABITEST\]  FAIL  sysabi: ' "$log" | tr -d '\r')"
        oks="$(grep -a '\[ABITEST\]   ok   sysabi: ' "$log" | tr -d '\r')"
        for w in "survive getpid" "survive yield" "survive cap_info"; do
            printf '%s\n' "$fails" | qgrep -qF "$w" || { why="the canary did not turn red: $w"; break; }
        done
        if [ -z "$why" ]; then
            for w in "clobbered registers come back zero or as passed"; do
                printf '%s\n' "$oks" | qgrep -qF "$w" || { why="not the canary's failure alone: $w did not pass"; break; }
            done
        fi
    fi
    if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
    bad; echo "      $why"
    grep -a 'sysabi: ' "$log" | tr -d '\r' | sed -n '1,8s|^|        |p'
    echo "      log kept: $log"
}
# D6 (`crates/core/abi/src/foreign.rs`): abitest's foreign-ABI probe (a child
# process, `abichild`'s `foreign` mode, registers a trap entry and resumes into
# a foreign program that traps three times) must fail when a resume does not restore the registers of its
# frame: the kernel built with `foreign-regs-canary` zeroes all but the stack
# pointer, the program counter and the result, and the probe's kept register
# comes back 0. That check alone must be red.
foreign_canary_row() { # <label> <isa: rv|arm>
    local label="$1" isa="$2" feats="qemu,foreign-regs-canary"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "$feats"; then bad; echo "      riscv64 kernel ($feats) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "$feats"; then bad; echo "      aarch64 kernel ($feats) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0 fault='panic|\[FATAL\]|AARCH64-TRAP\] unhandled'
    while [ "$i" -lt 180 ]; do
        grep -aqE "ABITEST\] [0-9]+ check\(s\) run" "$log" 2>/dev/null && break
        grep -aqiE "$fault" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    sleep 1; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    foreign_canary_judge "$log"
}
# foreign_canary_judge <log>: the canary's verdict, shared with x86_64's row.
foreign_canary_judge() {
    local log="$1" why="" fails
    if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled|KERNEL PANIC' "$log" 2>/dev/null; then
        why="the kernel faulted: $(grep -aiE -m1 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" | tr -d '\r')"
    elif ! grep -aqE "ABITEST\] [0-9]+ check\(s\) run" "$log"; then
        why="abitest never printed its own summary line"
    else
        # Narrowed to the family's own checks, as `sysabi_canary_judge` is to
        # `sysabi: `: abitest has failures of its own on some ISAs (aarch64's
        # vDSO flag, x86_64's endpoint lookup) that are not this canary's.
        fails="$(grep -a '\[ABITEST\]  FAIL  foreign: ' "$log" | tr -d '\r')"
        oks="$(grep -a '\[ABITEST\]   ok   foreign: ' "$log" | tr -d '\r')"
        if ! printf '%s\n' "$fails" | qgrep -qF "three traps reflected, answered and resumed"; then
            why="the canary did not turn the foreign check red"
        elif [ "$(printf '%s\n' "$fails" | grep -c .)" != 1 ]; then
            why="not the canary's failure alone: $(printf '%s\n' "$fails" | sed -n 1,4p | tr '\n' ';')"
        else
            for w in "spawn the probe child" "the probe child is reaped"; do
                printf '%s\n' "$oks" | qgrep -qF "$w" || { why="not the canary's failure alone: foreign: $w did not pass"; break; }
            done
        fi
    fi
    if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
    bad; echo "      $why"
    echo "      log kept: $log"
}
par_row foreign_canary_row "foreign: canary, resume drops the frame (rv)"  rv
par_row foreign_canary_row "foreign: canary, resume drops the frame (arm)" arm
par_row sysabi_canary_row "sysabi: canary, callee-saved bit lost (rv)"  rv
par_row sysabi_canary_row "sysabi: canary, callee-saved bit lost (arm)" arm

# ── threads: native thread groups (wave 13, THREADS) ──────────────────────
#
# abitest's `check_threads` prints seventeen `threads:` checks: two threads
# and the main thread contend on a futex lock over shared memory (the plain
# count exact), joins through the cleared clear-tid word, the futex answers
# (EAGAIN, ETIMEDOUT, a wake that wakes a parked waiter), a thread uses the
# creator's file handle and the creator the thread's (one capability table,
# one descriptor table), getpid is the process's, the kernel's task list
# shows the thread, and `exit` from one thread
# ends every thread. Canaries: `threads-private-table-canary` (a thread gets
# its own table: the handle checks fail), `futex-wake-noop-canary` (a wake
# wakes nobody: the wake check fails), `threads-no-cleartid-canary` (the word
# is never cleared: the joins fail). `threads-late-start-canary` starts every
# thread 100 ms late, as a loaded host does, and the row must stay green: no
# thread check may use a sleep as proof that a thread reached its wait. The
# wake check did (`sleep(50)`, then one wake) and failed 4 boots in 30 of the
# `vdso-write-window` row under gate load; with the old check this canary
# failed it 2/2.
#
# The thread storm (abitest's `check_thread_storm`, before these checks;
# CTXHUNT 2026-10-08): child processes whose spinning threads their exit must
# stop, threads that exit at once, and children whose thread faults while
# they exit, 200 rounds. Before the fixes it faulted the kernel in about a
# second, 10/10 loaded boots on each ISA. `exit-stale-hart-canary` (the exit
# path's stale hart id) and `reap-window-canary` (a Zombie's stack freed
# before its hart left it) must fault or wedge the kernel (`kbroken`).
# (`cow-spurious-canary`, a COW fault on an entry another thread just broke
# kills the thread, needs a COW copy of a process: only a hosted fork makes
# one, and no gate row takes it over yet.)
threads_row() { # <label> <isa: rv|arm> <features> <ok|privtable|futexnoop|noclear|kbroken>
    local label="$1" isa="$2" feats="$3" want="$4"
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR"
    local slug log kcopy dcopy
    slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
    log="$CI_LOG_DIR/${slug}.log"; kcopy="$CI_LOG_DIR/${slug}-kernel"; dcopy="$CI_LOG_DIR/${slug}-disk.img"
    rm -f "$log" "$kcopy" "$dcopy"
    if [ "$isa" = rv ]; then
        if ! kbuild "$feats"; then bad; echo "      riscv64 kernel ($feats) did not build"; return; fi
        rm -f $AZOS_OUT/build/disk-abitest.img
        make_disk $AZOS_OUT/build/disk-abitest.img
        cp "$KERNEL" "$kcopy"; cp $AZOS_OUT/build/disk-abitest.img "$dcopy"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$kcopy" -smp 4 \
            -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    else
        if ! a64_kbuild "$feats"; then bad; echo "      aarch64 kernel ($feats) did not build"; return; fi
        if ! make $AZOS_OUT/build/disk-aarch64-abitest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-abitest.img"; return
        fi
        cp "$A64_IMG" "$kcopy"; cp $AZOS_OUT/build/disk-aarch64-abitest.img "$dcopy"
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
            -kernel "$kcopy" -global virtio-mmio.force-legacy=false \
            -drive file="$dcopy",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
    fi
    local pid=$! i=0 fault='panic|\[FATAL\]|AARCH64-TRAP\] unhandled' last="threads: exit ends every thread"
    while [ "$i" -lt 240 ]; do
        grep -aqF "$last" "$log" 2>/dev/null && break
        grep -aqiE "$fault" "$log" 2>/dev/null && break
        kill -0 "$pid" 2>/dev/null || break
        i=$((i + 1)); sleep 1
    done
    kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    rm -f "$kcopy" "$dcopy"
    # A kernel canary (CTXHUNT) must break the kernel inside the cap: fault
    # it, or wedge it short of the thread checks (the aarch64 stale-hart
    # canary strands exits instead of faulting).
    if [ "$want" = kbroken ]; then
        if grep -aqiE "$fault" "$log" 2>/dev/null || ! grep -aqF "$last" "$log" 2>/dev/null; then
            # What broke it: the first fault line, or the wedge.
            ok; { grep -aiE -m1 -A3 "$fault" "$log" | grep -a '[^[:space:]]' | sed -n '1,4p'; grep -aqiE "$fault" "$log" || echo "wedged short of '$last'"; } | tr -d '\r' | cut -c1-160 | sed 's|^|      |'
            rm -f "$log"; return
        fi
        bad; echo "      the canary ($feats) left the kernel working"
        echo "      log kept: $log"; return
    fi
    if grep -aqiE "$fault" "$log" 2>/dev/null; then
        bad; echo "      the kernel faulted:"
        grep -aiE -m3 "$fault" "$log" | tr -d '\r' | sed 's|^|        |'
        echo "      log kept: $log"; return
    fi
    if ! grep -aqF "$last" "$log"; then
        bad; echo "      abitest never finished its thread checks"
        echo "      log kept: $log"; return
    fi
    local oks fails need
    oks="$(grep -a "\[ABITEST\]   ok   threads: " "$log" | wc -l | tr -d ' ')"
    fails="$(grep -a "\[ABITEST\]  FAIL  thread" "$log" | tr -d '\r')"
    case "$want" in
    ok)
        if [ "$oks" = 16 ] && [ -z "$fails" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      want 16 ok and no FAIL threads lines; read $oks ok:" ;;
    privtable|futexnoop|noclear)
        case "$want" in
        privtable) need="the thread read through the creator's handle" ;;
        futexnoop) need="futex_wake wakes the waiting thread" ;;
        noclear)   need="both joined through their cleared word" ;;
        esac
        if printf '%s\n' "$fails" | qgrep -qF "$need"; then
            ok; rm -f "$log"; return
        fi
        bad; echo "      the canary ($want) still passed '$need'; read $oks ok:" ;;
    esac
    [ -n "$fails" ] && printf '%s\n' "$fails" | sed -n '1,6s|^|        |p'
    echo "      log kept: $log"
}
par_row threads_row "threads: native groups"                 rv  qemu ok
par_row threads_row "aarch64 threads: native groups"         arm qemu ok
par_row threads_row "threads: private table canary"          rv  qemu,threads-private-table-canary privtable
par_row threads_row "aarch64 threads: private table canary"  arm qemu,threads-private-table-canary privtable
