# K-C5: aead-link-tests asserts the LINK_PROVISIONING_ENFORCED const in BOTH
# feature states, and the enforced arm only compiles under the feature —
# without this second run, the exact assertions written to prevent the
# secure-boot-style silently-absent-policy failure never execute. The plain
# run above covers the OFF state; this covers ON.
test_host_features() { # test_host_features <label> <crate-dir> <features>
    local label="$1" crate="$2" feats="$3" out
    ci_tier_skips "$label" && return 0
    printf "  %-26s" "${label}..."
    if host_cargo out "${crate}" test --release --features "$feats" \
       && ! echo "$out" | qgrep -q "test result: FAILED"; then
        ok
    else
        bad
        echo "$out" | sed -n 's/^---- \(.*\) stdout ----$/      failed test: \1/p'
        echo "$out" | grep -m4 -E "^error|test result: FAILED|panicked at" \
            | sed 's/^/      /'
        [ -n "${GATE_DEBUG_DIR:-}" ] && echo "$out" >"$GATE_DEBUG_DIR/hf-${label//[^A-Za-z0-9]/_}.log"
    fi
}
test_host_features "aead-link(enforced)" \
    "${REPO_ROOT}/tests/host/aead-link-tests" "enforced"

# Same two-state argument for the topology. The plain run above is a GENERIC
# board topology: it asserts no PWM channel, no GPIO pin the drivetrain owns,
# and — since 2026-09-21 — no motor capability at all. This run is the
# kernel's `qemu` shape, where `pwm.0`/`gpio.0` ARE granted so the
# `userspace: capabilities` scenario can watch them be refused, and where the
# actuation profile declares the drivetrain.
# One run alone proves only half of it: without the first, an unconditional
# grant ships to every deployment; without the second, the refusal stops being
# observable and a deleted guard looks like a missing capability.
test_host_features "topology(cap-canary)" \
    "${REPO_ROOT}/tests/host/topology-tests" "cap-refusal-canary,profile-actuation,ring3-driver-start,qemu-devices"
# The partition row's grant: `block.part.1` RW present under `disk-part-row`,
# and (the plain run above) absent everywhere else.
test_host_features "topology(disk-part)" \
    "${REPO_ROOT}/tests/host/topology-tests" "disk-part-row"
# Wave 11 (DRVPLACE): the kernel placement of the INA219 (no INADRV.ELF row)
# and the gate's `restart` rows (BUZZDRV.ELF always, INADRV.ELF no).
test_host_features "topology(drvplace)" \
    "${REPO_ROOT}/tests/host/topology-tests" "ina219-kernel,ring3-driver-start"
test_host_features "topology(restart)" \
    "${REPO_ROOT}/tests/host/topology-tests" "restart-smoke,ring3-driver-start"
# Canary: `EnergyModel::validate` accepts everything
# (`validate-canary`), so exactly the eight tests that expect a refusal (three
# in the model's own suites, five in cpuid.rs) must
# fail, and nothing else. A build error is its own FAIL (third bucket), not a
# passing canary.
if ci_row_begin "energy(validate-canary)"; then
printf "  %-26s" "energy(validate-canary)..."
if host_cargo en_out "${REPO_ROOT}/tests/host/energy-tests" test --release --features validate-canary; then
    bad; echo "      the suite passed with validation disabled: no test pins it"
# Only rustc/cargo-build print these; a failing test run ends in
# "error: test failed", which must NOT read as a build error.
elif echo "$en_out" | qgrep -qE "^error(\[E[0-9]+\]|: could not compile)"; then
    bad; echo "      did not compile:"; echo "$en_out" | grep -m3 -E "^error" | sed 's/^/        /'
else
    en_failed="$(echo "$en_out" | sed -n 's/^test \([a-z0-9_:]*\) \.\.\. FAILED$/\1/p' | sort | tr '\n' ' ')"
    en_vwant="cpuid::a_cpuid_model_that_fails_is_refused_with_its_own_fault cpuid::a_dtb_model_that_was_refused_is_not_replaced_by_cpuid cpuid::a_topology_model_that_was_refused_is_not_replaced_by_cpuid cpuid::no_clock_reading_is_a_model_the_validation_refuses cpuid::the_model_covers_the_cpus_that_started_and_validates_for_exactly_them dt::no_power_in_the_dtb_is_refused model::every_fault_is_found model::resolution_order "
    if [ "$en_failed" = "$en_vwant" ]; then
        ok
    else
        bad; echo "      expected exactly the eight refusal tests to fail: ${en_vwant}- got: ${en_failed:-none}"; ci_debug_dump "energy-validate" "$en_out"
    fi
fi
fi; ci_row_end
# Invariant canaries (wave 13): each removes one floor from
# `azos_energy` and exactly its invariant tests must fail — I1 (the
# deadline floor ignores reservations), I6 (the WCET floor is the slowest
# OPP), I3 (the idle choice ignores the RT slack). The policy canaries (owner
# plan Energy section 8) remove one limit of `azos_energy::policy` each: the
# OPP-range setter's floors (pl-floor), the evaluation-time clamp's floors
# (pl-clamp), the refusal record (pl-record). Same three buckets.
for en_c in "i1:governor::deadline_floor_covers_admitted_density_with_margin governor::i1_and_i6_hold_everywhere policy::a_cap_the_floors_override_is_counted policy::opp_cap_respects_the_deadline_floor " \
            "i6:governor::i1_and_i6_hold_everywhere governor::safety_floor_is_the_first_opp_at_the_wcet_reference policy::a_refusal_is_recorded policy::opp_cap_respects_the_safety_floor " \
            "i3:dt::teo_picks_the_deepest_dt_state_that_fits_the_timer idle::i3_holds_for_any_history idle::rt_slack_caps_the_exit_latency " \
            "pl-floor:policy::a_refusal_is_recorded policy::opp_cap_respects_the_deadline_floor policy::opp_cap_respects_the_safety_floor " \
            "pl-clamp:policy::a_cap_the_floors_override_is_counted policy::clamp_never_lowers_a_floor " \
            "pl-record:policy::a_refusal_is_recorded "; do
    en_f="${en_c%%:*}"; en_want="${en_c#*:}"
    ci_row_begin "energy(${en_f}-canary)" || { ci_row_end; continue; }
    printf "  %-26s" "energy(${en_f}-canary)..."
    if en_out=$( (cd "${REPO_ROOT}/tests/host/energy-tests" && "$CARGO" test --release --features "${en_f}-canary" 2>&1) ); then
        bad; echo "      the suite passed with the ${en_f} floor removed: no test pins it"
    elif echo "$en_out" | qgrep -qE "^error(\[E[0-9]+\]|: could not compile)"; then
        bad; echo "      did not compile:"; echo "$en_out" | grep -m3 -E "^error" | sed 's/^/        /'
    else
        en_failed="$(echo "$en_out" | sed -n 's/^test \([a-z0-9_:]*\) \.\.\. FAILED$/\1/p' | sort | tr '\n' ' ')"
        if [ "$en_failed" = "$en_want" ]; then
            ok
        else
            bad; echo "      expected exactly: ${en_want}— got: ${en_failed:-none}"; ci_debug_dump "energy-${en_f}" "$en_out"
        fi
    fi
    ci_row_end
done

# The decision journal with the ring built (decisions-tests `ring`, the gate's
# dev cell: DECISION_RECORDS_DEV and DECISION_REFUSALS_DURABLE both on). The
# ring's records claim ids between the durable ones, so a journal keyed by id
# lost a refusal to the next one N ids on; the `journal_` tests pin that the
# last N durable records are held, by id and by query. The suite's own row
# builds `durable` only, where the ids are dense and the keying cannot show.
if ci_row_begin "decisions(ring)"; then
printf "  %-26s" "decisions(ring)..."
if dr_out=$( (cd "${REPO_ROOT}/tests/host/decisions-tests" && CARGO_TARGET_DIR="$AZOS_OUT/target/host-canary/decisions-tests" "$CARGO" test --release --features ring journal_ 2>&1) ) \
   && echo "$dr_out" | qgrep -qE "^test result: ok\. [1-9][0-9]* passed"; then
    ok
else
    bad; echo "$dr_out" | grep -m5 -E "^error|panicked at|FAILED|^test result" | sed 's/^/      /'; ci_debug_dump "decisions-ring" "$dr_out"
fi
fi; ci_row_end

# Thermal framework: heat never lowers a clock below the real-time deadline
