if th_out=$( (cd "${REPO_ROOT}/tests/host/thermal-tests" && CARGO_TARGET_DIR="$AZOS_OUT/target/host-canary/thermal-tests" "$CARGO" test --release --features thermal-floor-canary 2>&1) ); then
