if ci_row_begin "energy(firmware-model-canary)"; then
printf "  %-26s" "energy(firmware-model-canary)..."
fm_ok=1
for fm_c in "energy-tests:firmware::a_range_that_cannot_make_a_table_is_refused firmware::a_wide_range_takes_a_wider_step_and_keeps_both_ends firmware::power_is_a_declared_placeholder_that_is_nonzero_and_strictly_increasing firmware::the_last_opp_is_the_firmwares_maximum_even_off_the_step_grid " \
            "thermal-tests:rpi::the_table_ends_at_the_maximum_the_firmware_reported "; do
