        bad; echo "      ${fm_crate} passed with the firmware table's guards removed: no test pins them"; fm_ok=0; break
    elif echo "$fm_out" | qgrep -qE "^error(\[E[0-9]+\]|: could not compile)"; then
        bad; echo "      ${fm_crate} did not compile:"; echo "$fm_out" | grep -m3 -E "^error" | sed 's/^/        /'; fm_ok=0; break
    else
