for pw_c in "fallback:decisions::a_cap_below_the_deadline_floor_is_answered_with_no_cap decisions::a_cap_below_the_safety_floor_is_answered_with_the_floor decisions::a_refused_fallback_is_not_retried decisions::the_fallback_table " \
