# Neverallow, the host suite's canary: `neverallow::check` finds nothing
# (`neverallow-canary`), so a topology that breaks a rule is admitted, and
# exactly the six tests that expect a refusal must fail. Three buckets: the
# suite passing means no test pins the rules; a build error is its own FAIL.
if ci_row_begin "topology(neverallow-canary)"; then
printf "  %-26s" "topology(neverallow-canary)..."
if na_out=$( (cd "${REPO_ROOT}/tests/host/topology-tests" && "$CARGO" test --release --features neverallow-canary 2>&1) ); then
    bad; echo "      the suite passed with the rules disabled: no test pins them"
elif echo "$na_out" | qgrep -qE "^error(\[E[0-9]+\]|: could not compile)"; then
    bad; echo "      did not compile:"; echo "$na_out" | grep -m3 -E "^error" | sed 's/^/        /'
else
    na_failed="$(echo "$na_out" | sed -n 's/^test \([a-z0-9_:]*\) \.\.\. FAILED$/\1/p' | sort | tr '\n' ' ')"
    if [ "$na_failed" = "exports_tests::a_proxy_endpoint_is_called_by_ordinary_rows_and_served_by_rpcsrv_only neverallow_tests::a_desktop_image_grants_no_motor neverallow_tests::admission_check_refuses_a_row_a_rule_forbids neverallow_tests::an_exception_covers_its_rule_its_row_and_its_grants_only neverallow_tests::each_rule_refuses_its_grant neverallow_tests::the_listed_rows_hold_only_their_own_actuators " ]; then
        ok
    else
