    # -1 lx_class_server_keeps_tpidr_el0, +2 native_tasks_keep_tpidr_el0 and
    # new_task_starts_with_tpidr_el0_zero (aarch64 only: EVERY task's
    # TPIDR_EL0 is kept per task; canary `tpidr-foreign-only-canary`) -> arm 125.
    # +1 rt_motor_coasts_a_held_wheel (B2: the control loop coasts a wheel the
    # kernel holds in its safe state) -> rv 123, arm 126.
    # +1 user_visible_state_is_set_on_every_cpu (tls-hygiene: the per-CPU
    # state ring 3 can read is set on every CPU; canary `el0-state-canary`,
    # aarch64) -> 124, arm 127.
    KTEST_N_RV=124
    KTEST_N_ARM=127
    # `decisions-durable`: the durable refusal path (Kconfig
    # DECISION_REFUSALS_DURABLE, on in every preset) that `why_resolves_a_refused_reservation`
    # needs; `KTEST_FEATS_NODUR` is the same kernel without it (the canary row).
    KTEST_FEATS="qemu,use-robot,ktest,chaos,decisions,decisions-durable"
    KTEST_FEATS_NODUR="qemu,use-robot,ktest,chaos,decisions"
    # KTEST_SMP (default 4) and KTEST_QEMU_EXTRA (default none) change the
    # boot for a row that needs it (`ktest hold bound, -icount`); the
    # environment's KCONFIG_CONFIG / AARCH64_CONFIG choose the kernel's
    # configuration, as for any `kbuild`.
    ktest_row() { # ktest_row <label> <isa: rv|arm> <extra features> <expected not-ok names, space separated> [kernel command line] [ERE the log must match] [disk image target]
        local label="$1" isa="$2" extra="$3" want="$4" n_want=$KTEST_N_RV
        local -a app=(); [ -n "${5:-}" ] && app=(-append "$5")
        # A disk (K1): a private copy of a fresh image, so FAT32 mounts and
        # `fs-wb` runs (the `ktest disk` rows).
        local -a drv=() dimg=
        [ "$isa" = arm ] && n_want=$KTEST_N_ARM
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/ktest-${tag}.log" kimg="$CI_LOG_DIR/kernel-ktest-${tag}"
        rm -f "$log" "$kimg"
        if [ -n "${7:-}" ]; then
            dimg="$CI_LOG_DIR/disk-ktest-${tag}.img"
            fresh_disk "$7" && cp "$7" "$dimg" || { bad; echo "      disk image $7 did not build"; return; }
            drv=(-drive "file=$dimg,if=none,format=raw,id=hd0" -device virtio-blk-device,drive=hd0)
        fi
        if [ "$isa" = rv ]; then
            kbuild "$KTEST_FEATS$extra" || { bad; echo "      riscv64 --features $KTEST_FEATS$extra did not build"; return; }
            cp "$KERNEL" "$kimg"
        else
            a64_kbuild "$KTEST_FEATS$extra" || { bad; echo "      aarch64 --features $KTEST_FEATS$extra did not build"; return; }
            a64_kernel_check || return
            cp "$A64_IMG" "$kimg"
        fi
        par_ready
        while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
        if [ "$isa" = rv ]; then
            "$QEMU" -machine virt -nographic -bios default -kernel "$kimg" -smp "${KTEST_SMP:-4}" ${KTEST_QEMU_EXTRA:-} \
                ${app[@]+"${app[@]}"} ${drv[@]+"${drv[@]}"} </dev/null >"$log" 2>&1 &
        else
            # Kconfig KTEST_SEMIHOSTING_EXIT: the runner's exit status rides
            # on semihosting SYS_EXIT (PSCI SYSTEM_OFF has none).
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp "${KTEST_SMP:-4}" ${KTEST_QEMU_EXTRA:-} -nographic \
                -semihosting-config enable=on,target=native \
                -kernel "$kimg" ${app[@]+"${app[@]}"} ${drv[@]+"${drv[@]}"} </dev/null >"$log" 2>&1 &
        fi
        local pid=$! i=0
        # The runner powers the machine off; the wait is only a backstop (the
        # late tests take about a minute together).
        while [ "$i" -lt 600 ] && kill -0 "$pid" 2>/dev/null; do i=$((i + 1)); sleep 0.5; done
        # QEMU's exit status carries the verdict too (kernel/src/ktest.rs
        # power_off): 0 for a clean run, 1 otherwise, on riscv64 (the
        # sifive_test finisher) and aarch64 (semihosting SYS_EXIT). The row
        # needs BOTH the TAP lines and the status to agree: either one wrong
        # fails it (a failed run that exits 0 was seen once in ~7 runs on
        # riscv64, when OpenSBI's shutdown overwrote the finisher's 1).
        local qrc=timeout
        if kill -0 "$pid" 2>/dev/null; then kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        else wait "$pid" 2>/dev/null; qrc=$?; fi
        rm -f "$kimg" ${dimg:+"$dimg"}
        tr -d '\r' < "$log" > "$log.t" && mv "$log.t" "$log"
        local plan why="" k name got
        plan="$(sed -n 's/^1\.\.\([0-9][0-9]*\)$/\1/p' "$log" | sed -n '1p')"
        got="$(sed -n 's/^not ok [0-9][0-9]* - \([A-Za-z0-9_]*\)\( #.*\)\{0,1\}$/\1/p' "$log" | grep . | sort | tr '\n' ' ')"
        want="$(printf '%s\n' $want | grep . | sort | tr '\n' ' ')"
        if [ -z "$plan" ]; then why="no TAP plan line (1..N)"
        elif [ "$plan" != "$n_want" ]; then why="plan 1..$plan, the gate expects $n_want tests (KTEST_N_*)"
        elif [ "$got" != "$want" ]; then why="not ok: [${got% }], expected [${want% }]"
        elif grep -aq '^Bail out!' "$log"; then
            # Only a canary that panics may stop the run, and only in its test.
            for name in $want; do grep -aq "^Bail out! ktest: $name panicked" "$log" && why=bail; done
            [ "$why" = bail ] && why="" || why="the run bailed out: $(grep -a '^Bail out!' "$log")"
        else
            k=1
            while [ "$k" -le "$plan" ]; do
                [ "$(grep -acE "^(not )?ok $k - " "$log")" = 1 ] || { why="test $k reported $(grep -acE "^(not )?ok $k - " "$log") times"; break; }
                k=$((k + 1))
            done
            [ -z "$why" ] && ! grep -aqE "^# ktest: $plan tests, $((plan - $(printf '%s\n' $want | grep -c .))) passed" "$log" \
                && why="no matching summary line"
        fi
        if [ -z "$why" ] && [ -n "${6:-}" ] && ! grep -aqE "$6" "$log"; then why="no line matching: $6"; fi
        local qwhy=""
        if [ "$qrc" = timeout ]; then qwhy="QEMU did not power off"
        elif [ -z "$want" ] && [ "$qrc" != 0 ]; then qwhy="QEMU exit status $qrc after a clean run"
        elif [ -n "$want" ] && [ "$qrc" != 1 ]; then qwhy="QEMU exit status $qrc after a failed run, not 1"
        fi
        # KTEST_STATUS_CANARY=1 (`canary=ktest-exit-pass`): the TAP lines
        # must hold and the status check must be what fails.
        if [ -z "$why" ] && [ "${KTEST_STATUS_CANARY:-0}" = 1 ]; then
            case "$qwhy" in
            *"after a failed run"*) ok; echo "      the status check fired: $qwhy"; rm -f "$log"; return ;;
            *) why="the status check did not fire on a failed run (QEMU status $qrc)" ;;
            esac
        fi
        [ -z "$why" ] && why="$qwhy"
        if [ -z "$why" ]; then
            ok; grep -aE '^# (ktest|spin_lock_fifo_bounded):' "$log" | sed 's/^/      /'; rm -f "$log"; return
        fi
        bad; echo "      $why"
        grep -aE '^(not ok|Bail out!|# ktest:)|KERNEL PANIC' "$log" | sed -n '1,8p' | sed 's/^/      /'
        echo "      log kept: $log"
    }
    par "ktest (rv)" ktest_row "ktest (rv)" rv "" ""
    par "ktest (arm)" ktest_row "ktest (arm)" arm "" ""
    # KASLR on the kernel the gate itself boots. The `kaslr:` rows judge images
    # tools/kaslr_image.sh builds with the Makefile's recipes; the rows here
    # boot kernels `kbuild` / `a64_kbuild` build with their own command lines.
    # Those once linked a `probe` kernel without `-pie` (the link flags lived
    # in kconfig_to_cargo.py --rustflags, which neither passes): an empty
    # relocation table, an image the boot slid anyway with its data still
    # pointing at the link address, and a hang at the first indirect call
    # after `[MM] W^X ok` (the NX sweep takes X off that address's alias),
    # with every `kaslr:` row green. This row takes the ktest row's own kernel
    # (`$KTEST_FEATS`, the gate's configuration) and wants (1) its ELF to be
    # a position-independent link with R_*_RELATIVE entries and no other
    # dynamic relocation, when that configuration's KASLR is not n, and (2)
    # two boots that slide it to different bases and reach the TAP plan
    # (`1..N`: the test runner started) with no failure on the way
    # (tools/kaslr_boot_row.sh with KASLR_END_ERE). Canary (run by hand, on
    # the kernels of the gate that found the hang): both halves FAIL, (1) on
    # "not a dynamic object", (2) on "never reached ^1\.\.[0-9]+$ ... stopped
    # after: [MM] W^X ok". The boot now refuses an empty table outright
    # (`[KASLR] FATAL: the image has no relocation table`), which (2) reads
    # as a failure too.
    kaslr_gate_row() { # kaslr_gate_row <rv|arm>
        local isa="$1" label="kaslr: gate ktest kernel ($1)" cfg elf img qisa ty rels n other out
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        out="$CI_LOG_DIR/kaslr-gate-$isa.out"
        img="$CI_LOG_DIR/kernel-kaslr-gate-$isa"
        if [ "$isa" = rv ]; then
            kbuild "$KTEST_FEATS" || { bad; echo "      riscv64 --features $KTEST_FEATS did not build"; return; }
            cfg="${KCONFIG_CONFIG:-$REPO_ROOT/.config}"; elf="$KERNEL"; qisa=riscv64; ty=R_RISCV_RELATIVE
            cp "$KERNEL" "$img"
        else
            a64_kbuild "$KTEST_FEATS" || { bad; echo "      aarch64 --features $KTEST_FEATS did not build"; return; }
            a64_kernel_check || return
            cfg="$AARCH64_CONFIG"; elf="$A64_KERNEL"; qisa=aarch64; ty=R_AARCH64_RELATIVE
            cp "$A64_IMG" "$img"
        fi
        if ! grep -qx 'CONFIG_KASLR_AVAILABLE=y' "$cfg" || grep -qx 'CONFIG_KASLR_NEVER=y' "$cfg"; then
            rm -f "$img"; ok; echo "      KASLR is n in $cfg: nothing to slide"; return
        fi
        if ! rels="$("$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objdump" -R "$elf" 2>&1)"; then
            rm -f "$img"; bad; echo "      $elf is not a position-independent link: $(printf '%s' "$rels" | sed -n '$p')"; return
        fi
        n="$(printf '%s\n' "$rels" | awk -v t="$ty" '$2 == t' | wc -l | tr -d ' ')"
        other="$(printf '%s\n' "$rels" | awk -v t="$ty" 'NF >= 3 && $1 ~ /^[0-9a-f]+$/ && $2 != t' | wc -l | tr -d ' ')"
        if [ "$n" -lt 1000 ] || [ "$other" != 0 ]; then
            rm -f "$img"; bad; echo "      $elf: $n $ty and $other other dynamic relocations (want thousands of the first, none of the second)"; return
        fi
        par_ready
        if ! KASLR_LOG_DIR="$CI_LOG_DIR" KASLR_END_ERE='^1\.\.[0-9]+$' KASLR_WAIT_S=120 \
             "$REPO_ROOT/tools/kaslr_boot_row.sh" "$qisa" "$img" slid 2 >"$out" 2>&1; then
            rm -f "$img"; bad; sed 's/^/      /' "$out"; return
        fi
        rm -f "$img"; ok; sed 's/^/      /' "$out"; rm -f "$out"
    }
    par "kaslr: gate ktest kernel (rv)" kaslr_gate_row rv
    par "kaslr: gate ktest kernel (arm)" kaslr_gate_row arm
    # K1 (io_ring hand-off): the same kernel and plan with a disk, so FAT32
    # mounts, `fs-wb` runs and Kconfig RT_BLOCK_IO_CHECK guards the block
    # layer: `ioring_fsync_completes_after_flush`'s RT submitter queues real
    # FAT32 writes and an fsync through the io_ring worker and never enters
    # the block layer. Its canary `ioring-rt-inline` runs them inline on the
    # RT task: the check panics and the run bails out in that test.
    # The panic line names the file only: boot/sched.rs's one panic on a
    # block-layer path is `rt_block_io_check` ("[RT-IO] ... entered the block
    # layer").
    KTEST_RT_IO_PANIC='^not ok [0-9]+ - ioring_fsync_completes_after_flush # panic at kernel/src/boot/sched\.rs:'
    par "ktest disk (rv)" ktest_row "ktest disk (rv)" rv "" "" "" "" $AZOS_OUT/build/disk.img
    par "ktest disk (arm)" ktest_row "ktest disk (arm)" arm "" "" "" "" $AZOS_OUT/build/disk-aarch64.img
    par "ktest disk RT-inline canary (rv)" ktest_row "ktest disk RT-inline canary (rv)" rv "" \
        "ioring_fsync_completes_after_flush" "canary=ioring-rt-inline" "$KTEST_RT_IO_PANIC" $AZOS_OUT/build/disk.img
    par "ktest disk RT-inline canary (arm)" ktest_row "ktest disk RT-inline canary (arm)" arm "" \
        "ioring_fsync_completes_after_flush" "canary=ioring-rt-inline" "$KTEST_RT_IO_PANIC" $AZOS_OUT/build/disk-aarch64.img
    KTEST_CANARIES=",wx-skip-canary,nx-skip-canary,ro-seal-skip-canary,percpu-oor-canary,commander-exit-nostop-canary"
    KTEST_CANARIED="mm_wx_image mm_nx_outside_image mm_ro_after_init_sealed percpu_areas_and_oor_refusal motor_commander_exit_stops_its_wheels"
    # Both ISAs (N2b): `wx-skip-canary` leaves the kernel text writable, so
    # the one text-write path (`text_poke`, W^X kept) refuses NotRx and the
    # SpinWait probe sites stay linked to their fallback
    # (`spin_sites_patched`; rv64 Zawrs/Zihintpause, `-cpu max` LSE).
    par "ktest canaries (rv)" ktest_row "ktest canaries (rv)" rv "$KTEST_CANARIES,zicboz-skip-canary" \
        "$KTEST_CANARIED mm_zicboz_zero_fill spin_sites_patched"
    # aarch64 also: the same refusal leaves the A64_PAN=probe sites the
    # slow-path branch (`a64_pan_sites_patched`).
    par "ktest canaries (arm)" ktest_row "ktest canaries (arm)" arm "$KTEST_CANARIES" \
        "$KTEST_CANARIED a64_pan_sites_patched spin_sites_patched"
    # DECISION_REFUSALS_DURABLE=n: no refusal leaves a receipt, so `why` has
    # nothing to resolve. `ktest_row` builds `$KTEST_FEATS`; this builds the
    # kernel without `decisions-durable` and expects the one row red.
    # The kernel is built from a Kconfig with DECISION_REFUSALS_DURABLE off: the
    # cargo `decisions-durable` feature is derived from the .config (ci_cargo.py
    # appends its base features), so leaving it out of --features alone changed
    # nothing and the canary never bit.
    ktest_row_nodur() {
        local KTEST_FEATS="$KTEST_FEATS_NODUR" isa="$2" defc cfg
        defc="$(gate_defc "$([ "$isa" = arm ] && echo a64 || echo rv)" "$KTEST_FEATS")"
        mkdir -p "$CI_LOG_DIR"
        cfg="$(cd "$CI_LOG_DIR" && pwd)/ktest-nodur-${isa}.config"
        cp "${REPO_ROOT}/config/defconfigs/${defc}.config" "$cfg" \
            && printf "# CONFIG_DECISION_REFUSALS_DURABLE is not set\n" >>"$cfg" \
            && (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1) \
            && ! grep -q "^CONFIG_DECISION_REFUSALS_DURABLE=y" "$cfg" \
            || { printf "  %-26s" "$1..."; bad; echo "      could not make a Kconfig with DECISION_REFUSALS_DURABLE off ($cfg)"; return; }
        if [ "$isa" = rv ]; then KCONFIG_CONFIG="$cfg" ktest_row "$@"; else AARCH64_CONFIG="$cfg" ktest_row "$@"; fi
    }
    par "ktest why durable-off canary (rv)" ktest_row_nodur "ktest why durable-off canary (rv)" rv "" "why_resolves_a_refused_reservation"
    par "ktest why durable-off canary (arm)" ktest_row_nodur "ktest why durable-off canary (arm)" arm "" "why_resolves_a_refused_reservation"
    par "ktest kcall atomic canary (rv)" ktest_row "ktest kcall atomic canary (rv)" rv ",kcall-atomic-canary" "kernel_endpoint_call_is_refused_under_a_spinlock"
    par "ktest kcall atomic canary (arm)" ktest_row "ktest kcall atomic canary (arm)" arm ",kcall-atomic-canary" "kernel_endpoint_call_is_refused_under_a_spinlock"
    # arm-tpidr-all-tasks: only a Linux task's TPIDR_EL0 is kept, not a
    # native task's, the old rule (aarch64 only; riscv64's `tp` is in the trap
    # frame, x86_64's FS base is not EL0-writable).
    par "ktest sched tpidr canary (arm)" ktest_row "ktest sched tpidr canary (arm)" arm ",tpidr-foreign-only-canary" "native_tasks_keep_tpidr_el0 new_task_starts_with_tpidr_el0_zero"
    # tls-hygiene: CNTKCTL_EL1's EL0 bits kept and a non-zero TPIDRRO_EL0,
    # standing for their UNKNOWN reset values (QEMU resets both to 0).
    # el0-state-audit: SCTLR_EL1 and MDSCR_EL1 left at the firmware's (QEMU's
    # EL1 reset: SPAN 1, TSCXT 0, TDCC 0). The summary line must name all
    # four, so each register's check is seen to fire.
    par "ktest el0 state canary (arm)" ktest_row "ktest el0 state canary (arm)" arm ",el0-state-canary" "user_visible_state_is_set_on_every_cpu" \
        "" "left unset: TPIDRRO_EL0 CNTKCTL_EL1 SCTLR_EL1 MDSCR_EL1"
    # el0-state-audit: senvcfg written with a stand-in that opens U-mode's
    # cache-block instructions (QEMU resets it to 0, the kernel's value).
    par "ktest el0 state canary (rv)" ktest_row "ktest el0 state canary (rv)" rv ",el0-state-canary" "user_visible_state_is_set_on_every_cpu" \
        "" "left unset: senvcfg"
    par "ktest slab canary (rv)" ktest_row "ktest slab canary (rv)" rv ",slab-freelist-canary" "kheap_slab_selftest"
    par "ktest slab canary (arm)" ktest_row "ktest slab canary (arm)" arm ",slab-freelist-canary" "kheap_slab_selftest"
    par "ktest zone canary (rv)" ktest_row "ktest zone canary (rv)" rv ",zone-share-canary" "mm_zone_no_cross_type_reuse"
    par "ktest zone canary (arm)" ktest_row "ktest zone canary (arm)" arm ",zone-share-canary" "mm_zone_no_cross_type_reuse"
    # QoS timer tolerance: `sc::timer_slack_us` gives the stop, deadline and
    # real-time classes the fair class's window (`qos-rt-slack-canary`, a
    # cargo feature: the arm path takes no runtime canary).
    par "ktest QoS RT slack canary (rv)" ktest_row "ktest QoS RT slack canary (rv)" rv ",qos-rt-slack-canary" "qos_timer_slack_never_real_time qos_timer_slack_rt_task_gets_zero"
    par "ktest QoS RT slack canary (arm)" ktest_row "ktest QoS RT slack canary (arm)" arm ",qos-rt-slack-canary" "qos_timer_slack_never_real_time qos_timer_slack_rt_task_gets_zero"
    # The integrated coalescing path (`timer_sleepers::ktest_coalescing`): the
    # slot's slack is forgotten / the bare deadline is reported as the armed
    # instant. Cargo features again; each must turn the one test red.
    par "ktest QoS fire canary (rv)" ktest_row "ktest QoS fire canary (rv)" rv ",qos-fire-canary" "qos_timer_coalescing_path"
    par "ktest QoS fire canary (arm)" ktest_row "ktest QoS fire canary (arm)" arm ",qos-fire-canary" "qos_timer_coalescing_path"
    par "ktest QoS armed-at canary (rv)" ktest_row "ktest QoS armed-at canary (rv)" rv ",qos-armed-at-canary" "qos_timer_coalescing_path"
    par "ktest QoS armed-at canary (arm)" ktest_row "ktest QoS armed-at canary (arm)" arm ",qos-armed-at-canary" "qos_timer_coalescing_path"
    par "ktest tlb local-only canary (rv)" ktest_row "ktest tlb local-only canary (rv)" rv ",tlb-local-only" "tlb_shootdown_cross_cpu"
    par "ktest tlb local-only canary (arm)" ktest_row "ktest tlb local-only canary (arm)" arm ",tlb-local-only" "tlb_shootdown_cross_cpu"
    # The accessors of the running task read the hart id and its slot in one
    # masked window (`scheduler::on_this_hart`); this cargo feature takes the
    # mask off, the old two steps: percpu_accessors_read_masked alone not ok.
    par "ktest percpu accessor canary (rv)" ktest_row "ktest percpu accessor canary (rv)" rv ",percpu-accessor-race-canary" "percpu_accessors_read_masked"
    par "ktest percpu accessor canary (arm)" ktest_row "ktest percpu accessor canary (arm)" arm ",percpu-accessor-race-canary" "percpu_accessors_read_masked"
    par "ktest tlb scan-bound canary (rv)" ktest_row "ktest tlb scan-bound canary (rv)" rv ",tlb-bound-canary" "tlb_shootdown_cross_cpu"
    par "ktest IMU frozen-stamp canary (rv)" ktest_row "ktest IMU frozen-stamp canary (rv)" rv ",sensor-ts-freeze" "sensors_imu_stamped_at_acquisition safety_geofence_breach_latches_estop"
    par "ktest IMU frozen-stamp canary (arm)" ktest_row "ktest IMU frozen-stamp canary (arm)" arm ",sensor-ts-freeze" "sensors_imu_stamped_at_acquisition safety_geofence_breach_latches_estop"
    # `classes::current` reads the hart id and its slot with interrupts on
    # (the hart-id-then-table audit, front percpu-hazard-b): the one test red.
    par "ktest percpu hazard canary (rv)" ktest_row "ktest percpu hazard canary (rv)" rv ",percpu-hazard-canary" "percpu_hazard_reads_are_masked"
    par "ktest percpu hazard canary (arm)" ktest_row "ktest percpu hazard canary (arm)" arm ",percpu-hazard-canary" "percpu_hazard_reads_are_masked"
    # Runtime canaries: the pass row's kernel (`qemu,ktest`, a kernel-cache
    # hit), armed by the command line.
    # `chaos-leak`: an injected frame failure loses a frame
    # (`chaos_frame_alloc_no_leak`); `decision-skip`: no decision record is
    # written (`decision_admission_recorded`, `decision_cap_denial_recorded`,
    # `why_resolves_a_refused_reservation`: no id is claimed, so nothing is kept);
    # `ioring-fsync-inline` (K1): an io_ring OP_FSYNC waits for the device in
    # the submit and completes there (`ioring_fsync_completes_after_flush`).
    # `camera-encode-per-consumer`: each camera ring consumer encodes its own
    # frame again, three encodes per frame (`camera_one_encode_per_frame`).
    # `preempt-isr-leak` (Chain E commit 7): the timer interrupt's probe
    # keeps the preempt guard it takes on top of the test's, so the per-hart
    # count comes out wrong (`preempt_count_survives_irq_nesting`).
    # `irq-storm` (L5): the budget rule of an interrupt line is off, a throttle
    # leaves an idle line live, so a storm delivers to a handler whose budget
    # is spent (`irq_storm_is_contained`).
    # `commander-exit-late`: a dying commander's wheels are stopped after its
    # file writeback and device releases, not first of all
    # (`motor_commander_exit_stops_its_wheels`).
    # `fdt-reserve-skip`: the device tree blob stays in the page allocator
    # (`mm_fdt_reserved`; QEMU leaves it in free RAM on both ISAs: riscv64
    # near the top, aarch64 mid-RAM).
    KTEST_RT_CANARIES="canary=stack-guard-skip,chaos-leak,decision-skip,ioring-fsync-inline,camera-encode-per-consumer,preempt-isr-leak,irq-storm,commander-exit-late,fdt-reserve-skip"
    KTEST_RT_CANARIED="sched_stack_guards_unmapped chaos_frame_alloc_no_leak decision_admission_recorded decision_cap_denial_recorded why_resolves_a_refused_reservation ioring_fsync_completes_after_flush camera_one_encode_per_frame preempt_count_survives_irq_nesting irq_storm_is_contained motor_commander_exit_stops_its_wheels mm_fdt_reserved"
    par "ktest runtime canaries (rv)" ktest_row "ktest runtime canaries (rv)" rv "" "$KTEST_RT_CANARIED" "$KTEST_RT_CANARIES"
    par "ktest runtime canaries (arm)" ktest_row "ktest runtime canaries (arm)" arm "" "$KTEST_RT_CANARIED" "$KTEST_RT_CANARIES"
    # Wave 15 (N1, lockdep-lite): `canary=lockdep-abba` takes the test's two
    # SpinLocks in both orders (`lockdep_lock_order_consistent`);
    # `canary=lockdep-spin-blk` holds a SpinLock across a block-layer read
    # (`lockdep_no_spinlock_across_block_io`, the rt7 shape). Neither
    # deadlocks: lockdep reports, and the runner fails the test. One boot.
    # N1b adds, in the same boot: `lockdep-scope-irq` (another CPU's
    # CpuOwned from interrupt context) and `lockdep-scope-preempt` (a PerCpu
    # with an assumed token, preemption on) -> lockdep_scope_rules;
    # `lockdep-irq-inversion` (an IRQ-safe class taken with interrupts on)
    # -> lockdep_irq_safe_class_taken_irqsave; `lockdep-hold` (a SpinLock
    # held twice LOCK_MAX_HOLD_US) -> lockdep_spinlock_hold_bounded;
    # `lockdep-rt-pi` (a Mutex contended by RT tasks on CPUs 1 and 2,
    # rule F7) -> lockdep_rt_tasks_share_only_spinlocks. N1d adds
    # `lockdep-early-abba` (an ABBA in early_main, before the scheduler)
    # -> lockdep_boot_phase_clean.
    KTEST_LOCKDEP_CANARIES="canary=lockdep-abba,lockdep-spin-blk,lockdep-scope-irq,lockdep-scope-preempt,lockdep-irq-inversion,lockdep-hold,lockdep-rt-pi,lockdep-early-abba"
    KTEST_LOCKDEP_CANARIED="lockdep_lock_order_consistent lockdep_no_spinlock_across_block_io lockdep_scope_rules lockdep_irq_safe_class_taken_irqsave lockdep_spinlock_hold_bounded lockdep_rt_tasks_share_only_spinlocks lockdep_boot_phase_clean"
    KTEST_LOCKDEP_RE='^# lockdep: lock order inversion \(ABBA\); holding SpinLock kernel/src/ktest\.rs:'
    par "ktest lockdep canaries (rv)" ktest_row "ktest lockdep canaries (rv)" rv "" "$KTEST_LOCKDEP_CANARIED" "$KTEST_LOCKDEP_CANARIES" "$KTEST_LOCKDEP_RE"
    par "ktest lockdep canaries (arm)" ktest_row "ktest lockdep canaries (arm)" arm "" "$KTEST_LOCKDEP_CANARIED" "$KTEST_LOCKDEP_CANARIES" "$KTEST_LOCKDEP_RE"
    # A64_PAN=probe: `canary=pan-patch-skip` leaves every UserAccess site the
    # slow-path branch (kernel/src/entry/aarch64/pan_patch.rs); only
    # `a64_pan_sites_patched` goes not ok. aarch64 only.
    par "ktest pan-patch-skip canary (arm)" ktest_row "ktest pan-patch-skip canary (arm)" arm "" "a64_pan_sites_patched" "canary=pan-patch-skip"
    # Wave 15 (plan 7b): `canary=chaos-inert` arms no injection point, so
    # every `chaos_*` test but the parser's reports `not ok` (one boot: the
    # inert registry would also hide `chaos-leak`, which rides above).
    KTEST_CHAOS_INERT="chaos_disk_io_error_recorded chaos_frame_alloc_no_leak chaos_heap_alloc_refused chaos_ipc_send_refused chaos_spurious_irq_tolerated chaos_timer_wake_late_not_lost"
    par "ktest chaos-inert canary (rv)" ktest_row "ktest chaos-inert canary (rv)" rv "" "$KTEST_CHAOS_INERT" "canary=chaos-inert"
    par "ktest chaos-inert canary (arm)" ktest_row "ktest chaos-inert canary (arm)" arm "" "$KTEST_CHAOS_INERT" "canary=chaos-inert"
    # Wave 15 (C2): `console_rt_lines_only_append` (an RT task's kernel lines
    # and ring-3 console writes take the append-only console path and never
    # wait for the wire). Its
    # runtime canary `canary=rt-console-own` sends the probe's lines to the
    # wire wait, where RT_CONSOLE_WIRE_CHECK panics: a boot of its own, since
    # the panic ends the run. Not on x86_64: a panic there powers the machine
    # off from another CPU before the ktest's Bail line is out (measured: the
    # report is cut mid-line), so `ktest (x86)` runs the pass side only.
    par "ktest RT console canary (rv)" ktest_row "ktest RT console canary (rv)" rv "" "console_rt_lines_only_append" "canary=rt-console-own"
    par "ktest RT console canary (arm)" ktest_row "ktest RT console canary (arm)" arm "" "console_rt_lines_only_append" "canary=rt-console-own"
    # `canary=rt-console-own-user`: the probe's kernel lines go out (its line
    # 159 must be on the console), then its first ring-3 console write
    # (`uart::console_write_ring3`, what sys_write calls) is sent to the wire
    # wait, and the check must stop the kernel there.
    par "ktest RT console user canary (rv)" ktest_row "ktest RT console user canary (rv)" rv "" "console_rt_lines_only_append" "canary=rt-console-own-user" "probe line 159 from the RT band"
    par "ktest RT console user canary (arm)" ktest_row "ktest RT console user canary (arm)" arm "" "console_rt_lines_only_append" "canary=rt-console-own-user" "probe line 159 from the RT band"
    # The command line's arming, end to end: delayed timer wakes (1 in 8
    # sweeps) and unsolicited IPIs (1 in 4) from the end of boot init to the
    # power-off, under a fixed seed. Every ktest stays `ok` and both points
    # fired (the runner's `# chaos:` summary lines).
    KTEST_SOAK="chaos=timer-wake:8,spurious-irq:4 chaos_seed=7"
    KTEST_SOAK_RE="^# chaos: timer-wake rate=8 checked=[0-9]+ fired=[1-9][0-9]*\$"
    par "ktest chaos soak (rv)" ktest_row "ktest chaos soak (rv)" rv "" "" "$KTEST_SOAK" "$KTEST_SOAK_RE"
    par "ktest chaos soak (arm)" ktest_row "ktest chaos soak (arm)" arm "" "" "$KTEST_SOAK" "$KTEST_SOAK_RE"
    # Wave 15 (N1c): the SpinLock hold bound enforced in instruction time.
    # The other ktest rows boot on TCG wall time, where a hold is whatever
    # the host made of it, so LOCKDEP_HOLD_ENFORCE is off on BOARD_QEMU and
    # the holds over LOCK_MAX_HOLD_US are notes. These rows build the ktest
    # kernel with LOCKDEP_HOLD_ENFORCE=y and boot it under
    # `-icount shift=0,sleep=off -smp 1`: the guest timer is QEMU's virtual
    # clock, which advances one nanosecond per guest instruction (shift=0),
    # so a hold of N us is N x 1,000 instructions of the holder (with the
    # interrupt handlers it took meanwhile), the same on every host and
    # every run. LOCK_MAX_HOLD_US stays at its default, 100 us = 100,000
    # instructions: a ~1 GHz single-issue core, slower than any board AzOS
    # targets, so a hold under it here is under it there. -smp 1 because
    # QEMU runs -icount vCPUs round-robin on one clock: a vCPU's slice is
    # the time to the next timer deadline over the vCPU count, and a hold
    # that straddles a slice boundary absorbs every other vCPU's slice
    # (measured at -smp 4: holds of a few hundred instructions read 0.2-2.4
    # ms, from any lock). Measured at -smp 1 on N1c's tree: longest
    # SpinLock holds 70,000 (rv) / 54,000 (arm) instructions, the boot's
    # static-key patching (ipc/trace.rs `keys_init`); every runtime path
    # under 12,000. One CPU means a hold that waits on another CPU (text_poke's
    # TLB shootdown / remote fence.i under its irqsave lock) is not measured
    # here; those run in the -smp 4 rows, as notes. The four tests that
    # need 2-3 CPUs say so and are the expected `not ok` (they run in every
    # other ktest row). Pass row: no
    # violation, the bound printed as enforced. Canary row:
    # `canary=lockdep-hold` holds the test's SpinLock twice the bound, and
    # with enforcement the test does not check its own histogram, so only
    # lockdep's report fails `lockdep_spinlock_hold_bounded`.
    KTEST_HOLD_US=100
    # The tests that need a second CPU answer `not ok` at -smp 1 (they say so).
    KTEST_HOLD_SMP1="lockdep_rt_tasks_share_only_spinlocks sched_deferred_tick_counted_as_preemption tlb_shootdown_cross_cpu spin_lock_contended_cross_cpu spin_lock_fifo_bounded fat_claim_waiter_donates_to_owner shootdown_reaches_a_masked_lock_waiter"
    KTEST_HOLD_RE="^# lockdep: violations=0 .* hold-bound=${KTEST_HOLD_US}us\$"
    KTEST_HOLD_CANARY_RE='^# lockdep: SpinLock held past LOCK_MAX_HOLD_US; SpinLock kernel/src/ktest\.rs:'
    ktest_hold_cfg() { # ktest_hold_cfg <Kconfig file> <defconfig name>: the row's configuration, checked
        cp "${REPO_ROOT}/config/defconfigs/$2.config" "$1"
        printf 'CONFIG_LOCKDEP_HOLD_ENFORCE=y\nCONFIG_LOCK_MAX_HOLD_US=%s\n' "$KTEST_HOLD_US" >>"$1"
        (cd "$REPO_ROOT" && KCONFIG_CONFIG="$1" python3 -m olddefconfig >/dev/null 2>&1) \
            && grep -q '^CONFIG_LOCKDEP_KTEST=y$' "$1" && grep -q '^CONFIG_LOCKDEP_HOLD_ENFORCE=y$' "$1" \
            && grep -q "^CONFIG_LOCK_MAX_HOLD_US=${KTEST_HOLD_US}\$" "$1"
    }
    ktest_hold_row() { # ktest_hold_row <label> <isa: rv|arm> <expected not-ok names> [kernel command line] [ERE]
        local label="$1" isa="$2" defc cfg tag
        defc="$(gate_defc "$([ "$isa" = arm ] && echo a64 || echo rv)" "$KTEST_FEATS")"
        mkdir -p "$CI_LOG_DIR"
        tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        # Absolute: `azos_limits`' build script resolves KCONFIG_CONFIG from
        # its own crate directory.
        cfg="$(cd "$CI_LOG_DIR" && pwd)/${tag}.config"
        if ! ktest_hold_cfg "$cfg" "$defc"; then
            printf "  %-26s" "${label}..."; bad
            echo "      $cfg: olddefconfig failed or lost LOCKDEP_KTEST, LOCKDEP_HOLD_ENFORCE=y or LOCK_MAX_HOLD_US=$KTEST_HOLD_US"
            return
        fi
        KCONFIG_CONFIG="$cfg" AARCH64_CONFIG="$cfg" KTEST_SMP=1 KTEST_QEMU_EXTRA="-icount shift=0,sleep=off" \
            ktest_row "$label" "$isa" "" "$3" "${4:-}" "${5:-}"
    }
    par "ktest hold bound, -icount (rv)" ktest_hold_row "ktest hold bound, -icount (rv)" rv "$KTEST_HOLD_SMP1" "" "$KTEST_HOLD_RE"
    par "ktest hold bound, -icount (arm)" ktest_hold_row "ktest hold bound, -icount (arm)" arm "$KTEST_HOLD_SMP1" "" "$KTEST_HOLD_RE"
    par "ktest hold bound canary, -icount (rv)" ktest_hold_row "ktest hold bound canary, -icount (rv)" rv \
        "$KTEST_HOLD_SMP1 lockdep_spinlock_hold_bounded" "canary=lockdep-hold" "$KTEST_HOLD_CANARY_RE"
    par "ktest hold bound canary, -icount (arm)" ktest_hold_row "ktest hold bound canary, -icount (arm)" arm \
        "$KTEST_HOLD_SMP1 lockdep_spinlock_hold_bounded" "canary=lockdep-hold" "$KTEST_HOLD_CANARY_RE"

    # Wave 15 (N2): `SpinWait` (crates/core/arch-api spin.rs) off the
    # extension, on CPUs QEMU builds without it. The plain `ktest (rv)` row
    # already boots QEMU's rv64, which has Zawrs and no Zacas (`[SPIN] cas:
    # lr/sc; wait: lr+wrs.nto`); `ktest (arm)` boots `-cpu max` (LSE).
    #   ktest spin fallback (arm, cortex-a53)  the A64_LSE=probe kernel on an
    #                               Armv8.0 core without LSE: `[SPIN] cas:
    #                               ldaxr/stlxr`, every test ok
    #   ktest spin claim canary (rv)  canary=spin-ext-claim on `-cpu
    #                               rv64,zawrs=false`: Zacas and Zawrs both
    #                               claimed, both refuted by the execution
    #                               probe (`[SPIN] ... refuted`), every test
    #                               ok. Skip the probe and the first lock
    #                               traps (Illegal instruction, shutdown).
    #                               On aarch64 (cortex-a53) and x86_64 (TCG)
    #                               the same canary traps: there the probe
    #                               is the ID register / CPUID, not an
    #                               execution probe.
    KTEST_SPIN_A53_RE='^\[SPIN\] cas: ldaxr/stlxr; wait: ldaxr\+wfe$'
    KTEST_SPIN_CLAIM_RE='\[SPIN\] cas: lr/sc \(zacas claimed, refuted by the execution probe\); wait: pause \(zawrs claimed, refuted by the execution probe\)$'
    ktest_cpu_row() { # ktest_cpu_row <QEMU -cpu> <ktest_row args...>
        local cpu="$1"; shift
        KTEST_QEMU_EXTRA="-cpu $cpu" ktest_row "$@"
    }
    par "ktest spin fallback (arm, cortex-a53)" ktest_cpu_row cortex-a53 \
        "ktest spin fallback (arm, cortex-a53)" arm "" "" "" "$KTEST_SPIN_A53_RE"
    par "ktest spin claim canary (rv)" ktest_cpu_row rv64,zawrs=false \
        "ktest spin claim canary (rv)" rv "" "" "canary=spin-ext-claim" "$KTEST_SPIN_CLAIM_RE"
    # Wave 15 (N2b): the probe sites are rewritten once at boot
    # (kernel/src/boot/spin_patch.rs); the plain ktest rows check every site
    # holds the probe's word (`spin_sites_patched`, `[SPIN] boot patch`).
    #   ktest spin-patch-skip canary (rv|arm)  canary=spin-patch-skip: no
    #                               site is rewritten; QEMU's rv64 has Zawrs
    #                               and Zihintpause, `-cpu max` has LSE, so
    #                               spin_sites_patched alone goes not ok
    par "ktest spin-patch-skip canary (rv)" ktest_row "ktest spin-patch-skip canary (rv)" rv "" \
        "spin_sites_patched" "canary=spin-patch-skip"
    par "ktest spin-patch-skip canary (arm)" ktest_row "ktest spin-patch-skip canary (arm)" arm "" \
        "spin_sites_patched" "canary=spin-patch-skip"
    # A copy helper called by a task with no user page table refuses a
    # user-range VA (the `thread` page fault at 0x14fb8,
    # `copyout_refused_in_kernel_context`).
    #   ktest copyout canary (rv|arm)  canary=copyout-raw-kernel-ctx: the
    #                               floor is not enforced, the test's first
    #                               question answers yes, that test alone is
    #                               not ok (before any copy runs)
    par "ktest copyout canary (rv)" ktest_row "ktest copyout canary (rv)" rv "" \
        "copyout_refused_in_kernel_context" "canary=copyout-raw-kernel-ctx"
    par "ktest copyout canary (arm)" ktest_row "ktest copyout canary (arm)" arm "" \
        "copyout_refused_in_kernel_context" "canary=copyout-raw-kernel-ctx"
    # Wave 15 (N3): the QEMU defconfigs build the queued SpinLock (Kconfig
    # SPINLOCK_IMPL=mcs), which every plain ktest row runs; the test-and-set
    # build is its canary. Same kernel otherwise, every other test ok,
    # `spin_lock_fifo_bounded` alone not ok: four CPUs on one lock, waiters
    # passed over by more acquisitions than the CPUs ahead of them.
    KTEST_TTAS_RE='^# spin_lock_fifo_bounded: impl=ttas '
    ktest_ttas_row() { # ktest_ttas_row <label> <isa: rv|arm>
        local label="$1" isa="$2" defc cfg tag
        defc="$(gate_defc "$([ "$isa" = arm ] && echo a64 || echo rv)" "$KTEST_FEATS")"
        mkdir -p "$CI_LOG_DIR"
        tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        cfg="$(cd "$CI_LOG_DIR" && pwd)/${tag}.config"
        cp "${REPO_ROOT}/config/defconfigs/${defc}.config" "$cfg"
        printf 'CONFIG_SPINLOCK_IMPL_TTAS=y\n' >>"$cfg"
        if ! (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1) \
            || ! grep -q '^CONFIG_SPINLOCK_IMPL_TTAS=y$' "$cfg"; then
            printf "  %-26s" "${label}..."; bad
            echo "      $cfg: olddefconfig failed or lost SPINLOCK_IMPL_TTAS=y"
            return
        fi
        KCONFIG_CONFIG="$cfg" AARCH64_CONFIG="$cfg" ktest_row "$label" "$isa" "" "spin_lock_fifo_bounded" "" "$KTEST_TTAS_RE"
    }
    par "ktest spinlock ttas canary (rv)" ktest_ttas_row "ktest spinlock ttas canary (rv)" rv
    par "ktest spinlock ttas canary (arm)" ktest_ttas_row "ktest spinlock ttas canary (arm)" arm
    # GR3: the verdict rides on QEMU's exit status as well as on the TAP
    # lines, and a row needs both. `canary=ktest-exit-pass` drops the
    # verdict in `power_off` (a failed run exits as a clean one: riscv64 0,
    # aarch64 0, x86_64 1), with `decision-skip` failing two tests: the TAP
    # lines hold and the status check alone must fail the row
    # (KTEST_STATUS_CANARY=1 turns that into this row's ok). Without the
    # canary the same boot is `ktest runtime canaries`' status 1.
    KTEST_STATUS_CANARIES="canary=decision-skip,ktest-exit-pass"
    # `decision-skip` also leaves `irq_storm_is_contained` without the irq-budget
    # record it looks for (the test reads the decision log since wave 15 L5).
    KTEST_STATUS_CANARIED="decision_admission_recorded decision_cap_denial_recorded irq_storm_is_contained why_resolves_a_refused_reservation"
    ktest_status_canary_row() { # ktest_status_canary_row <ktest_row|x86_ktest_row> <its args...>
        local fn="$1"; shift
        KTEST_STATUS_CANARY=1 "$fn" "$@"
    }
    par "ktest exit status canary (rv)" ktest_status_canary_row ktest_row "ktest exit status canary (rv)" rv "" \
        "$KTEST_STATUS_CANARIED" "$KTEST_STATUS_CANARIES"
    par "ktest exit status canary (arm)" ktest_status_canary_row ktest_row "ktest exit status canary (arm)" arm "" \
        "$KTEST_STATUS_CANARIED" "$KTEST_STATUS_CANARIES"
    # N4 (Kconfig RCU_QSBR, kernel/src/smokes/rcu.rs), one boot of the pass
    # row's kernel: `canary=rcu-free-no-grace` (`call_rcu` frees at once: the
    # reader sees the poison, rcu_free_waits_for_the_reader),
    # `rcu-idle-qs-skip` (the idle task never enters its extended quiescent
    # state: no idle CPU is quiescent at a grace period's start,
    # rcu_idle_cpu_is_quiescent), `lockdep-rcu-sleep` (a wait's entry inside
    # a read section: lockdep_no_sleep_in_rcu_read).
    KTEST_RCU_CANARIES="canary=rcu-free-no-grace,rcu-idle-qs-skip,lockdep-rcu-sleep"
    # N5: the same rcu-free-no-grace hands a destroyed endpoint's slot back
    # at once (ipc_endpoint_slot_reused_after_grace).
    KTEST_RCU_CANARIED="rcu_free_waits_for_the_reader rcu_idle_cpu_is_quiescent lockdep_no_sleep_in_rcu_read ipc_endpoint_slot_reused_after_grace"
    par "ktest rcu canaries (rv)" ktest_row "ktest rcu canaries (rv)" rv "" "$KTEST_RCU_CANARIED" "$KTEST_RCU_CANARIES"
    par "ktest rcu canaries (arm)" ktest_row "ktest rcu canaries (arm)" arm "" "$KTEST_RCU_CANARIED" "$KTEST_RCU_CANARIES"
    # N5 (kernel/src/smokes/ipc_endpoint.rs), one
    # boot of the pass row's kernel: `canary=ipc-no-peer-died` (a server's
    # death leaves its accepted call in service, nobody completes it, the
    # caller never returns: ipc_server_death_completes_call_peer_died times
    # out). N5b, the same boot: `canary=ipc-no-senders-wipe` (a task's exit
    # does not count its endpoint send capabilities out: the count never
    # falls, ipc_no_senders_once_after_staggered_exits times out) and
    # `port-no-vanish` (a destroyed port source stays bound and silent:
    # port_source_gone_wakes_the_waiter times out). N11: `ipc-reply-twice`
    # (a second reply on one warrant is delivered:
    # ipc_reply_warrant_moves_to_worker_and_is_send_once). N11b:
    # `canary=ipc-v2-as-v1`
    # (the v2 accept reads every call as v1, no badge:
    # ipc_v2_call_carries_caps_words_and_badge). N11c:
    # `canary=ipc-v1-takes-v2` (the v1 accept takes a v2 call instead of
    # refusing it: ipc_v2_call_refused_by_v1_accept). Chain E stage a:
    # `canary=ipc-force-slow` (the IPC fast path is off for the boot: every
    # answer is right but the hit counters do not move,
    # ipc_fastpath_taken_when_parked). Chain E commit 9:
    # `canary=ipc-resume-off` (no resume point is left:
    # ipc_fastpath_resumes_at_the_point, and the three ipc_fastpath_resume_point_*
    # find no task parked with one) and `canary=ipc-resume-stale` (a task
    # resumed where it blocked keeps its point: ipc_fastpath_resume_point_*);
    # `ipc-force-slow` alone turns those four red as well.
    KTEST_IPC_CANARIES="canary=ipc-no-peer-died,ipc-no-senders-wipe,port-no-vanish,ipc-reply-twice,ipc-v2-as-v1,ipc-v1-takes-v2,ipc-force-slow,ipc-resume-off,ipc-resume-stale"
    KTEST_IPC_CANARIED="ipc_server_death_completes_call_peer_died ipc_no_senders_once_after_staggered_exits port_source_gone_wakes_the_waiter ipc_reply_warrant_moves_to_worker_and_is_send_once ipc_v2_call_carries_caps_words_and_badge ipc_v2_call_refused_by_v1_accept ipc_v2_refused_call_caps_revoked_on_caller_exit ipc_fastpath_taken_when_parked ipc_fastpath_resumes_at_the_point ipc_fastpath_resume_point_kill ipc_fastpath_resume_point_drain ipc_fastpath_resume_point_ordinary_call ipc_fastpath_call_edge_is_in_the_graph"
    par "ktest ipc canary (rv)" ktest_row "ktest ipc canary (rv)" rv "" "$KTEST_IPC_CANARIED" "$KTEST_IPC_CANARIES"
    par "ktest ipc canary (arm)" ktest_row "ktest ipc canary (arm)" arm "" "$KTEST_IPC_CANARIED" "$KTEST_IPC_CANARIES"
    # N9 (Kconfig FUTEX_REQUEUE, kernel/src/smokes/futex_requeue.rs), one boot
    # of the pass row's kernel: `canary=futex-requeue-wake-all` (a requeue
    # wakes every waiter on the condition word and moves none: the herd
    # counter reads 6, futex_requeue_wakes_one_not_the_herd not ok).
    KTEST_FUTEX_CANARIES="canary=futex-requeue-wake-all"
    KTEST_FUTEX_CANARIED="futex_requeue_wakes_one_not_the_herd"
    par "ktest futex canary (rv)" ktest_row "ktest futex canary (rv)" rv "" "$KTEST_FUTEX_CANARIED" "$KTEST_FUTEX_CANARIES"
    par "ktest futex canary (arm)" ktest_row "ktest futex canary (arm)" arm "" "$KTEST_FUTEX_CANARIED" "$KTEST_FUTEX_CANARIES"
    # N8 (kernel Mutex, crates/core/sync/src/kmutex.rs), one boot of the
    # pass row's kernel: `canary=kmutex-io-held` (`unlocked_for_io` keeps the
    # mutex across the device wait, rule F1: kmutex_unlocked_for_io) and
    # `canary=claim-mutex-held` (a claim's owner keeps the exchange mutex, so
    # a Mutex is held across its device waits: claim_holds_no_mutex_across_a_device_wait).
    KTEST_KMUTEX_CANARIES="canary=kmutex-io-held,claim-mutex-held"
    KTEST_KMUTEX_CANARIED="kmutex_unlocked_for_io claim_holds_no_mutex_across_a_device_wait"
    par "ktest kmutex canary (rv)" ktest_row "ktest kmutex canary (rv)" rv "" "$KTEST_KMUTEX_CANARIED" "$KTEST_KMUTEX_CANARIES"
    par "ktest kmutex canary (arm)" ktest_row "ktest kmutex canary (arm)" arm "" "$KTEST_KMUTEX_CANARIED" "$KTEST_KMUTEX_CANARIES"
    # N6a + N7, one boot of the pass row's kernel: `canary=sched-class-invert`
    # (the class walk runs its precedence backwards: sched_class_precedence)
    # and `pi-depth-1` (the wait graph walks one owner: waitgraph_transitive_chain,
    # waitgraph_dl_donor_and_attr_changed, waitgraph_depth_cap; the cycle test
    # stays ok), N6b's `schedctl-no-warrant` (SYS_SCHEDCTL binds RT
    # without a time warrant: schedctl_self_promotion_refused), and FX5's
    # `sig-exit-drop` (a detached thread drops its process's signal:
    # signal_retarget_on_thread_detach; it replaced the userspace
    # `linux: signal retarget canary` rows, whose test no longer reaches
    # the path since N9's EINTR), and FX12's `claim-no-donate` (a FAT32
    # claim waiter lends nothing: fat_claim_waiter_donates_to_owner), and N6b's
    # `sched-dl-in-level` (a reservation ranks by its level again:
    # sched_dl_above_rt).
    KTEST_SCHED_CANARIES="canary=sched-class-invert,pi-depth-1,schedctl-no-warrant,sig-exit-drop,claim-no-donate,sched-dl-in-level"
    KTEST_SCHED_CANARIED="sched_class_precedence waitgraph_transitive_chain waitgraph_dl_donor_and_attr_changed waitgraph_depth_cap schedctl_self_promotion_refused signal_retarget_on_thread_detach fat_claim_waiter_donates_to_owner sched_dl_above_rt"
    par "ktest sched canary (rv)" ktest_row "ktest sched canary (rv)" rv "" "$KTEST_SCHED_CANARIED" "$KTEST_SCHED_CANARIES"
    par "ktest sched canary (arm)" ktest_row "ktest sched canary (arm)" arm "" "$KTEST_SCHED_CANARIED" "$KTEST_SCHED_CANARIES"

    # ── Wave 15 (X5): x86_64 in QEMU (`-M microvm`, PVH entry) ───────────────
    #
    # `make x86_64` (X86_64_FEATURES adds cargo features), booted by hand-made
    # QEMU lines like the Makefile's `qemu-x86_64`. These rows attach no
    # disk, so "boots" means the kernel shell on COM1 (the userspace rows
    # below attach one).
    #   x86_64: boots to the shell  the boot self-tests (int3, a self-NMI on
    #                               its IST stack, the tick), W^X, the
    #                               scheduler, the shell prompt; no panic,
    #                               no FAILED, no x86 trap report; COM1's
    #                               output went through the TX ring by the
    #                               THR-empty interrupt (C1; the canary
    #                               X86_64_FEATURES=console-tx-sync prints
    #                               "polled" and fails it)
    #   x86_64: smp 2               CPU 1 started by INIT-SIPI-SIPI, takes its
    #                               ticks and the reschedule IPI
    #   x86_64: baseline canary     -cpu qemu64 (below x86-64-v2): boot.S
    #                               refuses before Rust, nothing else runs
    #   ktest (x86)                 the ktest plan, -smp 4, every test ok, QEMU
    #                               exit status 1 (3 for the canary rows);
    #                               x86_ring3_syscall_fork_fp is the ring-3
    #                               syscall / fork / FP check in place of a
    #                               user image (kernel/src/smokes/x86_64_ring3.rs)
    #   ktest tlb local-only canary (x86)  the shootdown sends no IPI:
    #                               tlb_shootdown_cross_cpu alone not ok
    #   ktest percpu accessor canary (x86)  the accessors of the running task
    #                               take no mask: percpu_accessors_read_masked
    #                               alone not ok
    #   ktest sched tls canary (x86)  the old FS-base rule: an equal base is not
    #                               rewritten and a loaded FS selector stays;
    #                               the two fs_* tests not ok
    #   ktest el0 state canary (x86)  IA32_TSC_AUX not written (QEMU's 0 on
    #                               CPUs 1-3): user_visible_state_is_set_on_every_cpu
    #                               alone not ok
    #   ktest fork FP runtime canary (x86)  canary=x86-fork-fp-skip: a forked
    #                               child starts from the initial FP image;
    #                               x86_ring3_syscall_fork_fp alone not ok
    #   ktest percpu hazard canary (x86)  `classes::current` takes no mask:
    #                               percpu_hazard_reads_are_masked alone not ok
    #   ktest low-half alias runtime canary (x86)  canary=x86-low-alias: the
    #                               first kernel text page is mapped 1:1 in
    #                               the low half again (the layout before the
    #                               kernel linked high); x86_low_half_maps_no_ram
    #                               alone not ok
    # +9 with Kconfig CHAOS / DECISION_RECORDS_DEV (`chaos`, `decisions` ride in
    # every x86 ktest kernel, as on rv and arm); +2 x86_low_half_maps_no_ram,
    # x86_direct_map_image_alias_read_only; +1 camera_one_encode_per_frame
    # (wave 15, B2).
    #   ktest camera encode canary (x86)  canary=camera-encode-per-consumer:
    #                               each camera ring consumer encodes its own
    #                               frame again; camera_one_encode_per_frame
    #                               alone not ok
    # +2 the lockdep tests (N1), as on rv and arm.
    # +4 the N1b lockdep tests, as on rv and arm.
    # +2 spin_wait_cas_semantics, spin_lock_contended_cross_cpu (N2).
    # +1 spin_sites_patched (N2b; x86_64 links no site, so it holds).
    # +1 spin_lock_fifo_bounded (N3; -smp 4, as on rv and arm).
    # +1 link_key_hook_runs_unlocked (N3), as on rv and arm.
    # +5 the N4 RCU tests, as on rv and arm.
    # +4 the N5 endpoint tests, as on rv and arm.
    # +1 the N9 futex requeue test, as on rv and arm.
    # +4 the N5b notice tests, as on rv and arm.
    # +1 console_task_line_waits_never_drops (XC).
    # +1 futex_pi_boosts_the_owner (N10w), as on rv and arm.
    # +1 fat_write_device_wait_holds_no_mutex (N8c), as on rv and arm.
    # +1 the N11b v2 call test, as on rv and arm.
    # +2 sched_dl_above_rt, schedctl_self_promotion_refused (N6b), as on
    # rv and arm.
    # +1 the N11c v1-accept refusal test, as on rv and arm.
    # +2 waitgraph_exit_clears_state, kmutex_held_back_newcomer_is_in_the_graph
    # (N7b), as on rv and arm.
    # +1 tlb_space_mask_reaches_the_harts_that_ran (N12b), as on rv and arm.
    # +1 the FX3 refused-call exit-sweep test, as on rv and arm.
    # +1 kmutex_dead_holder_leaves_the_held_table (N7d), as on rv and arm.
    # +1 asid_one_per_space_across_rollover (N12c), as on rv and arm.
    # +1 futex_pi_owner_exit_hands_over (N10b), as on rv and arm.
    # +1 waitgraph_ring3_owner_floored (N7f), as on rv and arm.
    # +1 futex_requeue_pi_hands_the_mutex_over (N10d), as on rv and arm.
    # +1 kernel_half_shared_by_every_root (N12f), Ok at once on x86_64.
    # +1 waitgraph_ipc_call_boosts_server (N7g), as on rv and arm.
    # +1 lockdep_boot_phase_clean (N1d), as on rv and arm.
    # +2 ipc_fastpath_taken_when_parked, ipc_fastpath_not_taken_when_calls_queued
    # (Chain E stage a), as on rv and arm.
    # +1 ipc_resolve_cache_follows_revoke_and_reown (Chain E commit 5), as on
    # rv and arm.
    # +1 preempt_count_survives_irq_nesting (Chain E commit 7), as on rv and
    # arm.
    # +4 the resume-point tests (Chain E commit 9), as on rv and arm.
    # +2 the WAIT_GRAPH fast-path tests (Chain E), as on rv and arm.
    # +1 waitgraph_quiet_keys_match_base (Chain E cut 6), as on rv and arm.
    # +3 the claim tests and +1 block_read_has_a_bounce_buffer_per_call
    # (Chain A), +1 why_resolves_a_refused_reservation, +2 the QoS timer slack
    # tests, +1 the coalescing path test, as on rv and arm.
    # The same count on x86_64: 3552 / 32 = 111.
    # +2 as above, +2 for the interrupt ktests -> 116.
    # +1 hv_enter_guest (the guest entry of `Hypervisor::enter` on a real SVM CPU),
    # +1 hv_svm_guest_exits (the SVM guest-exit ladder, x86_64 only) -> 118.
    # +3 mm_ro_after_init_sealed, mm_kaslr_image_alias,
    # kaslr_stored_pointers_follow_the_image, as on rv and arm -> 121.
    # +1 copyout_refused_in_kernel_context, as on rv and arm -> 122.
    # +1 percpu_accessors_read_masked, as on rv and arm -> 123.
    # +1 percpu_hazard_reads_are_masked, as on rv and arm -> 124.
    # -1 procfs_entries_registered, as on rv and arm -> 123.
    # +1 uaccess_refuses_a_user_device_window, as on rv and arm -> 124.
    # +1 shootdown_reaches_a_masked_lock_waiter, as on rv and arm -> 125.
    # +1 rt_motor_coasts_a_held_wheel, as on rv and arm -> 126.
    # +1 tlb_kernel_shootdown_names_every_online_cpu (x86_64 only) -> 127.
    # +2 fs_selector_load_keeps_the_next_task_s_fs_base and
    # fs_gs_selectors_do_not_follow_a_task (tls-hygiene, x86_64 only; canary
    # `fs-base-cache-canary`) -> 129.
    # +1 user_visible_state_is_set_on_every_cpu (tls-hygiene), as on rv and
    # arm -> 130.
    KTEST_N_X86=130
    x86_kbuild() { # x86_kbuild <extra cargo features or ""> <image copy>
        par_shared "x86_64 kernel ${1:-plain}" || return 1
        # The copy is the row's own kernel (no `par_ready` clone needed): its
        # `.features` (the X86_64_FEATURES terms, "" for the plain kernel)
        # travels with it, for `x86_kernel_check`.
        rm -f "$2" "$2.features"
        # `X86_KBUILD_ARGS` / `X86_KBUILD_OUT`: a build from another
        # configuration into an image of its own (`x86_ktest_row_nodur`).
        # Without one, the gate's cell: generic, or robot when the features
        # close over `use-robot`, each expanded into its own file.
        local def; def="$(gate_defc x86 "$1")"
        make x86_64 X86_64_FEATURES="$1" ${X86_KBUILD_ARGS:-X86_64_DEFCONFIG=config/defconfigs/$def.config X86_64_KCONFIG=$AZOS_OUT/build/x86_64-$def.config} >/dev/null 2>&1 && cp "${X86_KBUILD_OUT:-$AZOS_OUT/build/kernel-x86_64.elf}" "$2" \
            && builtin printf '%s\n' "$1" >"$2.features"
    }
    x86_qemu() { # x86_qemu <image> <log> <secs> <stop ERE or ""> [qemu args...]; sets X86_QRC
        local img="$1" log="$2" secs="$3" stop="$4" i=0; shift 4
        X86_QRC=refused
        x86_kernel_check "$img" || return 1
        while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
        : >"$log"   # exists before the first poll reads it
        qemu-system-x86_64 -M "${X86_MACHINE:-microvm}" -cpu "${X86_CPU:-max}" -m 256M -nographic -no-reboot \
            -device isa-debug-exit,iobase=0xf4,iosize=0x04 "$@" -kernel "$img" </dev/null >"$log" 2>&1 &
        local pid=$!
        while [ "$i" -lt $((secs * 2)) ] && kill -0 "$pid" 2>/dev/null; do
            [ -n "$stop" ] && tr -d '\r' <"$log" | grep -aqE "$stop" && break
            i=$((i + 1)); sleep 0.5
        done
        X86_QRC=stopped
        if kill -0 "$pid" 2>/dev/null; then
            kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        else
            wait "$pid" 2>/dev/null; X86_QRC=$?
        fi
        tr -d '\r' <"$log" >"$log.t" && mv "$log.t" "$log"
        return 0   # only a refused kernel returns 1: its callers stop on it
    }
    x86_boot_row() { # x86_boot_row <label> <smp> <cpu model> <want lines, |-separated fixed strings> <stop ERE> [features] [boots]
        # `boots`: the model meets the baseline and must boot clean (default:
        # only `max` does; any other model is a below-baseline canary).
        local label="$1" smp="$2" cpu="$3" want="$4" stop="$5" feats="${6:-}" boots="${7:-}" why="" w
        [ -n "$boots" ] || { [ "$cpu" = max ] && boots=1 || boots=0; }
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}"
        x86_kbuild "$feats" "$kimg" || { bad; echo "      make x86_64 X86_64_FEATURES=$feats did not build"; return; }
        par_ready
        x86_qemu "$kimg" "$log" 60 "$stop" -smp "$smp" -cpu "$cpu" || { rm -f "$kimg" "$kimg.features"; return; }
        rm -f "$kimg" "$kimg.features"
        local IFS='|'
        for w in $want; do
            grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
        done
        unset IFS
        if [ -z "$why" ] && [ "$boots" = 1 ]; then
            grep -aqE 'KERNEL PANIC|FAILED|\[X86-TRAP\]' "$log" \
                && why="$(grep -aE 'KERNEL PANIC|FAILED|\[X86-TRAP\]' "$log" | sed -n 1p)"
        fi
        if [ -z "$why" ] && [ "$boots" = 0 ] && grep -aqF 'AzOS Rust kernel booted' "$log"; then
            why="a CPU below the baseline reached Rust"
        fi
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    X86_SHELL="AzOS shell — type 'help' for commands"
    # The trap and tick self-tests are boot self-tests (Kconfig BOOT_SELFTESTS),
    # which the x86_64 defconfig leaves off: the row asks for them.
    par "x86_64: boots to the shell" x86_boot_row "x86_64: boots to the shell" 1 max \
        "[TRAP] int3 self-test: PASS|[TRAP] NMI self-test: PASS|[TIMER] tick self-test: PASS|[MM] W^X ok|[MM] x86_64 SMEP=true SMAP=true UMIP=true|[UART] COM1 TX interrupt-driven|[SCHED] Starting scheduler on boot CPU|$X86_SHELL" \
        "AzOS shell|KERNEL PANIC" boot-selftests
    par "x86_64: smp 2" x86_boot_row "x86_64: smp 2" 2 max \
        "[SMP] CPU 1 online: APIC ID 1|[SMP] CPU 1 took|[IPI] sent by CPU 0, received by CPU 1|$X86_SHELL" \
        "AzOS shell|KERNEL PANIC"
    par "x86_64: baseline canary (qemu64)" x86_boot_row "x86_64: baseline canary (qemu64)" 1 qemu64 \
        "[X86] CPU below the configured baseline" "below the configured baseline"
    # `boot: no self-tests by default` on x86_64 (see the riscv64/aarch64 rows'
    # comment, beside the NR_CPUS rows): the plain kernel, booted to the shell.
    x86_selftests_off_row() {
        local label="boot: no self-tests by default (x86)" why
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/x86-selftests-off.log" kimg="$CI_LOG_DIR/kernel-x86-selftests-off"
        x86_kbuild "" "$kimg" || { bad; echo "      make x86_64 did not build"; return; }
        par_ready
        x86_qemu "$kimg" "$log" 60 "AzOS shell|KERNEL PANIC" -smp 2 -cpu max || { rm -f "$kimg" "$kimg.features"; return; }
        why="$(selftests_off_check "$log" "$kimg")"
        rm -f "$kimg" "$kimg.features"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; printf '%s\n' "$why" | sed 's/^/      /'; echo "      log kept: $log"
    }
    par "boot: no self-tests by default (x86)" x86_selftests_off_row
    # CPU microcode at boot (Kconfig X86_UCODE_LOAD, crates/core/arch-x86_64/src/
    # cpu/ucode.rs, kernel/src/entry/x86_64/ext/ucode.rs): the signed image
    # (`make ucode`, mk/firmware.mk, every Intel and AMD file under AZOS_DL) as
    # the PVH boot module, one kernel embedding the TEST key the image is
    # signed with, four boots. With the hypervisor bit off the loader runs as on
    # bare metal; QEMU's TCG reads IA32_PLATFORM_ID as 0 (platform flag 0x1) and
    # IA32_BIOS_SIGN_ID as revision 1, and ignores the MSR write:
    #   * Skylake-Server (0x50654): 06-55-04's update lists flag 0x1: chosen,
    #     checksummed, written, and the revision reads back unchanged;
    #   * Skylake-Client (0x506e3): 06-5e-03's signature matches, its flags
    #     (0x36) do not: refused, "no matching patch";
    #   * the image with one payload byte flipped: the signature refuses it;
    #   * EPYC-Rome with the hypervisor bit on (QEMU's default): nothing written.
    # Every boot reaches the shell, the mitigation probe after the [UCODE] line.
    # (Not a row: AMD with the bit off, because TCG answers `rdpmc` with #UD and
    # the PMU probe assumes AMD's legacy counters on bare metal; the loader's
    # line, "patch revision 0x830107c written, not taken", comes before it.)
    # SKIPPED, not failed, without the downloads.
    x86_ucode_row() { # x86_ucode_row <label>
        local label="$1" why="" tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        printf "  %-26s" "${label}..."
        local dl="${AZOS_DL:-$HOME/azos-dl}"
        if [ ! -d "$dl/intel-ucode/intel-ucode" ] || [ ! -d "$dl/amd-fw/amd-ucode" ]; then
            SKIP=$((SKIP + 1)); echo "skipped (no intel-ucode or amd-ucode under $dl)"; return
        fi
        mkdir -p "$CI_LOG_DIR"
        local kimg="$CI_LOG_DIR/kernel-x86-${tag}" full="$CI_LOG_DIR/${tag}-full.bin" bad_img="$CI_LOG_DIR/${tag}-corrupt.bin"
        PROD_PUBKEY_PATH="$REPO_ROOT/tools/keys/test_pub.bin" x86_kbuild "" "$kimg" \
            || { bad; echo "      make x86_64 (TEST key) did not build"; return; }
        make -s ucode UCODE_BIN="$full" >/dev/null 2>&1 \
            || { bad; echo "      make ucode did not build the image"; rm -f "$kimg" "$kimg.features"; return; }
        # One byte of the payload (past the 112-byte RSIG) flipped.
        python3 -c 'import sys; b = bytearray(open(sys.argv[1], "rb").read()); b[4096] ^= 1; open(sys.argv[2], "wb").write(b)' "$full" "$bad_img"
        par_ready
        local case img cpu want log
        for case in match pf corrupt guest; do
            img="$full"
            case "$case" in
                match) cpu="Skylake-Server-v1,-hypervisor"
                    want="signature 0x50654 platform flags 0x1 revision 0x1|[UCODE] patch revision 0x2007006 written, not taken: revision 0x1 -> 0x1" ;;
                pf) cpu="Skylake-Client-v1,-hypervisor"
                    want="signature 0x506e3 platform flags 0x1 revision 0x1|[UCODE] no matching patch for this CPU: revision 0x1 stays" ;;
                corrupt) cpu="Skylake-Client-v1,-hypervisor"; img="$bad_img"
                    want="[UCODE] REFUSED: the image at|does not verify against the update key" ;;
                guest) cpu="EPYC-Rome-v1"
                    want="[UCODE] image verified (|under a hypervisor, which owns the microcode: nothing written" ;;
            esac
            log="$CI_LOG_DIR/x86-${tag}-${case}.log"
            X86_CPU="$cpu" x86_qemu "$kimg" "$log" 90 "$X86_SHELL|KERNEL PANIC|\[X86-TRAP\]" -smp 2 -initrd "$img" \
                || { why="$case: the kernel was refused"; break; }
            local w IFS='|'
            for w in $want "$X86_SHELL"; do
                grep -aqF -- "$w" "$log" || { why="$case: missing: $w"; break; }
            done
            unset IFS
            [ -n "$why" ] && break
            local u m
            u="$(grep -anF '[UCODE]' "$log" | sed -n 1p | cut -d: -f1)"
            m="$(grep -anF '[MITIGATE] cpu ' "$log" | sed -n 1p | cut -d: -f1)"
            if [ -z "$m" ] || [ "$u" -gt "$m" ]; then why="$case: the mitigation probe did not run after the update"; break; fi
            if grep -aqE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log"; then why="$case: $(grep -aE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" | sed -n 1p)"; break; fi
            rm -f "$log"
        done
        rm -f "$kimg" "$kimg.features" "$full" "$bad_img"
        if [ -z "$why" ]; then ok; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: microcode loader" x86_ucode_row "x86_64: microcode loader"
    # An AMD model with the hypervisor bit hidden (`-cpu EPYC,-hypervisor`):
    # CPUID looks like bare metal, family 0x17 without PerfCtrExtCore. The
    # PMU probe must name no counter (`azos_arch_api::pmu::amd_decode`'s
    # family gate) and the liveness check reads counters through their MSRs,
    # never `rdpmc`, which TCG answers with #UD: the boot reaches the shell
    # with the TSC standing in for cycles. Canary (by hand, 2026-10-23): the
    # family gate dropped, the legacy four are assumed and, with `rdpmc` in
    # the liveness check, the boot traps right after the mitigation line.
    par "x86_64: PMU probe, EPYC without the hypervisor bit" x86_boot_row "x86_64: PMU probe, EPYC without the hypervisor bit" 1 "EPYC,-hypervisor" \
        "[PMU] x86_64 cycles=tsc/64 instret=none events=0 user=none sample=none|$X86_SHELL" "AzOS shell|KERNEL PANIC" "" 1
    # Stack frames and the deepest trap chain (`frame_row`, `chain_row`, beside
    # the riscv64 kernels' rows) on the gate's two x86_64 kernels, the generic
    # cell's and the robot cell's. Every indirect call goes through a retpoline
    # thunk on x86_64; tools/stack_chain.py reads the thunk's target from the
    # instruction stream where it is static (`edges`).
    x86_stack_row() { # x86_stack_row <label> <frames|chain> <features or "">
        local kimg="$CI_LOG_DIR/kernel-x86-stack-$2-${3:-generic}"
        mkdir -p "$CI_LOG_DIR"
        if ! x86_kbuild "$3" "$kimg"; then
            printf "  %-26s" "${1}..."; bad; echo "      make x86_64 X86_64_FEATURES=$3 did not build"; return
        fi
        par_ready
        if [ "$2" = frames ]; then frame_row "$1" "$kimg" 8192
        else chain_row "$1" "$kimg" "$AZOS_OUT/build/x86_64-$(gate_defc x86 "$3").config" 192; fi
        rm -f "$kimg" "$kimg.features"
    }
    par "stack frames: x86_64" x86_stack_row "stack frames: x86_64" frames ""
    par "stack chain: x86_64" x86_stack_row "stack chain: x86_64" chain ""
    par "stack frames: x86_64 robot" x86_stack_row "stack frames: x86_64 robot" frames use-robot
    par "stack chain: x86_64 robot" x86_stack_row "stack chain: x86_64 robot" chain use-robot
    # The same two on the gate's aarch64 kernel (the generic cell's), with its
    # 304-byte trap frame (`TrapFrame`'s size assert, kernel/src/entry/aarch64/
    # mod.rs). Until 2026-10-24 only riscv64 and x86_64 kernels had them.
    a64_stack_row() { # a64_stack_row <label> <frames|chain>
        if ! a64_kbuild ""; then
            printf "  %-26s" "${1}..."; bad; echo "      the aarch64 kernel did not build"; return
        fi
        par_ready
        if [ "$2" = frames ]; then frame_row "$1" "$A64_KERNEL" 8192
        else chain_row "$1" "$A64_KERNEL" "$AARCH64_CONFIG" 304; fi
    }
    par "stack frames: aarch64" a64_stack_row "stack frames: aarch64" frames
    par "stack chain: aarch64" a64_stack_row "stack chain: aarch64" chain
    # virtio-input on x86_64 (Kconfig DRV_VIRTIO_INPUT): the kernel shell reads a
    # `-device virtio-keyboard-device` (a virtio-mmio v1 transport on microvm)
    # with the serial stdin silent. A typist in the background waits for the
    # `robot> ` prompt and types `help` through the QEMU monitor
    # (tools/qemu_sendkeys.py); the row needs the help text itself, which the
    # typed echo does not contain. The canary kernel drops every key byte at the
    # driver: the boot line is there, the shell never sees the command.
    x86_vkbd_row() { # x86_vkbd_row <label> <extra features or ""> <PASS|FAIL>
        local label="$1" extra="$2" expect="$3" why=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" sock="$CI_LOG_DIR/x86-${tag}.mon"
        x86_kbuild "$extra" "$kimg" || { bad; echo "      make x86_64 X86_64_FEATURES=$extra did not build"; return; }
        rm -f "$sock"; : >"$log"
        par_ready
        ( local t=0
          while [ "$t" -lt 120 ] && ! grep -aqF 'robot> ' "$log" 2>/dev/null; do t=$((t + 1)); sleep 0.5; done
          sleep 1
          python3 tools/qemu_sendkeys.py "$sock" "help" ) >/dev/null 2>&1 &
        local typist=$!
        local stop="help +- this message" secs=60
        [ "$expect" = FAIL ] && { stop=""; secs=30; }
        x86_qemu "$kimg" "$log" "$secs" "$stop" -smp 1 -device virtio-keyboard-device \
            -chardev "socket,id=mon0,path=$sock,server=on,wait=off" -mon chardev=mon0,mode=readline \
            || { kill "$typist" 2>/dev/null; rm -f "$kimg" "$kimg.features" "$sock"; return; }
        wait "$typist" 2>/dev/null
        rm -f "$kimg" "$kimg.features" "$sock"
        grep -aqF '[VIRTIO-INPUT] keyboard events by interrupt' "$log" || why="no virtio-input boot line"
        if [ "$expect" = FAIL ]; then
            if grep -aqF -- 'help              - this message' "$log"; then
                bad; echo "      the canary build passed: the row does not discriminate"; echo "      log kept: $log"
            elif [ -n "$why" ]; then
                bad; echo "      $why: the canary never wired the device, so it proves nothing"; echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: the keyboard was wired, the command never reached the shell"; rm -f "$log"
            fi
            return
        fi
        [ -z "$why" ] && ! grep -aqF -- 'help              - this message' "$log" && why="the typed command never ran"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: virtio keyboard" x86_vkbd_row "x86_64: virtio keyboard" "" PASS
    par "x86_64: virtio keyboard canary" x86_vkbd_row "x86_64: virtio keyboard canary" "virtio-input-canary" FAIL
    # virtio-sound on x86_64 (Kconfig DRV_VIRTIO_SND): the device on the
    # microvm's virtio-mmio bus (version 2: the sound device has no legacy
    # interface) is found by the hardware bus, bring-up reads its streams and
    # picks a run point, and its interrupt line is wired. The playback itself
    # is `sh: beep on virtio-sound`; this machine boots the kernel shell and no
    # ring-3 one. The canary is the same boot with no sound device: no line.
    x86_snd_row() { # x86_snd_row <label> <with|without> <PASS|FAIL>
        local label="$1" dev="$2" expect="$3" why=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" extra=()
        x86_kbuild "" "$kimg" || { bad; echo "      make x86_64 did not build"; return; }
        [ "$dev" = with ] && extra=(-audiodev none,id=a -device virtio-sound-device,audiodev=a)
        x86_qemu "$kimg" "$log" 40 "$X86_SHELL" -smp 1 -global virtio-mmio.force-legacy=false ${extra[@]+"${extra[@]}"} \
            || { rm -f "$kimg" "$kimg.features"; return; }
        rm -f "$kimg" "$kimg.features"
        grep -aqE '\[VIRTIO-SND\] virtio-mmio .* streams' "$log" || why="no virtio-sound bring-up line"
        grep -aqF '[VIRTIO-SND] completions by interrupt on line' "$log" || why="${why:+$why; }the line was not wired"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then ok; echo "      canary failed as it must: no device, no line"; rm -f "$log"
            else bad; echo "      the canary build passed: the row does not discriminate"; echo "      log kept: $log"; fi
            return
        fi
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: virtio sound" x86_snd_row "x86_64: virtio sound" with PASS
    par "x86_64: virtio sound canary" x86_snd_row "x86_64: virtio sound canary" without FAIL
    # PCI on x86_64 (Kconfig DRV_PCI + DRV_NVME, config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config):
    # QEMU microvm has no PCI bus unless `pcie=on`, and then neither an MCFG nor
    # ports 0xCF8/0xCFC, so the ECAM comes from Kconfig X86_PCI_ECAM_BASE. The
    # FAT32 volume is an NVMe namespace: the controller enumerates, completes by
    # MSI-X straight to the local APIC (a vector from the MSI block), and the
    # volume mounts from it. The canary kernel names an ECAM base nothing
    # decodes: the bus must read as empty (no phantom 0000:0000 functions), so
    # no controller, no NVMe boot disk and no mount, with the host bridge line
    # printed to show the PCI code ran.
    x86_pci_row() { # x86_pci_row <label> <ecam base override or ""> <PASS|FAIL>
        local label="$1" ecam="$2" expect="$3" why="" w
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" dimg="$CI_LOG_DIR/disk-x86-${tag}.img"
        local def=config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config
        rm -f "$kimg" "$kimg.features"
        if [ -n "$ecam" ]; then
            def="$CI_LOG_DIR/x86-${tag}.defconfig"
            sed "s/^CONFIG_X86_PCI_ECAM_BASE=.*/CONFIG_X86_PCI_ECAM_BASE=$ecam/" config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config >"$def"
        fi
        make x86_64 X86_64_DEFCONFIG="$def" X86_64_KCONFIG="$AZOS_OUT/build/x86_64-pci-${tag}.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-pci-${tag}" X86_64_IMG="$kimg" >/dev/null 2>&1 \
            && builtin printf '\n' >"$kimg.features" \
            || { bad; echo "      make x86_64 (qemu-x86_64-pci.config) did not build"; return; }
        fresh_disk $AZOS_OUT/build/disk-x86_64.img && cp $AZOS_OUT/build/disk-x86_64.img "$dimg" \
            || { bad; echo "      $AZOS_OUT/build/disk-x86_64.img did not build"; return; }
        par_ready
        X86_MACHINE=microvm,pcie=on x86_qemu "$kimg" "$log" 60 'prp selftest|KERNEL PANIC' -smp 1 \
            -drive "file=$dimg,if=none,format=raw,id=pcinvme0" -device nvme,serial=deadbeef,drive=pcinvme0 \
            || { rm -f "$kimg" "$kimg.features" "$dimg"; return; }
        rm -f "$kimg" "$kimg.features" "$dimg"
        grep -aqF '[PCI] host bridge: ECAM' "$log" || why="no PCI host bridge line: the PCI code did not run"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then
                bad; echo "      $why: the canary proves nothing"; echo "      log kept: $log"
            elif grep -aqE 'NVME\] controller .* ns1|0000:0000|FAT32 mounted' "$log"; then
                bad; echo "      the canary kernel (ECAM $ecam) found a bus: the row does not discriminate"; echo "      log kept: $log"
            elif ! grep -aqF '[PCI] bus 0 enumeration: 0 function(s) found' "$log"; then
                bad; echo "      the canary bus did not read as empty"; echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: ECAM $ecam read as an empty bus (no phantom functions)"; rm -f "$log"
            fi
            return
        fi
        if [ -z "$why" ]; then
            for w in '[PCI] host bridge: ECAM 0xe0000000 (kconfig)' '[PCI] bus 0 enumeration: 2 function(s) found' \
                     ' 1b36:0010 ' '[NVME] controller 00:01.0 ns1' '[NVME] completions by interrupt' \
                     '[FS] Block device OK' '[FS] FAT32 mounted at /fat' '[NVME] prp selftest PASS'; do
                grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
            done
        fi
        [ -z "$why" ] && ! grep -aqE '\[NVME\] by interrupt: [1-9][0-9]* taken' "$log" && why="no NVMe completion arrived by interrupt"
        [ -z "$why" ] && grep -aqF '0000:0000' "$log" && why="a phantom function (vendor 0) was enumerated"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: PCI NVMe mounts FAT (microvm pcie)" x86_pci_row "x86_64: PCI NVMe mounts FAT (microvm pcie)" "" PASS
    par "x86_64: PCI wrong ECAM canary" x86_pci_row "x86_64: PCI wrong ECAM canary" "0xF0000000" FAIL
    # A SATA disk behind an AHCI host (Kconfig DRV_AHCI, crates/drivers/block/src/ahci.rs)
    # on QEMU q35 (its MCFG names the ECAM window): the FAT32 volume is a disk on
    # an `ich9-ahci` the row adds next to q35's own (which has no drive). The
    # driver resets the HBA, finds the port with the disk, identifies it, takes
    # the HBA's MSI to the local APIC and becomes the block device: the volume
    # mounts from it, a read and a flush from task context are completions by
    # interrupt that woke a sleeping waiter. The canary kernel is the same image
    # without DRV_AHCI: the controller enumerates (8086:2922) and nothing drives
    # it, so there is no `[AHCI]` line and no mount (the disk is on no other bus).
    # First boot (2026-10-23, ahci-ncq-fua-trim): the PASS, NCQ-off and no-TRIM
    # boots were run by hand with this function's QEMU line and their logs
    # replayed through its greps; the function itself has not run under `par`.
    #
    # The queue and the features (boot/ahci.rs `ahci_queue_selftest`): QEMU's
    # HBA and ide-hd queue (NCQ), so the disk gets more than one command slot
    # and a read of four commands' worth has two or more in it at once; ide-hd
    # advertises TRIM by default, so the scratch file FAT32 writes and removes
    # has its chain discarded as DATA SET MANAGEMENT (TRIMs > 0); FUA is what
    # IDENTIFY word 84 says, and the block layer's fsync commit must agree
    # (QEMU's ide-hd has no FUA: only the fallback is seen here; a FUA write
    # is proven by the host model, `ahci_tests.rs`).
    # Canaries: the same image built with AHCI_NCQ_DEPTH=1 must fail the queue
    # checks and pass the rest; the pass image on an ide-hd with
    # discard_granularity=0 must show trim=n and no TRIM, and still mount.
    # The queue evidence is a boot self-test (it writes and removes a scratch
    # file): every image of the row is built with Kconfig BOOT_SELFTESTS.
    x86_ahci_row() { # x86_ahci_row <label> <PASS|FAIL|NONCQ|NOTRIM>
        local label="$1" expect="$2" why="" qwhy="" w
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" dimg="$CI_LOG_DIR/disk-x86-${tag}.img"
        local base=config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config def="$CI_LOG_DIR/x86-${tag}.defconfig"
        local hd="ide-hd,drive=sata0,bus=ahci.0" stop='AHCI\] queue:|KERNEL PANIC'
        rm -f "$kimg" "$kimg.features"
        case "$expect" in
            FAIL)
                { sed '/^CONFIG_DRV_AHCI=y/d' "$base"; echo "$GATE_KCONFIG_EXTRA"; } >"$def"
                stop='AHCI\] by interrupt|KERNEL PANIC' ;;
            NONCQ)
                { sed '/^CONFIG_AHCI_NCQ_DEPTH=/d' "$base"; echo CONFIG_AHCI_NCQ_DEPTH=1; echo "$GATE_KCONFIG_EXTRA"; } >"$def" ;;
            *)
                { cat "$base"; echo "$GATE_KCONFIG_EXTRA"; } >"$def"
                [ "$expect" = NOTRIM ] && hd="$hd,discard_granularity=0" ;;
        esac
        make x86_64 X86_64_DEFCONFIG="$def" X86_64_KCONFIG="$AZOS_OUT/build/x86_64-ahci-${tag}.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-ahci-${tag}" X86_64_IMG="$kimg" >/dev/null 2>&1 \
            && builtin printf '\n' >"$kimg.features" \
            || { bad; echo "      make x86_64 (qemu-x86_64-pci.config) did not build"; return; }
        fresh_disk $AZOS_OUT/build/disk-x86_64.img && cp $AZOS_OUT/build/disk-x86_64.img "$dimg" \
            || { bad; echo "      $AZOS_OUT/build/disk-x86_64.img did not build"; return; }
        par_ready
        X86_MACHINE=q35 x86_qemu "$kimg" "$log" 60 "$stop" -smp 1 \
            -drive "file=$dimg,if=none,format=raw,id=sata0" -device ich9-ahci,id=ahci -device "$hd" \
            || { rm -f "$kimg" "$kimg.features" "$dimg"; return; }
        rm -f "$kimg" "$kimg.features" "$dimg"
        grep -aqF '[PCI] host bridge: ECAM' "$log" || why="no PCI host bridge line: the PCI code did not run"
        [ -z "$why" ] && ! grep -aqF ' 8086:2922 ' "$log" && why="the ich9-ahci function was not enumerated"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then
                bad; echo "      $why: the canary proves nothing"; echo "      log kept: $log"
            elif grep -aqE 'AHCI\]|FAT32 mounted' "$log"; then
                bad; echo "      the canary kernel (no DRV_AHCI) drove the disk: the row does not discriminate"; echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: without DRV_AHCI the SATA disk is not driven and nothing mounts"; rm -f "$log"
            fi
            return
        fi
        if [ -z "$why" ]; then
            for w in '[AHCI] completions by interrupt' '[FS] Block device OK' '[FS] FAT32 mounted at /fat'; do
                grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
            done
        fi
        [ -z "$why" ] && ! grep -aqE '\[AHCI\] port [0-9]+ .*: [0-9]+ sectors mode=irq' "$log" && why="no AHCI disk identified in interrupt mode"
        [ -z "$why" ] && ! grep -aqE '\[AHCI\] by interrupt: [1-9][0-9]* taken, [1-9][0-9]* waits slept \(read ok, flush Ok\(\(\)\), sig 55aa\)' "$log" \
            && why="no AHCI completion arrived by interrupt"
        [ -z "$why" ] && ! grep -aqE '\[AHCI\] queue: .*scratch file write ok remove ok$' "$log" && why="the FAT32 scratch file was not written and removed"
        # What IDENTIFY said (fua, trim: y/n), and what the driver counted.
        local id fua trim q
        id="$(grep -aE '\[AHCI\] port [0-9]+ .*: [0-9]+ sectors mode=' "$log" | sed -n 's/.* fua=\([yn]\) trim=\([yn]\) .*/\1 \2/p' | sed -n 1p)"
        fua="${id% *}" trim="${id#* }"
        q="$(grep -aE '\[AHCI\] queue: ' "$log" | sed -n 1p)"
        [ -z "$why" ] && [ -z "$id" ] && why="the identify line names no fua=/trim="
        [ -z "$why" ] && ! printf '%s\n' "$q" | qgrep -qF "fua commit $fua (" && why="the block layer's FUA commit does not follow IDENTIFY (fua=$fua): $q"
        if [ "$expect" = NOTRIM ]; then
            [ -z "$why" ] && [ "$trim" != n ] && why="a disk with discard_granularity=0 identified with TRIM"
            [ -z "$why" ] && ! printf '%s\n' "$q" | qgrep -qE '; 0 TRIMs;' && why="a TRIM went to a disk without it: $q"
        else
            [ -z "$why" ] && [ "$trim" != y ] && why="the disk did not identify with TRIM"
            [ -z "$why" ] && ! printf '%s\n' "$q" | qgrep -qE '; [1-9][0-9]* TRIMs;' && why="the removed file's chain was not TRIMmed: $q"
        fi
        grep -aqE '\[AHCI\] port [0-9]+: ([2-9]|[12][0-9]|3[0-2]) command slot\(s\), native command queuing' "$log" \
            || qwhy="the disk was not driven with NCQ"
        [ -z "$qwhy" ] && ! printf '%s\n' "$q" | qgrep -qE '^\[AHCI\] queue: [0-9]+ slot\(s\), ([2-9]|[1-9][0-9]+) in the disk at once \(read of [0-9]+ sectors ok\)' \
            && qwhy="never two commands in the disk at once: $q"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" | sed -n 1p)"
        if [ "$expect" = NONCQ ]; then
            if [ -n "$why" ]; then
                bad; echo "      $why: the canary proves nothing"; echo "      log kept: $log"
            elif [ -z "$qwhy" ]; then
                bad; echo "      the queue checks pass with AHCI_NCQ_DEPTH=1: they do not discriminate"; echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: $qwhy"; rm -f "$log"
            fi
            return
        fi
        [ -z "$why" ] && why="$qwhy"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: PCI AHCI mounts FAT (q35)" x86_ahci_row "x86_64: PCI AHCI mounts FAT (q35)" PASS
    par "x86_64: PCI AHCI canary (no driver)" x86_ahci_row "x86_64: PCI AHCI canary (no driver)" FAIL
    par "x86_64: PCI AHCI canary (NCQ off)" x86_ahci_row "x86_64: PCI AHCI canary (NCQ off)" NONCQ
    par "x86_64: PCI AHCI disk without TRIM" x86_ahci_row "x86_64: PCI AHCI disk without TRIM" NOTRIM
    # Ring-3 port I/O (Kconfig X86_IOPORT_*, `ty::IOPORT`, DEVICE_IOPORT_ENABLE):
    # BUZZDRV.ELF opens PIT channel 2 (0x42-0x43) and the speaker gate (0x61)
    # through its topology grants and checks, silently, that channel 2 counts
    # before it drives the PC speaker (`drivers/pcspk`); a speaker that does
    # not tick falls back to the pwm endpoint. q35 (its PIT and speaker), the
    # system volume on an `ich9-ahci` as in the AHCI rows above. The negative
    # half (a port outside the grant kills the task) is abitest's.
    x86_pcspk_row() {
        local label="x86_64: buzzer drives the PC speaker (q35)" why=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" dimg="$CI_LOG_DIR/disk-x86-${tag}.img"
        local def=config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config
        rm -f "$kimg" "$kimg.features"
        make x86_64 X86_64_DEFCONFIG="$def" X86_64_KCONFIG="$AZOS_OUT/build/x86_64-pcspk.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-pcspk" X86_64_IMG="$kimg" >/dev/null 2>&1 \
            && builtin printf '\n' >"$kimg.features" \
            || { bad; echo "      make x86_64 ($def) did not build"; return; }
        fresh_disk $AZOS_OUT/build/disk-x86_64.img && cp $AZOS_OUT/build/disk-x86_64.img "$dimg" \
            || { bad; echo "      $AZOS_OUT/build/disk-x86_64.img did not build"; return; }
        par_ready
        X86_MACHINE=q35 x86_qemu "$kimg" "$log" 90 'buzzdrv\] (PC speaker|FAILED)|KERNEL PANIC' -smp 1 \
            -drive "file=$dimg,if=none,format=raw,id=sata0" -device ich9-ahci,id=ahci -device ide-hd,drive=sata0,bus=ahci.0 \
            || { rm -f "$kimg" "$kimg.features" "$dimg"; return; }
        rm -f "$kimg" "$kimg.features" "$dimg"
        if ! grep -aqF '[buzzdrv] PC speaker: PIT channel 2 ticks, ports 0x42-0x43 and 0x61 open in ring 3' "$log"; then
            why="$(grep -a 'buzzdrv\]\|KERNEL PANIC' "$log" | sed -n 1p)"
            bad; echo "      ${why:-no [buzzdrv] line}"; echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "x86_64: buzzer drives the PC speaker (q35)" x86_pcspk_row
    # IOMMU on (x86_64): the rv/arm `iommu:` rows on q35 with the unit QEMU models
    # first on the bus: AMD-Vi (`amd-iommu,dma-remap=on`, found through the ACPI
    # IVRS; every device-table entry blocks until its function is placed). No
    # VT-d row: QEMU's `intel-iommu` offers no pass-through (ECAP.PT clear), which
    # the vt-d unit needs for the functions it does not translate, so the unit
    # is refused there ("no pass-through translation type"). The NIC is a
    # virtio-net-pci function (`-nic none`: no q35 default e1000e) with
    # `iommu_platform=on`, so its DMA goes through the unit. Canary
    # `iommu-tx-canary` as there.
    x86_iommu_row() { # x86_iommu_row <label> <qemu IOMMU device> <flavour> <PASS|CANARY>
        local label="$1" unit="$2" flavour="$3" expect="$4" feats="dhcp-smoke" stop='DHCPSMOKE\]|KERNEL PANIC|\[X86-TRAP\]'
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        [ "$expect" = CANARY ] && { feats="$feats,iommu-tx-canary"; stop='IOMMU\] fault|KERNEL PANIC|\[X86-TRAP\]'; }
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}"
        rm -f "$kimg" "$kimg.features"
        # One target directory per feature set: the two PASS rows share theirs.
        make x86_64 X86_64_DEFCONFIG=config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config X86_64_KCONFIG="$AZOS_OUT/build/x86_64-${tag}.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-iommu-${expect}" X86_64_IMG="$kimg" X86_64_FEATURES="$feats" >/dev/null 2>&1 \
            && builtin printf '%s\n' "$feats" >"$kimg.features" \
            || { bad; echo "      make x86_64 (qemu-x86_64-pci.config, $feats) did not build"; return; }
        par_ready
        X86_MACHINE=q35 x86_qemu "$kimg" "$log" 90 "$stop" -smp 1 -nic none -device "$unit" \
            -netdev user,id=net0 -device virtio-net-pci,netdev=net0,disable-legacy=on,iommu_platform=on \
            || { rm -f "$kimg" "$kimg.features"; return; }
        rm -f "$kimg" "$kimg.features"
        iommu_net_verdict "$log" "$flavour" "$expect" 'KERNEL PANIC|\[X86-TRAP\]'
    }
    par "x86_64 iommu: amd-vi translates the NIC" x86_iommu_row "x86_64 iommu: amd-vi translates the NIC" \
        amd-iommu,dma-remap=on amd-vi PASS
    par "x86_64 iommu: amd-vi refuses unmapped" x86_iommu_row "x86_64 iommu: amd-vi refuses unmapped" \
        amd-iommu,dma-remap=on amd-vi CANARY
    # The TPM 2.0 over the Command Response Buffer (crates/drivers/tpm/src/crb.rs,
    # kernel/src/boot/tpm.rs) on QEMU q35's `-device tpm-crb`: the ACPI TPM2 table
    # names start method 7 with the control area at 0xFED40040, the locality
    # registers below it and one buffer at 0xFED40080. The kernel probes the CRB,
    # runs Startup, reads the PCR banks (GetCapability) and extends the kernel
    # image into PCR TPM_PCR_BASE. The TPM behind the device is swtpm (QEMU's
    # `-tpmdev emulator`); without swtpm on the host the row SKIPs, with the
    # reason (no download here). The canary kernel is built with azos_tpm's
    # canary-crb-start (CTRL_START never written): the probe still answers, the
    # Startup times out on `Start` and the TPM is not used, which also proves
    # the row reached the CRB path.
    # First boot: not run when this was written (no swtpm on the build host).
    x86_tpm_crb_row() { # x86_tpm_crb_row <label> <PASS|FAIL>
        local label="$1" expect="$2" why="" w feats=""
        if ! command -v swtpm >/dev/null 2>&1; then
            SKIP=$((SKIP + 1)); printf "  %-26s%s\n" "${label}..." "SKIP (no swtpm on this host: QEMU's tpm-crb needs it)"; return 0
        fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" tdir="$CI_LOG_DIR/swtpm.$$.${expect}"
        [ "$expect" = FAIL ] && feats=tpm-crb-canary
        x86_kbuild "$feats" "$kimg" || { bad; echo "      make x86_64 (${feats:-plain}) did not build"; return; }
        rm -rf "$tdir"; mkdir -p "$tdir"
        swtpm socket --tpm2 --tpmstate dir="$tdir" --ctrl type=unixio,path="$tdir/sock" --terminate \
            >"$tdir/swtpm.log" 2>&1 &
        local spid=$! i=0
        while [ ! -S "$tdir/sock" ] && [ "$i" -lt 20 ] && kill -0 "$spid" 2>/dev/null; do i=$((i + 1)); sleep 0.5; done
        if [ ! -S "$tdir/sock" ]; then
            kill "$spid" 2>/dev/null; wait "$spid" 2>/dev/null
            bad; echo "      swtpm did not open its socket"; sed -n 1,3p "$tdir/swtpm.log" | sed 's/^/      /'; return
        fi
        par_ready
        X86_MACHINE=q35 x86_qemu "$kimg" "$log" 60 '\[TPM\] PCR[0-9]+ <- kernel|TPM not used|KERNEL PANIC' -smp 1 \
            -chardev socket,id=chrtpm,path="$tdir/sock" -tpmdev emulator,id=tpm0,chardev=chrtpm -device tpm-crb,tpmdev=tpm0 \
            || { kill "$spid" 2>/dev/null; wait "$spid" 2>/dev/null; rm -f "$kimg" "$kimg.features"; return; }
        kill "$spid" 2>/dev/null; wait "$spid" 2>/dev/null
        rm -rf "$tdir" "$kimg" "$kimg.features"
        if [ "$expect" = FAIL ]; then
            if grep -aqF '[TPM] TPM 2.0 vendor' "$log"; then
                bad; echo "      the canary kernel (CTRL_START never written) started the TPM: the row does not discriminate"
                echo "      log kept: $log"
            # QEMU's tpm-crb never sets CTRL_START itself, so the wait for it
            # to clear returns at once and the driver reads its own command
            # back from the shared buffer as the reply: Startup's command
            # code (0x144) as the response code. A real CRB that latched a
            # stale START would time out instead; both prove the CRB path.
            elif ! grep -aqE 'acpi TPM2, CRB: Startup failed \((Timeout\(Start\)|Tpm\(324\))\)' "$log"; then
                bad; echo "      no CRB Startup failure: the canary did not reach the CRB path, it proves nothing"
                echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: without CTRL_START the CRB runs no command"; rm -f "$log"
            fi
            return
        fi
        # QEMU's CRB says IBM (0x1014) in INTF_ID; the device id is not pinned.
        grep -aqE '\[TPM\] TPM 2\.0 vendor 0x1014 device 0x[0-9a-f]{4} rev [0-9]+ via acpi TPM2, CRB$' "$log" \
            || why="no TPM 2.0 line from the CRB (vendor 0x1014)"
        [ -z "$why" ] && ! grep -aqE '\[TPM\] PCR banks:.* sha256' "$log" && why="no sha256 PCR bank listed"
        [ -z "$why" ] && ! grep -aqE '\[TPM\] PCR[0-9]+ <- kernel [0-9a-f]{64}' "$log" && why="the kernel image was not extended"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: TPM over CRB (q35 tpm-crb)" x86_tpm_crb_row "x86_64: TPM over CRB (q35 tpm-crb)" PASS
    par "x86_64: TPM over CRB canary (no START)" x86_tpm_crb_row "x86_64: TPM over CRB canary (no START)" FAIL
    # The TSC watchdog (Kconfig X86_TSC_WATCHDOG, crates/core/arch-x86_64/src/
    # timer.rs `watch`, kernel/src/entry/x86_64/ext/tsc_watchdog.rs) on QEMU q35,
    # the machine with an HPET to watch the TSC against (microvm has none, so
    # its rows never start the task). QEMU's TSC is not invariant, so the
    # kernel is the PCI one with X86_TSC_CLOCK_ALWAYS: the TSC is the clock and
    # the watchdog checks it every X86_TSC_WATCHDOG_MS. Its bound is 2%
    # (X86_TSC_WATCHDOG_PPM=20000): QEMU's 20 ms boot calibration is already
    # 1000-1800 ppm off unloaded, more under the gate's load. The plain boot
    # runs 20 s, about 40 checks, and must not demote the TSC; the canary boot
    # arms `canary=x86-tsc-skew` (the TSC made to run four times the bound
    # fast) on the same kernel, and the watchdog must demote it to the HPET,
    # whose clock must then run one more interval.
    x86_tsc_watchdog_row() { # x86_tsc_watchdog_row <label> <PASS|FAIL>
        local label="$1" expect="$2" why="" w
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}"
        local def="$CI_LOG_DIR/x86-${tag}.defconfig" append="" stop='KERNEL PANIC|TSC demoted' secs=20
        rm -f "$kimg" "$kimg.features"
        { cat config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config; echo 'CONFIG_X86_TSC_CLOCK_ALWAYS=y'; echo 'CONFIG_X86_TSC_WATCHDOG_PPM=20000'; } >"$def"
        make x86_64 X86_64_DEFCONFIG="$def" X86_64_KCONFIG="$AZOS_OUT/build/x86_64-tscwd-${tag}.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-tscwd" X86_64_IMG="$kimg" >/dev/null 2>&1 \
            && builtin printf '\n' >"$kimg.features" \
            || { bad; echo "      make x86_64 (robot-sbc-x86_64-dev+qemu+linux+pci.config + X86_TSC_CLOCK_ALWAYS) did not build"; return; }
        if [ "$expect" = FAIL ]; then
            append="canary=x86-tsc-skew" stop='KERNEL PANIC|clock runs: '
            secs=60
        fi
        par_ready
        X86_MACHINE=q35 x86_qemu "$kimg" "$log" "$secs" "$stop" -smp 2 ${append:+-append "$append"} \
            || { rm -f "$kimg" "$kimg.features"; return; }
        rm -f "$kimg" "$kimg.features"
        for w in '[TIMER] watchdog: TSC against the HPET every' '[SCHED] Starting scheduler on boot CPU'; do
            grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
        done
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        if [ -z "$why" ] && [ "$expect" = FAIL ]; then
            if ! grep -aqE '\[TIMER\] TSC demoted: it ran \+[0-9]+ ppm from the HPET \(bound [0-9]+ ppm\); the clock is the HPET from now on' "$log"; then
                why="the skewed TSC was not demoted: the watchdog does not discriminate"
            elif ! grep -aqE '\[TIMER\] the HPET clock runs: [1-9][0-9]* ms over one [0-9]+ ms interval' "$log"; then
                why="the HPET clock did not run an interval after the demotion"
            fi
        elif [ -z "$why" ]; then
            grep -aqF 'TSC demoted' "$log" && why="an agreeing TSC was demoted: $(grep -aF 'TSC demoted' "$log" | sed -n 1p)"
        fi
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: TSC watchdog keeps the TSC (q35)" x86_tsc_watchdog_row "x86_64: TSC watchdog keeps the TSC (q35)" PASS
    par "x86_64: TSC watchdog demotes a skewed TSC (q35)" x86_tsc_watchdog_row "x86_64: TSC watchdog demotes a skewed TSC (q35)" FAIL
    # The Intel I225/I226 driver (Kconfig DRV_IGC, crates/drivers/net/src/igc.rs, built
    # into qemu-x86_64-pci.config) on QEMU's `-device igb`: an 82576, the same advanced
    # descriptors, bound to the same driver by its id (hwbus.ids) but with the 82576's
    # interrupt registers (0xc0, not the I225's 0x1500) and PHY address (igc.rs `family`).
    # The controller is reset, its PHY's auto-negotiation restarted, it reads its station
    # address, starts both rings and reports the link up; microvm routes the MSI
    # (`mode=irq`), and a host datagram through a UDP hostfwd must then reach the ring and
    # raise an RX MSI whose cause the driver reads (net-poll's `RX MSI woke this task` or
    # `RX MSI taken but no ISR wake dispatched`: whether the wake found net-poll asleep is
    # the scheduler's business, not the NIC's). Interrupt registers at the wrong offsets
    # leave the mask clear and the cause unread, and neither line comes. Canary: the same
    # kernel with QEMU's
    # `-device e1000e` (an 82574L, the e1000e driver's id): igc must not bind it, and the
    # e1000e driver must (so the NIC was present and the PCI stage ran).
    x86_igc_row() { # x86_igc_row <label> <QEMU NIC device> <PASS|FAIL>
        local label="$1" nic="$2" expect="$3" why="" w port=47125 stop='\[NET\] (igc|e1000e): MAC|KERNEL PANIC' fwd=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" dimg="$CI_LOG_DIR/disk-x86-${tag}.img"
        if [ "$expect" = PASS ]; then
            if lsof -iUDP:"$port" >/dev/null 2>&1; then
                bad; echo "      host UDP port $port is in use; row not run"; return
            fi
            stop='NET-POLL\] RX MSI (woke|taken)|KERNEL PANIC|\[X86-TRAP\]'
            fwd=",hostfwd=udp:127.0.0.1:${port}-:7777"
        fi
        rm -f "$kimg" "$kimg.features"
        make x86_64 X86_64_DEFCONFIG=config/defconfigs/robot-sbc-x86_64-dev+qemu+linux+pci.config \
            X86_64_KCONFIG="$AZOS_OUT/build/x86_64-igc-${tag}.config" \
            X86_64_TARGET_DIR="$AZOS_OUT/target/x86_64-igc-${tag}" X86_64_IMG="$kimg" >/dev/null 2>&1 \
            && builtin printf '\n' >"$kimg.features" \
            || { bad; echo "      make x86_64 (qemu-x86_64-pci.config) did not build"; return; }
        fresh_disk $AZOS_OUT/build/disk-x86_64.img && cp $AZOS_OUT/build/disk-x86_64.img "$dimg" \
            || { bad; echo "      $AZOS_OUT/build/disk-x86_64.img did not build"; return; }
        par_ready
        local poke=""
        if [ "$expect" = PASS ]; then
            # Once net-poll runs, three datagrams to the guest's port 7777. A log
            # kept by a failed run would say so at once: it goes first. The sender
            # waits up to 120 s, x86_qemu's 90 s plus a wait for a QEMU slot.
            rm -f "$log"
            ( i=0; while [ "$i" -lt 240 ]; do
                  grep -aqF 'NET-POLL] Phase U1' "$log" 2>/dev/null && break
                  i=$((i + 1)); sleep 0.5
              done
              sleep 3
              for n in 1 2 3; do printf 'igc-%s' "$n" | nc -u -w1 127.0.0.1 "$port" 2>/dev/null; done ) &
            poke=$!
        fi
        X86_MACHINE=microvm,pcie=on x86_qemu "$kimg" "$log" 90 "$stop" -smp 1 \
            -drive "file=$dimg,if=none,format=raw,id=pcinvme0" -device nvme,serial=deadbeef,drive=pcinvme0 \
            -netdev "user,id=igcn0$fwd" -device "$nic,netdev=igcn0" \
            || { [ -n "$poke" ] && { kill "$poke" 2>/dev/null; wait "$poke" 2>/dev/null; }; rm -f "$kimg" "$kimg.features" "$dimg"; return; }
        [ -n "$poke" ] && { kill "$poke" 2>/dev/null; wait "$poke" 2>/dev/null; }
        rm -f "$kimg" "$kimg.features" "$dimg"
        grep -aqF '[PCI] host bridge: ECAM' "$log" || why="no PCI host bridge line: the PCI code did not run"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then
                bad; echo "      $why: the canary proves nothing"; echo "      log kept: $log"
            elif ! grep -aqF '[NET] e1000e: MAC' "$log"; then
                bad; echo "      the e1000e driver did not bind its own NIC: the canary proves nothing"; echo "      log kept: $log"
            elif grep -aqE '\[NET\] igc ' "$log"; then
                bad; echo "      the igc driver bound a NIC that is not an igb: the row does not discriminate"; echo "      log kept: $log"
            else
                ok; echo "      canary failed as it must: igc left the e1000e NIC to the e1000e driver"; rm -f "$log"
            fi
            return
        fi
        if [ -z "$why" ]; then
            for w in ' 8086:10c9 ' '[NET] igc ' ' mode=irq ' ' model=Igb ' '[NET] igc link up ' '[NET] igc: MAC 52:54:00:12:34:56'; do
                grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
            done
        fi
        [ -z "$why" ] && ! grep -aqE '\[NET-POLL\] RX MSI (woke this task|taken but no ISR wake dispatched): rx [0-9]+ -> [0-9]+' "$log" \
            && why="no RX MSI from the datagrams: the receive cause was not read"
        [ -z "$why" ] && grep -aqE '\[NET\] igc .* not used' "$log" && why="$(grep -aE '\[NET\] igc .* not used' "$log" | sed -n 1p)"
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]|FAILED' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then
            ok; echo "      $(grep -aE '\[NET\] igc .*mode=' "$log" | sed -n 1p)"
            echo "      $(grep -aE '\[NET-POLL\] RX MSI' "$log" | sed -n 1p)"; rm -f "$log"; return
        fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: igc binds QEMU igb" x86_igc_row "x86_64: igc binds QEMU igb" igb PASS
    par "x86_64: igc leaves e1000e canary" x86_igc_row "x86_64: igc leaves e1000e canary" e1000e FAIL
    # The x86 PC on QEMU q35, under OVMF and Limine (Kconfig X86_BOOT_LIMINE,
    # `make run-x86-pc`), once per CPU model: the speculation mitigations
    # (Kconfig X86_MIT_*, crates/core/arch-x86_64/src/mitigations.rs) are chosen
    # by probe, so the path each model takes is the assertion. The `[MITIGATE]`
    # lines name the identity the probe read (the model's family and model
    # from CPUID.1) and the verdicts; <want> lines must be in the log and
    # <deny> lines must not (the other path: a model that takes retpoline
    # must not print eibrs, and the reverse, so a probe that always answered
    # one way fails a row). The models are pinned to `-v1`, the original
    # definition QEMU keeps stable across versions, with the capability bits
    # a model gained later named by hand (`+spec-ctrl,+arch-capabilities` and
    # the ARCH_CAPABILITIES bits `+rdcl-no,+ibrs-all,...`): which bits a
    # model has is QEMU's, not this tree's, and the expectations below were
    # written from the architecture and QEMU's model tables, not from a boot
    # (first boot: check each against its log). Image: the same
    # `make x86_64-limine` kernel for every model, booted from a per-row ESP.
    # SKIPPED, not failed, without Limine or the UEFI firmware (Limine is the
    # gitlink third_party/limine, `tools/third_party_fetch.sh limine`, or
    # LIMINE_DIR; `make x86-pc-prereq` says what is missing).
    x86_pc_row() { # x86_pc_row <label> <qemu -cpu> <want, |-separated fixed strings> <deny, |-separated or "">
        local label="$1" cpu="$2" want="$3" deny="$4" why="" w i=0
        printf "  %-26s" "${label}..."
        if ! make -s x86-pc-prereq >/dev/null 2>&1; then
            SKIP=$((SKIP + 1)); echo "skipped (no Limine or OVMF: tools/third_party_fetch.sh limine, see make x86-pc-prereq)"; return
        fi
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86pc-${tag}.log" esp="$CI_LOG_DIR/x86pc-${tag}-esp" vars="$CI_LOG_DIR/x86pc-${tag}-vars.fd"
        make x86-pc-esp X86_PC_ESP="$esp" X86_PC_VARS="$vars" >/dev/null 2>&1 \
            || { bad; echo "      make x86-pc-esp (x86_64-limine) did not build"; return; }
        local args; args="$(make -s x86-pc-qemu-args QEMU_X86_64_CPU="$cpu" X86_PC_ESP="$esp" X86_PC_VARS="$vars")" \
            || { bad; echo "      make x86-pc-qemu-args failed"; return; }
        par_ready
        while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
        : >"$log"
        # shellcheck disable=SC2086
        qemu-system-x86_64 $args </dev/null >"$log" 2>&1 &
        local pid=$!
        # The banner line the decision ends with, or the end of the road.
        while [ "$i" -lt 480 ] && kill -0 "$pid" 2>/dev/null; do
            tr -d '\r' <"$log" | grep -aqE '\[MITIGATE\] indirect branches:|KERNEL PANIC|\[LIMINE\] refusing|REFUSED' && break
            i=$((i + 1)); sleep 0.5
        done
        if kill -0 "$pid" 2>/dev/null; then kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; fi
        wait "$pid" 2>/dev/null
        tr -d '\r' <"$log" >"$log.t" && mv "$log.t" "$log"
        rm -rf "$esp" "$vars"
        grep -aqF '[LIMINE] image linked at' "$log" || why="Limine never started the kernel (no [LIMINE] image line)"
        if [ -z "$why" ]; then
            local IFS='|'
            for w in $want; do
                grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
            done
            if [ -z "$why" ] && [ -n "$deny" ]; then
                for w in $deny; do
                    grep -aqF -- "$w" "$log" && { why="took the wrong path: $w"; break; }
                done
            fi
            unset IFS
        fi
        [ -z "$why" ] && grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log" \
            && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    # Intel without eIBRS: the retpoline (the thunk keeps its assembled body);
    # no IA32_ARCH_CAPABILITIES, so Meltdown is not ruled out.
    X86_PC_RETPOLINE="spectre_v2=retpoline|meltdown=vulnerable"
    X86_PC_NOT_EIBRS="spectre_v2=eibrs|spectre_v2=autoibrs"
    par "x86_pc: Nehalem" x86_pc_row "x86_pc: Nehalem" Nehalem-v1 \
        "[MITIGATE] cpu Intel family 6 model 0x1a stepping|$X86_PC_RETPOLINE" "$X86_PC_NOT_EIBRS"
    par "x86_pc: Haswell" x86_pc_row "x86_pc: Haswell" Haswell-v1 \
        "[MITIGATE] cpu Intel family 6 model 0x3c stepping|$X86_PC_RETPOLINE" "$X86_PC_NOT_EIBRS"
    par "x86_pc: Skylake-Client" x86_pc_row "x86_pc: Skylake-Client" Skylake-Client-v1 \
        "[MITIGATE] cpu Intel family 6 model 0x5e stepping|$X86_PC_RETPOLINE|retbleed=vulnerable" "$X86_PC_NOT_EIBRS"
    # Intel with eIBRS: IA32_SPEC_CTRL.IBRS, the thunk patched to a plain jmp,
    # RDCL_NO makes Meltdown not-affected. Ice Lake's -v1 predates
    # ARCH_CAPABILITIES in QEMU, so its bits are named.
    par "x86_pc: Icelake-Server" x86_pc_row "x86_pc: Icelake-Server" \
        "Icelake-Server-v1,+spec-ctrl,+arch-capabilities,+rdcl-no,+ibrs-all,+mds-no,+taa-no" \
        "[MITIGATE] cpu Intel family 6 model 0x86 stepping|spectre_v2=eibrs|meltdown=not-affected" "spectre_v2=retpoline"
    par "x86_pc: SapphireRapids" x86_pc_row "x86_pc: SapphireRapids" SapphireRapids-v1 \
        "[MITIGATE] cpu Intel family 6 model 0x8f stepping|spectre_v2=eibrs|meltdown=not-affected" "spectre_v2=retpoline"
    # AMD: Zen 2 has no AutoIBRS (retpoline) and Zenbleed's DE_CFG bit; Zen 3
    # is not Retbleed- or Zenbleed-affected; Zen 4 has AutoIBRS.
    par "x86_pc: EPYC-Rome" x86_pc_row "x86_pc: EPYC-Rome" EPYC-Rome-v1 \
        "[MITIGATE] cpu AMD family 23 model 0x31 stepping|spectre_v2=retpoline|meltdown=not-affected|zenbleed=de-cfg" "$X86_PC_NOT_EIBRS"
    par "x86_pc: EPYC-Milan" x86_pc_row "x86_pc: EPYC-Milan" EPYC-Milan-v1 \
        "[MITIGATE] cpu AMD family 25 model 0x1 stepping|spectre_v2=retpoline|zenbleed=not-affected|retbleed=not-affected" "$X86_PC_NOT_EIBRS"
    par "x86_pc: EPYC-Genoa" x86_pc_row "x86_pc: EPYC-Genoa" EPYC-Genoa-v1 \
        "[MITIGATE] cpu AMD family 25 model 0x11 stepping|spectre_v2=autoibrs|retbleed=not-affected" "spectre_v2=retpoline|spectre_v2=eibrs"
    # Network boot, nothing on a disk (tools/netboot/row.sh, Documentation/
    # building.md "Network boot"): the firmware fetches AzOS over the network and
    # the console is judged. x86_64 on q35 + OVMF: UEFI PXE (TFTP) and UEFI HTTP
    # Boot (a host HTTP server on a port of the row's own), both reaching
    # Limine, which verifies the kernel by BLAKE2B; riscv64 on virt + OpenSBI +
    # U-Boot: `dhcp` + `tftpboot` of a signed FIT image that `bootm` verifies
    # (sha256 + rsa2048). Each case has a canary that sabotages the fetch (a
    # missing file, one changed kernel byte, a foreign key, a changed
    # configuration) and passes only on the loader's named refusal with the
    # banner absent. aarch64 has none: its tree has no EFI entry (see the
    # document). The kernel of each ISA is built once, here, outside the rows
    # (tools/netboot/kernel_image.sh); a row SKIPS when the firmware, Limine or
    # the U-Boot tools are not on this host (row.sh exits 2).
    NETBOOT_IMG_X86_64=""; NETBOOT_IMG_RISCV64=""
    netboot_build() { # netboot_build <isa> <image variable>: build the ISA's image once, or say so in a row
        local isa="$1" var="$2" img
        if img="$(cd "$REPO_ROOT" && bash tools/netboot/kernel_image.sh "$isa" 2>/dev/null)" && [ -f "$img" ]; then
            printf -v "$var" '%s' "$img"
        else
            printf "  %-26s" "netboot: $isa image..."
            bad; echo "      bash tools/netboot/kernel_image.sh $isa did not build"
        fi
    }
    netboot_row() { # netboot_row <label> <case> <image>
        local label="$1" case_="$2" img="$3" out rc
        printf "  %-26s" "${label}..."
        [ -n "$img" ] && [ -f "$img" ] || { bad; echo "      no image to boot (the build row above says why)"; return; }
        mkdir -p "$CI_LOG_DIR"
        par_ready
        out="$(cd "$REPO_ROOT" && bash tools/netboot/row.sh "$case_" "$img" "$CI_LOG_DIR" 2>&1)"; rc=$?
        case "$rc" in
            0) ok ;;
            2) SKIP=$((SKIP + 1)); echo "skipped ($out)" ;;
            *) bad; printf '%s\n' "$out" | sed 's/^/      /' ;;
        esac
    }
    if ci_wants "netboot x86_64: UEFI PXE" "netboot x86_64: PXE missing file canary" "netboot x86_64: PXE kernel hash canary" \
            "netboot x86_64: PXE config hash canary" "netboot x86_64: UEFI HTTP Boot" \
            "netboot x86_64: HTTP missing file canary" "netboot x86_64: HTTP kernel hash canary"; then
        netboot_build x86_64 NETBOOT_IMG_X86_64
    fi
    par -h "netboot x86_64: UEFI PXE"                netboot_row "netboot x86_64: UEFI PXE"                x86-pxe             "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: PXE missing file canary" netboot_row "netboot x86_64: PXE missing file canary" x86-pxe-nofile     "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: PXE kernel hash canary"  netboot_row "netboot x86_64: PXE kernel hash canary"  x86-pxe-badkernel   "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: PXE config hash canary"  netboot_row "netboot x86_64: PXE config hash canary"  x86-pxe-badconfig   "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: UEFI HTTP Boot"          netboot_row "netboot x86_64: UEFI HTTP Boot"          x86-http            "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: HTTP missing file canary" netboot_row "netboot x86_64: HTTP missing file canary" x86-http-nofile   "$NETBOOT_IMG_X86_64"
    par -h "netboot x86_64: HTTP kernel hash canary" netboot_row "netboot x86_64: HTTP kernel hash canary" x86-http-badkernel  "$NETBOOT_IMG_X86_64"
    if ci_wants "netboot riscv64: U-Boot tftpboot" "netboot riscv64: missing file canary" \
            "netboot riscv64: kernel hash canary" "netboot riscv64: foreign key canary"; then
        netboot_build riscv64 NETBOOT_IMG_RISCV64
        # U-Boot is built here, once, not by the first row to need it (minutes of
        # compiling inside the parallel phase). Without its toolchain the rows
        # skip: they are told a path that does not exist.
        U_BOOT_BIN="$(cd "$REPO_ROOT" && bash tools/netboot/uboot_build.sh 2>/dev/null)" || U_BOOT_BIN="/nonexistent/u-boot-qemu-riscv64.bin"
        export U_BOOT_BIN
    fi
    par -h "netboot riscv64: U-Boot tftpboot"        netboot_row "netboot riscv64: U-Boot tftpboot"        riscv64-tftp          "$NETBOOT_IMG_RISCV64"
    par -h "netboot riscv64: missing file canary"    netboot_row "netboot riscv64: missing file canary"    riscv64-tftp-nofile   "$NETBOOT_IMG_RISCV64"
    par -h "netboot riscv64: kernel hash canary"     netboot_row "netboot riscv64: kernel hash canary"     riscv64-tftp-badkernel "$NETBOOT_IMG_RISCV64"
    par -h "netboot riscv64: foreign key canary"     netboot_row "netboot riscv64: foreign key canary"     riscv64-tftp-badkey   "$NETBOOT_IMG_RISCV64"
    x86_ktest_row() { # x86_ktest_row <label> <extra features or ""> <expected not-ok names> [kernel command line] [disk image target]
        local label="$1" extra="$2" want="$3" why="" k plan got name
        local -a app=(); [ -n "${4:-}" ] && app=(-append "$4")
        local -a drv=(); local dimg=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/ktest-${tag}.log" kimg="$CI_LOG_DIR/kernel-ktest-${tag}"
        x86_kbuild "use-robot,ktest,chaos,decisions$extra" "$kimg" || { bad; echo "      make x86_64 X86_64_FEATURES=use-robot,ktest,chaos,decisions$extra did not build"; return; }
        if [ -n "${5:-}" ]; then
            dimg="$CI_LOG_DIR/disk-ktest-${tag}.img"
            fresh_disk "$5" && cp "$5" "$dimg" || { bad; echo "      disk image $5 did not build"; return; }
            drv=(-drive "file=$dimg,if=none,format=raw,id=d0" -device virtio-blk-device,drive=d0)
        fi
        par_ready
        x86_qemu "$kimg" "$log" 300 "" -smp 4 ${app[@]+"${app[@]}"} ${drv[@]+"${drv[@]}"} || { rm -f "$kimg" "$kimg.features" ${dimg:+"$dimg"}; return; }
        rm -f "$kimg" "$kimg.features" ${dimg:+"$dimg"}
        plan="$(sed -n 's/^1\.\.\([0-9][0-9]*\)$/\1/p' "$log" | sed -n '1p')"
        got="$(sed -n 's/^not ok [0-9][0-9]* - \([A-Za-z0-9_]*\)\( #.*\)\{0,1\}$/\1/p' "$log" | grep . | sort | tr '\n' ' ')"
        want="$(printf '%s\n' $want | grep . | sort | tr '\n' ' ')"
        if [ -z "$plan" ]; then why="no TAP plan line (1..N)"
        elif [ "$plan" != "$KTEST_N_X86" ]; then why="plan 1..$plan, the gate expects $KTEST_N_X86 tests (KTEST_N_X86)"
        elif [ "$got" != "$want" ]; then why="not ok: [${got% }], expected [${want% }]"
        elif grep -aq '^Bail out!' "$log"; then
            # Only a canary that panics may stop the run, and only in its test
            # (the rule `ktest_row` applies; K1's `ioring-rt-inline`).
            for name in $want; do grep -aq "^Bail out! ktest: $name panicked" "$log" && why=bail; done
            [ "$why" = bail ] && why="" || why="the run bailed out: $(grep -a '^Bail out!' "$log")"
        else
            k=1
            while [ "$k" -le "$plan" ]; do
                [ "$(grep -acE "^(not )?ok $k - " "$log")" = 1 ] || { why="test $k reported $(grep -acE "^(not )?ok $k - " "$log") times"; break; }
                k=$((k + 1))
            done
            [ -z "$why" ] && ! grep -aqE "^# ktest: $plan tests, $((plan - $(printf '%s\n' $want | grep -c .))) passed" "$log" \
                && why="no matching summary line"
        fi
        # The verdict also rides on QEMU's exit status (isa-debug-exit, see
        # kernel/src/ktest.rs power_off): 1 after a clean run, 3 after a failed one.
        local qwhy=""
        if [ "$X86_QRC" = stopped ]; then qwhy="QEMU did not power off"
        elif [ -z "$want" ] && [ "$X86_QRC" != 1 ]; then qwhy="QEMU exit status $X86_QRC after a clean run, not 1"
        elif [ -n "$want" ] && [ "$X86_QRC" != 3 ]; then qwhy="QEMU exit status $X86_QRC after a failed run, not 3"
        fi
        # KTEST_STATUS_CANARY=1: see `ktest_row`.
        if [ -z "$why" ] && [ "${KTEST_STATUS_CANARY:-0}" = 1 ]; then
            case "$qwhy" in
            *"after a failed run"*) ok; echo "      the status check fired: $qwhy"; rm -f "$log"; return ;;
            *) why="the status check did not fire on a failed run (QEMU status $X86_QRC)" ;;
            esac
        fi
        [ -z "$why" ] && why="$qwhy"
        if [ -z "$why" ]; then
            ok; grep -aE '^# (ktest|spin_lock_fifo_bounded):' "$log" | sed 's/^/      /'; rm -f "$log"; return
        fi
        bad; echo "      $why"
        grep -aE '^(not ok|Bail out!|# ktest:)|KERNEL PANIC' "$log" | sed -n '1,8p' | sed 's/^/      /'
        echo "      log kept: $log"
    }
    par "ktest (x86)" x86_ktest_row "ktest (x86)" "" ""
    # S6: the same ktests on an AMD model with SVM on (TCG runs VMRUN). Under `-cpu max`
    # the two hv ktests (`hv_svm_guest_exits`, `hv_enter_guest`) pass without running a
    # guest; here they run one: the first the VMCB and the exits one VMRUN at a time,
    # the second the entry `Hypervisor::enter` is (CPUID, an empty port, two device
    # stores, HLT; the faulting instruction read through the nested tables).
    x86_ktest_row_svm() {
        local X86_CPU="EPYC-Rome,svm=on"
        x86_ktest_row "$@"
    }
    par "ktest hv enter (x86 svm)" x86_ktest_row_svm "ktest hv enter (x86 svm)" "" ""
    # K1: with a disk, and the RT-inline canary (see `ktest disk (rv)`).
    par "ktest disk (x86)" x86_ktest_row "ktest disk (x86)" "" "" "" $AZOS_OUT/build/disk-x86_64.img
    par "ktest disk RT-inline canary (x86)" x86_ktest_row "ktest disk RT-inline canary (x86)" "" \
        "ioring_fsync_completes_after_flush" "canary=ioring-rt-inline" $AZOS_OUT/build/disk-x86_64.img
    # See the riscv64 and aarch64 `ktest why durable-off canary` rows. On
    # x86_64 the cargo features come from the Kconfig expansion
    # (`decisions-durable` is a `base` feature, on while
    # DECISION_REFUSALS_DURABLE=y), so the canary kernel is built from a
    # configuration with the symbol off, into an image and target dir of its own.
    x86_ktest_row_nodur() {
        local def="$CI_LOG_DIR/x86-why-nodur.defconfig" X86_KBUILD_OUT=$AZOS_OUT/build/kernel-x86_64-why-nodur.elf X86_KBUILD_ARGS
        mkdir -p "$CI_LOG_DIR"
        { cat config/defconfigs/${GATE_ROBOT_DEFC_X86}.config; echo "CONFIG_DECISION_REFUSALS_DURABLE=n"; } >"$def"
        X86_KBUILD_ARGS="X86_64_DEFCONFIG=$def X86_64_KCONFIG=$AZOS_OUT/build/x86_64-why-nodur.config X86_64_TARGET_DIR=$AZOS_OUT/target/x86_64-why-nodur X86_64_IMG=$X86_KBUILD_OUT"
        x86_ktest_row "$@"
    }
    par "ktest why durable-off canary (x86)" x86_ktest_row_nodur "ktest why durable-off canary (x86)" "" "why_resolves_a_refused_reservation"
    par "ktest tlb local-only canary (x86)" x86_ktest_row "ktest tlb local-only canary (x86)" ",tlb-local-only" "tlb_shootdown_cross_cpu"
    # An AP that publishes no CR3 when it comes online (the old step): a CPU
    # that has only run kernel tasks is no target of a kernel-wide shootdown.
    par "ktest tlb join canary (x86)" x86_ktest_row "ktest tlb join canary (x86)" "" \
        "tlb_kernel_shootdown_names_every_online_cpu" "canary=x86-tlb-join-skip"
    par "ktest percpu accessor canary (x86)" x86_ktest_row "ktest percpu accessor canary (x86)" ",percpu-accessor-race-canary" "percpu_accessors_read_masked"
    # tls-hygiene: the old FS-base rule (an equal base is not rewritten, the
    # FS/GS selectors ring 3 loaded stay).
    par "ktest sched tls canary (x86)" x86_ktest_row "ktest sched tls canary (x86)" ",fs-base-cache-canary" "fs_selector_load_keeps_the_next_task_s_fs_base fs_gs_selectors_do_not_follow_a_task"
    par "ktest el0 state canary (x86)" x86_ktest_row "ktest el0 state canary (x86)" ",el0-state-canary" "user_visible_state_is_set_on_every_cpu"
    # The same boot carries K1's `ioring-fsync-inline` (an io_ring OP_FSYNC
    # completes in the submit): `ioring_fsync_completes_after_flush`.
    par "ktest fork FP runtime canary (x86)" x86_ktest_row "ktest fork FP runtime canary (x86)" "" \
        "x86_ring3_syscall_fork_fp ioring_fsync_completes_after_flush" "canary=x86-fork-fp-skip,ioring-fsync-inline"
    par "ktest chaos-inert canary (x86)" x86_ktest_row "ktest chaos-inert canary (x86)" "" \
        "$KTEST_CHAOS_INERT" "canary=chaos-inert"
    par "ktest low-half alias runtime canary (x86)" x86_ktest_row "ktest low-half alias runtime canary (x86)" "" \
        "x86_low_half_maps_no_ram" "canary=x86-low-alias"
    par "ktest camera encode canary (x86)" x86_ktest_row "ktest camera encode canary (x86)" "" \
        "camera_one_encode_per_frame" "canary=camera-encode-per-consumer"
    par "ktest percpu hazard canary (x86)" x86_ktest_row "ktest percpu hazard canary (x86)" ",percpu-hazard-canary" "percpu_hazard_reads_are_masked"
    # L5: the interrupt-line budget rule is off (see the RT runtime canaries,
    # rv/arm); a storm delivers to a throttled handler.
    par "ktest irq-storm canary (x86)" x86_ktest_row "ktest irq-storm canary (x86)" "" \
        "irq_storm_is_contained" "canary=irq-storm"
    # N1 (lockdep-lite): see `ktest lockdep canaries (rv)`.
    par "ktest lockdep canaries (x86)" x86_ktest_row "ktest lockdep canaries (x86)" "" \
        "$KTEST_LOCKDEP_CANARIED" "$KTEST_LOCKDEP_CANARIES"
    # GR3: see `ktest exit status canary (rv)`; x86_64's clean status is 1.
    # KTEST_STATUS_CANARIED already names `irq_storm_is_contained` (every ISA
    # reads the irq-budget record since wave 15 L5).
    par "ktest exit status canary (x86)" ktest_status_canary_row x86_ktest_row "ktest exit status canary (x86)" "" \
        "$KTEST_STATUS_CANARIED" "$KTEST_STATUS_CANARIES"
    # N4: see `ktest rcu canaries (rv)`.
    par "ktest rcu canaries (x86)" x86_ktest_row "ktest rcu canaries (x86)" "" \
        "$KTEST_RCU_CANARIED" "$KTEST_RCU_CANARIES"
    # N5: see `ktest ipc canary (rv)`.
    par "ktest ipc canary (x86)" x86_ktest_row "ktest ipc canary (x86)" "" \
        "$KTEST_IPC_CANARIED" "$KTEST_IPC_CANARIES"
    # N9: see `ktest futex canary (rv)`.
    par "ktest futex canary (x86)" x86_ktest_row "ktest futex canary (x86)" "" \
        "$KTEST_FUTEX_CANARIED" "$KTEST_FUTEX_CANARIES"
    # N8: see `ktest kmutex canary (rv)`.
    par "ktest kmutex canary (x86)" x86_ktest_row "ktest kmutex canary (x86)" "" \
        "$KTEST_KMUTEX_CANARIED" "$KTEST_KMUTEX_CANARIES"
    # N6a + N7: see `ktest sched canary (rv)`.
    par "ktest sched canary (x86)" x86_ktest_row "ktest sched canary (x86)" "" \
        "$KTEST_SCHED_CANARIED" "$KTEST_SCHED_CANARIES"

    # ── Wave 15 (XU): x86_64 userspace (ring 3 from a FAT volume) ───────────
    #
    # The x86_64 images (`make userspace-x86_64`, bound by
    # build/image_hashes_x86_64.rs) on a virtio-blk-device in microvm's
    # virtio-mmio window, the same kernel `make x86_64` builds.
    #   x86_64: first user task     build/disk-x86_64.img: the console program
    #                               (SH.ELF, Kconfig CONSOLE_PROGRAM) starts
    #                               from the volume, takes the console, and
    #                               answers a typed `echo` with a line of its
    #                               own (ring-3 read and write of the console);
    #                               no panic, no x86 trap report
    #   x86_64 abitest              ABITEST.ELF autorun, -smp 2: every check,
    #                               read back, none may fail (the vDSO's TSC
    #                               scale makes `rdtsc` native: aarch64's one
    #                               known gap is not x86_64's); the `sse:`
    #                               checks hold XMM0-XMM15/MXCSR across 300
    #                               yields in four tasks
    #                               and the vDSO hwcap word: the kernel's
    #                               `[VDSO] hwcap=` names AVX2, AES, SHA-NI,
    #                               RDRAND, RDSEED (not FSGSBASE/PKU: CR4
    #                               does not enable them) and abitest's word
    #                               read in ring 3 is the same
    #   x86_64 abitest hwcap canary, -sha-ni  `-cpu max,-sha-ni`: the SHA-NI
    #                               bit clears, the others stay, abitest passes
    #   x86_64 abitest sysabi canary  `syscall-abi-canary`: the native
    #                               syscall exit flips a bit of rbx for
    #                               abitest's probes, whose `survive` checks
    #                               alone fail (sysabi_canary_judge)
    #   x86_64 ipctest              IPCTEST.ELF autorun, -smp 2: phase A's
    #                               1600 calls and every check
    #   x86_64 image digest canary  the abitest volume with one byte appended
    #                               to ABITEST.ELF: the x86_64 table binds no
    #                               such bytes, autorun refuses it, abitest
    #                               never runs (the same image bytes pass the
    #                               row above, so the table is what decides)
    x86_disk_prep() { # x86_disk_prep <disk target> <kernel copy> <disk copy> [kernel features]
        x86_kbuild "${4:-}" "$2" || { bad; echo "      make x86_64 did not build"; return 1; }
        make "$1" >/dev/null 2>&1 || { bad; echo "      make $1 did not build"; return 1; }
        cp "$1" "$3"
    }
    x86_user_shell_row() {
        local label="x86_64: first user task" why="" w
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/x86-first-user-task.log" kimg="$CI_LOG_DIR/kernel-x86-first-user-task"
        local disk="$CI_LOG_DIR/disk-x86-first-user-task.img"
        x86_disk_prep $AZOS_OUT/build/disk-x86_64.img "$kimg" "$disk" || return
        x86_kernel_check "$kimg" || { rm -f "$kimg" "$kimg.features" "$disk"; return; }
        par_ready
        while [ "$(par_qemu_count)" -ge 4 ]; do sleep 2; done
        : >"$log"; rm -f "$log.end"
        # The input waits for the shell to own the console (typed earlier it
        # would reach the kernel's console instead), and the feeder ends with
        # QEMU (`$log.end`), not on a timer of its own.
        ( i=0
          while [ "$i" -lt 120 ] && [ ! -e "$log.end" ] && ! grep -aqF 'has the console' "$log"; do sleep 0.5; i=$((i + 1)); done
          sleep 1; printf 'echo x86-ring3-echo\r'
          while [ "$i" -lt 160 ] && [ ! -e "$log.end" ]; do sleep 0.5; i=$((i + 1)); done ) |
        qemu-system-x86_64 -M microvm -cpu max -m 256M -nographic -no-reboot \
            -device isa-debug-exit,iobase=0xf4,iosize=0x04 \
            -drive "file=$disk,if=none,format=raw,id=d0" -device virtio-blk-device,drive=d0 \
            -kernel "$kimg" >"$log" 2>&1 &
        local pid=$! i=0
        while [ "$i" -lt 160 ] && kill -0 "$pid" 2>/dev/null; do
            tr -d '\r' <"$log" | grep -aqx 'x86-ring3-echo' && break
            i=$((i + 1)); sleep 0.5
        done
        sleep 1
        kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        : >"$log.end"; sleep 1; rm -f "$log.end"
        tr -d '\r' <"$log" >"$log.t" && mv "$log.t" "$log"
        rm -f "$kimg" "$kimg.features" "$disk"
        local IFS='|'
        # The prompt and the typed line are checked apart: kernel log lines
        # may land between the prompt and what the shell echoes back.
        for w in "[compmgr] start SH.ELF tid=" "[CONSOLE] user shell tid=" "azos\$ " "echo x86-ring3-echo"; do
            grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
        done
        unset IFS
        # The answer is a line of its own, not the typed command echoed back.
        [ -z "$why" ] && ! grep -aqx 'x86-ring3-echo' "$log" && why="the shell never printed its echo"
        if [ -z "$why" ] && grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log"; then
            why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        fi
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64: first user task" x86_user_shell_row
    # Wave 11 (DRVPLACE) on x86_64: the INA219 placement rows of riscv64
    # (`drivers: INA219 placed in kernel`, `... placement canary`, `... build
    # canary`) and aarch64. x86_64, like them, reads the QEMU simulation of
    # the INA219 (crates/drivers/bus/src/i2c.rs: no controller driver is
    # compiled for QEMU). `ring3-drv-smoke` boots build/disk-x86_64.img, which
    # carries INADRV.ELF and the component manager; the kinds and their
    # verdicts are `drvplace_row`'s:
    #   ina-kernel  `[DRV1] ina219 PASS 7400 mV 1500 mA .. (kernel tid=`: the
    #               kernel host answered, no ring-3 owner of the power monitor
    #   ina-canary  `ina219-placement-canary`: must fail on `placement is
    #               kernel but the topology declares` (the boot check)
    # The build bucket is `drvplace_build_canary_row ... x86`.
    x86_drvplace_row() { # x86_drvplace_row <label> <features> <ina-kernel|ina-canary>
        local label="$1" feats="$2" kind="$3" why=""
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" disk="$CI_LOG_DIR/disk-x86-${tag}.img"
        x86_disk_prep $AZOS_OUT/build/disk-x86_64.img "$kimg" "$disk" "$feats" || return
        par_ready
        x86_qemu "$kimg" "$log" 240 "DRV1\] ina219 (PASS|FAIL)|KERNEL PANIC|\[X86-TRAP\]" -smp 4 \
            -drive "file=$disk,if=none,format=raw,id=d0" -device virtio-blk-device,drive=d0 \
            || { rm -f "$kimg" "$kimg.features" "$disk"; return; }
        rm -f "$kimg" "$kimg.features" "$disk"
        case "$kind" in
            ina-kernel)
                grep -aqE "\[DRV1\] ina219 PASS 7400 mV 1500 mA [0-9]+% \(kernel tid=" "$log" \
                    || why="no '[DRV1] ina219 PASS 7400 mV 1500 mA .. (kernel tid=' line"
                grep -aqF "[DRV1] ina219 FAIL" "$log" && why="an ina219 FAIL line"
                ;;
            ina-canary)
                grep -aqF "[DRV1] ina219 FAIL: placement is kernel but the topology declares" "$log" \
                    || why="the canary did not fail on the placement check"
                ;;
        esac
        grep -aqE 'KERNEL PANIC|\[X86-TRAP\]' "$log" && why="$(grep -aE 'KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then
            ok
            grep -a "ina219 read path" "$log" | sed -n '1s|^|      |p'
            rm -f "$log"; return
        fi
        bad; echo "      $why"
        grep -aE "\[DRV1\] (ina219|buzzer)|\[INA219\]|\[SUP\]" "$log" | sed -n '1,12p' | sed 's|^|        |'
        echo "      log kept: $log"
    }
    par "x86_64 INA219 placed in kernel" x86_drvplace_row "x86_64 INA219 placed in kernel" "ring3-drv-smoke,ina219-kernel" ina-kernel
    par "x86_64 INA219 placement canary" x86_drvplace_row "x86_64 INA219 placement canary" "ring3-drv-smoke,ina219-placement-canary" ina-canary
    ci_row "x86_64 INA219 placement build canary" drvplace_build_canary_row "x86_64 INA219 placement build canary" x86
    # D6 on x86_64 (Kconfig LINUX_RUNTIME): the ring-3 runtime hosts a static
    # Linux x86-64 binary. `lxhello rt` (userspace/tests/lxhello/lxhello_x86_64.c)
    # issues the calls a static musl binary issues, in Linux's x86-64 numbers
    # and registers (`syscall`, `rdi rsi rdx r10 r8 r9`, the `open`, `stat`,
    # `pipe`, `dup2` and `fork` the asm-generic table dropped, the 144-byte
    # `struct stat`) and the runtime answers them through
    # `azos_linux_abi::x86_64`; `lxhello spawn` then reads the working
    # directory and the descriptors a spawn request hands over in `rsi`'s
    # startup block (a pipe, and a file in and out). The shell is fed a line at
    # a time, each after the previous job's last line (a typed line a Linux
    # job does not read would be lost). `[SPAWN] ... hosted by the ring-3
    # runtime` is printed only for a hosted child (`spawn-log`), so a kernel
    # that translated in-kernel (LINUX_RUNTIME off) cannot pass.
    # Canaries: the host tests of the x86-64 face (tests/host/linux-abi-tests,
    # linux-rt-tests: the argument registers, `struct stat`, `dup2` onto itself,
    # `sigaction`, `uname`); at boot, a runtime that read `rcx` for `r10` makes
    # `mmap` read its flags as 0 and fail `rt: mmap` and `rt: pipe`.
    x86_lxrt_row() {
        local label="x86_64 linux: hosted by the ring-3 runtime" why="" w
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/x86-lxrt.log" kimg="$CI_LOG_DIR/kernel-x86-lxrt" disk="$CI_LOG_DIR/disk-x86-lxrt.img"
        local def="$CI_LOG_DIR/x86-lxrt.defconfig" X86_KBUILD_OUT=$AZOS_OUT/build/kernel-x86_64-lxrt.elf X86_KBUILD_ARGS
        { cat config/defconfigs/${GATE_DEFC_X86}.config; echo "CONFIG_LINUX_RUNTIME=y"; } >"$def"
        X86_KBUILD_ARGS="X86_64_DEFCONFIG=$def X86_64_KCONFIG=$AZOS_OUT/build/x86_64-lxrt.config X86_64_TARGET_DIR=$AZOS_OUT/target/x86_64-lxrt X86_64_IMG=$X86_KBUILD_OUT"
        # The runtime is embedded in the kernel (`include_bytes!`): built first.
        make $X86_KBUILD_ARGS "$AZOS_OUT/build/x86_64/linux_rt.elf" >/dev/null 2>&1 \
            || { bad; echo "      make linux_rt.elf (x86_64) did not build"; return; }
        x86_disk_prep $AZOS_OUT/build/disk-x86_64.img "$kimg" "$disk" "linux-abi-test,spawn-log" || return
        x86_kernel_check "$kimg" || { rm -f "$kimg" "$kimg.features" "$disk"; return; }
        par_ready
        while [ "$(par_qemu_count)" -ge 4 ]; do sleep 2; done
        : >"$log"; rm -f "$log.end"
        ( i=0
          wf() { while [ "$i" -lt 300 ] && [ ! -e "$log.end" ] && ! grep -aqF -- "$1" "$log"; do sleep 0.5; i=$((i + 1)); done; }
          wf 'has the console'; sleep 1; printf 'lxhello rt\r'
          wf 'lx: rt done failures='; sleep 1; printf 'cd /fat\r'
          sleep 1; printf 'echo piped-ok | lxhello spawn\r'
          wf 'lx: spawn done'; sleep 1; printf 'echo from-a-file > /fat/RTIN.TXT\r'
          sleep 1; printf 'lxhello spawn < /fat/RTIN.TXT > /fat/RTOUT.TXT\r'
          sleep 6; printf 'cat /fat/RTOUT.TXT\r'
          while [ "$i" -lt 300 ] && [ ! -e "$log.end" ]; do sleep 0.5; i=$((i + 1)); done ) |
        qemu-system-x86_64 -M microvm -cpu max -m 256M -nographic -no-reboot \
            -device isa-debug-exit,iobase=0xf4,iosize=0x04 \
            -drive "file=$disk,if=none,format=raw,id=d0" -device virtio-blk-device,drive=d0 \
            -kernel "$kimg" >"$log" 2>&1 &
        local pid=$! i=0
        while [ "$i" -lt 300 ] && kill -0 "$pid" 2>/dev/null; do
            tr -d '\r' <"$log" | grep -aqF 'lx: spawn stdin=[from-a-file]' && break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2
        kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        : >"$log.end"; sleep 1; rm -f "$log.end"
        tr -d '\r' <"$log" >"$log.t" && mv "$log.t" "$log"
        rm -f "$kimg" "$kimg.features" "$disk"
        for w in "hosted by the ring-3 runtime" "lx: auxv ok" "lx: stack aligned ok" "lx: rt: getpid ok" \
            "lx: rt: uname ok" "lx: rt: getcwd ok" "lx: rt: umask ok" "lx: rt: nanosleep ok" "lx: rt: brk ok" \
            "lx: rt: mmap ok" "lx: rt: ioctl tty ok" "lx: rt: signal state ok" "lx: rt: pipe ok" \
            "lx: rt: close twice ok" "lx: rt: dup2 onto itself, not open ok" "lx: rt: file ok" \
            "lx: rt: ioctl on a file ok" "lx: rt: stat ok" "lx: rt: lstat ok" "lx: rt: newfstatat ok" \
            "lx: rt: stat a directory ok" "lx: rt: missing file ok" "lx: rt: getdents64 ok" "lx: writev ok" \
            "lx: rt: wait4 ok" "lx: rt: fcntl ok" "lx: rt: create outside caps refused ok" \
            "lx: rt: unanswered call ok" "lx: fork+wait4 ok" "lx: fork child ids ok" \
            "lx: fork child holds only its row ok" "lx: fork shares the file offset ok" \
            "lx: rt done failures=0" "lx: spawn cwd=/fat" "lx: spawn stdin kind=fifo" \
            "lx: spawn stdin=[piped-ok]" "lx: spawn stdin kind=file" "lx: spawn stdin=[from-a-file]" "lx: spawn done"; do
            grep -aqF -- "$w" "$log" || { why="missing: $w"; break; }
        done
        if [ -z "$why" ] && grep -aqE 'lx: .* FAIL|SECCOMP|KERNEL PANIC|\[X86-TRAP\]' "$log"; then
            why="$(grep -aE 'lx: .* FAIL|SECCOMP|KERNEL PANIC|\[X86-TRAP\]' "$log" | sed -n 1p)"
        fi
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64 linux: hosted by the ring-3 runtime" x86_lxrt_row
    x86_autorun_row() { # x86_autorun_row <abitest|ipctest|canary>
        local which="$1" label tag disk_t stop
        case "$which" in
            abitest) label="x86_64 abitest"; disk_t=$AZOS_OUT/build/disk-x86_64-abitest.img
                     stop='ABITEST\] [0-9]+ check\(s\) run' ;;
            ipctest) label="x86_64 ipctest"; disk_t=$AZOS_OUT/build/disk-x86_64-ipctest.img
                     stop='IPCTEST\] [0-9]+ check\(s\) run' ;;
            canary)  label="x86_64 image digest canary"; disk_t=$AZOS_OUT/build/disk-x86_64-abitest.img
                     stop='matches no seccomp image profile' ;;
            hwcapcanary) label="x86_64 abitest hwcap canary, -sha-ni"; disk_t=$AZOS_OUT/build/disk-x86_64-abitest.img
                     stop='ABITEST\] [0-9]+ check\(s\) run' ;;
            sysabicanary) label="x86_64 abitest sysabi canary"; disk_t=$AZOS_OUT/build/disk-x86_64-abitest.img
                     stop='ABITEST\] [0-9]+ check\(s\) run' ;;
            foreigncanary) label="x86_64 abitest foreign regs canary"; disk_t=$AZOS_OUT/build/disk-x86_64-abitest.img
                     stop='ABITEST\] [0-9]+ check\(s\) run' ;;
            # The riscv64 "userspace: syscall ABI" / "userspace: syscall
            # latency" / "userspace: capabilities" twins. captest runs on its
            # own hard-reservation row (`captest-row`, CPU 3: four CPUs), the
            # one the IRQ bind needs under IRQ_THREADED; its canary boots the
            # robot kernel without that row, whose autorun row has none, so the
            # bind of the absent line is refused -EPERM instead of -ENODEV.
            systest) label="x86_64 syscall ABI"; disk_t=$AZOS_OUT/build/disk-x86_64-systest.img
                     stop='SYSCALL_TEST\] (ALL PASSED|FAILED)' ;;
            latbench) label="x86_64 syscall latency"; disk_t=$AZOS_OUT/build/disk-x86_64-latbench.img
                     stop='LATBENCH\] (DONE|FATAL|PANIC)' ;;
            captest) label="x86_64 captest"; disk_t=$AZOS_OUT/build/disk-x86_64-captest.img
                     stop='CAPTEST\] (ALL PASSED|FAILED)' ;;
            captestcanary) label="x86_64 captest canary, no hard reservation"; disk_t=$AZOS_OUT/build/disk-x86_64-captest.img
                     stop='CAPTEST\] (ALL PASSED|FAILED)' ;;
        esac
        local -a app=()
        # The later `-cpu` wins over x86_qemu's `-cpu max`: the same CPU
        # without SHA-NI, so the vDSO bit must follow CPUID, not a constant.
        [ "$which" = hwcapcanary ] && app=(-cpu max,-sha-ni)
        # The later `-smp` wins too: captest's row is pinned to CPU 3.
        case "$which" in captest|captestcanary) app=(-smp 4) ;; esac
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}" disk="$CI_LOG_DIR/disk-x86-${tag}.img"
        local kfeat=""; [ "$which" = sysabicanary ] && kfeat=syscall-abi-canary
        [ "$which" = foreigncanary ] && kfeat=foreign-regs-canary
        [ "$which" = captest ] && kfeat=captest-row
        # The robot kernel without the row: the sensors and motors captest
        # reads are there, the hard reservation is not (the generic kernel
        # failed every robot check, and its bind passed as -ENODEV).
        [ "$which" = captestcanary ] && kfeat=use-robot
        x86_disk_prep "$disk_t" "$kimg" "$disk" "$kfeat" || return
        if [ "$which" = canary ]; then
            local elf="$CI_LOG_DIR/x86-${tag}-ABITEST.ELF"
            mcopy -n -i "$disk" ::ABITEST.ELF "$elf" && printf '\0' >>"$elf" && mcopy -o -i "$disk" "$elf" ::ABITEST.ELF \
                || { bad; echo "      could not alter ABITEST.ELF on the volume copy"; rm -f "$kimg" "$kimg.features" "$disk" "$elf"; return; }
            rm -f "$elf"
        fi
        par_ready
        x86_qemu "$kimg" "$log" 300 "$stop|KERNEL PANIC" -smp 2 ${app[@]+"${app[@]}"} \
            -drive "file=$disk,if=none,format=raw,id=d0" -device virtio-blk-device,drive=d0 \
            || { rm -f "$kimg" "$kimg.features" "$disk"; return; }
        # The `FAILED: N` line follows the summary; the FAIL lines precede it.
        rm -f "$kimg" "$kimg.features" "$disk"
        local why="" fails fail_lines
        if [ "$which" = sysabicanary ]; then sysabi_canary_judge "$log"; return; fi
        if [ "$which" = foreigncanary ]; then foreign_canary_judge "$log"; return; fi
        case "$which" in
            canary)
                if ! grep -aqF "[AUTORUN] REFUSED: /fat/ABITEST.ELF" "$log"; then why="autorun did not refuse the altered ABITEST.ELF"
                elif grep -aqF "[ABITEST]" "$log"; then why="the altered ABITEST.ELF ran"
                fi ;;
            systest)
                if ! grep -aqF "[SYSCALL_TEST] ALL PASSED!" "$log"; then why="syscall_test did not print ALL PASSED"
                elif grep -aqF "[SYSCALL_TEST] FAILED!" "$log"; then why="syscall_test printed FAILED"
                fi ;;
            latbench)
                if grep -aqE "LATBENCH\] (FATAL|PANIC)" "$log"; then why="$(grep -aE 'LATBENCH\] (FATAL|PANIC)' "$log" | sed -n 1p)"
                elif ! grep -aqF "[LATBENCH] DONE" "$log"; then why="latbench never printed DONE"
                fi ;;
            captest|captestcanary)
                fail_lines="$(grep -a "\[CAPTEST\]  FAIL  " "$log" | sed "s/^\[CAPTEST\]  FAIL  //")"
                fails="$(printf '%s\n' "$fail_lines" | grep -c .)"
                if [ "$which" = captestcanary ]; then
                    # The bind is refused for the missing reservation, and
                    # only that: the canary proves the row reads the IRQ case.
                    if ! printf '%s\n' "$fail_lines" | grep -qF "irq: irq_bind(absent line) -> -ENODEV rc=-1"; then
                        why="the absent line's bind was not refused -EPERM without the row's reservation: $(printf '%s\n' "$fail_lines" | sed -n 1,3p | tr '\n' ';')"
                    elif [ "$fails" -ne 1 ]; then why="captest failed $fails checks, the canary expects only the bind: $(printf '%s\n' "$fail_lines" | sed -n 1,4p | tr '\n' ';')"
                    else ok; echo "      canary failed as it must: [irq_bind(absent line) rc=-1]"; rm -f "$log"; return
                    fi
                elif [ "$fails" -gt 0 ]; then why="captest reported $fails failure(s): $(printf '%s\n' "$fail_lines" | sed -n 1,4p | tr '\n' ';')"
                elif ! grep -aqF "[CAPTEST] ALL PASSED" "$log"; then why="captest never printed ALL PASSED"
                elif ! grep -aqF "[IRQ] ring-3 line 1000 refused by the interrupt controller" "$log" \
                     || ! grep -aqE "\[IRQ\] ring-3 line 1000 refused .*bindings left on the line: 0" "$log"; then
                    why="the kernel did not refuse the absent line 1000 with no binding left"
                fi ;;
            *)
                local tagw; tagw="$(printf '%s' "$which" | tr 'a-z' 'A-Z')"
                [ "$which" = hwcapcanary ] && tagw=ABITEST
                if ! grep -aqE "\[$tagw\] [0-9]+ check\(s\) run" "$log"; then why="$which never printed its own summary line"
                elif [ "$which" = ipctest ] && ! grep -aqF "[IPCTEST] all=1600 of 1600 OK" "$log"; then
                    why="phase A did not complete all 1600 calls: $(grep -a 'IPCTEST\] all=' "$log" | sed -n 1p)"
                elif grep -aq "\[MM\] page-table root" "$log"; then why="a teardown found its root still live"
                else
                    fail_lines="$(grep -a "\[$tagw\]  FAIL  " "$log" | sed "s/^\[$tagw\]  FAIL  //")"
                    fails="$(printf '%s\n' "$fail_lines" | grep -c .)"
                    if [ "$fails" -gt 0 ]; then
                        why="$which reported $fails failure(s): $(printf '%s\n' "$fail_lines" | sed -n 1,4p | tr '\n' ';')"
                    fi
                fi ;;
        esac
        # The vDSO hwcap word (x86_64 arm): what `-cpu max` must publish
        # (TCG, QEMU 11: AVX2, AES, SHA-NI, RDRAND, RDSEED among others;
        # FSGSBASE and PKU are in CPUID but stay clear, CR4 does not enable
        # them), and the word abitest read in ring 3 must be the kernel's.
        # The canary drops SHA-NI from the CPU: its bit must clear, the rest
        # stay, and abitest's own checks (above) still all pass.
        if [ -z "$why" ] && { [ "$which" = abitest ] || [ "$which" = hwcapcanary ]; }; then
            local kline kw uw n want="avx2 aes rdrand rdseed" gone="fsgsbase pku"
            if [ "$which" = abitest ]; then want="$want sha-ni"; else gone="$gone sha-ni"; fi
            kline="$(grep -a '^\[VDSO\] hwcap=' "$log" | sed -n 1p)"
            kw="$(printf '%s' "$kline" | sed -n 's/^\[VDSO\] hwcap=\(0x[0-9a-f]*\):.*/\1/p')"
            uw="$(grep -a '^\[ABITEST\] hwcap=' "$log" | sed -n 's/^\[ABITEST\] hwcap=\(0x[0-9a-f]*\).*/\1/p' | sed -n 1p)"
            if [ -z "$kw" ]; then why="the kernel printed no [VDSO] hwcap= line"
            elif [ "$kw" != "$uw" ]; then why="ring 3 read hwcap ${uw:-nothing}, the kernel published $kw"
            else
                for n in $want; do
                    printf ' %s \n' "${kline#*:}" | qgrep -qF " $n " || { why="hwcap lacks $n: $kline"; break; }
                done
                if [ -z "$why" ]; then
                    for n in $gone; do
                        printf ' %s \n' "${kline#*:}" | qgrep -qF " $n " && { why="hwcap has $n: $kline"; break; }
                    done
                fi
            fi
        fi
        [ -z "$why" ] && grep -aq "KERNEL PANIC" "$log" && why="$(grep -a 'KERNEL PANIC' "$log" | sed -n 1p)"
        if [ -z "$why" ]; then ok; rm -f "$log"; return; fi
        bad; echo "      $why"; echo "      log kept: $log"
    }
    par "x86_64 abitest" x86_autorun_row abitest
    par "x86_64 ipctest" x86_autorun_row ipctest
    par "x86_64 image digest canary" x86_autorun_row canary
    par "x86_64 abitest hwcap canary, -sha-ni" x86_autorun_row hwcapcanary
    par "x86_64 abitest sysabi canary" x86_autorun_row sysabicanary
    par "x86_64 abitest foreign regs canary" x86_autorun_row foreigncanary
    par "x86_64 syscall ABI" x86_autorun_row systest
    par "x86_64 syscall latency" x86_autorun_row latbench
    par "x86_64 captest" x86_autorun_row captest
    par "x86_64 captest canary, no hard reservation" x86_autorun_row captestcanary

    # ── Wave 15 (GR5): the panic report is not spliced (see the rv/arm rows,
    # `panic_splice_row`, for the property and the read). Same smoke and
    # canaries on x86_64, -smp 2; judged by `panic_splice_judge`.
    x86_panic_splice_row() { # x86_panic_splice_row <label> <want: pass|stop|splice|fatal|fatalskip|nested|rereport> [kernel command line]
        local label="$1" want="$2" app="${3:-}" why="" try=1 tries=1 v
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local tag; tag="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-')"
        local log="$CI_LOG_DIR/x86-${tag}.log" kimg="$CI_LOG_DIR/kernel-x86-${tag}"
        x86_kbuild "use-robot,panic-splice-smoke" "$kimg" || { bad; echo "      make x86_64 (panic-splice-smoke) did not build"; return; }
        par_ready
        local -a ap=(); [ -n "$app" ] && ap=(-append "$app")
        case "$want" in pass|fatal|nested|rereport) ;; *) tries=$PANIC_SPLICE_TRIES ;; esac
        while [ "$try" -le "$tries" ]; do
            x86_qemu "$kimg" "$log" 60 'Crash counter = |\[TRACE\] cpu0|no second report; (halted|rebooting in [0-9]+ ms)' -smp 3 ${ap[@]+"${ap[@]}"} || { rm -f "$kimg" "$kimg.features"; return; }
            v="$(splice_judge_for "$want" "$log")"
            why="$(panic_splice_verdict "$want" "$v")"
            [ -z "$why" ] && break
            try=$((try + 1))
        done
        rm -f "$kimg" "$kimg.features"
        if [ -z "$why" ]; then
            ok; echo "      $v (boot $try)"; rm -f "$log"
        else
            bad; echo "      $why ($tries boot(s))"
            grep -a -m1 -B2 -A7 'KERNEL PA\|!!! K\|^\[FATAL\]' "$log" | sed 's/^/        /'
            echo "      log kept: $log"
        fi
    }
    par "panic: report not spliced by a console flood (x86)" x86_panic_splice_row \
        "panic: report not spliced by a console flood (x86)" pass
    par "panic: other CPUs parked, stop canary (x86)" x86_panic_splice_row \
        "panic: other CPUs parked, stop canary (x86)" stop "canary=panic-stop-skip"
    par "panic: report spliced, quiesce canary (x86)" x86_panic_splice_row \
        "panic: report spliced, quiesce canary (x86)" splice "canary=panic-quiesce-skip"
    par "fatal: report not spliced by a console flood (x86)" x86_panic_splice_row \
        "fatal: report not spliced by a console flood (x86)" fatal "canary=panic-splice-fatal"
    par "fatal: no quiesce, quiesce canary (x86)" x86_panic_splice_row \
        "fatal: no quiesce, quiesce canary (x86)" fatalskip "canary=panic-splice-fatal,panic-quiesce-skip"
    par "panic: a panic inside the handler prints one line (x86)" x86_panic_splice_row \
        "panic: a panic inside the handler prints one line (x86)" nested "canary=panic-nested"
    par "panic: nested, second report canary (x86)" x86_panic_splice_row \
        "panic: nested, second report canary (x86)" rereport "canary=panic-nested,panic-nested-report"

    # ── Wave 15 (DAIF): the interrupt-mask primitives are compiler barriers ──
    #
    # aarch64's `read_daif`/`write_daif`/`enable_irq` were `nomem`, so LLVM
    # could move plain loads and stores across `ARCH.disable_all()` /
    # `restore()`, out of the window the caller masked. They are barriers now
    # (riscv64's `sstatus` accessors always were). `irq-order-probe` builds
    # `azos_irq_order_probe` (kernel/src/smokes/irq_order_probe.rs): store 1,
    # mask, store 2, restore. Read in the disassembly: two stores, the first
    # before the masking write (`csrw sstatus` / `msr DAIF`).
    #
    # Canary (both ISAs, in the gate): `irq-nomem-canary` gives the mask asm
    # `nomem` back; the first store is then dead and LLVM drops it, so the
    # row must find one store, or the first store after the mask.
    irq_order_row() { # irq_order_row <isa: rv|arm> <features> <pass|canary>
        local isa="$1" feats="$2" want="$3" elf objdump dis mask
        local label="irq order: store before mask ($isa)"
        [ "$want" = canary ] && label="irq order: canary refused ($isa)"
        printf "  %-26s" "${label}..."
        if [ "$isa" = rv ]; then
            kbuild "$feats" || { bad; echo "      riscv64 --features $feats did not build"; return; }
            elf="$KERNEL"; mask='csrw[[:space:]]+sstatus'
        else
            a64_kbuild "$feats" || { bad; echo "      aarch64 --features $feats did not build"; return; }
            elf="$A64_KERNEL"; mask='msr[[:space:]]+DAIF,'
        fi
        objdump="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-objdump"
        dis="$("$objdump" -d --no-show-raw-insn --disassemble-symbols=azos_irq_order_probe "$elf" 2>/dev/null \
               | grep -E '^[[:space:]]*[0-9a-f]+:[[:space:]]')"
        local stores first_store first_mask
        stores="$(printf '%s\n' "$dis" | grep -cE '[[:space:]](sd|str)[[:space:]]')"
        first_store="$(printf '%s\n' "$dis" | grep -nE '[[:space:]](sd|str)[[:space:]]' | sed -n '1s/:.*//p')"
        first_mask="$(printf '%s\n' "$dis" | grep -nE "$mask" | sed -n '1s/:.*//p')"
        if [ -z "$dis" ] || [ -z "$first_mask" ]; then
            bad; echo "      azos_irq_order_probe not found or has no mask instruction in $elf"; return
        fi
        local ordered=0
        [ "$stores" -eq 2 ] && [ -n "$first_store" ] && [ "$first_store" -lt "$first_mask" ] && ordered=1
        if { [ "$want" = pass ] && [ "$ordered" = 1 ]; } || { [ "$want" = canary ] && [ "$ordered" = 0 ]; }; then
            ok; return
        fi
        bad; echo "      stores=$stores first store at line ${first_store:-none}, first mask at line $first_mask:"
        printf '%s\n' "$dis" | sed 's/^/        /'
    }
    par -s "irq order: store before mask (rv)" irq_order_row rv qemu,irq-order-probe pass
    par -s "irq order: store before mask (arm)" irq_order_row arm qemu,irq-order-probe pass
    par -s "irq order: canary refused (rv)" irq_order_row rv qemu,irq-nomem-canary canary
    par -s "irq order: canary refused (arm)" irq_order_row arm qemu,irq-nomem-canary canary
    kbuild "qemu"

    # The diagnostic counters that must stay at zero, on a kernel that has them.
    #
    # This row used to assert `handoff taken=[1-9]` for the direct hand-off. That
    # hand-off was **reverted** after measurement: `-smp 1` + icount, control
    # `syscall-floor` bit-identical at 318, showed it cost **52 instructions
    # per round trip and saved none** — on the benchmark lane the server is the
    # only runnable task, so `do_schedule` would have picked it anyway and the
    # hint paid a swap, an `idx_for_tid`, a state check and a `cpu_remove` scan
    # for a decision already made.
    #
    # The row stays because the FAILURE guard below is what it is really worth:
    # it prints from the `ipc-census` dump and must be zero.
    #
    #   * `mem quota refused` — owner decision 102's per-task frame budget must
    #     not bind a legitimate program (2048 pages against a measured peak of
    #     512 for vsbench).
    kbuild "qemu,ipc-census"
    fresh_disk $AZOS_OUT/build/disk-ipctest.img
    # Chain E commit 3 (2026-10-11): the placement-histogram audit
    # (`scheduler::hist_check`, compiled by ipc-census) prints HIST_DRIFT when a
    # recorded key and the live one disagree for 10 ms; the IPC hand-off now
    # stores keys crosswise, so a drift here fails the row instead of scrolling.
    QEMU_FAIL_RE="$QEMU_FAIL_RE|mem quota refused=[1-9]|HIST_DRIFT" \
    par_row qemu_run "ipc: census counters zero" "IPCTEST] ALL PASSED" 180 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-ipctest.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    kbuild "qemu"

    # The reflex daemon must REACT, not merely start. A kernel task moves the
    # simulated rangefinder to 100 mm and then back to 1500 mm; reflex has to
    # trip and then recover. Asserting on "Clear" rather than the trigger is
    # deliberate: `overriding` is only ever set by a trigger, so that one
    # string proves both the reaction and the exit from it — and a daemon
    # wedged in override means motors held in reverse forever.
    kbuild "qemu,reflex-smoke"
    rm -f $AZOS_OUT/build/disk-reflex.img
    make_disk $AZOS_OUT/build/disk-reflex.img
    # KNOWN GAP, measured twice rather than assumed. This marker proves reflex
    # RAN and logged; it does not prove the motors were COMMANDED. Stubbing
    # `MotorServer::speed` to return 0 without calling `motor_stop` leaves
    # this scenario GREEN (2026-09-07).
    #
    # A marker at the actuation gate was tried on the same day and removed: it
    # does not discriminate either. `rt_motor_task` writes the motors every
    # control tick, so a print in `actuation_gate` fires ~2300 times per boot
    # regardless — 2328 in the baseline, 2308 with the typed call stubbed to
    # actuate nothing. A check on it would always pass, which is worse than no
    # check because it reads as coverage.
    #
    # What would work needs one of: caller identity at the gate hook (whose
    # signature is `(id, speed)` and is on the actuation path, so widening it
    # is not a test change), or a marker inside `MotorServer::speed` with
    # the smoke feature plumbed into `crates/core/syscall`. Recorded rather than
    # guessed at.
    par_row qemu_run "userspace: reflex reacts" "reflex] Clear" 180 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-reflex.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # THE GAP ABOVE, CLOSED 2026-09-09. The scenario proves reflex REACTED;
    # this one proves it COMMANDED the motors.
    #
    # `[ACTSMOKE]` prints the duty the actuation itself left on the PWM
    # channel, so a handler stubbed to return success without driving anything
    # cannot produce it — which is exactly what the comment above records as
    # having been measured and left uncovered. The value is reported out of the
    # write (`motor_set_reporting`) rather than read back afterwards; see the
    # ring-3 scenario below for why that distinction is the whole assertion.
    #
    # ASSERTED ON THE REVERSE, NOT THE STOP, and that took a measurement to
    # get right. Reflex's stops go through the typed call and every one of
    # them reads `ask=0 duty=0` — indistinguishable from a stub, because
    # nothing was driving the motors beforehand in this scenario. The backup
    # is the actuation with a number in it: `dir=1` (Backward) and the duty
    # the kernel fixes at 50. It goes through the `motor.direction` op,
    # the typed form of the retired `SYS_MOTOR_ENABLE`; the marker is
    # printed by `motor_direction_reporting`, shared by both, so `dir=1 ask=30 duty=30`
    # is unchanged.
    #
    # Both wheels, because a reflex that backs up one of them steers into the
    # obstacle.
    reflex_actuation_scenario() {
        local label="userspace: reflex COMMANDS"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/reflex-commands.log"
        rm -f "$log"

        kbuild "qemu,reflex-smoke,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-reflex.img
        make_disk $AZOS_OUT/build/disk-reflex.img
        job_disk $AZOS_OUT/build/disk-reflex.img
        par_ready

        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$JDISK",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        local qpid=$!
        local i=0
        while [ "$i" -lt 360 ]; do
            grep -aq "reflex] Clear" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        if ! grep -aq "reflex] CRITICAL OBSTACLE" "$log" 2>/dev/null; then
            bad; echo "      the reflex never tripped, so there was nothing to"
            echo "      command. This is the 'reacts' scenario's property."
            echo "      log kept: $log"; return
        fi
        local m=0
        for id in 0 1; do
            grep -aq "ACTSMOKE] ring3 motor id=$id dir=1 ask=30 duty=30" "$log" 2>/dev/null \
                && m=$((m + 1))
        done
        if [ "$m" -ne 2 ]; then
            bad; echo "      reflex logged but did not drive both wheels backwards"
            echo "      ($m/2 matched). What the markers say:"
            grep -a -m4 "ACTSMOKE" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "userspace: reflex COMMANDS" reflex_actuation_scenario

    # ── 2026-09-25 owner decisions Q1.4/Q1.3: gate fails closed; actuation record ──
    # Gate rows for Q1.4 (fail-closed motor gate) and Q1.3 (actuation record),
    # owner decisions 2026-09-25. NOT wired into tools/ci_check.sh — delivered as
    # text per the task brief (tools/ci_check.sh is off-limits to this agent).
    # Written to slot in beside `reflex_actuation_scenario` (tools/ci_check.sh,
    # ~line 4076), reusing its exact QEMU invocation and helpers:
    #   - kbuild()   tools/ci_check.sh ~line 47  — build, fail loudly on error
    #   - make_disk() tools/ci_check.sh ~line 288 — `make <target>`, fail loudly
    #   - qemu_run() / QEMU_FAIL_RE  tools/ci_check.sh ~line 356-399 — the
    #     general scenario runner; NOT used verbatim below because (like
    #     reflex_actuation_scenario) both rows need two sequential markers in one
    #     boot, so they follow that scenario's own hand-rolled loop instead.
    #   - CI_LOG_DIR  tools/ci_check.sh ~line 311
    #
    # Rules followed throughout, per the task brief:
    #   - `grep -q` (or `grep -aq`), never `grep -c` into an integer test.
    #   - No `^` anchors: QEMU's UART emits `\r` before each line, so an anchor
    #     would silently never match.
    #   - Every assertion is POSITIVE (a `grep -aq PATTERN` that must find
    #     something), including the "absent" property — see below.
    #   - A negative property ("the gate is not installed") is proved by
    #     grepping for a string ONLY the skip path prints
    #     ("[SAFETY] actuation gate SKIPPED"), never by the ABSENCE of a string
    #     the working path prints — absence-of-output is indistinguishable from
    #     "the scenario did not reach that code yet" or "the boot hung".
    #   - Where a number exists, it is read back and compared, not merely
    #     matched: `duty=0` / `duty=50` / the ring length, not just "ACTSMOKE
    #     appeared".
    #
    # Both rows share ONE disk image (build/disk-reflex.img — `reflex-smoke`'s
    # autorun is `/fat/REFLEX.ELF`; neither `gate-skip-smoke` nor
    # `actuation-smoke` touch what goes ON the disk, only what the KERNEL binary
    # does), so a real gate script would build it once, before either row.
    #
    # Circularity note (why the fail-closed row does NOT prove itself by "motors
    # never move"): with the gate genuinely skipped, `autorun_task` still starts
    # ring-3 code today (the boot-refusal half of Q1.4 is a DIFFERENT boundary —
    # see the delivered kernel/src/main.rs diff, not yet applied because this
    # agent may not touch that file). So `reflex.elf` still runs and still
    # commands the wheels; what must change is the DUTY that command leaves on
    # the channel (50 -> 0), not whether a command is issued at all. Asserting
    # only "no ACTSMOKE line" would be proving nothing once the boot-refusal
    # lands and no ring-3 program starts at all — asserting the NUMBER inside
    # the line survives that future change and keeps discriminating.

    # ── Row 1: Q1.4 — the actuation gate fails closed ──────────────────────────
    #
    # Baseline build (gate installed) must show `ask=30 duty=30` (REFLEX.ELF's own
    # BACKUP_SPEED_PCT through the `motor.drive` op; until 2026-09-26 the
    # daemon could only reach `motor_direction_typed`'s kernel-fixed 50%, and
    # this row encoded that 50 — the envelope-clamped
    # reflex backup speed — see reflex_actuation_scenario's own comment for why
    # 50, not the raw ask, is what a working gate leaves on the channel).
    # `gate-skip-smoke` build (gate NOT installed): since Q1.4 autorun refuses
    # to start REFLEX.ELF at all, so the half asserts the refusal + the
    # kernel-side writer clamped to 0 — it used to expect `duty=0` for the
    # SAME command — `gate_speed`'s `None` arm now clamps instead of passing the
    # request through. The SKIPPED line proves the skip build is the one that
    # ACTUALLY reached `install()` without arming the gate, not merely a build
    # that happens to also produce duty=0 for some unrelated reason.
    gate_fails_closed_scenario() {
        local label="safety: actuation gate fails closed"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"

        kbuild "qemu,reflex-smoke,actuation-smoke" || return
        rm -f $AZOS_OUT/build/disk-reflex.img
        make_disk $AZOS_OUT/build/disk-reflex.img
        # Both kernels and both volumes are taken before the first boot, so
        # the row's boots can run beside other rows' (see `par`).
        local k1="$CI_LOG_DIR/gate-baseline.kernel" d1="$CI_LOG_DIR/gate-baseline.img"
        local k2="$CI_LOG_DIR/gate-skip.kernel" d2="$CI_LOG_DIR/gate-skip.img"
        cp "$KERNEL" "$k1"; cp $AZOS_OUT/build/disk-reflex.img "$d1"
        kbuild "qemu,reflex-smoke,actuation-smoke,gate-skip-smoke" || return
        fresh_disk $AZOS_OUT/build/disk-reflex.img
        cp "$KERNEL" "$k2"; cp $AZOS_OUT/build/disk-reflex.img "$d2"
        par_ready

        local baseline_log="$CI_LOG_DIR/gate-baseline.log"
        rm -f "$baseline_log"
        "$QEMU" -machine virt -nographic -bios default -kernel "$k1" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$d1",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$baseline_log" 2>&1 &
        local qpid=$!
        local i=0
        while [ "$i" -lt 360 ]; do
            grep -aq "reflex] Clear" "$baseline_log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$baseline_log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        rm -f "$k1" "$d1"

        if grep -aqiE "panic|\[FATAL\]" "$baseline_log" 2>/dev/null; then
            bad; echo "      baseline: kernel panic or fatal exception:"
            grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$baseline_log" | sed "s|^|      |"
            echo "      log kept: $baseline_log"; return
        fi
        # Positive: the baseline (gate armed) must show the clamped 50, both
        # wheels, driven by reflex reacting to the obstacle.
        local baseline_ok=0
        for id in 0 1; do
            grep -aq "ACTSMOKE] ring3 motor id=$id dir=1 ask=30 duty=30" "$baseline_log" 2>/dev/null \
                && baseline_ok=$((baseline_ok + 1))
        done
        if [ "$baseline_ok" -ne 2 ]; then
            bad; echo "      baseline (gate armed) did not show ask=30 duty=30 on both wheels"
            echo "      ($baseline_ok/2 matched) — the scenario itself is broken,"
            echo "      not the property under test. What the markers say:"
            grep -a -m6 "ACTSMOKE" "$baseline_log" | sed "s|^|      |"
            echo "      log kept: $baseline_log"; return
        fi

        local skip_log="$CI_LOG_DIR/gate-skip.log"
        rm -f "$skip_log"
        "$QEMU" -machine virt -nographic -bios default -kernel "$k2" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$d2",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$skip_log" 2>&1 &
        qpid=$!
        i=0
        while [ "$i" -lt 360 ]; do
            # REFLEX.ELF never starts on this build (see below), so its
            # "Clear" line cannot end the wait; the smoke script's own DONE can.
            grep -aq "reflex] Clear\|REFLEXSMOKE] DONE" "$skip_log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$skip_log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        rm -f "$k2" "$d2"

        if grep -aqiE "panic|\[FATAL\]" "$skip_log" 2>/dev/null; then
            bad; echo "      gate-skip build: kernel panic or fatal exception"
            echo "      (a fail-closed motor write must not be able to crash the"
            echo "      boot — this itself would be a regression):"
            grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$skip_log" | sed "s|^|      |"
            echo "      log kept: $skip_log"; return
        fi
        # Positive: the skip build genuinely reached `install()` without arming
        # the gate — a string only that code path prints.
        if ! grep -aq "SAFETY] actuation gate SKIPPED" "$skip_log" 2>/dev/null; then
            bad; echo "      gate-skip-smoke build did not print the SKIPPED"
            echo "      line — the feature did not wire the way this row assumes."
            echo "      log kept: $skip_log"; return
        fi
        # Q1.4 (owner decision, landed 2026-09-26): with no actuation gate
        # installed, `autorun` REFUSES to start any ring-3 program at all —
        # REFLEX.ELF is never loaded, so the "same command now reads 0" line
        # this row used to look for cannot be printed on this build. The
        # fail-closed property is now enforced one layer earlier, and that is
        # what this half asserts. Anchors, all positive and all from lines
        # only these code paths print:
        #   1. the refusal itself (`[AUTORUN] REFUSED: actuation gate is not
        #      installed`);
        #   2. `[REFLEXSMOKE] DONE` — the smoke script ran to its end, so the
        #      boot did not merely die before a ring-3 line could appear;
        #   3. the kernel-side smoke writer still wrote (`kernel motor id=N
        #      duty=0` is its on-change print), which anchors the negation
        #      that no `duty=80` got through — the baseline above shows the
        #      same writer alternating 0/80 when the gate is armed.
        # With 1–3 in hand, the negation "no ring-3 motor line at all" is
        # tied to a refusal that only the fail-closed path prints, not to
        # a boot that simply printed nothing.
        if ! grep -aq "AUTORUN] REFUSED: actuation gate is not installed" "$skip_log" 2>/dev/null; then
            bad; echo "      gate-skip build: autorun did NOT refuse to start ring-3"
            echo "      programs with the gate absent (Q1.4 regressed):"
            grep -a -m3 "AUTORUN\]" "$skip_log" | sed "s|^|      |"
            echo "      log kept: $skip_log"; return
        fi
        if ! grep -aq "REFLEXSMOKE] DONE" "$skip_log" 2>/dev/null; then
            bad; echo "      gate-skip build: the smoke script did not run to DONE,"
            echo "      so an absent ring-3 line would prove nothing."
            echo "      log kept: $skip_log"; return
        fi
        local skip_ok=0
        for id in 0 1; do
            grep -aq "ACTSMOKE] kernel motor id=$id duty=0" "$skip_log" 2>/dev/null \
                && ! grep -aq "ACTSMOKE] kernel motor id=$id duty=80" "$skip_log" 2>/dev/null \
                && skip_ok=$((skip_ok + 1))
        done
        if [ "$skip_ok" -ne 2 ]; then
            bad; echo "      gate-skip build: the kernel-side smoke writer did not clamp"
            echo "      both wheels to duty=0 ($skip_ok/2). What the markers say:"
            grep -a -m6 "ACTSMOKE" "$skip_log" | sed "s|^|      |"
            echo "      log kept: $skip_log"; return
        fi
        if grep -aq "ACTSMOKE] ring3 motor" "$skip_log" 2>/dev/null; then
            bad; echo "      gate-skip build: a ring-3 motor write reached the kernel"
            echo "      although autorun announced the refusal above:"
            grep -a -m4 "ACTSMOKE] ring3" "$skip_log" | sed "s|^|      |"
            echo "      log kept: $skip_log"; return
        fi
        ok; rm -f "$baseline_log" "$skip_log"
    }

    # ── Row 2: Q1.3 — an admitted actuation command reaches the flight recorder ─
    #
    # Same baseline boot (gate armed, `actuation-smoke` on) already commands both
    # wheels via reflex. `[ACTREC]` (domains/robot/safety-core/src/actuation.rs,
    # `record_motor_change`) is the record hook itself printing its own
    # admission, `duty=` the value it just wrote to `log_actuator_cmd`, and
    # `ring_len=` the flight recorder's ring depth read back immediately after —
    # a NUMBER through the real `logger_ring_len()`, not merely a line's
    # presence. Failure mode this discriminates against: a build where the
    # record hook is never installed, or is installed but never called
    # (canary below).
    record_reaches_the_ring_scenario() {
        local label="safety: actuation record reaches the ring"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"

        kbuild "qemu,reflex-smoke,actuation-smoke" || return
        rm -f $AZOS_OUT/build/disk-reflex.img
        make_disk $AZOS_OUT/build/disk-reflex.img
        job_disk $AZOS_OUT/build/disk-reflex.img
        par_ready

        local log="$CI_LOG_DIR/actrec.log"
        rm -f "$log"
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$JDISK",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        local qpid=$!
        local i=0
        while [ "$i" -lt 360 ]; do
            grep -aq "reflex] Clear" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"
            grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        # Positive, with a number: the same admitted command (dir=1 duty=30,
        # matching row 1's baseline) reached the recorder, for BOTH wheels, and
        # the ring depth it reports is > 0 (it went somewhere, not just printed).
        local seen=0
        for id in 0 1; do
            if grep -aq "ACTREC] motor id=$id dir=1 duty=30 ring_len=" "$log" 2>/dev/null; then
                local ring_len
                ring_len=$(grep -a "ACTREC] motor id=$id dir=1 duty=30 ring_len=" "$log" \
                    | sed -n '1{s/.*ring_len=\([0-9]*\).*/\1/p;}')
                if [ -n "$ring_len" ] && [ "$ring_len" -gt 0 ]; then
                    seen=$((seen + 1))
                fi
            fi
        done
        if [ "$seen" -ne 2 ]; then
            bad; echo "      the admitted 30% command was not recorded for both"
            echo "      wheels with a positive ring length ($seen/2). What the"
            echo "      markers say:"
            grep -a -m8 "ACTREC" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        # Positive: the record hook does not flood — the tree already learned
        # this the hard way for a marker at the GATE hook (2026-09-07, see
        # actuation.rs's own note: ~2300 prints/boot with no discrimination).
        # A held command must be at most MOTOR_RECORD_BUDGET_PER_WINDOW (4) per
        # motor per ~1s window, not one per control tick — so over a boot that
        # settles within a few seconds, dozens, not thousands.
        local actrec_count
        actrec_count=$(grep -ac "ACTREC" "$log")
        if [ "$actrec_count" -gt 200 ]; then
            bad; echo "      $actrec_count ACTREC lines — the rate limiter is not"
            echo "      bounding this the way it is supposed to (expected order"
            echo "      of magnitude: tens, not hundreds)."
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }

    # ── Canaries (run by hand, not part of the gate — proved once, recorded here) ─
    #
    # Three buckets per scenario: (a) discriminates, (b) does not discriminate,
    # (c) did not compile. All three were exercised for real during this task
    # (see the report), not merely asserted:
    #
    #   Q1.4 fail-closed, host test `no_gate_installed_clamps_every_speed_to_
    #   zero_not_passthrough` (tests/host/behavior-tests/src/lib.rs):
    #     (a) discriminates — revert `domains/robot/robot/src/motor.rs`'s
    #         `gate_speed`'s `None => 0` to `None => speed_pct`: RED,
    #         `left: Some(77) / right: Some(0)`.
    #     (c) did not compile — this row's OWN mechanism: `kbuild` fails loudly
    #         on any build error rather than reusing a stale binary (its own doc,
    #         citing gate 116's postmortem) — reproduced directly during this
    #         task by a one-identifier typo in `admit_motor_record`
    #         (domains/robot/safety-core/src/actuation.rs): `cargo build` exited
    #         nonzero with `error[E0425]: cannot find value
    #         'MOTOR_RECORD_BUDGET_PER_WINDOOP' in this scope`.
    #     (b) does not discriminate — N/A for this property: there is no
    #         "records but ignores the gate" middle state for a return value.
    #
    #   Q1.3 record-on-change, host test `a_change_is_recorded_but_a_repeat_is_
    #   not`:
    #     (a) discriminates — make `motor_set_reporting`'s
    #         `if changed { record_motor_change(...) }` unconditional: RED,
    #         `left: 2 / right: 1` (the repeat was recorded too).
    #     (b) does not discriminate — the ALREADY-REJECTED precedent this
    #         design deliberately avoided: a marker at the GATE hook itself
    #         (`actuation.rs`'s own comment, 2026-09-07) fired ~2300 times per
    #         boot whether or not any ring-3 program commanded anything (2328
    #         baseline vs 2308 with the handler stubbed to actuate nothing) —
    #         a check that always passes. This task's own QEMU row above
    #         confirms the RECORD hook does not repeat that mistake: 36
    #         `[ACTREC]` lines in a real boot that commands both wheels
    #         continuously via `rt_motor_task`, not thousands.
    #     (c) did not compile — same `kbuild` mechanism as above.
    par "safety: actuation gate fails closed" gate_fails_closed_scenario
    par "safety: actuation record reaches the ring" record_reaches_the_ring_scenario

    # ── config: unsigned CONFIG.INI fails closed (owner V1.4, 2026-09-26) ────
    # CONFIG.INI on the USB-exposed FAT volume decides the kill-switch pin,
    # link encryption, an OTA listener, bench_boot and autorun. It is now
    # signed with the topology key (CONFIG.SIG); a tampered sidecar must boot
    # into factory defaults with the kernel saying so — a string only the
    # FailClosed branch prints.
    kbuild "qemu"
    rm -f $AZOS_OUT/build/disk-configtamper.img
    make_disk $AZOS_OUT/build/disk-configtamper.img
    # Wave 11: the marker names the reason (a v2 sidecar whose signature does
    # not verify), so a refusal for any other reason cannot pass the row.
    par_row qemu_run "config: tampered CONFIG.SIG fails closed" "(CONFIG.SIG did not verify) — fell back to factory defaults" 90 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-configtamper.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0


    # ── config: CONFIG.SIG v2 — a replay is refused, a lost signature latches ──
    #
    # Wave 11. CONFIG.SIG used to be a bare signature over
    # CONFIG.INI's bytes: an older, validly signed pair copied back verified,
    # and deleting CONFIG.SIG left the kill switch at its "unconfigured"
    # sentinel with one boot-log line. v2 signs the device id (reserved tail
    # sector 2) and a counter; the device record keeps the lowest counter
    # still accepted (the floor). Three boots of ONE copy of the image, which
    # is re-provisioned first (its own id, floor 0) whatever booted the base:
    #   1. counter 2: loads, and the kernel raises the floor 0 -> 2. The floor
    #      is then read back OFF THE IMAGE (`device_provision.py --show`), not
    #      off the log. No latch line.
    #   2. the counter-1 pair, validly signed for this device (an older file
    #      put back): refused as a replay, defaults, e-stop latched with
    #      `estop_is_active=1`, and the durable record written. Floor still 2.
    #   3. CONFIG.SIG deleted: latched again, reason "CONFIG.SIG absent".
    # Every boot's marker is a line only its own path prints.
    # Canaries (by hand, 2026-10-02): the `c >= f` guard in
    # `config_authority_decision` made `true` -> boot 2 loads the replay (no
    # "below the floor" line, red); the `_ if f == 0` arm made `_` -> boot 3
    # takes defaults without latching (red). The host table is in config-tests.
    config_authority_row() { # <label> <isa: rv|arm>
        local label="$1" isa="$2"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug base img kimg dir log why="" pid i
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        img="$CI_LOG_DIR/${slug}.img"; kimg="$CI_LOG_DIR/${slug}-kernel"; dir="$CI_LOG_DIR/${slug}.d"
        if [ "$isa" = rv ]; then
            base=$AZOS_OUT/build/disk.img
            kbuild "qemu" >/dev/null || { bad; echo "      riscv64 kernel (qemu) did not build"; return; }
            cp "$KERNEL" "$kimg"
        else
            base=$AZOS_OUT/build/disk-aarch64.img
            a64_kbuild "qemu" >/dev/null || { bad; echo "      aarch64 kernel (qemu) did not build"; return; }
            cp "$A64_IMG" "$kimg"
        fi
        rm -rf "$img" "$dir"; mkdir -p "$dir"
        make_disk "$base"; cp "$base" "$img"
        # Three short boots of one volume: start its boot count at 0 (the
        # Makefile's BOOTMETA), so none of them is the fourth unconfirmed boot
        # that enters SAFE MODE whatever booted the base image before.
        printf "active_slot=a\nboot_count=0\nlast_good=a\nfw_version_a=0\nfw_version_b=0\n" >"$dir/BOOTMETA"
        mdel -i "$img" ::BOOTMETA.A ::BOOTMETA.B >/dev/null 2>&1 || true
        if ! mcopy -o -i "$img" "$dir/BOOTMETA" ::BOOTMETA 2>/dev/null \
           || ! python3 tools/device_provision.py "$img" >/dev/null \
           || ! mcopy -n -i "$img" ::CONFIG.INI "$dir/CONFIG.INI" 2>/dev/null \
           || ! python3 tools/gen_config_sig.py "$dir/CONFIG.INI" --config-v2 --counter 1 --image "$img" --out "$dir/old.sig" >/dev/null \
           || ! python3 tools/gen_config_sig.py "$dir/CONFIG.INI" --config-v2 --counter 2 --image "$img" --out "$dir/new.sig" >/dev/null \
           || ! mcopy -o -i "$img" "$dir/new.sig" ::CONFIG.SIG 2>/dev/null; then
            bad; echo "      could not provision and sign $img"; rm -f "$kimg"; return
        fi
        cfgauth_boot() { # <boot#> <marker (fixed string)> -> log path in $log
            log="$CI_LOG_DIR/${slug}-boot$1.log"; rm -f "$log"
            if [ "$isa" = rv ]; then
                par_ready
                "$QEMU" -machine virt -nographic -bios default -kernel "$kimg" -smp 4 \
                    -global virtio-mmio.force-legacy=false \
                    -drive file="$img",if=none,format=raw,id=hd0 \
                    -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
            else
                par_ready
                qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                    -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                    -drive file="$img",if=none,format=raw,id=hd0 \
                    -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
            fi
            pid=$!; i=0
            while [ "$i" -lt 180 ]; do
                grep -aqF "$2" "$log" 2>/dev/null && break
                grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
                kill -0 "$pid" 2>/dev/null || break
                i=$((i + 1)); sleep 0.5
            done
            # Past the marker the line that follows it (the durable record) may
            # still be in flight: give it the time a flush takes.
            sleep 2
            kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        }
        cfgauth_boot 1 "[CFG] config counter floor raised 0 -> 2"
        if ! grep -aqF "[CFG] config counter floor raised 0 -> 2" "$log"; then why="boot 1: the counter-2 file did not load and raise the floor"
        elif grep -aqF "E-STOP LATCHED" "$log"; then why="boot 1 latched"
        elif [ "$(python3 tools/device_provision.py --show "$img" | awk '{print $NF}')" != 2 ]; then why="boot 1: the image's floor is not 2"
        fi
        if [ -z "$why" ]; then
            mcopy -o -i "$img" "$dir/old.sig" ::CONFIG.SIG 2>/dev/null
            cfgauth_boot 2 "config-authority stop recorded"
            if ! grep -aqF "[CFG] REPLAY: CONFIG.SIG counter 1 is below the floor 2" "$log"; then why="boot 2: the counter-1 file was not refused as a replay"
            elif ! grep -aqF "config authority lost (CONFIG.SIG counter below the floor (replay))" "$log" \
                 || ! grep -aqF "estop_is_active=1" "$log"; then why="boot 2: the replay did not latch the e-stop"
            elif ! grep -aqF "config-authority stop recorded" "$log"; then why="boot 2: the stop was not recorded"
            elif grep -aqF "CONFIG.SIG v2 verified" "$log"; then why="boot 2 loaded the replayed file"
            elif [ "$(python3 tools/device_provision.py --show "$img" | awk '{print $NF}')" != 2 ]; then why="boot 2 moved the floor"
            fi
        fi
        if [ -z "$why" ]; then
            mdel -i "$img" ::CONFIG.SIG 2>/dev/null
            cfgauth_boot 3 "config-authority stop recorded"
            if ! grep -aqF "config authority lost (CONFIG.SIG absent)" "$log" \
               || ! grep -aqF "estop_is_active=1" "$log"; then why="boot 3: a deleted CONFIG.SIG did not latch the e-stop"
            fi
        fi
        rm -f "$kimg"
        if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then why="${why:-crash}; kernel crashed"; fi
        if [ -z "$why" ]; then ok; rm -rf "$img" "$dir" "$CI_LOG_DIR/${slug}"-boot*.log; return; fi
        bad; echo "      $why"
        grep -a "\[CFG\]" "$log" | tr -d '\r' | sed -n '1,6p' | sed 's/^/      /'
        echo "      logs kept: $CI_LOG_DIR/${slug}-boot*.log"
    }
    par_row config_authority_row "config: replay refused, lost sig latches"         rv
    par_row config_authority_row "aarch64 config: replay refused, lost sig latches" arm

    # ── topology: the signed capability topology from the volume (wave 15) ──
    #
    # Kconfig TOPOLOGY_SOURCE (QEMU default SIGNED_OR_BUILTIN): the kernel
    # installs /fat/CAPS.TOM + CAPS.SIG and /fat/SCHED.TOM when CAPS.SIG
    # verifies against the embedded key, CAPS.TOM's binding names this device,
    # a counter no lower than the floor (reserved tail sector 3) and SCHED.TOM's
    # SHA-256, and the set parses and is admitted. `make topo-volume` writes the
    # gate kernel's built-in topology onto an image, bound to the image's own
    # device id, counter TOPO_COUNTER (TEST key: these are QEMU fixtures).
    #
    # Shared prep for every row below: copies of the plain disk, each bound by
    # `topo-volume`, and the boot helper. A boot's verdict data: the log, the
    # SAFETY_TOPO_SOURCE (0x1A) records left on the volume ("<n> <action>
    # <detail>" of the last: header 16 B, 32-byte records, kind at 8 (0x03),
    # code at 12, action at 13, detail u32 LE at 16, `LogRecord::encode`), and
    # the topology counter floor read back off the image.
    topo_prep() { # <isa> <out image> [make vars...]: base disk + a bound set
        local isa="$1" out="$2" base tisa; shift 2
        base=$AZOS_OUT/build/disk.img; tisa=riscv64
        [ "$isa" = arm ] && { base=$AZOS_OUT/build/disk-aarch64.img; tisa=aarch64; }
        par_shared "make topo-volume" || return 1
        make_disk "$base"
        cp "$base" "$out"
        make topo-volume TOPO_IMAGE="$out" TOPO_ISA="$tisa" TOPO_KCONFIG_RISCV64="$PRIMARY_CONFIG" \
            TOPO_KCONFIG_AARCH64="$AARCH64_CONFIG" "$@" >/dev/null 2>&1
    }
    topo_boot() { # <isa> <kernel> <image> <log>: boot to the topology install, then read the volume
        local isa="$1" k="$2" img="$3" pid i
        log="$4"; rm -f "$log"
        if [ "$isa" = rv ]; then
            par_ready
            "$QEMU" -machine virt -nographic -bios default -kernel "$k" -smp 2 \
                -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        else
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                -kernel "$k" -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        fi
        pid=$!; i=0
        while [ "$i" -lt 240 ]; do
            grep -aqF "[TOPO] Topology installed:" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled|\[TOPO\] HALTED" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 2   # margin past the marker (records and the floor are flushed before it)
        kill "$pid" 2>/dev/null; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid"; wait "$pid" 2>/dev/null
        # This boot's recorder file: each boot opens the next LOG/LOGnnnnn.BIN
        # (the replay mode boots one volume twice).
        rec="0 0 0"
        lastlog="$(mdir -b -i "$img" ::LOG 2>/dev/null | grep -aiE 'LOG[0-9]+\.BIN$' | sort | sed -n '$p')"
        if [ -n "$lastlog" ] && mcopy -n -i "$img" "$lastlog" "$img.rec" 2>/dev/null; then
            rec="$(python3 - "$img.rec" <<'PY'
import struct, sys
b = open(sys.argv[1], 'rb').read()
n, last = 0, (0, 0)
for off in range(16, len(b) - 31, 32):
    r = b[off:off + 32]
    if r[8] == 0x03 and r[12] == 0x1A:
        n += 1; last = (r[13], struct.unpack_from('<I', r, 16)[0])
print(n, last[0], '%#010x' % last[1])
PY
)"
            rm -f "$img.rec"
        fi
        floor="$(python3 tools/device_provision.py --show --topo-floor "$img" | sed -n 's/^topo-floor //p')"
        installed="$(grep -a "\[TOPO\] Topology installed:" "$log" | sed -n '1s/.*installed: \([0-9]*\) classes, \([0-9]*\) tasks.*/\1 \2/p')"
        crashed=""
        grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" && crashed=1
        return 0
    }
    topo_kernel() { # <isa> <extra features> <out kernel>
        if [ "$1" = rv ]; then
            kbuild "qemu$2" >/dev/null || return 1
            cp "$KERNEL" "$3"
        else
            a64_kbuild "qemu$2" >/dev/null || return 1
            cp "$A64_IMG" "$3"
        fi
    }

    # Signed set, then a tampered one. Two boots of copies of one bound image:
    #   1. as bound: "[TOPO] source: signed", installed "from the signed
    #      files", the floor raised 0 -> 1, no SAFETY_TOPO_SOURCE record;
    #   2. CAPS.TOM with one row's `priority = 16` made 17 (still parses, still
    #      admitted, binding intact: only the signature can refuse it):
    #      REFUSED with Signature(Caps, InvalidSignature), installed "from the
    #      built-in topology", exactly one record, action 2 (fallback invalid),
    #      detail 0x31000000 (signature step, CAPS file).
    # Boot 1's class and task counts must equal boot 2's: the signed files
    # carry the built-in topology.
    # Canary: `topo-verify-skip-canary` installs the tampered file: red.
    toposign_row() { # <label> <isa: rv|arm> <extra features, comma-led or empty> <expect: PASS|FAIL>
        local label="$1" isa="$2" extra="$3" expect="$4"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug kimg dir log why="" rec floor installed crashed counts1="" lastlog
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        kimg="$CI_LOG_DIR/${slug}-kernel"; dir="$CI_LOG_DIR/${slug}.d"
        rm -rf "${dir:?}"; mkdir -p "$dir"
        topo_kernel "$isa" "$extra" "$kimg" || { bad; echo "      $isa kernel (qemu$extra) did not build"; return; }
        if ! topo_prep "$isa" "$dir/bound.img"; then bad; echo "      make topo-volume failed"; rm -f "$kimg"; return; fi
        mcopy -n -i "$dir/bound.img" ::CAPS.TOM "$dir/CAPS.TOM" 2>/dev/null
        sed 's/^priority = 16$/priority = 17/' "$dir/CAPS.TOM" >"$dir/CAPS.TAMPERED"
        if cmp -s "$dir/CAPS.TOM" "$dir/CAPS.TAMPERED"; then
            bad; echo "      the bound CAPS.TOM has no 'priority = 16' row to tamper with"; rm -f "$kimg"; return
        fi
        cp "$dir/bound.img" "$dir/boot1.img"
        topo_boot "$isa" "$kimg" "$dir/boot1.img" "$CI_LOG_DIR/${slug}-boot1.log"
        counts1="$installed"
        if [ -n "$crashed" ]; then why="boot 1: kernel crashed"
        elif ! grep -aqF "[TOPO] source: signed /fat/CAPS.TOM" "$log"; then why="boot 1: the signed set was not installed"
        elif ! grep -aqF "tasks, from the signed files in" "$log"; then why="boot 1: not installed from the signed files"
        elif [ "$floor" != 1 ]; then why="boot 1: the topology floor on the image is '${floor:-absent}', not 1"
        elif [ "${rec%% *}" != 0 ]; then why="boot 1: SAFETY_TOPO_SOURCE records on the volume ($rec)"
        fi
        if [ -z "$why" ]; then
            cp "$dir/bound.img" "$dir/boot2.img"
            mcopy -o -i "$dir/boot2.img" "$dir/CAPS.TAMPERED" ::CAPS.TOM
            topo_boot "$isa" "$kimg" "$dir/boot2.img" "$CI_LOG_DIR/${slug}-boot2.log"
            if [ -n "$crashed" ]; then why="boot 2: kernel crashed"
            elif ! grep -aqF "[TOPO] REFUSED: the signed topology on the volume: Signature(Caps, InvalidSignature)" "$log"; then
                why="boot 2: the tampered CAPS.TOM was not refused by its signature"
            elif ! grep -aqF "tasks, from the built-in topology in" "$log"; then why="boot 2: the built-in topology was not installed"
            elif [ "$rec" != "1 2 0x31000000" ]; then why="boot 2: SAFETY_TOPO_SOURCE records on the volume are '$rec', not one fallback-invalid (2) with detail 0x31000000"
            elif [ -z "$counts1" ] || [ "$counts1" != "$installed" ]; then
                why="the signed set installed '$counts1' classes/tasks, the built-in topology '$installed'"
            fi
        fi
        rm -f "$kimg"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then ok; echo "      canary red as it must: $why"; rm -rf "${dir:?}"; rm -f "${CI_LOG_DIR:?}/${slug:?}"-boot*.log
            else bad; echo "      the canary kernel refused the tampered file: the row does not discriminate"
                 echo "      logs kept: $CI_LOG_DIR/${slug}-boot*.log"; fi
            return
        fi
        if [ -z "$why" ]; then
            ok; echo "      signed and built-in: ${counts1% *} classes, ${counts1#* } tasks; floor 0 -> 1; tampered refused, record $rec"
            rm -rf "${dir:?}"; rm -f "${CI_LOG_DIR:?}/${slug:?}"-boot*.log; return
        fi
        bad; echo "      $why"
        grep -a "\[TOPO\]" "$log" | tr -d '\r' | sed -n '1,6p' | sed 's/^/      /'
        echo "      logs kept: $CI_LOG_DIR/${slug}-boot*.log"
    }
    par_row toposign_row "topology: signed set, tampered refused"         rv  ""                         PASS
    par_row toposign_row "topology: tampered, verify skipped (canary)"    rv  ",topo-verify-skip-canary" FAIL
    par_row toposign_row "aarch64 topology: signed set, tampered refused" arm ""                         PASS
    par_row toposign_row "aarch64 topology: verify skipped (canary)"      arm ",topo-verify-skip-canary" FAIL

    # ── topology: anti-replay — the binding in the signed CAPS.TOM (wave 15) ──
    #
    # One signature covers both files; CAPS.TOM binds SCHED.TOM's hash, the
    # device id and a counter. Each mode boots files that are validly signed
    # and refused for one binding reason only, and reads the reason back from
    # the console AND from the SAFETY_TOPO_SOURCE record's detail:
    #   replay: counter 2 boots and raises the floor 0 -> 2 (read back off the
    #           image); then the counter-1 CAPS.TOM + CAPS.SIG (validly signed
    #           for this device) on the same volume: REFUSED Replay { counter:
    #           1, floor: 2 }, detail 0x91000001, the floor still 2;
    #   sched:  SCHED.TOM swapped for a well-formed one with one class's
    #           time slice changed: REFUSED SchedHashMismatch, 0x72000000;
    #   device: a set bound to another device id: REFUSED WrongDevice,
    #           0x81000000.
    # Every refusal falls back to the built-in topology with one record,
    # action 2. Canaries: `topo-replay-canary`, `topo-sched-hash-canary`,
    # `topo-device-canary` each skip the one check: the file installs, red.
    toposign_bind_row() { # <label> <isa: rv|arm> <mode: replay|sched|device> <extra features> <expect: PASS|FAIL>
        local label="$1" isa="$2" mode="$3" extra="$4" expect="$5"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug kimg dir log why="" rec floor installed crashed want lastlog
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        kimg="$CI_LOG_DIR/${slug}-kernel"; dir="$CI_LOG_DIR/${slug}.d"
        rm -rf "${dir:?}"; mkdir -p "$dir"
        topo_kernel "$isa" "$extra" "$kimg" || { bad; echo "      $isa kernel (qemu$extra) did not build"; return; }
        case "$mode" in
        replay)
            want="Replay { counter: 1, floor: 2 }|1 2 0x91000001"
            # The counter-1 pair for this image's device, then the image bound at 2.
            if ! topo_prep "$isa" "$dir/old.img" TOPO_COUNTER=1; then bad; echo "      topo-volume (counter 1) failed"; return; fi
            mcopy -n -i "$dir/old.img" ::CAPS.TOM "$dir/CAPS.OLD" && mcopy -n -i "$dir/old.img" ::CAPS.SIG "$dir/SIG.OLD"
            cp "$dir/old.img" "$dir/vol.img"
            if ! make topo-volume TOPO_IMAGE="$dir/vol.img" TOPO_ISA="$([ "$isa" = arm ] && echo aarch64 || echo riscv64)" \
                    TOPO_KCONFIG_RISCV64="$PRIMARY_CONFIG" TOPO_KCONFIG_AARCH64="$AARCH64_CONFIG" TOPO_COUNTER=2 >/dev/null 2>&1; then
                bad; echo "      topo-volume (counter 2) failed"; return
            fi
            topo_boot "$isa" "$kimg" "$dir/vol.img" "$CI_LOG_DIR/${slug}-boot1.log"
            if [ -n "$crashed" ]; then why="boot 1: kernel crashed"
            elif ! grep -aqF "tasks, from the signed files in" "$log"; then why="boot 1: the counter-2 set was not installed"
            elif ! grep -aqF "[TOPO] topology counter floor raised 0 -> 2" "$log" || [ "$floor" != 2 ]; then
                why="boot 1: the floor was not raised 0 -> 2 (image: '${floor:-absent}')"
            fi
            if [ -z "$why" ]; then
                mcopy -o -i "$dir/vol.img" "$dir/CAPS.OLD" ::CAPS.TOM && mcopy -o -i "$dir/vol.img" "$dir/SIG.OLD" ::CAPS.SIG
                topo_boot "$isa" "$kimg" "$dir/vol.img" "$CI_LOG_DIR/${slug}-boot2.log"
                [ "$floor" = 2 ] || why="boot 2 moved the floor to '${floor:-absent}'"
            fi ;;
        sched)
            want="SchedHashMismatch|1 2 0x72000000"
            if ! topo_prep "$isa" "$dir/vol.img"; then bad; echo "      make topo-volume failed"; return; fi
            mcopy -n -i "$dir/vol.img" ::SCHED.TOM "$dir/SCHED.TOM"
            awk '!d && /^time_slice_ms = /{sub(/= /, "= 1"); d = 1} {print}' "$dir/SCHED.TOM" >"$dir/SCHED.SWAP"
            if cmp -s "$dir/SCHED.TOM" "$dir/SCHED.SWAP"; then bad; echo "      could not change SCHED.TOM"; return; fi
            mcopy -o -i "$dir/vol.img" "$dir/SCHED.SWAP" ::SCHED.TOM
            topo_boot "$isa" "$kimg" "$dir/vol.img" "$CI_LOG_DIR/${slug}-boot2.log" ;;
        device)
            want="WrongDevice|1 2 0x81000000"
            if ! topo_prep "$isa" "$dir/vol.img" TOPO_DEVICE=0e0e0e0e0e0e0e0e0e0e0e0e0e0e0e0e; then
                bad; echo "      make topo-volume failed"; return
            fi
            topo_boot "$isa" "$kimg" "$dir/vol.img" "$CI_LOG_DIR/${slug}-boot2.log" ;;
        esac
        if [ -z "$why" ]; then
            if [ -n "$crashed" ]; then why="kernel crashed"
            elif ! grep -aqF "[TOPO] REFUSED: the signed topology on the volume: ${want%%|*}" "$log"; then
                why="not refused as ${want%%|*}"
            elif ! grep -aqF "tasks, from the built-in topology in" "$log"; then why="the built-in topology was not installed"
            elif [ "$rec" != "${want#*|}" ]; then why="SAFETY_TOPO_SOURCE records on the volume are '$rec', not '${want#*|}'"
            fi
        fi
        rm -f "$kimg"
        if [ "$expect" = FAIL ]; then
            if [ -n "$why" ]; then ok; echo "      canary red as it must: $why"; rm -rf "${dir:?}"; rm -f "${CI_LOG_DIR:?}/${slug:?}"-boot*.log
            else bad; echo "      the canary kernel refused the file: the row does not discriminate"
                 echo "      logs kept: $CI_LOG_DIR/${slug}-boot*.log"; fi
            return
        fi
        if [ -z "$why" ]; then
            ok; echo "      refused as ${want%%|*}, record ${want#*|}"
            rm -rf "${dir:?}"; rm -f "${CI_LOG_DIR:?}/${slug:?}"-boot*.log; return
        fi
        bad; echo "      $why"
        grep -a "\[TOPO\]" "$log" | tr -d '\r' | sed -n '1,6p' | sed 's/^/      /'
        echo "      logs kept: $CI_LOG_DIR/${slug}-boot*.log"
    }
    par_row toposign_bind_row "topology: replay refused"                rv  replay ""                        PASS
    par_row toposign_bind_row "topology: replay, floor skipped (canary)" rv replay ",topo-replay-canary"     FAIL
    par_row toposign_bind_row "topology: swapped SCHED.TOM refused"     rv  sched  ""                        PASS
    par_row toposign_bind_row "topology: SCHED hash skipped (canary)"   rv  sched  ",topo-sched-hash-canary" FAIL
    par_row toposign_bind_row "topology: wrong device refused"          rv  device ""                        PASS
    par_row toposign_bind_row "topology: device skipped (canary)"       rv  device ",topo-device-canary"     FAIL
    par_row toposign_bind_row "aarch64 topology: replay refused"        arm replay ""                        PASS
    par_row toposign_bind_row "aarch64 topology: replay (canary)"       arm replay ",topo-replay-canary"     FAIL
    par_row toposign_bind_row "aarch64 topology: swapped SCHED.TOM"     arm sched  ""                        PASS
    par_row toposign_bind_row "aarch64 topology: SCHED hash (canary)"   arm sched  ",topo-sched-hash-canary" FAIL
    par_row toposign_bind_row "aarch64 topology: wrong device"          arm device ""                        PASS
    par_row toposign_bind_row "aarch64 topology: device (canary)"       arm device ",topo-device-canary"     FAIL

    # ── topology: SIGNED_REQUIRED halts without the set (wave 15) ──────────
    #
    # A kernel built with CONFIG_TOPOLOGY_SOURCE_SIGNED_REQUIRED boots the
    # plain disk (no CAPS.TOM/SCHED.TOM): the REFUSED line naming the policy,
    # one durable SAFETY_TOPO_SOURCE record with action 3 (halt missing), the
    # HALTED line as the last line of the boot, and no topology installed
    # (no task, no scheduler: nothing after the halt). Its own .config, as
    # rt7_row builds the panic policies.
    toposign_required_row() { # <label> <isa: rv|arm>
        local label="$1" isa="$2"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug defc base cfg kimg img log why="" pid i rec last
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        defc="$GATE_DEFC_RV"; base=$AZOS_OUT/build/disk.img
        [ "$isa" = arm ] && { defc="$GATE_DEFC_A64"; base=$AZOS_OUT/build/disk-aarch64.img; }
        cfg="$(cd "$CI_LOG_DIR" && pwd)/${slug}.config"
        kimg="$CI_LOG_DIR/${slug}-kernel"; img="$CI_LOG_DIR/${slug}.img"; log="$CI_LOG_DIR/${slug}.log"
        rm -f "$log" "$img" "$kimg"
        cp "${REPO_ROOT}/config/defconfigs/${defc}.config" "$cfg"
        printf '# CONFIG_TOPOLOGY_SOURCE_BUILTIN is not set\n# CONFIG_TOPOLOGY_SOURCE_SIGNED_OR_BUILTIN is not set\nCONFIG_TOPOLOGY_SOURCE_SIGNED_REQUIRED=y\n' >>"$cfg"
        (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1) \
            || { bad; echo "      olddefconfig failed on $cfg"; return; }
        grep -q '^CONFIG_TOPOLOGY_SOURCE_SIGNED_REQUIRED=y$' "$cfg" \
            || { bad; echo "      $cfg does not carry CONFIG_TOPOLOGY_SOURCE_SIGNED_REQUIRED=y"; return; }
        if [ "$isa" = rv ]; then
            KCONFIG_CONFIG="$cfg" kbuild "qemu" >/dev/null || { bad; echo "      riscv64 SIGNED_REQUIRED kernel did not build"; return; }
            cp "$KERNEL" "$kimg"
        else
            AARCH64_CONFIG="$cfg" a64_kbuild "qemu" >/dev/null || { bad; echo "      aarch64 SIGNED_REQUIRED kernel did not build"; return; }
            cp "$A64_IMG" "$kimg"
        fi
        # From scratch: the record is read back off LOG00000.BIN, and an
        # image an earlier boot wrote (`make` calls it up to date) holds that
        # session's file there (`rt_watchdog_record_row`, wave 15).
        rm -f "$base"; make_disk "$base"
        cp "$base" "$img"
        if [ "$isa" = rv ]; then
            par_ready
            "$QEMU" -machine virt -nographic -bios default -kernel "$kimg" -smp 2 \
                -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        else
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        fi
        pid=$!; i=0
        while [ "$i" -lt 240 ]; do
            grep -aqF "[TOPO] HALTED" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled|\[TOPO\] Topology installed" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 4   # a boot that went on past the halt would print in this time
        kill "$pid" 2>/dev/null; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid"; wait "$pid" 2>/dev/null
        rm -f "$kimg"
        rec="0 0"
        if mcopy -n -i "$img" ::LOG/LOG00000.BIN "$img.rec" 2>/dev/null; then
            rec="$(python3 - "$img.rec" <<'PY'
import sys
b = open(sys.argv[1], 'rb').read()
acts = [b[o + 13] for o in range(16, len(b) - 31, 32) if b[o + 8] == 0x03 and b[o + 12] == 0x1A]
print(len(acts), acts[-1] if acts else 0)
PY
)"
        fi
        rm -f "$img" "$img.rec"
        last="$(tr -d '\r' <"$log" | grep -av '^qemu-system-\|^[[:space:]]*$' | sed -n '$p')"
        if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log"; then why="kernel crashed"
        elif ! grep -aqF "[TOPO] REFUSED: no signed topology on the volume and TOPOLOGY_SOURCE_SIGNED_REQUIRED" "$log"; then why="no refusal naming SIGNED_REQUIRED"
        elif grep -aqF "[TOPO] Topology installed" "$log"; then why="a topology was installed"
        elif [ "$rec" != "1 3" ]; then why="SAFETY_TOPO_SOURCE records on the volume are '$rec', not one halt-missing (3)"
        elif [ "$last" != "[TOPO] HALTED: no capability topology installed — the boot stops here" ]; then
            why="the boot went on past the halt; last line: $last"
        fi
        if [ -z "$why" ]; then ok; echo "      halted before any task, record action 3"; rm -f "$log" "$cfg"; return; fi
        bad; echo "      $why"
        grep -a "\[TOPO\]" "$log" | tr -d '\r' | sed -n '1,4p' | sed 's/^/      /'
        echo "      log kept: $log"
    }
    par_row toposign_required_row "topology: SIGNED_REQUIRED halts"         rv
    par_row toposign_required_row "aarch64 topology: SIGNED_REQUIRED halts" arm

    # ── topology: the DMA pool is reserved at admission, not estimated ──
    #
    # One `admit` (kernel/src/boot/topology.rs) serves the signed candidate
    # and the built-in topology, and RESERVES the DMA pool (a contiguous run,
    # `pmm::reserve_dma_pool`) instead of comparing it with the free total.
    # `dma-contig-canary` takes one free frame in every pool-length before the
    # boot's first admission reserves its pool, and gives them back when it
    # returns: the total still covers the pool and every row's budget, no free
    # run is as long as the pool.
    #   builtin — no signed set on the volume: the built-in topology's
    #             admission halts with "Memory admission REFUSED: DmaPool",
    #             its `free` at least its `need`;
    #   signed  — a bound signed set: the candidate is refused with
    #             Admission(Memory(DmaPool ..)) before it is published, one
    #             fallback-invalid record, and the built-in topology (the
    #             second admission, RAM whole again) installs with its pool.
    # Canary bucket: an admission that only compared the pool with the free
    # total (the old candidate estimate) admits both, so the built-in boot
    # prints the admitted line and the signed boot installs the signed files.
    dma_contig_row() { # <label> <isa: rv|arm> <mode: builtin|signed>
        local label="$1" isa="$2" mode="$3"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug kimg img why="" base ref need free rec floor installed crashed lastlog
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        kimg="$CI_LOG_DIR/${slug}-kernel"; img="$CI_LOG_DIR/${slug}.img"
        topo_kernel "$isa" ",dma-contig-canary" "$kimg" || { bad; echo "      $isa kernel (qemu,dma-contig-canary) did not build"; return; }
        if [ "$mode" = signed ]; then
            if ! topo_prep "$isa" "$img"; then bad; echo "      make topo-volume failed"; rm -f "$kimg"; return; fi
        else
            base=$AZOS_OUT/build/disk.img; [ "$isa" = arm ] && base=$AZOS_OUT/build/disk-aarch64.img
            make_disk "$base"; cp "$base" "$img"
        fi
        if [ "$mode" = signed ]; then
            topo_boot "$isa" "$kimg" "$img" "$CI_LOG_DIR/${slug}.log"
        else
            # Not `topo_boot`: it stops at "Topology installed", which the
            # built-in topology prints BEFORE its admission. Wait for the halt.
            log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"; crashed=""
            par_ready
            if [ "$isa" = rv ]; then
                "$QEMU" -machine virt -nographic -bios default -kernel "$kimg" -smp 2 \
                    -global virtio-mmio.force-legacy=false \
                    -drive file="$img",if=none,format=raw,id=hd0 \
                    -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
            else
                qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                    -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                    -drive file="$img",if=none,format=raw,id=hd0 \
                    -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
            fi
            local pid=$! i=0
            while [ "$i" -lt 120 ]; do
                grep -aqE "Memory admission REFUSED: .* — halting|TOPO\] Memory admission: [0-9]" "$log" 2>/dev/null && break
                grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
                kill -0 "$pid" 2>/dev/null || break
                i=$((i + 1)); sleep 0.5
            done
            kill "$pid" 2>/dev/null; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid"; wait "$pid" 2>/dev/null
            grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" && crashed=1
        fi
        rm -f "$kimg" "$img"
        ref="$(grep -a "Memory admission REFUSED: DmaPool\|Admission(Memory(DmaPool" "$log" | sed -n '1s/.*DmaPool { need: \([0-9]*\), free: \([0-9]*\) }.*/\1 \2/p')"
        need="${ref% *}"; free="${ref#* }"
        if [ -n "$crashed" ]; then why="kernel crashed"
        elif ! grep -aq "\[CANARY\] dma-contig: [1-9][0-9]* of [0-9]* free frames taken" "$log"; then why="the canary did not fragment RAM"
        elif [ -z "$ref" ]; then why="no DmaPool refusal"
        elif [ "$free" -lt "$need" ]; then why="refused with free $free < need $need: not a contiguity refusal"
        elif [ "$mode" = builtin ]; then
            if ! grep -aqF "[TOPO] Memory admission REFUSED: DmaPool {" "$log"; then why="the built-in topology was not refused"
            elif grep -aq "TOPO\] Memory admission: [0-9]" "$log"; then why="the built-in topology was admitted"
            fi
        elif ! grep -aqF "[TOPO] REFUSED: the signed topology on the volume: Admission(Memory(DmaPool {" "$log"; then why="the candidate was not refused before it was published"
        elif ! grep -aqF "tasks, from the built-in topology in" "$log"; then why="the built-in topology was not installed"
        elif ! grep -aq "MM\] DMA pool: [0-9]* KiB reserved" "$log"; then why="the built-in topology has no DMA pool"
        elif [ "${rec% *}" != "1 2" ]; then why="SAFETY_TOPO_SOURCE records '$rec', not one fallback-invalid (2)"
        fi
        if [ -z "$why" ]; then
            ok; echo "      refused: need $need, free $free pages; $mode"; rm -f "$log"; return
        fi
        bad; echo "      $why"
        grep -a "\[TOPO\]\|\[CANARY\]" "$log" | tr -d '\r' | sed -n '1,6p' | sed 's/^/      /'
        echo "      log kept: $log"
    }
    par_row dma_contig_row "topology: DMA pool needs a run, built-in"         rv  builtin
    par_row dma_contig_row "topology: DMA pool needs a run, signed"           rv  signed
    par_row dma_contig_row "aarch64 topology: DMA pool needs a run, built-in" arm builtin
    par_row dma_contig_row "aarch64 topology: DMA pool needs a run, signed"   arm signed
    kbuild "qemu"
    a64_kbuild "qemu" >/dev/null 2>&1 || true

    # The motor envelope refuses a command above the per-robot-type
    # cap at the real MotorCmd -> PWM chokepoint. The marker carries the exact
    # numbers so a scenario that merely reached the code cannot pass: the ask
    # (100,-100) and what was applied (80,-80) must both appear.
    kbuild "qemu,envelope-smoke"
    # Two markers, because the thesis sentence has two halves and the scenario
    # used to prove only one. "refused" is the clamp; RECORDED is the kernel
    # reading its own flight-recorder file back off the disk and finding the
    # refusal in it. A run that clamps and does not record now fails, which is
    # the point: a safety intervention nobody can audit afterwards may as well
    # not have been made.
    rm -f $AZOS_OUT/build/disk-envelope.img
    make_disk $AZOS_OUT/build/disk-envelope.img
    par_row qemu_run "safety: envelope refuses" "ENVELOPE] refused: asked (100,-100) applied (80,-80)" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-envelope.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    # Fresh image again: the run above WROTE its log to this FAT32, so reusing
    # the image would let "RECORDED" pass on the previous run's leftovers
    # instead of on anything this boot did.
    rm -f $AZOS_OUT/build/disk-envelope.img
    make_disk $AZOS_OUT/build/disk-envelope.img
    par_row qemu_run "safety: envelope RECORDS" "ENVSMOKE] RECORDED" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-envelope.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # An e-stop is the event most likely to be followed by the reset that would
    # erase an unflushed record, so it must reach the disk synchronously rather
    # than on the watchdog's ~500 ms cadence. Fresh image again for the same
    # reason as above.
    rm -f $AZOS_OUT/build/disk-envelope.img
    make_disk $AZOS_OUT/build/disk-envelope.img
    par_row qemu_run "safety: estop record is durable" "ENVSMOKE] ESTOP DURABLE" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-envelope.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # ── The brain lies (scenario 2) ────────────────────
    #
    # A host-side peer sends frames that are structurally valid — right magic,
    # right length field, correct CRC — and semantically wrong. That is the
    # case with no coverage anywhere: a bit-garbled frame is dropped by
    # `parse_packet`'s CRC check before it reaches the dispatch, so it tests
    # the parser; these reach the dispatch and test the safety layer. The design
    # review named this gap explicitly: "the fail-closed unwrap_or(CONTAINED) on a
    # truncated packet is the single most safety-relevant line in the design
    # and has no runtime coverage at all."
    #
    # Its own function rather than `qemu_run`, for the negative half: `qemu_run`
    # deletes the log on success, and the assertion that matters here is that a
    # string is ABSENT. Proving the kernel clamped to CONTAINED says nothing
    # about the sibling handler that used to do the opposite on the same input.
    #
    # The peer is `tools/fake_brain.py` on the host; QEMU's SLIRP maps
    # 10.0.2.2 to it, and the image's CONFIG.INI dials 10.0.2.2 on the port
    # the peer was given (`run_brain_peer_boot`; 9000 is every other guest's). Its
    # framing is pinned against the kernel's by the golden vectors in
    # `tests/host/behavior-tests` — without those, a drifted CRC would make every
    # frame get dropped at the parser and the log would look exactly like a
    # kernel that ignored them.
    #
    # This was also the FIRST gate scenario to boot a disk image and a NIC at
    # the same time, which is the configuration a real robot runs in and the
    # one nothing covered: until then every networked scenario booted diskless
    # (no CONFIG.INI, so no autorun) and every disk-backed scenario booted
    # without a NIC. Writing it found that a ring-3 autorun created inside the real-time
    # band starved `net-poll` on its hart so completely that the RX ring was
    # never drained — no ARP reply learned, no SYN ever sent, brain link
    # permanently down. Hence the `[NET-POLL]` assertion below: it is cheap and
    # it fails first, before the frame assertions, if that returns.
    #
    # What it does NOT assert: the 4th frame's `SAFETY_UNKNOWN_PKT` record.
    # `log_safety_violation` writes the flight recorder, not the console, so
    # reading it back needs a kernel-side smoke feature the way
    # `envelope-smoke` does. The frame is still sent, so the dispatch's `else`
    # arm is exercised — it is the RECORD that is unasserted, not the path.
    # Start the lying peer, boot a disk+NIC kernel against it, wait for the
    # peer's verdict, and tear both down. Extracted 2026-09-08 so the record
    # scenario below does not become a second copy of the boot sequence — the
    # part with the race in it, which is the part worth having once.
    #
    #   run_brain_peer_boot <kernel-log> <peer-log> <image> <settle-s> [peer-args...]
    #
    # The peer's arguments are the last parameter because the two callers need
    # different peers: the lying script sends four refusable frames and leaves,
    # while `--serve` reads SensorPackets and answers with ActuatorCmd frames.
    # Same boot sequence, same race, one copy.
    run_brain_peer_boot() {
        local log="$1" blog="$2" image="$3" settle="$4"; shift 4
        local peer_args="${*:---wait 90}"
        # The kernel's brain link is always a Noise session, so every peer but
        # `--reconnect` (which only resets connections) runs the brain side of
        # it with AzOSRobotBrain's secure_channel (see AZOS_BRAIN_DIR above)
        # and needs the link key the image carries. Without the sibling repo
        # the peer exits at import after it has already printed its port, so
        # the boot would run against nobody: fail here, by name.
        case " $peer_args " in *" --reconnect "*) ;; *)
            local brain_dir="${AZOS_BRAIN_DIR:-../AzOSRobotBrain}"
            if [ ! -f "$brain_dir/secure_channel.py" ]; then
                echo "[fake-brain] FAIL no-robot — AzOSRobotBrain not found at $brain_dir (set AZOS_BRAIN_DIR)" >>"$blog"
                echo "      AzOSRobotBrain not found at $brain_dir: the peer cannot start (set AZOS_BRAIN_DIR)"
                return 1
            fi
            case " $peer_args " in *" --link-key "*) ;; *) peer_args="$peer_args --image $image" ;; esac ;;
        esac
        # A port of the peer's own, never 9000 (see `peer_port_image`): bound
        # first, read back, written into the image, and only then the boot.
        # `--port 0` goes last, so it is the one argparse keeps. The image
        # is rewritten with the peer already up, which is safe: every peer
        # mode reads its key files before it binds.
        # shellcheck disable=SC2086
        python3 tools/fake_brain.py $peer_args --port 0 >"$blog" 2>&1 &
        local bpid=$!
        local k=0 port=""
        while [ "$k" -lt 60 ]; do
            port=$(sed -n 's/^\[fake-brain\] listening on [0-9.]*:\([0-9][0-9]*\)$/\1/p' "$blog" 2>/dev/null | sed -n 1p)
            [ -n "$port" ] && break
            kill -0 "$bpid" 2>/dev/null || break
            k=$((k + 1)); sleep 0.25
        done
        if [ -z "$port" ] || ! peer_port_image "$image" "$port"; then
            # Every caller checks this line first and fails naming it.
            echo "[fake-brain] FAIL no-robot — the row could not point $image at the peer's port (${port:-none})" >>"$blog"
            kill "$bpid" 2>/dev/null; wait "$bpid" 2>/dev/null
            return 1
        fi
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$image",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 \
            -netdev user,id=net0 -device virtio-net-device,netdev=net0 \
            ${PEER_BOOT_QEMU_EXTRA:-} \
            >"$log" 2>&1 &
        local qpid=$!

        # Wait on the PEER's verdict, not on the kernel's first log line.
        # Waiting for "semantic level set to 3" is wrong and silently
        # under-tests: that line appears after frame 1 of 4, so the loop broke
        # and killed QEMU before the DEGRADE and unknown-type frames were ever
        # sent. It passed standalone (the peer had already finished) and failed
        # in the suite (a colder cache made the kernel slower than the peer) —
        # the timing tells you nothing about the kernel, only about which
        # process won a race the test should not have had.
        local i=0
        while [ "$i" -lt 240 ]; do
            # Either peer's own verdict: the lying script's "sent 4 frames", or
            # the serving peer's second ActuatorCmd (its script is two long, so
            # that is the point where both branches have been exercised).
            grep -aq "sent 4 frames\|ActuatorCmd 'reverse'\|phase 3 done\|reconnect done\|FAIL no-robot" "$blog" 2>/dev/null && break
            # The kill-switch scenario's peer never stops driving, so its
            # verdict is the kernel's: the smoke task says when it is done.
            grep -aq "ESTOPGPIO] DONE" "$log" 2>/dev/null && break
            # A ring-3 client that refused to run has nothing more to say.
            grep -aq "brain_client\] FATAL" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        # Settle: the last frame is sent, not yet dispatched. The peer holds
        # the connection open 2 s after its last write for exactly this, but
        # the kernel's behaviour loop runs at 10 Hz, so give it its own margin
        # rather than racing the peer's teardown. A scenario whose verdict is
        # printed by the kernel after the peer is done sets PEER_BOOT_DONE_RE:
        # the settle is then a ceiling that ends at that line, not a guess.
        local j=0
        while [ "$j" -lt $((settle * 2)) ]; do
            if [ -n "${PEER_BOOT_DONE_RE:-}" ] \
                && grep -aqE "$PEER_BOOT_DONE_RE" "$log" 2>/dev/null; then
                break
            fi
            # The same, for a verdict only the PEER can print (wave 9: the
            # brain opening a record the client sealed after its own REKEY).
            if [ -n "${PEER_BOOT_PEER_DONE_RE:-}" ] \
                && grep -aqE "$PEER_BOOT_PEER_DONE_RE" "$blog" 2>/dev/null; then
                break
            fi
            kill -0 "$qpid" 2>/dev/null || break
            j=$((j + 1)); sleep 0.5
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        kill "$bpid" 2>/dev/null; wait "$bpid" 2>/dev/null
    }

    brain_lies_scenario() {
        local label="userspace: the brain lies"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/brain-lies.log"
        local blog="$CI_LOG_DIR/brain-lies-peer.log"
        rm -f "$log" "$blog"

        # Build the PLAIN kernel. Without this the scenario inherits whatever
        # binary the previous block left in place — today `envelope-smoke`,
        # which spawns an extra task — and the thing this scenario is most
        # valuable for is a SCHEDULING property (that `net-poll` gets to run on
        # its hart). Proving that for a build nobody ships is proving the wrong
        # thing, and the inheritance is invisible: the scenario passes either
        # way, so nothing would ever tell you.
        kbuild "qemu,use-robot"   # the brain link is the robot's: the robot cell

        if ! python3 tools/fake_brain.py --selftest >/dev/null 2>&1; then
            bad; echo "      tools/fake_brain.py selftest failed — its framing no"
            echo "      longer matches brain_protocol.rs, so every frame it sends"
            echo "      would be dropped at the CRC check and this scenario would"
            echo "      fail for the wrong reason."
            return
        fi

        # A dedicated image: same GPIODRV autorun as build/disk.img (that is
        # what exposed the starvation), but with a link key. With no key the
        # kernel connects and closes at once (the link is always a Noise
        # session) — correct, and it would stop every frame here from reaching
        # the dispatch. The peer runs the brain side of that session with the
        # key it reads out of this image.
        rm -f $AZOS_OUT/build/disk-brainlies.img
        make_disk $AZOS_OUT/build/disk-brainlies.img

        # The peer is done after frame 4 is WRITTEN; the kernel dispatches at
        # 10 Hz from its own loop and, on a loaded host, had handled only
        # frame 1 when a fixed 3 s settle killed it (gate 187: timer ISR
        # jitter 38 ms, the peer PASS, no DEGRADE line). The settle is now a
        # 20 s ceiling ending at the kernel's verdict on the DEGRADE frame,
        # armed OR cleared, so the negative check below still sees a clear.
        PEER_BOOT_DONE_RE='degraded mode (armed|cleared)' \
            run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-brainlies.img 20

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the robot never connected — no SYN reached the peer."
            echo "      Check '[NET-POLL]' in the kernel log first: if it is"
            echo "      absent, a task on hart 3 starved the poller and the RX"
            echo "      ring was never drained."
            echo "      logs kept: $log $blog"; return
        fi

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        # Positive: a truncated 0x8B reached the dispatch and clamped closed.
        if ! grep -aq "semantic level set to 3" "$log" 2>/dev/null; then
            bad; echo "      no 'semantic level set to 3' — the malformed frame"
            echo "      never reached the dispatch, or did not fail closed."
            echo "      peer said: $(tail -2 "$blog" 2>/dev/null | tr "\n" " ")"
            echo "      logs kept: $log $blog"; return
        fi
        # Negative: the empty 0x8A must ARM containment, never clear it. Until
        # 2026-09-06 it read `unwrap_or(DEGRADE_CLEAR)` and a truncated frame
        # disarmed containment — resetting a CONTAINED level to FULL through
        # the same atomic the assertion above just proved was set.
        if grep -aq "degraded mode cleared" "$log" 2>/dev/null; then
            bad; echo "      a DEGRADE frame with no reason byte CLEARED containment"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "degraded mode armed — reason byte missing" "$log" 2>/dev/null; then
            bad; echo "      the empty DEGRADE frame did not arm containment"
            echo "      logs kept: $log $blog"; return
        fi
        # And the reason the frames arrived at all: the network poller ran.
        # Checked last because the three assertions above cannot pass without
        # it — it is here to name the cause when they fail together.
        if ! grep -aq "NET-POLL" "$log" 2>/dev/null; then
            bad; echo "      net-poll never started — a task on hart 3 starved"
            echo "      it, so the RX ring was never drained (see the"
            echo "      AUTORUN_PRIORITY block in kernel/src/main.rs)"
            echo "      logs kept: $log $blog"; return
        fi
        ok; mv -f "$log" "$log.green"; mv -f "$blog" "$blog.green"   # the last green pair, to diff a red one against
    }
    par -s "userspace: the brain lies" brain_lies_scenario   # the brain peer on a host port of its own

    # The record half of the same frame, which the scenario above states it
    # does not cover: `log_safety_violation` writes the flight recorder, not
    # the console, so the fourth frame's `SAFETY_UNKNOWN_PKT` was exercised on
    # every run and asserted on none.
    #
    # A SEPARATE build and scenario, not a second marker on the one above.
    # That one exists to prove a SCHEDULING property — that `net-poll` gets to
    # run on its hart — and its own comment explains why it forces a plain
    # kernel: adding a task changes the thing being measured. So the probe
    # lives behind its own feature and gets its own boot.
    #
    # `brain_lies_smoke_task` polls: flush, scan the log, block on the timer for
    # half a second, repeat, for 60 s. The peer is done in ~4 s, well before the
    # record is on disk, so the settle waits for the probe's own verdict line
    # and 70 s is only the ceiling.
    brain_lies_record_scenario() {
        local label="userspace: unknown packet RECORDED"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/brain-record.log"
        local blog="$CI_LOG_DIR/brain-record-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,brain-lies-smoke"
        # Fresh image: the probe reads LOG00000.BIN back, and a reused image
        # would let it pass on a previous run's record instead of this boot's.
        rm -f $AZOS_OUT/build/disk-brainrec.img
        make_disk $AZOS_OUT/build/disk-brainrec.img

        PEER_BOOT_DONE_RE='BRAINSMOKE\] (NOT )?RECORDED' \
            run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-brainrec.img 70

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the robot never connected — no frame was ever sent,"
            echo "      so there was nothing to record. Check '[NET-POLL]'."
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aq "BRAINSMOKE] NOT RECORDED" "$log" 2>/dev/null; then
            bad; echo "      the frame arrived and the record did not reach the disk:"
            grep -a -m1 "BRAINSMOKE] NOT RECORDED" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "BRAINSMOKE] RECORDED" "$log" 2>/dev/null; then
            bad; echo "      the probe never reached a verdict — it ran out of"
            echo "      attempts, or the task never started."
            echo "      peer said: $(tail -2 "$blog" 2>/dev/null | tr "\n" " ")"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: unknown packet RECORDED" brain_lies_record_scenario   # the brain peer on a host port of its own

    # THE RING-3 PRODUCT PATH, END TO END. Sensors up, ActuatorCmd down,
    # motors driven — from a userspace ELF, through typed capabilities.
    #
    # `userspace/services/brain_client` is the only program in the tree that does the
    # whole loop, and until 2026-09-08 NOTHING booted its image: it was built
    # on every run and started by no scenario. Booting it by hand that day
    # immediately found a live defect (the ARP microbenchmarks were writing the
    # gateway's MAC into the live cache), which is the argument for this
    # scenario existing at all.
    #
    # THE ASSERTION IS THE PAIR `ask=60 duty=60`, NOT THE MARKER'S PRESENCE.
    # `[ACTSMOKE]` prints after the actuation and carries the duty that landed
    # on the PWM channel. A handler stubbed to return success without driving
    # anything still prints the line — measured: `ask=60 duty=0 rc=0`. Only the
    # applied value separates "ring 3 commanded a motor" from "the handler
    # ran", which is exactly the distinction the reflex scenario could not make
    # (stubbing the typed call left it green, 2026-09-07).
    #
    # THAT VALUE COMES OUT OF THE WRITE, NOT FROM READING THE CHANNEL BACK.
    # The first version of this assertion did the readback at the call site
    # with `pwm_get`, and it was racy: `rt_motor_task` drives these same two
    # wheels every control tick, so between the write and the read its duty
    # could be what came back. It was not theoretical — a run on 2026-09-10
    # printed `ask=60 duty=0 rc=0` for wheel 0 with the handler intact, which
    # is a red this scenario would have reported as a kernel defect. The
    # opposite direction is worse: had the other writer happened to write 60,
    # the scenario would have passed while proving nothing. The readback now
    # happens inside the critical section that performs the write
    # (`pwm::pwm_set_duty_pct_reporting`), which is what makes asserting
    # `ask == duty` legitimate at all.
    #
    # Canaries, 2026-09-10: dropping the duty write while still reporting gives
    # `duty=50` (the stale value) and 0/2; clamping `gate_speed` to half gives
    # `ask=60 duty=30` and 0/2. Both compiled and booted, and the restored tree
    # is 2/2.
    #
    # 60 is what `fake_brain.py --serve` sends first, and forward goes through
    # the `motor.speed` op; `apply_motor_cmd` sends reverse down
    # the `motor.direction` op, the typed form of the retired 231.
    #
    # `MotorServer::speed` is reachable only by `ecall`, so this marker
    # cannot be produced by the kernel's own brain link, which also connects to
    # this peer and drives motors through a channel instead.
    ring3_actuation_scenario() {
        local label="userspace: ring-3 drives motors"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/ring3-actuation.log"
        local blog="$CI_LOG_DIR/ring3-actuation-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-braincli.img $AZOS_OUT/build/disk-braincli-linkkey.img $AZOS_OUT/build/braincli_linkkey.bin
        make_disk $AZOS_OUT/build/disk-braincli-linkkey.img

        # Wave 9 (P3): brain_client runs the encrypted link, whose
        # ephemeral keys come from the entropy pool — so virtio-rng — and the
        # peer runs the brain side of it (`--link-key`, AzOSRobotBrain's
        # secure_channel; AZOS_BRAIN_DIR as for `tools/link_peer.py`). The
        # kernel's own brain link dials the same port with the same key; the
        # peer tells it from brain_client by its first message and never
        # answers it.
        PEER_BOOT_QEMU_EXTRA="-device virtio-rng-device" \
        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-braincli-linkkey.img 8 \
            --serve --duration 40 --link-key $AZOS_OUT/build/braincli_linkkey.bin

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the robot never connected, so no command was ever"
            echo "      sent. Check '[NET-POLL]' in the kernel log first."
            echo "      logs kept: $log $blog"; return
        fi

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "ACTSMOKE] ring3 motor" "$log" 2>/dev/null; then
            bad; echo "      ring 3 never reached MotorServer::speed — the"
            echo "      ActuatorCmd did not arrive, or was refused before the"
            echo "      capability check."
            echo "      peer said: $(tail -2 "$blog" 2>/dev/null | tr "\n" " ")"
            echo "      logs kept: $log $blog"; return
        fi
        # Both wheels, and the duty must MATCH the ask on each.
        local m=0
        for id in 0 1; do
            grep -aq "ACTSMOKE] ring3 motor id=$id ask=60 duty=60" "$log" 2>/dev/null \
                && m=$((m + 1))
        done
        if [ "$m" -ne 2 ]; then
            bad; echo "      the handler ran but the motors were not driven to the"
            echo "      commanded speed on both wheels ($m/2 matched):"
            grep -a -m4 "ACTSMOKE" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: ring-3 drives motors" ring3_actuation_scenario   # the brain peer on a host port of its own

    # A RING-3 CLIENT THAT RECONNECTS MUST GIVE ITS SOCKET BACK EVERY TIME.
    #
    # `brain_client` reconnects forever by design. A client that ends a
    # connection without releasing its socket keeps working for exactly
    # `MAX_SOCKETS_PER_TASK` dials (8 with the tree's `.config`, MAX_SOCKETS=16)
    # and then can never create another — "Connection failed, retrying..." for
    # the rest of its life — while every other scenario, each one connection
    # long, stays green. So the peer here resets every connection after its
    # first bytes, and the client has to dial again about every two seconds.
    #
    # The count comes from the kernel log, not from the peer: the kernel's own
    # brain link dials the same port and SLIRP hides which dialer is which. Ten
    # is past the quota with room for a slow first connect.
    ring3_reconnect_scenario() {
        local label="userspace: ring-3 reconnects"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/ring3-reconnect.log"
        local blog="$CI_LOG_DIR/ring3-reconnect-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-braincli.img $AZOS_OUT/build/disk-braincli-linkkey.img $AZOS_OUT/build/braincli_linkkey.bin $AZOS_OUT/build/brain_client.elf
        make_disk $AZOS_OUT/build/disk-braincli-linkkey.img
        # The rebuilt ELF must be the bytes the kernel's seccomp table lists, or
        # autorun refuses it and the scenario reads like a kernel fault. Userspace
        # builds do not depend on the checkout path (Makefile, USPACE_BUILD), so a
        # mismatch here is a source change since `make build/image_hashes.rs`.
        if ! python3 userspace/image_hashes.py --check $AZOS_OUT/build/image_hashes.rs \
                BRAINCLI.ELF=$AZOS_OUT/build/brain_client.elf; then
            bad; echo "      the rebuilt BRAINCLI.ELF is not the image this kernel was built for:"
            echo "      run make $AZOS_OUT/build/image_hashes.rs, then rebuild the kernel."; return
        fi

        # Wave 9: the peer opens every connection with the encrypted-link HELLO (the
        # client sends nothing before one) and resets it after the reply.
        PEER_BOOT_QEMU_EXTRA="-device virtio-rng-device" \
        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-braincli-linkkey.img 1 \
            --reconnect --duration 80 --link-key $AZOS_OUT/build/braincli_linkkey.bin

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      nothing ever connected, so nothing was reset."
            echo "      Check '[NET-POLL]' in the kernel log first."
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        local dials
        dials=$(grep -ac "\[brain_client\] Connected!" "$log" 2>/dev/null)
        if [ "${dials:-0}" -lt 10 ]; then
            bad; echo "      brain_client connected ${dials:-0} time(s) in 80 s; a client"
            echo "      that stops at 8 is not releasing its socket."
            grep -a -m3 "brain_client\] Connection failed" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: ring-3 reconnects" ring3_reconnect_scenario   # the brain peer on a host port of its own

    # THE EMERGENCY STOP, FROM RING 3, END TO END — and it is asserted on the
    # LATCH, not on the stop.
    #
    # the `motor.estop` op was declared in the ABI, exposed by `libsys` and
    # swallowed by `dispatch`'s stub range, so `brain_client` mapped the
    # brain's `FLAG_EMERGENCY` onto two ordinary `motor_speed_typed(cap, 0)`
    # calls. Measured before the fix, with the peer driving again afterwards:
    # the robot kept going at 60% for 101 more commands, and the boot log held
    # no e-stop record of any kind.
    #
    # WHY THE ASSERTION IS `ask=60 duty=0` AFTER, NOT `ask=0 duty=0` AT THE
    # EMERGENCY. A stop command and a stubbed handler both print
    # `ask=0 duty=0`; that pair has never been able to discriminate and it
    # still cannot. What only a real e-stop produces is a REFUSAL of the next
    # drive: the peer's script ends with a plain 60% command that repeats for
    # the rest of the run, and every one of those must come back `duty=0`.
    # Same ask, same marker, opposite duty, separated by the e-stop.
    #
    # AND NOT ON THE `[SAFETY]` LINE EITHER. Measured: a handler that stops the
    # wheels but skips `estop_activate()` still prints
    # "motors stopped, envelope latched" — and the robot drove 20 more times.
    # Grepping the console line would have been a false green.
    #
    # What this does NOT cover: that the `SAFETY_ESTOP` record reaches DISK.
    # The durability of that mechanism is pinned by the `[ENVSMOKE] ESTOP
    # DURABLE` self-check; this scenario pins the wiring to it.
    ring3_estop_scenario() {
        local label="userspace: ring-3 e-stop"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/ring3-estop.log"
        local blog="$CI_LOG_DIR/ring3-estop-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        # The ring-3 ELF carries half of this path, so it must be rebuilt too —
        # a stale `brain_client.elf` would test yesterday's userspace against
        # today's kernel and pass either way.
        rm -f $AZOS_OUT/build/disk-braincli.img $AZOS_OUT/build/disk-braincli-linkkey.img $AZOS_OUT/build/braincli_linkkey.bin $AZOS_OUT/build/brain_client.elf
        make_disk $AZOS_OUT/build/disk-braincli-linkkey.img
        # As in `userspace: ring-3 reconnects`: the rebuilt ELF must be the bytes
        # the kernel's seccomp table lists, or autorun refuses it.
        if ! python3 userspace/image_hashes.py --check $AZOS_OUT/build/image_hashes.rs \
                BRAINCLI.ELF=$AZOS_OUT/build/brain_client.elf; then
            bad; echo "      the rebuilt BRAINCLI.ELF is not the image this kernel was built for:"
            echo "      run make $AZOS_OUT/build/image_hashes.rs, then rebuild the kernel."; return
        fi

        PEER_BOOT_QEMU_EXTRA="-device virtio-rng-device" \
        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-braincli-linkkey.img 20 \
            --serve --emergency --duration 40 --link-key $AZOS_OUT/build/braincli_linkkey.bin

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the robot never connected, so no emergency was"
            echo "      ever sent. logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        local estop_line
        estop_line=$(grep -an "\[SAFETY\] ESTOP from ring 3" "$log" 2>/dev/null \
                     | sed -n "1p" | cut -d: -f1)
        if [ -z "$estop_line" ]; then
            bad; echo "      motor.estop never reached the kernel handler —"
            echo "      the emergency was not declared as one."
            grep -a -m4 "ACTSMOKE] ring3" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        # It has to have been DRIVING first, or "stopped" means nothing.
        local drove_before
        drove_before=$(grep -an "ACTSMOKE] ring3 motor id=[01] ask=60 duty=60" "$log" 2>/dev/null \
                       | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        if [ "$drove_before" -lt 2 ]; then
            bad; echo "      the wheels were never driven before the e-stop"
            echo "      ($drove_before/2 wheels at 60%), so a later duty=0 proves"
            echo "      nothing. logs kept: $log $blog"; return
        fi

        # After it: every 60% ask must be refused, on both wheels.
        local drove_after refused_l refused_r
        drove_after=$(grep -an "ACTSMOKE] ring3 motor id=[01] ask=60 duty=60" "$log" 2>/dev/null \
                      | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)
        refused_l=$(grep -an "ACTSMOKE] ring3 motor id=0 ask=60 duty=0 rc=" "$log" 2>/dev/null \
                    | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)
        refused_r=$(grep -an "ACTSMOKE] ring3 motor id=1 ask=60 duty=0 rc=" "$log" 2>/dev/null \
                    | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)

        if [ "$drove_after" -ne 0 ]; then
            bad; echo "      THE E-STOP DID NOT HOLD: $drove_after commands reached the"
            echo "      wheels at full duty after it latched."
            grep -an "ACTSMOKE] ring3 motor id=[01] ask=60 duty=60" "$log" \
                | awk -F: -v n="$estop_line" '$1 > n' | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        # Two each, so one sampled refusal cannot carry the verdict.
        if [ "$refused_l" -lt 2 ] || [ "$refused_r" -lt 2 ]; then
            bad; echo "      the peer did not keep asking after the e-stop"
            echo "      (refusals seen: left=$refused_l right=$refused_r, want >=2 each),"
            echo "      so the latch was never actually tested."
            echo "      logs kept: $log $blog"; return
        fi

        # THE SAME LATCH THROUGH THE io_ring (owner decision 81).
        # brain_client submits each forward command a second time as one
        # `OP_MOTOR_SPEED` entry for both wheels, and the kernel's op-table
        # entry prints `ACTSMOKE] ioring motor` per wheel with the duty its own
        # write reported. The checks mirror the typed ones: driven through the
        # ring before the e-stop, never at duty 60 after it, refused on each
        # wheel after it — and the refusal carried back to ring 3 in the
        # completion as -EAGAIN with CQE_F_REFUSED (`result=-11 flags=1`). A
        # wheel written at duty 0 by an entry that answered success would pass
        # the first three and not the last.
        if grep -aq "\[brain_client\] FAILED: io_ring" "$log" 2>/dev/null; then
            bad; echo "      brain_client could not create its motor ring:"
            grep -a -m2 "\[brain_client\] FAILED: io_ring" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        local ring_before_l ring_before_r ring_after ring_refused_l ring_refused_r ring_cqe
        ring_before_l=$(grep -an "ACTSMOKE] ioring motor id=0 ask=60 duty=60 rc=" "$log" 2>/dev/null \
                        | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        ring_before_r=$(grep -an "ACTSMOKE] ioring motor id=1 ask=60 duty=60 rc=" "$log" 2>/dev/null \
                        | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        ring_after=$(grep -an "ACTSMOKE] ioring motor id=[01] ask=60 duty=60 rc=" "$log" 2>/dev/null \
                     | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)
        ring_refused_l=$(grep -an "ACTSMOKE] ioring motor id=0 ask=60 duty=0 rc=" "$log" 2>/dev/null \
                         | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)
        ring_refused_r=$(grep -an "ACTSMOKE] ioring motor id=1 ask=60 duty=0 rc=" "$log" 2>/dev/null \
                         | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)
        ring_cqe=$(grep -anE "\[brain_client\] ioring motor cqe result=-11 flags=1([^0-9]|$)" "$log" 2>/dev/null \
                   | awk -F: -v n="$estop_line" '$1 > n' | grep -c .)

        if [ "$ring_before_l" -lt 1 ] || [ "$ring_before_r" -lt 1 ]; then
            bad; echo "      the io_ring never drove the wheels before the e-stop"
            echo "      (ring entries at 60%: left=$ring_before_l right=$ring_before_r, want >=1 each),"
            echo "      so its refusals after it prove nothing. First ring lines:"
            grep -a -m4 "ioring motor" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if [ "$ring_after" -ne 0 ]; then
            bad; echo "      THE E-STOP DID NOT HOLD ON THE io_ring: $ring_after ring entries"
            echo "      reached the wheels at full duty after it latched."
            grep -an "ACTSMOKE] ioring motor id=[01] ask=60 duty=60 rc=" "$log" \
                | awk -F: -v n="$estop_line" '$1 > n' | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if [ "$ring_refused_l" -lt 2 ] || [ "$ring_refused_r" -lt 2 ]; then
            bad; echo "      the io_ring entries after the e-stop did not reach the motor layer"
            echo "      (ring refusals seen: left=$ring_refused_l right=$ring_refused_r, want >=2 each)."
            grep -an "ioring motor" "$log" \
                | awk -F: -v n="$estop_line" '$1 > n' | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if [ "$ring_cqe" -lt 1 ]; then
            bad; echo "      no io_ring completion after the e-stop came back refused with"
            echo "      -EAGAIN (want result=-11 flags=1); completions seen:"
            grep -an "ioring motor cqe" "$log" \
                | awk -F: -v n="$estop_line" '$1 > n' | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: ring-3 e-stop" ring3_estop_scenario   # the brain peer on a host port of its own

    # RING 3's BRAIN LINK IS THE ENCRYPTED ONE (wave 9, owner decision P3).
    #
    # brain_client used to verify the HMAC envelope directly under the PSK,
    # with its replay floor only in RAM, per connection. It now runs the same
    # handshake and record layer as the kernel's own link, with its
    # ephemeral key from the kernel-hosted `entropy` endpoint. The rows above prove the
    # commands still arrive; this one proves the MODE, each claim anchored on
    # a line only the encrypted path prints:
    #   * `[brain_client] link: Noise_<pattern> session established` — printed after
    #     `handle_initiator_confirm` accepted the brain's PSK proof, nowhere else;
    #   * the peer OPENED a sealed SensorPacket from the client — its record
    #     layer and its envelope check both passed on bytes the client sealed;
    #   * the brain's REKEY was followed (`peer REKEY, rx generation 1`) and a
    #     ring-3 motor command landed AFTER it — so records under the ratcheted
    #     key opened;
    #   * the client's own wall-clock REKEY (`brain_client_rekey_secs=10` on
    #     this image) COMPLETED: `client REKEY #1 completed` is printed by the
    #     peer only when a SensorPacket sealed AFTER the client's REKEY record
    #     opened and its envelope verified — the REKEY record opening alone
    #     (`client REKEY #1 opened`) only announces the ratchet. The crate's
    #     own limits (2^20 records, 1 GiB) are far out of this boot's reach,
    #     so the rekey is the CONFIG.INI clock's; the key can only shorten
    #     the hour (`azos_crypto::secure_channel::rekey_interval_secs`, host-tested).
    #
    # Canary, 2026-09-28 (wave 9): `link::handshake` short-circuited to return
    # `true` without a handshake and `seal_frame` sending the bare frame
    # (the pre-wave HMAC-only client, since deleted). See the ENT report for what printed.
    # Canary, 2026-09-28 (wave 10, ENT2): `brain_client_rekey_secs=10` dropped
    # from the image's CONFIG.INI (default hour): RED, "brain_client's own
    # REKEY did not complete", no REKEY line on either side.
    ring3_encrypted_link_scenario() {
        local label="userspace: ring-3 link encrypted"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/ring3-enc.log"
        local blog="$CI_LOG_DIR/ring3-enc-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-braincli.img $AZOS_OUT/build/disk-braincli-linkkey.img $AZOS_OUT/build/braincli_linkkey.bin $AZOS_OUT/build/brain_client.elf
        make_disk $AZOS_OUT/build/disk-braincli-linkkey.img
        if ! python3 userspace/image_hashes.py --check $AZOS_OUT/build/image_hashes.rs \
                BRAINCLI.ELF=$AZOS_OUT/build/brain_client.elf; then
            bad; echo "      the rebuilt BRAINCLI.ELF is not the image this kernel was built for:"
            echo "      run make $AZOS_OUT/build/image_hashes.rs, then rebuild the kernel."; return
        fi

        # Ends at the brain completing the client's REKEY, with a 30 s
        # ceiling. On the PEER's line, not the client's `REKEY sent`: that
        # prints before the record reaches the host, and ending there killed
        # the peer first.
        PEER_BOOT_QEMU_EXTRA="-device virtio-rng-device" \
        PEER_BOOT_PEER_DONE_RE="client REKEY #1 completed" \
        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-braincli-linkkey.img 30 \
            --serve --duration 60 --link-key $AZOS_OUT/build/braincli_linkkey.bin
        sleep 1

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "\[brain_client\] link: Noise_.* session established" "$log" 2>/dev/null; then
            bad; echo "      brain_client never established an encrypted-link session:"
            grep -a -m4 "brain_client\]" "$log" | sed "s|^|      |"
            echo "      peer said: $(grep -a -m3 "encrypted\|FAIL\|refused" "$blog" | tr "\n" " ")"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "opened a sealed SensorPacket from the client" "$blog" 2>/dev/null; then
            bad; echo "      the brain never opened a sealed SensorPacket from brain_client"
            echo "      logs kept: $log $blog"; return
        fi
        local rk_line after
        rk_line=$(grep -an "\[brain_client\] link: peer REKEY, rx generation 1" "$log" 2>/dev/null \
                  | sed -n "1p" | cut -d: -f1)
        if [ -z "$rk_line" ]; then
            bad; echo "      brain_client never followed the brain's REKEY"
            echo "      logs kept: $log $blog"; return
        fi
        after=$(grep -an "ACTSMOKE] ring3 motor id=[01] " "$log" 2>/dev/null \
                | awk -F: -v n="$rk_line" '$1 > n' | grep -c .)
        if [ "$after" -lt 2 ]; then
            bad; echo "      no ring-3 motor command landed after the brain's REKEY ($after),"
            echo "      so records under the ratcheted key were not shown to open."
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "\[brain_client\] link: REKEY sent, tx generation 1" "$log" 2>/dev/null \
           || ! grep -aq "client REKEY #1 completed" "$blog" 2>/dev/null; then
            bad; echo "      brain_client's own REKEY did not complete (sent, then a record"
            echo "      under the new key opened by the brain):"
            grep -a -m3 "REKEY" "$log" "$blog" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: ring-3 link encrypted" ring3_encrypted_link_scenario   # the brain peer on a host port of its own

    # NO FRESH KEYS, NO LINK (wave 9, owner decision P9).
    #
    # The same image booted WITHOUT virtio-rng: the pool stays unseeded, so
    # the kernel-hosted `entropy` endpoint answers NOT_READY (outcome 3) and brain_client, which
    # draws every handshake's ephemeral key from it, refuses to run the link.
    # Anchored on the two lines only the refusal prints — the kernel's
    # one-per-boot `[ENTROPY] REFUSED: ring-3 read` (it also writes the
    # durable SAFETY_ENTROPY_UNSEEDED_REFUSED record) and brain_client's FATAL
    # with the kernel's answer in it — then on the session line's absence.
    #
    # Canary, 2026-09-28 (wave 9): the handler's `!got` branch disabled, so an
    # unseeded pool hands out its zero buffer as "entropy". See the ENT report.
    ring3_entropy_refused_scenario() {
        local label="userspace: ring-3 entropy refused"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/ring3-noent.log"
        local blog="$CI_LOG_DIR/ring3-noent-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-braincli.img $AZOS_OUT/build/disk-braincli-linkkey.img $AZOS_OUT/build/braincli_linkkey.bin $AZOS_OUT/build/brain_client.elf
        make_disk $AZOS_OUT/build/disk-braincli-linkkey.img
        if ! python3 userspace/image_hashes.py --check $AZOS_OUT/build/image_hashes.rs \
                BRAINCLI.ELF=$AZOS_OUT/build/brain_client.elf; then
            bad; echo "      the rebuilt BRAINCLI.ELF is not the image this kernel was built for:"
            echo "      run make $AZOS_OUT/build/image_hashes.rs, then rebuild the kernel."; return
        fi

        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-braincli-linkkey.img 2 \
            --serve --duration 30 --link-key $AZOS_OUT/build/braincli_linkkey.bin

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "\[ENTROPY\] pool unseeded" "$log" 2>/dev/null; then
            bad; echo "      the pool was not unseeded on this boot, so nothing was tested"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "\[ENTROPY\] REFUSED: ring-3 read tid=" "$log" 2>/dev/null; then
            bad; echo "      the kernel never refused a ring-3 entropy read on an unseeded pool"
            grep -a -m3 "brain_client\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "\[brain_client\] FATAL entropy refused outcome=3 " "$log" 2>/dev/null; then
            bad; echo "      brain_client did not refuse to run the link on NOT_READY (outcome 3):"
            grep -a -m4 "brain_client\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aq "\[brain_client\] link: Noise_.* session established" "$log" 2>/dev/null; then
            bad; echo "      a session was established with no entropy behind it"
            echo "      logs kept: $log $blog"; return
        fi
        ok; rm -f "$log" "$blog"
    }
    par -s "userspace: ring-3 entropy refused" ring3_entropy_refused_scenario   # the brain peer on a host port of its own

    # THE BRAIN'S E-STOP OVER TCP — the second of the four sources, and the
    # first scenario in this gate where the KERNEL's own actuation path moves a
    # wheel.
    #
    # A different image from the ring-3 one, and not for convenience:
    # `PKT_ESTOP` over TCP is handled in `behavior_task` on the kernel's own
    # link, whose peer here is the brain itself (the Noise session keyed from
    # the key this image carries), while the ring-3 image's autorun is
    # BRAINCLI and its peer answers brain_client.
    #
    # WHAT IT TOOK TO MAKE THIS ASSERTABLE AT ALL. The first attempt found the
    # wheels at duty 0 for the whole run with the brain commanding 60%. The
    # command was arriving (`remote_action` held it); the arbiter was returning
    # L0 every tick with `violation=LowBattery`, because the sensor task
    # fabricated 3700 mV when there is no ADS1115 and every pack threshold in
    # `safety.rs` is 6500. The entire L1/L2/L3 stack was permanently overridden
    # in every scenario in this gate, and nothing here could tell.
    #
    # THE ASSERTION IS THE PAIR "drove, then did not", on the KERNEL's own
    # writes. `[ACTSMOKE] kernel motor` reports what `motor_set_reporting`
    # applied, from inside the write. A non-zero duty must appear BEFORE the
    # e-stop and none after it, while the peer keeps commanding 60% for the
    # rest of the run. Asserting on `[BRAIN] ESTOP received` would be a false
    # green: measured on the ring-3 path, a handler that skipped the latch
    # still printed "envelope latched" and the robot drove 20 more times.
    brain_estop_tcp_scenario() {
        local label="safety: brain e-stop (tcp)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/brain-estop-tcp.log"
        local blog="$CI_LOG_DIR/brain-estop-tcp-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        rm -f $AZOS_OUT/build/disk-brainestop.img
        make_disk $AZOS_OUT/build/disk-brainestop.img

        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-brainestop.img 4 \
            --kernel-estop --duration 45 --gap 0.25

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the kernel's brain link never connected — check"
            echo "      the link key in this image before suspecting the stack."
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "phase 3 done" "$blog" 2>/dev/null; then
            bad; echo "      the peer never got to the post-e-stop phase, so the"
            echo "      latch was never actually tested:"
            tail -3 "$blog" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        local estop_line
        estop_line=$(grep -an "\[BRAIN\] ESTOP received" "$log" 2>/dev/null \
                     | sed -n "1p" | cut -d: -f1)
        if [ -z "$estop_line" ]; then
            bad; echo "      PKT_ESTOP never reached the TCP handler."
            echo "      logs kept: $log $blog"; return
        fi

        # It must have been DRIVING first, on both wheels, or "stopped" is
        # not a claim about anything.
        local drove_l drove_r
        drove_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        drove_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        if [ "$drove_l" -lt 1 ] || [ "$drove_r" -lt 1 ]; then
            bad; echo "      the kernel's control loop never drove the wheels before"
            echo "      the e-stop (left=$drove_l right=$drove_r), so a later duty=0"
            echo "      proves nothing. If this went red after a change to the"
            echo "      sensor bus, check that no absent sensor is being"
            echo "      fabricated into a safety violation."
            grep -a -m6 "ACTSMOKE] kernel motor" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        # THE ASSERTION IS THE FINAL STATE, NOT THE ABSENCE OF TRANSITIONS.
        # `[ACTSMOKE] kernel motor` prints only when the duty CHANGES, so
        # "no non-zero line after the e-stop" is also what a wheel that never
        # stopped looks like — it just keeps applying the same 80 and says
        # nothing. Measured on the kill-switch scenario below, where exactly
        # that produced a false green. What discriminates is the LAST value
        # each wheel was left at, plus where the last NON-ZERO one falls.
        #
        # **Why the reference point is the last non-zero duty and not the
        # console line.** This asked that the final `duty=0` come AFTER
        # "[BRAIN] ESTOP received", which assumes the wheels cannot stop before
        # the handler announces itself. They can, and on 2026-09-11 they
        # started to: `estop_activate()` now installs the stop as the standing
        # action, so the control loop on another hart applies 0 inside the
        # window between the latch and the `kprintln` three statements later.
        # The scenario reported a FASTER stop as a failure. The property has
        # nothing to do with print interleaving — it is "drove, then went to
        # zero, and stayed there, and nothing drove after the latch" — so that
        # is what is asserted, and the non-zero bound is strictly stricter than
        # the console one it replaces.
        local last_l last_r
        last_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null | sed -n '$p')
        last_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null | sed -n '$p')
        local nz_l nz_r
        nz_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null \
               | grep -v "duty=0$" | sed -n '$p' | cut -d: -f1)
        nz_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null \
               | grep -v "duty=0$" | sed -n '$p' | cut -d: -f1)
        for w in "$last_l:$nz_l" "$last_r:$nz_r"; do
            local rec nz val
            rec=${w%:*}; nz=${w##*:}; val=${rec##*duty=}
            if [ -z "$rec" ] || [ "$val" != "0" ] || [ -z "$nz" ] \
               || [ "$nz" -gt "$estop_line" ]; then
                bad; echo "      THE E-STOP DID NOT HOLD. Each wheel's last applied duty"
                echo "      must be 0, and its last NON-ZERO duty must fall before the"
                echo "      latch; got:"
                echo "        left : ${last_l:-<none>}   (last non-zero at line ${nz_l:-<none>})"
                echo "        right: ${last_r:-<none>}   (last non-zero at line ${nz_r:-<none>})"
                echo "      e-stop at line $estop_line"
                echo "      logs kept: $log $blog"; return
            fi
        done
        ok; rm -f "$log" "$blog"
    }
    par -s "safety: brain e-stop (tcp)" brain_estop_tcp_scenario   # the brain peer on a host port of its own

    # ── 2026-09-25 owner decision Q1.2: e-stop release needs operator authority ──
    # Gate rows for the 2026-09-25 owner decision: "the brain may REQUEST an
    # e-stop release; it may never CLEAR the latch." Delivered as TEXT, to be
    # spliced into tools/ci_check.sh by the owner/coordinator (I do not own that
    # file). Written in its own style, using its EXISTING helpers verbatim:
    # `kbuild`, `make_disk`, `run_brain_peer_boot`, `ok`/`bad`, `$QEMU`/`$KERNEL`,
    # `$CI_LOG_DIR`. Two new scenario functions plus one static (no-QEMU) canary.
    #
    # Provisioning note: these rows need a 32-byte Ed25519 OPERATOR key pair, the
    # same shape `build/disk-linkkey.img` already gives LINK.KEY (see the
    # Makefile's `build/disk-linkkey.img` recipe for the pattern this mirrors).
    # I did not add a Makefile target (Makefile is not in my file ownership for
    # this change) — `operator_key_scenario_setup` below generates the pair with
    # the SAME `cryptography` package `tools/gen_test_key.py` already requires,
    # and provisions it with `mcopy`, exactly like the CONFIG.INI edit in
    # `link_peer_scenario` does today. If the coordinator prefers a Makefile
    # target instead (`build/disk-estopauth.img`, mirroring `disk-linkkey.img`),
    # swap the setup block below for one; nothing else here depends on how the
    # image was built, only on what is IN it (the link key, as in
    # `disk-brainestop.img`, and a fresh OPERATOR.PUB).

    # ── Setup: a disk image + a fresh operator keypair for this run ─────────────
    operator_key_scenario_setup() {
        # $1 = image to build (e.g. build/disk-estopauth.img), by copying the
        # existing `disk-brainestop.img` recipe's output (GPIODRV autorun, the
        # link key; the enforced-link build boots the same image in the
        # SEPARATE row below).
        local img="$1" keydir="$2"
        # rm first: `safety: brain e-stop (tcp)` boots build/disk-brainestop.img
        # DIRECTLY and leaves its flight recorder ending LATCHED; `make` then
        # sees an up-to-date target and hands that dirty image over, the boot
        # restores the latch, and PKT_ESTOP becomes a no-op ("already latched
        # is already done") — gate 182f, 2026-09-26. Fresh image, every time.
        rm -f $AZOS_OUT/build/disk-brainestop.img
        make_disk $AZOS_OUT/build/disk-brainestop.img
        cp $AZOS_OUT/build/disk-brainestop.img "$img"
        mkdir -p "$keydir"
        python3 - "$keydir" <<'PYEOF'
import sys
try:
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
    from cryptography.hazmat.primitives import serialization
except ImportError:
    print("error: install the 'cryptography' package: pip install cryptography",
          file=sys.stderr)
    sys.exit(1)
d = sys.argv[1]
# Fixed seed: reproducible across runs, and distinct from
# tools/keys/test_priv.bin (secure boot) so the two authorities cannot be
# confused if a future change accidentally shared state between them.
seed = bytes([0x37] * 32)
priv = Ed25519PrivateKey.from_private_bytes(seed)
pub = priv.public_key().public_bytes(
    encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)
open(f"{d}/operator_priv.bin", "wb").write(seed)
open(f"{d}/operator_pub.bin", "wb").write(pub)
PYEOF
        mcopy -o -i "$img" "$keydir/operator_pub.bin" ::OPERATOR.PUB
    }

    # ── Row 1: request does not clear, signed release does (QEMU, brain link) ──
    #
    # Reuses `run_brain_peer_boot`'s boot sequence with `tools/fake_brain.py
    # --kernel-estop-release` as the peer (the ONE new message this change adds
    # to that file — see its own doc for the six phases). Same image shape as
    # `brain_estop_tcp_scenario` (link key, GPIODRV autorun), plus
    # `/fat/OPERATOR.PUB`.
    #
    # THE ASSERTION IS THE PAIR, on the kernel's OWN console lines, which are
    # printed by the exact branch that does or does not call `safety::
    # estop_release` — not a re-derivation of the gate. (A stricter version would
    # additionally read `[ACTSMOKE] kernel motor duty=` back, the way
    # `brain_estop_tcp_scenario` does, for the wheel-level evidence; that
    # assertion is straightforward to add the same way but is NOT included below
    # — see the agent report for why the run that produced these lines did not
    # also capture clean ACTSMOKE output.)
    #
    # `estop_release_authority_run <label> <features> <tag>`: the same
    # script and the same assertions on any kernel build — the enforced-link
    # row below runs it again with `link-provisioning-enforced`, whose boot gate
    # needs the image's key and whose UART bridge is down, and must change
    # nothing about the release authority.
    estop_release_authority_run() {
        local label="$1" features="$2" tag="$3"
        # The kernel's handshake needs a seeded entropy pool (the enforced
        # build refuses it otherwise, `refuse_unseeded`), and QEMU's pool is
        # seeded by virtio-rng.
        local PEER_BOOT_QEMU_EXTRA="-device virtio-rng-device"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/${tag}.log"
        local blog="$CI_LOG_DIR/${tag}-peer.log"
        local img="$AZOS_OUT/build/disk-${tag}.img"
        local keydir="$CI_LOG_DIR/${tag}-keys"
        rm -f "$log" "$blog"

        kbuild "$features"
        operator_key_scenario_setup "$img" "$keydir"

        # settle 20, not 4: `run_brain_peer_boot` stops waiting at the peer's
        # "phase 3 done"; the signed release and the 12 s drive-again window
        # (`n_each * gap`) come AFTER that line, and the PASS marker after
        # those. With 4 the boot was killed mid-phase-5 (gate 182e).
        run_brain_peer_boot "$log" "$blog" "$img" 20 \
            --kernel-estop-release --operator-priv "$keydir/operator_priv.bin" \
            --duration 60 --gap 0.25

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the kernel's brain link never connected."
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"
            grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "SECCHAN\] link key loaded" "$log" 2>/dev/null; then
            bad; echo "      the kernel did not load the image's link key, so its"
            echo "      brain link could not run."
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "PASS kernel-estop-release" "$blog" 2>/dev/null; then
            bad; echo "      the peer script did not complete:"
            tail -5 "$blog" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        # THE ESTOP MUST HAVE LATCHED.
        if ! grep -aq "BRAIN\] ESTOP received" "$log" 2>/dev/null; then
            bad; echo "      PKT_ESTOP never reached the TCP handler."
            echo "      logs kept: $log $blog"; return
        fi

        # THE BARE REQUEST MUST NOT HAVE CLEARED IT — key line 1. Failure-only
        # string: the OLD (pre-2026-09-25) behaviour printed "ESTOP cleared by
        # MODE command" here instead, which this positive check would simply not
        # find, so a regression reads as this assertion failing, not as a
        # different string appearing.
        if ! grep -aq "BRAIN\] ESTOP_RESET recorded as a REQUEST" "$log" 2>/dev/null; then
            bad; echo "      the bare ESTOP_RESET request was not recorded as a"
            echo "      request (either it was silently ignored, or — check the"
            echo "      next line below — it cleared the latch on its own, which"
            echo "      is the exact regression this row exists to catch)."
            echo "      logs kept: $log $blog"; return
        fi

        # And the ORDER matters: the request-refusal line must come BEFORE the
        # verified-authority line, or a kernel that clears first and merely LOGS
        # a stray "recorded as a REQUEST" afterwards would still pass a
        # presence-only check.
        local refuse_line clear_line
        refuse_line=$(grep -an "BRAIN\] ESTOP_RESET recorded as a REQUEST" "$log" \
                      | sed -n "1p" | cut -d: -f1)
        clear_line=$(grep -an "BRAIN\] ESTOP cleared by verified operator authority" "$log" \
                     | sed -n "1p" | cut -d: -f1)
        if [ -z "$clear_line" ]; then
            bad; echo "      the signed release was never accepted — no"
            echo "      'ESTOP cleared by verified operator authority' line."
            echo "      logs kept: $log $blog"; return
        fi
        if [ -z "$refuse_line" ] || [ "$refuse_line" -ge "$clear_line" ]; then
            bad; echo "      the request-refusal line did not come BEFORE the"
            echo "      verified-release line (refuse=$refuse_line clear=$clear_line)."
            echo "      logs kept: $log $blog"; return
        fi

        ok; rm -f "$log" "$blog"; rm -rf "$keydir"
    }
    estop_release_authority_scenario() {
        estop_release_authority_run "safety: e-stop release requires operator authority" \
            "qemu,actuation-smoke" estop-authority
    }
    par -s "safety: e-stop release requires operator authority" estop_release_authority_scenario   # the brain peer on a host port of its own

    # ── Row 2: the enforced-link build, booted — the audit's named measurement ─
    #
    # `link-provisioning-enforced` is compile-time only: no runtime flag relaxes it.
    # It halts the boot without a link key, refuses a handshake without seeded
    # entropy and holds the UART bridge down; the brain link itself is the
    # same Noise session in every build. So this row is row 1 on that build:
    # it must BOOT (the image carries the key), bring the link up, and leave
    # the release authority exactly as row 1 proves it. Named in the owner's
    # brief as "never booted in the gate" — `build "vf2"` / `build "k1"` only
    # BUILD it.
    estop_release_authority_enforced_link_boot() {
        estop_release_authority_run "safety: e-stop authority under link-provisioning-enforced" \
            "qemu,actuation-smoke,link-provisioning-enforced" estop-authority-enforced
    }
    par -s "safety: e-stop authority under link-provisioning-enforced" estop_release_authority_enforced_link_boot   # the brain peer on a host port of its own

    # ── Row 3 (static, no QEMU): the test-only proof constructor never ships ───
    #
    # `safety::ReleaseAuthority::for_test` and `safety::test_reset_operator_
    # authority` are `#[cfg(test)]` — compiled into `tests/host/behavior-tests`
    # (which pulls `safety.rs` in with `#[path]`) and this crate's own `cargo
    # test`, never into a kernel binary. This is the grep the module comments on
    # `ReleaseAuthority`/`estop_release` promise: a real kernel ELF, built
    # normally, must not contain the symbol. `nm`'s Rust v0 mangling embeds the
    # literal path components, so a plain string match on the demangled-looking
    # substring is enough — no demangler required, and no `^` anchor (the symbol
    # is preceded by the mangling prefix, not by a line start).
    #
    # NEGATIVE check, failure-only string: absence of "for_test" is what PASSES
    # here, so this is really a presence check inverted — `grep -q` returning
    # nonzero is success. Paired with a POSITIVE check on the same binary (the
    # production symbols the mechanism actually needs) so a kernel that failed to
    # link `safety.rs` at all — which would ALSO pass the negative half — cannot
    # read green here.
    estop_release_authority_binary_canary() {
        local label="safety: no test-only e-stop proof in the kernel binary"
        printf "  %-26s" "${label}..."
        # The e-stop's release authority is the robot's (use-robot): the robot cell.
        kbuild "qemu,use-robot"
        local elf="$AZOS_OUT/target/riscv64imac-unknown-none-elf/release/kernel"
        if [ ! -f "$elf" ]; then
            bad; echo "      $elf does not exist after a supposedly successful build."
            return
        fi
        # `nm | grep -q` is the wrong shape under `set -o pipefail`: grep -q
        # exits on the first MATCH, nm takes SIGPIPE, the pipeline reports
        # 141 — so the positive check below read "not linked" on a kernel
        # that DOES link it (gate 182e). Symbols go to a file first.
        local syms="$CI_LOG_DIR/estop-canary-syms.txt"
        mkdir -p "$CI_LOG_DIR"
        nm "$elf" > "$syms" 2>/dev/null
        if grep -q "for_test" "$syms"; then
            bad; echo "      the kernel binary links a #[cfg(test)]-only symbol"
            echo "      (for_test) — the test-only release-authority bypass is"
            echo "      reachable from a real kernel image."
            return
        fi
        # Wave 11 (DOMAIN): the latch and its release moved from
        # `azos_behavior::safety` to `azos_actuation::estop`
        # (behavior re-exports it), so that is the symbol's path now.
        if ! grep -q "14azos_actuation5estop13estop_release" "$syms"; then
            bad; echo "      estop::estop_release is not linked into the kernel"
            echo "      at all — the canary above would pass vacuously against a"
            echo "      kernel that dropped the whole mechanism, so this positive"
            echo "      half is required, not optional."
            return
        fi
        ok
    }
    ci_row "safety: no test-only e-stop proof in the kernel binary" estop_release_authority_binary_canary
    # THE PHYSICAL KILL SWITCH — the third of the four e-stop sources, and the
    # one QEMU cannot present by itself.
    #
    # Two things had to be built before this could be asserted at all, and both
    # were defects rather than missing test scaffolding:
    #
    #  1. `sys-wdt`, which owned this poll until the edge interrupt and the
    #     `kill-switch` task replaced it (2026-10-23), NEVER RAN UNDER LOAD. Priority 20 —
    #     the lowest in the system bar idle — under strict priority with no
    #     aging. Measured with a probe verified present in the binary: it
    #     entered and iterated on an idle boot and did not execute one
    #     instruction in 50 s with the brain link, a disk and a NIC attached.
    #     Six mechanisms died with it: stack canaries, timer liveness, this
    #     poll, the flight-recorder flush, driver health and the OTA boot-good
    #     mark. It is now priority 11, pinned to hart 2, and sleeps on a timer
    #     instead of spinning.
    #  2. The branch was not EDGE-TRIGGERED, because it had never run twice.
    #     One press wrote 14 durable `SAFETY_ESTOP` records at 500 ms apart.
    #
    # `estop_gpio_pin` is set by the smoke task, not by CONFIG.INI, and the
    # ORDER is the reason: every simulated GPIO pin powers up reading 0 and the
    # switch is active-low, so a configured pin would latch the e-stop at the
    # arm before anything could move. The task drives the pin high —
    # the released switch, which on a board is a pull-up — and only then arms
    # the config. See `estop_gpio_smoke_task`.
    killswitch_gpio_scenario() {
        local label="safety: kill switch (gpio)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/killswitch-gpio.log"
        local blog="$CI_LOG_DIR/killswitch-gpio-peer.log"
        rm -f "$log" "$blog"

        kbuild "qemu,estop-gpio-smoke"
        rm -f $AZOS_OUT/build/disk-estopgpio.img
        make_disk $AZOS_OUT/build/disk-estopgpio.img

        # `--kernel-drive` is the TCP script with the PKT_ESTOP withheld: the
        # peer only ever asks the robot to MOVE, so whatever stops it can only
        # have been the switch.
        # QEMU is killed on the recorder's own word, not on a timer (FX11):
        # the settle ends when the kernel says the latching record's fsync
        # returned (`[SAFETY] ESTOP record durable`, printed by the task that
        # wrote it, after the device flush), with 30 s as a ceiling only. Gate
        # 792e33af killed this boot 4 s after DONE with the record still in
        # RAM, and the latch row after it booted released.
        PEER_BOOT_DONE_RE='SAFETY\] ESTOP record durable' \
        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-estopgpio.img 30 \
            --kernel-drive --duration 50 --gap 0.25

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the kernel's brain link never connected, so the"
            echo "      wheels were never turning. logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        if ! grep -aq "ESTOPGPIO] kill switch armed" "$log" 2>/dev/null; then
            bad; echo "      the smoke task never armed the pin — nothing was"
            echo "      testable. logs kept: $log $blog"; return
        fi

        # Two anchors, and they are not interchangeable.
        #
        # `wdt_line` is where the watchdog RECORDED the event; `press_line` is
        # where the switch was pressed. The stop is applied by the actuation
        # gate, which can zero a wheel BEFORE the watchdog task gets to print,
        # so "the wheel stopped because of the press" must be measured against
        # the press. Gate 78 (2026-09-19) failed on exactly that: press at 532,
        # right wheel zeroed at 537, watchdog record at 538, left wheel at 540 —
        # both wheels stopped after the press, and the row still called it
        # "THE KILL SWITCH DID NOT HOLD".
        #
        # The record is still required to exist, and exactly once: that is the
        # `hits` check below, and it is a different property from the ordering.
        local wdt_line hits press_line
        wdt_line=$(grep -an "KILLSW] GPIO ESTOP" "$log" 2>/dev/null | sed -n "1p" | cut -d: -f1)
        press_line=$(grep -an "ESTOPGPIO] pressing the kill switch" "$log" 2>/dev/null | sed -n "1p" | cut -d: -f1)
        if [ -z "$press_line" ]; then
            bad; echo "      the smoke task never pressed the switch — nothing was"
            echo "      testable. logs kept: $log $blog"; return
        fi
        if [ -z "$wdt_line" ]; then
            bad; echo "      the kill-switch task never saw the switch. If this went"
            echo "      red after a scheduling change, check FIRST that kill-switch"
            echo "      runs at all under load (sys-wdt, which polled it before"
            echo "      2026-10-23, did not until 2026-09-10)."
            echo "      logs kept: $log $blog"; return
        fi
        # The press reached the task by its EDGE, not by the slow re-check: the
        # task prints the edge-to-latch time only for a press an edge woke it
        # for. The number is TCG time and is not asserted (the 1 ms target is
        # the board's); a press the re-check found has no such line.
        local edge_us
        edge_us=$(grep -a "KILLSW] edge to latch" "$log" 2>/dev/null | sed -n "1p" | tr -d '\r' | sed 's/.*latch \([0-9]*\) us.*/\1/')
        if [ -z "$edge_us" ]; then
            bad; echo "      the press was not taken by its edge (no 'edge to latch'"
            echo "      line): the stop came from the re-check, up to"
            echo "      KILL_SWITCH_RECHECK_MS late. logs kept: $log $blog"; return
        fi
        # The latching record reached the medium before QEMU was killed: the
        # marker follows the fsync, and it must follow the press. Canary,
        # run by hand: `PEER_BOOT_QEMU_EXTRA="-append canary=log-latch-defer"`
        # holds every flush back while the record is pending, and this row
        # goes red here (the latch row after it boots released).
        local durable_line
        durable_line=$(grep -an "SAFETY\] ESTOP record durable (action 2)" "$log" 2>/dev/null | sed -n "1p" | cut -d: -f1)
        if [ -z "$durable_line" ] || [ "$durable_line" -lt "$press_line" ]; then
            bad; echo "      the latching SAFETY_ESTOP was never acknowledged durable"
            echo "      before QEMU was killed (no fsync covered it):"
            grep -a "ESTOPGPIO\] recorder\|SAFETY\] ESTOP record" "$log" | tr -d '\r' | sed "s|^|        |"
            echo "      logs kept: $log $blog"; return
        fi
        # Exactly one record for one press: the edge trigger.
        hits=$(grep -ac "KILLSW] GPIO ESTOP" "$log" 2>/dev/null)
        if [ "$hits" -ne 1 ]; then
            bad; echo "      one press produced $hits e-stop records. A held switch"
            echo "      is one event; repeating it writes a durable record every"
            echo "      500 ms and buries the incident it is meant to explain."
            echo "      logs kept: $log $blog"; return
        fi

        local drove_l drove_r
        drove_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$wdt_line" '$1 < n' | grep -c .)
        drove_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$wdt_line" '$1 < n' | grep -c .)
        if [ "$drove_l" -lt 1 ] || [ "$drove_r" -lt 1 ]; then
            bad; echo "      the wheels were never turning before the switch was"
            echo "      pressed (left=$drove_l right=$drove_r), so stopping proves nothing."
            grep -a -m6 "ACTSMOKE] kernel motor" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        # The peer must still have been ASKING after the press, or a stopped
        # wheel proves only that nobody wanted it to move.
        local asks_after
        asks_after=$(grep -an "TCP-RX" "$log" 2>/dev/null \
                     | awk -F: -v n="$wdt_line" '$1 > n' | grep -c .)
        if [ "$asks_after" -lt 5 ]; then
            bad; echo "      the brain stopped talking after the switch was pressed"
            echo "      ($asks_after frames), so the latch was never tested."
            echo "      logs kept: $log $blog"; return
        fi

        # FINAL STATE, not absence of transitions — see the TCP scenario above
        # for why. This is where that false green was measured: without the
        # latch the wheel stayed at 80 and the change-only marker said nothing,
        # so counting non-zero lines after the press returned 0 and passed.
        #
        # Three facts per wheel: its last applied duty is 0, no non-zero duty
        # was applied after the press, and the stop wrote it (`ACTREC`, every
        # write, not change-only) after the press. The last `ACTSMOKE` line
        # itself may come BEFORE the press: the wheels here toggle 80/0 with
        # the peer's command age, and since the edge interrupt (2026-10-23)
        # the latch lands within a millisecond of the press, often while the
        # wheel already reads 0, so the change-only marker has nothing new to
        # print. It came after the press under the 500 ms poll by accident.
        local wheel
        for wheel in 0 1; do
            local last ln val after_nz stop_rec
            last=$(grep -an "ACTSMOKE] kernel motor id=$wheel duty=" "$log" 2>/dev/null | tr -d '\r' | sed -n '$p')
            ln=${last%%:*}; val=${last##*duty=}
            after_nz=$(grep -an "ACTSMOKE] kernel motor id=$wheel duty=" "$log" 2>/dev/null | tr -d '\r' \
                       | grep -v "duty=0$" | awk -F: -v n="$press_line" '$1 > n' | grep -c .)
            stop_rec=$(grep -an "ACTREC] motor id=$wheel .*duty=0 " "$log" 2>/dev/null \
                       | awk -F: -v n="$press_line" '$1 > n' | grep -c .)
            if [ -z "$last" ] || [ "$val" != "0" ] || [ "$after_nz" -ne 0 ] || [ "$stop_rec" -lt 1 ]; then
                bad; echo "      THE KILL SWITCH DID NOT HOLD (wheel $wheel). Its last applied"
                echo "      duty must be 0, nothing non-zero may follow the press, and the"
                echo "      stop must write it after the press; got last=${last:-<none>},"
                echo "      non-zero after=$after_nz, stop writes after=$stop_rec"
                echo "      (press at line $press_line, record at $wdt_line)"
                echo "      logs kept: $log $blog"; return
            fi
        done
        # Boot 1's log outlives this verdict: `safety: latch survives reboot`
        # boots the disk this boot left, and when it goes red the question is
        # what THIS boot did with the record. That row removes it on ok.
        ok; rm -f "$blog"
    }
    par -s "safety: kill switch (gpio)" killswitch_gpio_scenario   # the brain peer on a host port of its own

    # The latch survives a reset. Owner decision, 2026-09-13: boot reads the
    # last `SAFETY_ESTOP` in the flight recorder and starts latched if the last
    # session ended latched.
    #
    # DELIBERATELY NOT HERMETIC, and it is the one scenario that must not be:
    # the second boot reading what the first one wrote is the property. It boots
    # the image the kill-switch scenario just left — a durable `SAFETY_ESTOP`
    # with action 2 and nothing after it that clears it — on the plain
    # actuation kernel, with no kill switch configured and a peer that only ever
    # asks to drive. So whatever keeps the wheels still can only be the record.
    #
    # The assertion is on the kernel's own writes, as above: each wheel's loop
    # ran, no duty it applied was ever positive, the last one is 0, and the peer
    # kept asking the whole time.
    latch_survives_reboot_scenario() {
        local label="safety: latch survives reboot"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/latch-reboot.log"
        local blog="$CI_LOG_DIR/latch-reboot-peer.log"
        # Boot 1 (the kill switch row) kept its log for this verdict.
        local klog="$CI_LOG_DIR/killswitch-gpio.log"
        rm -f "$log" "$blog"

        kbuild "qemu,actuation-smoke"
        if [ ! -f $AZOS_OUT/build/disk-estopgpio.img ]; then
            bad; echo "      $AZOS_OUT/build/disk-estopgpio.img is missing: this scenario boots"
            echo "      the image the kill-switch scenario leaves behind."; return
        fi
        # Boot 1 must have said the record is on the medium; otherwise a
        # released boot here is boot 1's failure, not this boot's.
        if ! grep -aq "SAFETY\] ESTOP record durable (action 2)" "$klog" 2>/dev/null; then
            bad; echo "      boot 1 (kill switch row) never acknowledged its latching"
            echo "      record durable, so this disk need not carry it:"
            grep -a "ESTOPGPIO\] recorder\|SAFETY\] ESTOP record" "$klog" 2>/dev/null | tr -d '\r' | sed "s|^|        |"
            echo "      log kept: $klog"; return
        fi

        run_brain_peer_boot "$log" "$blog" $AZOS_OUT/build/disk-estopgpio.img 4 \
            --kernel-drive --duration 40 --gap 0.25

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the kernel's brain link never connected, so nothing"
            echo "      asked the wheels to move. logs kept: $log $blog $klog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog $klog"; return
        fi
        if ! grep -aq "SAFETY] ESTOP restored: the last session ended latched (action 2)" "$log" 2>/dev/null; then
            bad; echo "      boot did not restore the latch the kill switch left on disk:"
            grep -a -m3 "SAFETY] .*booting released\|SAFETY] ESTOP restored" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog $klog"; return
        fi

        local asks
        asks=$(grep -ac "TCP-RX" "$log" 2>/dev/null)
        if [ "$asks" -lt 20 ]; then
            bad; echo "      only $asks frames from the peer reached the kernel, so a"
            echo "      still wheel proves nothing. logs kept: $log $blog $klog"; return
        fi

        local w line
        for w in 0 1; do
            line=$(grep -a "ACTSMOKE] kernel motor id=$w duty=" "$log" 2>/dev/null | sed -n '$p')
            if [ -z "$line" ] || [ "${line##*duty=}" != "0" ]; then
                bad; echo "      wheel $w: the control loop's last applied duty must be 0;"
                echo "      got: ${line:-<no write at all>}. logs kept: $log $blog $klog"; return
            fi
        done
        if grep -aqE "ACTSMOKE] kernel motor id=[01] duty=[1-9]" "$log" 2>/dev/null; then
            bad; echo "      THE LATCH DID NOT SURVIVE THE RESET — a wheel was driven:"
            grep -aE -m4 "ACTSMOKE] kernel motor id=[01] duty=[1-9]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog $klog"; return
        fi
        ok; rm -f "$log" "$blog" "$klog"
    }
    par -s "safety: latch survives reboot" latch_survives_reboot_scenario   # the brain peer on a host port of its own

    # The latch record reaches the MEDIUM, not only the device's write cache.
    #
    # `safety: latch survives reboot` cannot see a missing flush: a killed QEMU
    # leaves every write it accepted in the host file, flushed or not. This row
    # boots with the device's write cache ON (`write-cache=on`, which the
    # kernel's VIRTIO_BLK_F_FLUSH negotiation keeps on) behind QEMU's
    # `blklogwrites` filter, which logs every write and every flush in order.
    # `tools/blklog_crash_image.py` then rebuilds the disk a power cut would
    # leave -- the pre-boot copy plus every write up to the LAST flush -- and a
    # second boot on that image must restore the latch.
    #
    # `estop-latch-smoke` writes one durable latching SAFETY_ESTOP and then
    # parks the boot, so no write after the claim (a periodic logger flush,
    # BOOTMETA) can add a flush that hides a missing one. Canaries, run by
    # hand: `virtio::blk::flush` answering Ok without sending T_FLUSH gives
    # "0 flushes" and boot 2 "booting released"; dropping the flush after the
    # directory entry in `fat32_fsync` gives "1 dropped" and the same; the
    # tree before the flush existed fails "flush not negotiated" (QEMU then
    # runs writethrough and the kernel's flush is not what made it durable).
    latch_flush_scenario() {
        local label="safety: latch record flushed"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log1="$CI_LOG_DIR/latch-flush-boot1.log"
        local log2="$CI_LOG_DIR/latch-flush-boot2.log"
        local img="$CI_LOG_DIR/latch-flush.img"
        local pristine="$CI_LOG_DIR/latch-flush-pristine.img"
        local wlog="$CI_LOG_DIR/latch-flush.wlog"
        local crash="$CI_LOG_DIR/latch-flush-crash.img"
        rm -f "$log1" "$log2" "$img" "$pristine" "$wlog" "$crash"
        if ! kbuild "qemu,use-robot,estop-latch-smoke"; then return; fi
        # A fresh image: earlier rows write to build/disk.img, and a latching
        # record they left would let boot 2 restore the latch with no flush.
        rm -f $AZOS_OUT/build/disk.img
        make_disk $AZOS_OUT/build/disk.img
        cp $AZOS_OUT/build/disk.img "$img"; cp $AZOS_OUT/build/disk.img "$pristine"
        if ! qemu-img create -f raw "$wlog" 256M >/dev/null 2>&1; then
            bad; echo "      qemu-img could not create the write log"; return
        fi

        local pid i
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 2 \
            -blockdev "driver=blklogwrites,node-name=d0,file.driver=file,file.filename=$img,log.driver=file,log.filename=$wlog,log-sector-size=512,log-super-update-interval=1" \
            -device virtio-blk-device,drive=d0,write-cache=on >"$log1" 2>&1 &
        pid=$!; i=0
        while [ "$i" -lt 240 ]; do
            grep -aq "ESTOPLATCHSMOKE\] parked" "$log1" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log1" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.25
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        if grep -aqiE "panic|\[FATAL\]" "$log1" 2>/dev/null; then
            bad; echo "      boot 1: kernel panic or fatal exception:"
            grep -aiE -m3 "panic|\[FATAL\]" "$log1" | sed "s|^|      |"
            echo "      log kept: $log1"; return
        fi
        if ! grep -aq "VIRTIO-BLK\] flush: negotiated" "$log1" 2>/dev/null; then
            bad; echo "      boot 1: VIRTIO_BLK_F_FLUSH was not negotiated, so the"
            echo "      kernel cannot flush and QEMU ran writethrough:"
            grep -a "VIRTIO-BLK\]" "$log1" | tr -d '\r' | sed "s|^|        |"
            echo "      log kept: $log1"; return
        fi
        # Boot 2 restoring the latch proves this boot's record only if the
        # image started released; otherwise the row cannot discriminate.
        # A fresh `make_disk` image has no recorder file at all, and the kernel
        # says so in its own words; both lines mean "no latch on this disk".
        # Gate 187 was this row's first gate, and it went red on exactly that.
        if ! grep -aqF "SAFETY] the last session ended released" "$log1" 2>/dev/null \
           && ! grep -aqF "SAFETY] no flight recorder on this disk — booting released" "$log1" 2>/dev/null; then
            bad; echo "      boot 1 did not start released, so the pristine image already"
            echo "      carries a latch and boot 2 could restore it with no flush:"
            grep -a "SAFETY\] .*boot\|SAFETY\] ESTOP" "$log1" | tr -d '\r' | sed "s|^|        |"
            echo "      log kept: $log1"; return
        fi
        if ! grep -aqF "ESTOPLATCHSMOKE] wrote durable SAFETY_ESTOP record" "$log1" 2>/dev/null \
           || ! grep -aq "ESTOPLATCHSMOKE\] parked" "$log1" 2>/dev/null; then
            bad; echo "      boot 1: no durable SAFETY_ESTOP claim, or the boot never parked:"
            grep -a "ESTOPLATCHSMOKE\]\|LOG\]" "$log1" | tr -d '\r' | sed "s|^|        |"
            echo "      log kept: $log1"; return
        fi

        local summary
        if ! summary="$(python3 tools/blklog_crash_image.py "$pristine" "$wlog" "$crash" 2>&1)"; then
            bad; echo "      could not rebuild the power-cut image: $summary"; return
        fi

        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 2 \
            -drive "file=$crash,if=none,format=raw,id=d0" \
            -device virtio-blk-device,drive=d0 >"$log2" 2>&1 &
        pid=$!; i=0
        while [ "$i" -lt 240 ]; do
            grep -aq "ESTOPLATCHSMOKE\] parked" "$log2" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log2" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.25
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        if ! grep -aqF "SAFETY] ESTOP restored: the last session ended latched (action 2)" \
                "$log2" 2>/dev/null; then
            bad; echo "      the power-cut image lost the latch boot 1 called durable"
            echo "      ($summary):"
            grep -a "SAFETY\] .*boot\|SAFETY\] ESTOP" "$log2" | tr -d '\r' | sed "s|^|        |"
            echo "      logs kept: $log1 $log2"; return
        fi
        ok; rm -f "$log1" "$log2" "$img" "$pristine" "$wlog" "$crash"
    }
    par "safety: latch record flushed" latch_flush_scenario

    # FAT32 journal barriers under a power cut that REORDERS (wave 7, STOR).
    #
    # The row above cuts at the last flush, which never reorders, so it cannot
    # see a missing ordering barrier. `fat-barrier-smoke` checks BARRIER.DAT
    # right after mount (journal recovery has run), then creates it (1400 B,
    # 3 clusters) and overwrites it (900 B, 2 clusters) through
    # `fat32_write_file`, and parks. Boot 1 runs on a write-cache=on disk
    # behind `blklogwrites`; `blklog_crash_image.py --cuts` then lists, for
    # every flush epoch from the first PENDING journal record on, every
    # subset of that epoch's writes grouped by class (journal / FAT / root
    # directory / data), and each distinct image is booted: the check must
    # find the file absent, old or new, its chain sound (no link into a free
    # cluster, EOC at the length its size needs) and the journal idle.
    # Class granularity only; `tests/host/fs-tests` `power_cut::*` enumerates
    # every per-sector subset. Canary, run by hand: delete barrier 1 of the
    # overwrite arm in `write_file_journaled` (after the PENDING record) and
    # a cut that keeps only the FAT writes of that epoch prints
    # `FATBARRIER] FAIL ... FREE`.
    fat_barrier_scenario() {
        local label="storage: journal power cuts"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log1="$CI_LOG_DIR/fat-barrier-boot1.log"
        local log2="$CI_LOG_DIR/fat-barrier-cut.log"
        local img="$CI_LOG_DIR/fat-barrier.img"
        local pristine="$CI_LOG_DIR/fat-barrier-pristine.img"
        local wlog="$CI_LOG_DIR/fat-barrier.wlog"
        local crash="$CI_LOG_DIR/fat-barrier-crash.img"
        local cuts="$CI_LOG_DIR/fat-barrier-cuts.txt"
        rm -f "$log1" "$log2" "$img" "$pristine" "$wlog" "$crash" "$cuts"
        if ! kbuild "qemu,fat-barrier-smoke"; then return; fi
        rm -f $AZOS_OUT/build/disk.img
        make_disk $AZOS_OUT/build/disk.img
        cp $AZOS_OUT/build/disk.img "$img"; cp $AZOS_OUT/build/disk.img "$pristine"
        if ! qemu-img create -f raw "$wlog" 256M >/dev/null 2>&1; then
            bad; echo "      qemu-img could not create the write log"; return
        fi
        local pid i
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 1 \
            -blockdev "driver=blklogwrites,node-name=d0,file.driver=file,file.filename=$img,log.driver=file,log.filename=$wlog,log-sector-size=512,log-super-update-interval=1" \
            -device virtio-blk-device,drive=d0,write-cache=on >"$log1" 2>&1 &
        pid=$!; i=0
        while [ "$i" -lt 240 ]; do
            grep -aqE "FATBARRIER\] (parked|FAIL)" "$log1" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log1" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.25
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        if ! grep -aq "VIRTIO-BLK\] flush: negotiated" "$log1" 2>/dev/null \
           || ! grep -aqF "FATBARRIER] check: BARRIER.DAT absent" "$log1" 2>/dev/null \
           || ! grep -aqF "FATBARRIER] parked" "$log1" 2>/dev/null; then
            bad; echo "      boot 1 did not negotiate FLUSH, start without BARRIER.DAT, or park:"
            grep -a "VIRTIO-BLK\] flush\|FATBARRIER\]" "$log1" | tr -d '\r' | sed "s|^|        |"
            echo "      log kept: $log1"; return
        fi
        if ! python3 tools/blklog_crash_image.py --cuts "$pristine" "$wlog" >"$cuts" 2>"$cuts.sum"; then
            bad; echo "      could not list the cut images: $(cat "$cuts.sum")"; return
        fi
        local k cls n=0 absent=0 old=0 new=0
        while read -r k cls; do
            # stdin from /dev/null for both: this loop reads the cut list
            # on stdin, and QEMU (-nographic) would swallow the rest of it.
            python3 tools/blklog_crash_image.py --cut "$k" "$cls" "$pristine" "$wlog" "$crash" </dev/null || {
                bad; echo "      could not build cut $k $cls"; return; }
            rm -f "$log2"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 1 \
                -drive "file=$crash,if=none,format=raw,id=d0" \
                -device virtio-blk-device,drive=d0 </dev/null >"$log2" 2>&1 &
            pid=$!; i=0
            while [ "$i" -lt 240 ]; do
                grep -aqE "FATBARRIER\] (check|FAIL)" "$log2" 2>/dev/null && break
                grep -aqiE "panic|\[FATAL\]" "$log2" 2>/dev/null && break
                kill -0 "$pid" 2>/dev/null || break
                i=$((i + 1)); sleep 0.25
            done
            kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
            if ! grep -aqE "FATBARRIER\] check: BARRIER.DAT (absent|old|new), chain sound, journal idle" "$log2"; then
                bad; echo "      cut in epoch $k keeping classes '$cls' ($(cat "$cuts.sum")):"
                grep -a "FATBARRIER\]\|FAT32\] Journal" "$log2" | tr -d '\r' | sed "s|^|        |"
                cp "$log2" "$log2.kept"; echo "      logs kept: $log1 $log2.kept"; return
            fi
            n=$((n + 1))
            grep -aqF "BARRIER.DAT absent" "$log2" && absent=$((absent + 1))
            grep -aqF "BARRIER.DAT old" "$log2" && old=$((old + 1))
            grep -aqF "BARRIER.DAT new" "$log2" && new=$((new + 1))
        done <"$cuts"
        # All three outcomes must have been reached, or the cuts did not span
        # the operations they claim to.
        if [ "$n" -lt 3 ] || [ "$absent" -eq 0 ] || [ "$old" -eq 0 ] || [ "$new" -eq 0 ]; then
            bad; echo "      $n cut boots: absent=$absent old=$old new=$new -- the cuts do not span create + overwrite"
            return
        fi
        ok; echo "      $n cut boots: absent=$absent old=$old new=$new ($(sed 's/^# //' "$cuts.sum"))"
        rm -f "$log1" "$log2" "$img" "$pristine" "$wlog" "$crash" "$cuts" "$cuts.sum"
    }
    par "storage: journal power cuts" fat_barrier_scenario

    # MMC flush on an SDHCI-v3 host (wave 7, STOR). `mmc.rs` is compiled
    # for QEMU under `mmc-pci` and bound to `sdhci-pci`'s BAR 0; the block
    # device stays virtio. `mmc_flush_smoke` (kernel/src/smokes/storage.rs): write -> flush Ok
    # with at least one CMD13 status read -> read back; a write past the
    # card's end (QEMU answers ADDRESS_ERROR in the CMD24 response) -> flush
    # Err; flush again -> Ok. The canary row builds `mmc-flush-canary`
    # (flush answers Ok at entry, no CMD13) and must see the FAIL line only
    # that path prints. Busy/prg polling and the eMMC CMD6 path are
    # board-only: QEMU's card is never busy and has no cache.
    # Data moves by ADMA2 and completes by the function's INTx interrupt:
    # `mmc_irq_smoke_task` (once the scheduler runs) writes 24 sectors
    # (a three-descriptor table), flushes, reads back, and requires that the
    # driver's handler took the controller's interrupts; the row passes on its
    # `IRQ PASS` line, which only prints after the polled half passed. QEMU's
    # sdhci completes a command inside the MMIO write that issues it, so no
    # wait has to sleep here (`slept` is printed, not required); the sleep and
    # the wake by TID are drivers-tests' (mmc_tests.rs). The poll canary
    # (`mmc-poll-canary`: the driver stays polled, no interrupt is taken) must
    # print the `completions were polled` FAIL.
    mmc_sd_img="$CI_LOG_DIR/mmc-sd.img"
    mkdir -p "$CI_LOG_DIR"
    if kbuild "qemu,mmc-flush-smoke"; then
        rm -f "$mmc_sd_img"; dd if=/dev/zero of="$mmc_sd_img" bs=1M count=64 2>/dev/null
        QEMU_FAIL_RE="$QEMU_FAIL_RE|MMCSMOKE\] (IRQ )?FAIL" \
            par_row qemu_run "storage: mmc flush (sdhci)" "MMCSMOKE] IRQ PASS" 60 -smp 1 \
            -device sdhci-pci -drive file="$mmc_sd_img",if=none,format=raw,id=sd0 \
            -device sd-card,drive=sd0
    fi
    mmc_flush_canary_row() {
        local label="storage: mmc flush canary"
        printf "  %-26s" "${label}..."
        local log="$CI_LOG_DIR/mmc-flush-canary.log" sd="$CI_LOG_DIR/mmc-sd-canary.img"
        rm -f "$log" "$sd"; dd if=/dev/zero of="$sd" bs=1M count=64 2>/dev/null
        if ! kbuild "qemu,mmc-flush-canary" >/dev/null; then
            bad; echo "      qemu,mmc-flush-canary kernel did NOT build (row not run)"; return
        fi
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 1 \
            -device sdhci-pci -drive file="$sd",if=none,format=raw,id=sd0 \
            -device sd-card,drive=sd0 >"$log" 2>&1 &
        local pid=$! i=0
        while [ "$i" -lt 120 ]; do
            grep -aqE "MMCSMOKE\] (PASS|FAIL)" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        if grep -aqF "MMCSMOKE] FAIL flush answered Ok without reading the card status" "$log"; then
            ok; rm -f "$log" "$sd"
        else
            bad; echo "      a flush that never asks the card was not caught — log kept: $log"
        fi
    }
    par "storage: mmc flush canary" mmc_flush_canary_row
    mmc_poll_canary_row() {
        local label="storage: mmc irq canary"
        printf "  %-26s" "${label}..."
        local log="$CI_LOG_DIR/mmc-poll-canary.log" sd="$CI_LOG_DIR/mmc-sd-poll-canary.img"
        rm -f "$log" "$sd"; dd if=/dev/zero of="$sd" bs=1M count=64 2>/dev/null
        if ! kbuild "qemu,mmc-poll-canary" >/dev/null; then
            bad; echo "      qemu,mmc-poll-canary kernel did NOT build (row not run)"; return
        fi
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" -smp 1 \
            -device sdhci-pci -drive file="$sd",if=none,format=raw,id=sd0 \
            -device sd-card,drive=sd0 >"$log" 2>&1 &
        local pid=$! i=0
        while [ "$i" -lt 120 ]; do
            grep -aqE "MMCSMOKE\] IRQ (PASS|FAIL)" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        if grep -aqF "MMCSMOKE] IRQ FAIL completions were polled" "$log"; then
            ok; rm -f "$log" "$sd"
        else
            bad; echo "      a driver that never takes the interrupt was not caught — log kept: $log"
        fi
    }
    par "storage: mmc irq canary" mmc_poll_canary_row
    kbuild "qemu"

    # NVMe as the BOOT disk (Kconfig DRV_NVME, crates/drivers/block/src/nvme.rs).
    # The gate's own FAT32 image on `-device nvme` instead of virtio-blk: the
    # PCI bring-up attaches the controller before `blkdev::init`, so the mount
    # that follows reads from it. Asserts, in this order of weight: the
    # controller came up in IRQ mode (MSI-X into the IMSIC / through the ITS);
    # FAT32 mounted; a task waited by interrupt (`taken` and `slept` both
    # non-zero) and read sector 0 (boot signature 55aa) and flushed Ok; and
    # the PRP self-test (64 sectors over a PRP list against 64 single-sector
    # reads) passed. The canary row builds `nvme-prp-canary` (PRP2 names a data
    # page, not the list) and must see the self-test FAIL.
    # nvme_qemu <riscv64|aarch64> <kernel-image> <log> <disk> [<command line> <stdin>]:
    # the NVMe boot, in the background.
    nvme_qemu() {
        local isa="$1" kimg="$2" log="$3" disk="$4" append=() in="${6:-/dev/null}"
        [ -n "${5:-}" ] && append=(-append "$5")
        if [ "$isa" = riscv64 ]; then
            "$QEMU" -machine virt,aia=aplic-imsic -nographic -bios default -smp 1 -m 256M -kernel "$kimg" ${append[@]+"${append[@]}"} \
                -drive file="$disk",if=none,format=raw,id=nv -device nvme,serial=x,drive=nv <"$in" >"$log" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -m 256M -nographic -kernel "$kimg" ${append[@]+"${append[@]}"} \
                -drive file="$disk",if=none,format=raw,id=nv -device nvme,serial=x,drive=nv <"$in" >"$log" 2>&1 &
        fi
    }
    nvme_boot_boot() { # nvme_boot_boot <riscv64|aarch64> <kernel-image> <log> <disk>
        local isa="$1" kimg="$2" log="$3" disk="$4"
        rm -f "$log"
        par_ready
        nvme_qemu "$isa" "$kimg" "$log" "$disk"
        local qpid=$! i=0
        while [ "$i" -lt 240 ]; do
            grep -aqE "NVME\] prp selftest (PASS|FAIL)|NVME\] controller .* not used|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
    }
    nvme_boot_prepare() { # nvme_boot_prepare <isa> <features>: builds the kernel, echoes the image path
        local isa="$1" feats="$2"
        # `kbuild`/`a64_kbuild` turn Kconfig DRV_PCI and DRV_NVME on for the pci and
        # nvme features (`kb_cfg`): the NVMe id is in the native match table only then.
        if [ "$isa" = riscv64 ]; then
            kbuild "$feats" || return 1
            echo "$KERNEL"
        else
            a64_kbuild "$feats" || return 1
            a64_kernel_check || return 1
            local img="$CI_LOG_DIR/kernel-aarch64-nvme.img"
            cp "$A64_IMG" "$img"; echo "$img"
        fi
    }
    nvme_boot_row() { # nvme_boot_row <riscv64|aarch64>
        local isa="$1" label="nvme: boot disk ($1)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/nvme-boot-$isa.log" disk="$CI_LOG_DIR/nvme-boot-$isa.img" dsrc kimg feats
        if [ "$isa" = riscv64 ]; then dsrc=$AZOS_OUT/build/disk.img; feats=qemu,pci,nvme; else dsrc=$AZOS_OUT/build/disk-aarch64.img; feats=qemu,pci,nvme; fi
        kimg="$(nvme_boot_prepare "$isa" "$feats")" || return
        rm -f "$dsrc" "$disk"; make_disk "$dsrc"; cp "$dsrc" "$disk"
        nvme_boot_boot "$isa" "$kimg" "$log" "$disk"
        if grep -aqE "EXCEPTION\]|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel fault — log kept: $log"; return
        fi
        if grep -aqE "NVME\] controller [0-9a-f:.]+ ns1 [0-9]+ sectors mode=irq depth=" "$log" \
            && grep -aqF "[FS] FAT32 mounted at /fat" "$log" \
            && grep -aqE "NVME\] by interrupt: [1-9][0-9]* taken, [1-9][0-9]* waits slept \(read ok, flush Ok\(\(\)\), sig 55aa\)" "$log" \
            && grep -aqE "NVME\] prp selftest PASS: 64 sectors in 8 pages" "$log"; then
            ok; rm -f "$log" "$disk"
        else
            bad; echo "      expected NVMe in irq mode, FAT32 mounted from it, waits slept by interrupt, flush Ok, PRP self-test PASS — log kept: $log"
            grep -a "NVME\]\|FS\] FAT32" "$log" | tr -d '\r' | sed 's/^/        /'
        fi
    }
    par "nvme: boot disk (riscv64)" nvme_boot_row riscv64
    nvme_canary_row() { # nvme_canary_row <riscv64|aarch64>
        local isa="$1" label="nvme: prp canary ($1)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/nvme-canary-$isa.log" disk="$CI_LOG_DIR/nvme-canary-$isa.img" dsrc kimg feats
        if [ "$isa" = riscv64 ]; then dsrc=$AZOS_OUT/build/disk.img; feats=qemu,pci,nvme-prp-canary; else dsrc=$AZOS_OUT/build/disk-aarch64.img; feats=qemu,pci,nvme-prp-canary; fi
        kimg="$(nvme_boot_prepare "$isa" "$feats")" || return
        cp "$dsrc" "$disk"
        nvme_boot_boot "$isa" "$kimg" "$log" "$disk"
        if grep -aqE "NVME\] prp selftest FAIL" "$log" && ! grep -aqE "NVME\] prp selftest PASS" "$log"; then
            ok; rm -f "$log" "$disk"
        else
            bad; echo "      canary did not bite: a PRP2 that names a data page was not caught — log kept: $log"
        fi
    }
    par "nvme: prp canary (riscv64)" nvme_canary_row riscv64
    # The per-device DMA limit (hwbus Device::dma_mask -> azos_dma::alloc_below
    # -> the NVMe queue and staging pages). QEMU's tree has no `dma-ranges`, so
    # tools/nvme_dma_mask_row.sh boots the same kernel on edited copies of it
    # (none / above RAM / under RAM / translated bus) and checks NVMe comes up
    # or is refused accordingly. Canary (by hand, reverted): `alloc_page` in
    # nvme.rs ignoring `dma_mask` -> the "under RAM" and "translated bus"
    # variants bring NVMe up and the row FAILs.
    nvme_dma_row() { # nvme_dma_row <riscv64>
        local isa="$1" label="nvme: dma limit ($1)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local disk="$CI_LOG_DIR/nvme-dma-$isa.img" out="$CI_LOG_DIR/nvme-dma-$isa.out" kimg feats=qemu,pci,nvme
        kimg="$(nvme_boot_prepare "$isa" "$feats")" || return
        cp "$kimg" "$CI_LOG_DIR/kernel-nvme-dma-$isa"; kimg="$CI_LOG_DIR/kernel-nvme-dma-$isa"
        rm -f "$disk"; make_disk "$AZOS_OUT/build/disk.img"; cp "$AZOS_OUT/build/disk.img" "$disk"
        par_ready
        if "$REPO_ROOT/tools/nvme_dma_mask_row.sh" "$isa" "$kimg" "$disk" >"$out" 2>&1; then
            ok; rm -f "$disk" "$out" "$kimg"
        else
            bad; sed 's/^/      /' "$out"
        fi
    }
    par "nvme: dma limit (riscv64)" nvme_dma_row riscv64
    # dev_boot_shell <pid> <log> <seconds> <reset-bre> <provoke> <then> <stop-ere>:
    # drive the boot's shell (`robot> `) through fd 9, the write end of the
    # fifo QEMU reads: before the reset line, type `provoke` (every 8 s; `-`
    # types nothing) so the device has commands to time out; after it, type
    # `then` (every 8 s), until `stop` is printed after the reset line, the
    # boot panics or exits, or `seconds` pass. Typed one byte per 50 ms (the
    # aarch64 UART's RX path is paced, see `shell_help_row`). Then the boot is
    # killed.
    dev_boot_shell() {
        local pid="$1" log="$2" limit="$3" reset_re="$4" provoke="$5" then="$6" stop="$7" i=0 last=-100 cmd k
        while [ "$i" -lt $((limit * 2)) ] && kill -0 "$pid" 2>/dev/null; do
            grep -aqE "!!! KERNEL PANIC !!!|AARCH64-TRAP\] unhandled|\[FATAL\]" "$log" 2>/dev/null && break
            sed -n "/$reset_re/,\$p" "$log" 2>/dev/null | grep -aqE "$stop" && break
            cmd="$provoke"
            grep -aq "$reset_re" "$log" 2>/dev/null && cmd="$then"
            if [ "$cmd" != - ] && [ $((i - last)) -ge 16 ] && grep -aqF "robot> " "$log" 2>/dev/null; then
                ( for ((k = 0; k < ${#cmd}; k++)); do printf '%s' "${cmd:k:1}"; sleep 0.05; done; printf '\r' ) >&9 2>/dev/null
                last=$i
            fi
            i=$((i + 1)); sleep 0.5
        done
        sleep 1
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    }
    # The NVMe boot disk's reset after a timeout (`dev_reset_verdict`): a lost
    # completion (`nvme-completion-drop`) in a Kconfig CHAOS kernel. The
    # lost one is the first after boot init, whichever command it is (a
    # write-back, often), and its timeout is found by the next command that
    # waits: the shell lists /fat until the reset line, then reads a file no
    # boot step reads (HELLO.TXT: its sectors come from the disk, not the
    # page cache), whose text proves the disk served after the reset.
    nvme_reset_row() { # nvme_reset_row <riscv64|aarch64> <once|twice>
        local isa="$1" mode="$2" label rate dsrc kimg
        if [ "$mode" = once ]; then label="nvme: timeout resets once ($isa)"; rate=1:1; else label="nvme: second timeout latches ($isa)"; rate=1; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/nvme-reset-$mode-$isa.log" disk="$CI_LOG_DIR/nvme-reset-$mode-$isa.img"
        local kcopy="$CI_LOG_DIR/kernel-nvme-reset-$mode-$isa"
        if [ "$isa" = riscv64 ]; then dsrc=$AZOS_OUT/build/disk.img; else dsrc=$AZOS_OUT/build/disk-aarch64.img; fi
        kimg="$(nvme_boot_prepare "$isa" qemu,pci,nvme,chaos)" || return
        cp "$kimg" "$kcopy"
        fresh_disk "$dsrc" || return
        cp "$dsrc.pristine" "$disk"
        local fifo="$CI_LOG_DIR/nvme-reset-$mode-$isa.fifo" reset_re='\[NVME\] controller reset and brought up again'
        rm -f "$log" "$fifo"; mkfifo "$fifo" || { bad; echo "      mkfifo failed: $fifo"; return; }
        par_ready
        nvme_qemu "$isa" "$kcopy" "$log" "$disk" "chaos=nvme-completion-drop:$rate" "$fifo"
        local pid=$!
        exec 9>"$fifo"
        dev_boot_shell "$pid" "$log" 120 "$reset_re" "ls /fat" "cat /fat/HELLO.TXT" \
            "Hello from AzOS FAT32|nvme timed out again"
        exec 9>&-
        rm -f "$disk" "$kcopy" "$fifo"
        dev_reset_verdict "$mode" "$log" BLK nvme "$reset_re" 'Hello from AzOS FAT32'
    }
    par "nvme: timeout resets once (riscv64)" nvme_reset_row riscv64 once
    par "nvme: second timeout latches (riscv64)" nvme_reset_row riscv64 twice
    par "nvme: timeout resets once (aarch64)" nvme_reset_row aarch64 once
    par "nvme: second timeout latches (aarch64)" nvme_reset_row aarch64 twice
    # dev_boot_wait <pid> <log> <seconds> <stop-ere>: until the boot prints
    # `stop`, panics, or exits; then it is killed.
    dev_boot_wait() {
        local pid="$1" log="$2" limit="$3" stop="$4" i=0
        while [ "$i" -lt $((limit * 2)) ] && kill -0 "$pid" 2>/dev/null; do
            grep -aqE "$stop|!!! KERNEL PANIC !!!|AARCH64-TRAP\] unhandled|\[FATAL\]" "$log" 2>/dev/null && break
            i=$((i + 1)); sleep 0.5
        done
        sleep 1
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    }
    # virtio-net's reset after a timeout (`dev_reset_verdict`): a wedged
    # transmit ring (`virtio-net-tx-wedge`) in a Kconfig CHAOS kernel. The
    # traffic is the shell's `dhcp` against QEMU's server, typed until the
    # reset line (the frames sit in the wedged ring until a send finds them
    # past NET_TX_TIMEOUT_MS) and again after it: a lease after the reset
    # line is a DISCOVER and a REQUEST sent and an OFFER and an ACK received
    # through the reset device.
    net_reset_row() { # net_reset_row <riscv64|aarch64> <once|twice>
        local isa="$1" mode="$2" label rate dsrc
        if [ "$mode" = once ]; then label="network: tx timeout resets once ($isa)"; rate=1:1; else label="network: second tx timeout latches ($isa)"; rate=1; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/net-reset-$mode-$isa.log" disk="$CI_LOG_DIR/net-reset-$mode-$isa.img"
        local kcopy="$CI_LOG_DIR/kernel-net-reset-$mode-$isa"
        if [ "$isa" = riscv64 ]; then
            dsrc=$AZOS_OUT/build/disk.img
            kbuild "qemu,chaos" || return; ci_kernel_check || return; cp "$KERNEL" "$kcopy"
        else
            dsrc=$AZOS_OUT/build/disk-aarch64.img
            a64_kbuild "qemu,chaos" || return; a64_kernel_check || return; cp "$A64_IMG" "$kcopy"
        fi
        fresh_disk "$dsrc" || return
        cp "$dsrc.pristine" "$disk"
        local fifo="$CI_LOG_DIR/net-reset-$mode-$isa.fifo" reset_re='\[NET\] virtio-net: device reset and programmed again'
        rm -f "$log" "$fifo"; mkfifo "$fifo" || { bad; echo "      mkfifo failed: $fifo"; return; }
        par_ready
        local dev=(-append "chaos=virtio-net-tx-wedge:$rate" -global virtio-mmio.force-legacy=false
            -drive "file=$disk,if=none,format=raw,id=hd0" -device virtio-blk-device,drive=hd0
            -netdev user,id=n0 -device virtio-net-device,netdev=n0)
        if [ "$isa" = riscv64 ]; then
            "$QEMU" -machine virt -nographic -bios default -smp 2 -kernel "$kcopy" "${dev[@]}" <"$fifo" >"$log" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic -kernel "$kcopy" "${dev[@]}" <"$fifo" >"$log" 2>&1 &
        fi
        local pid=$!
        exec 9>"$fifo"
        dev_boot_shell "$pid" "$log" 150 "$reset_re" dhcp dhcp "DHCP\] Configuration complete|virtio-net timed out again"
        exec 9>&-
        rm -f "$disk" "$kcopy" "$fifo"
        dev_reset_verdict "$mode" "$log" NET virtio-net "$reset_re" 'DHCP\] Configuration complete'
    }
    par "network: tx timeout resets once (riscv64)" net_reset_row riscv64 once
    par "network: second tx timeout latches (riscv64)" net_reset_row riscv64 twice
    par "network: tx timeout resets once (aarch64)" net_reset_row aarch64 once
    par "network: second tx timeout latches (aarch64)" net_reset_row aarch64 twice
    # The xHCI controller's reset after a timeout (`dev_reset_verdict`): a
    # command never answered (`xhci-command-drop`) in a Kconfig CHAOS kernel,
    # with a keyboard and a stick on a `qemu-xhci` (the first boot of a USB
    # device in the gate). The first command after boot init is the first
    # device's Enable Slot; after the reset both are enumerated again and the
    # mass-storage class driver reads the stick's sector 0. The class
    # drivers' side of a reset (their devices go away and come back, the
    # transfers in flight end Disconnected) is tests/host/usb-tests (`reset`).
    usb_reset_row() { # usb_reset_row <riscv64|aarch64> <once|twice>
        local isa="$1" mode="$2" label rate dsrc
        if [ "$mode" = once ]; then label="usb: timeout resets once ($isa)"; rate=1:1; else label="usb: second timeout latches ($isa)"; rate=1; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/usb-reset-$mode-$isa.log" stick="$CI_LOG_DIR/usb-reset-$mode-$isa.img"
        local kcopy="$CI_LOG_DIR/kernel-usb-reset-$mode-$isa"
        if [ "$isa" = riscv64 ]; then
            dsrc=$AZOS_OUT/build/disk.img
            kbuild "qemu,pci,usb-xhci,usb-storage,chaos" || return; ci_kernel_check || return; cp "$KERNEL" "$kcopy"
        else
            dsrc=$AZOS_OUT/build/disk-aarch64.img
            a64_kbuild "qemu,pci,usb-xhci,usb-storage,chaos" || return; a64_kernel_check || return; cp "$A64_IMG" "$kcopy"
        fi
        fresh_disk "$dsrc" || return
        cp "$dsrc.pristine" "$stick"
        rm -f "$log"
        par_ready
        local dev=(-m 256M -append "chaos=xhci-command-drop:$rate" -device qemu-xhci,id=xhci -device usb-kbd,bus=xhci.0
            -drive "if=none,id=stick,format=raw,file=$stick" -device usb-storage,bus=xhci.0,drive=stick)
        if [ "$isa" = riscv64 ]; then
            "$QEMU" -machine virt -nographic -bios default -smp 2 -kernel "$kcopy" "${dev[@]}" </dev/null >"$log" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic -kernel "$kcopy" "${dev[@]}" </dev/null >"$log" 2>&1 &
        fi
        if [ "$mode" = once ]; then
            dev_boot_wait $! "$log" 90 "mass storage sector 0 read|xhci timed out again"
        else
            dev_boot_wait $! "$log" 90 "xhci timed out again"
        fi
        rm -f "$stick" "$kcopy"
        dev_reset_verdict "$mode" "$log" USB xhci '\[USB\] xhci timed out after [0-9]* ms: device reset' \
            'USB\] mass storage sector 0 read: boot signature present'
    }
    par "usb: timeout resets once (riscv64)" usb_reset_row riscv64 once
    par "usb: second timeout latches (riscv64)" usb_reset_row riscv64 twice
    kbuild "qemu"

    # Brain-link key gate (`link-provisioning-enforced`), BOTH directions. build/disk.img
    # carries no link key, so the enforced kernel must refuse; build/disk-linkkey.img
    # carries one, so the same kernel must boot past the gate. Testing only the
    # refusal would pass just as happily on a gate wired to always refuse.
    par "link auth rejects missing key" kq "qemu,use-robot,link-provisioning-enforced" "link auth rejects missing key" "SECCHAN] FATAL" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    rm -f $AZOS_OUT/build/disk-linkkey.img
    make_disk $AZOS_OUT/build/disk-linkkey.img
    par_row qemu_run "link auth accepts valid key" "brain link authenticated" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-linkkey.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # THE ENCRYPTED BRAIN LINK, END TO END. The scenario above shows
    # the key loads; this one runs the link the key protects: a handshake,
    # sealed frames both ways, a REKEY in each direction, a tampered frame the
    # kernel closes on, and a second handshake. The peer is `tools/link_peer.py`, which imports
    # AzOSRobotBrain's `secure_channel.py` — the brain's implementation, not a
    # copy — and reads the PSK out of the image this kernel boots.
    #
    # Two smoke features. `actuation-smoke`, because the PKT_ESTOP the peer
    # seals right after its REKEY is asserted the way `safety: brain e-stop
    # (tcp)` asserts it: on the wheels, never on the console line — see that
    # scenario for why a handler that prints and does not latch must read red.
    # `link-rekey-smoke`, because the kernel's own rekey interval is an hour;
    # under the feature it is 5 s, so its REKEY records reach the peer.
    #
    # Its own boot sequence, not `run_brain_peer_boot`, which starts
    # `tools/fake_brain.py`. The race that helper documents is handled the same
    # way — wait on the peer's verdict, never on a kernel line — with one
    # addition: QEMU starts only once the peer says `listening`, because the
    # peer reads LINK.KEY out of the image with mtools and QEMU locks it.
    #
    # `link_peer_scenario <label> <camera 0|1>`: with a camera port (C1), the
    # image's CONFIG.INI sets `behavior_camera_port` (a free port, as the
    # control port is) and the peer also accepts the kernel's camera
    # connections there; every assertion below still holds,
    # and the camera connection adds its own.
    link_peer_scenario() {
        local label="$1" camera_port="$2" tag="link-peer"
        if [ "$camera_port" != 0 ]; then tag="link-camera"; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/${tag}.log"
        local blog="$CI_LOG_DIR/${tag}-peer.log"
        local img="$AZOS_OUT/build/disk-${tag}.img"
        rm -f "$log" "$blog"

        if ! python3 tools/link_peer.py --selftest >"$blog" 2>&1; then
            bad; echo "      tools/link_peer.py --selftest failed: AzOSRobotBrain's"
            echo "      secure_channel is not importable or no longer matches the peer,"
            echo "      so a boot would fail for the wrong reason:"
            grep -a "FAIL\|Error" "$blog" | sed -n "1,3p" | sed "s|^|      |"
            echo "      log kept: $blog"; return
        fi
        if ! "$CARGO" build --release --features qemu,actuation-smoke,link-rekey-smoke \
                >/dev/null 2>&1; then
            bad; echo "      kernel build with link-rekey-smoke failed; not booting the"
            echo "      previous binary in its place."; return
        fi
        # Hermetic: a fresh LINK.KEY image, and a copy only this boot writes.
        rm -f $AZOS_OUT/build/disk-linkkey.img "$img"
        make_disk $AZOS_OUT/build/disk-linkkey.img
        cp $AZOS_OUT/build/disk-linkkey.img "$img"
        # Ports of its own, never 9000/9001: every other disk+NIC guest on the
        # host dials 9000, and a stranger reaching this peer is accepted as
        # session 2 at phase 5 (see `peer_port_image`). The peer binds free
        # ports (`--port 0`, `--camera-port -1`) and prints them; this copy's
        # CONFIG.INI is pointed at them once it says `listening`, which it
        # prints after reading LINK.KEY, so the rewrite never races that read.
        local cam_arg=0
        [ "$camera_port" != 0 ] && cam_arg=-1
        python3 tools/link_peer.py --port 0 --camera-port "$cam_arg" --image "$img" \
            >>"$blog" 2>&1 &
        local bpid=$!
        local i=0
        while [ "$i" -lt 30 ]; do
            grep -aq "\[link-peer\] listening\|\[link-peer\] FAIL" "$blog" 2>/dev/null && break
            kill -0 "$bpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        local port cport="" extra=""
        port=$(sed -n 's/^\[link-peer\] listening on [0-9.]*:\([0-9][0-9]*\) .*/\1/p' "$blog" | sed -n 1p)
        if [ "$camera_port" != 0 ]; then
            cport=$(sed -n 's/^\[link-peer\] camera listener on [0-9.]*:\([0-9][0-9]*\)$/\1/p' "$blog" | sed -n 1p)
            extra="behavior_camera_port=${cport:-none}"
        fi
        if [ -z "$port" ] || { [ "$camera_port" != 0 ] && [ -z "$cport" ]; } \
           || ! peer_port_image "$img" "$port" "$extra"; then
            kill "$bpid" 2>/dev/null; wait "$bpid" 2>/dev/null
            bad; echo "      could not point $img at the peer's ports (${port:-none}/${cport:-none}):"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed -n "1,3p" | sed "s|^|      |"
            echo "      log kept: $blog"; return
        fi
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$img",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 \
            -netdev user,id=net0 -device virtio-net-device,netdev=net0 \
            >"$log" 2>&1 &
        local qpid=$!
        i=0
        while [ "$i" -lt 720 ]; do
            grep -aq "\[link-peer\] PASS\|\[link-peer\] FAIL" "$blog" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            kill -0 "$bpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        # Settle: the kernel logs a dispatch after the peer has written it.
        sleep 2
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        kill "$bpid" 2>/dev/null; wait "$bpid" 2>/dev/null

        if grep -aq "FAIL no-robot" "$blog" 2>/dev/null; then
            bad; echo "      the kernel's brain link never connected to the peer."
            echo "      logs kept: $log $blog"; return
        fi
        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        local sid1
        sid1=$(grep -a "\[link-peer\] session 1 established sid=" "$blog" 2>/dev/null \
               | sed -n '1s/.*sid=//p')
        if [ -z "$sid1" ]; then
            bad; echo "      no encrypted-link handshake completed between the kernel and the peer:"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed "s|^|      |"
            grep -a "\[BRAIN\] hs:\|encrypted.link" "$log" 2>/dev/null | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        # Phases 1-3: a SensorPacket opened, drive frames sealed, then the
        # brain's REKEY + PKT_ESTOP and more drive frames under the new keys.
        # A kernel that refuses records after a REKEY stops the peer here.
        if ! grep -aq "\[link-peer\] phase 3 done" "$blog" 2>/dev/null; then
            bad; echo "      the peer did not get through its REKEY + PKT_ESTOP phase:"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed "s|^|      |"
            grep -a "encrypted-link record layer" "$log" 2>/dev/null | sed -n "1,2p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        # The e-stop sealed after the brain's REKEY must have LATCHED. Same
        # evidence as `safety: brain e-stop (tcp)`: both wheels drove before
        # it, and each wheel's last applied duty is 0 with its last non-zero
        # duty before the latch, while the peer kept commanding 60 %.
        local estop_line
        estop_line=$(grep -an "\[BRAIN\] ESTOP received" "$log" 2>/dev/null \
                     | sed -n "1p" | cut -d: -f1)
        if [ -z "$estop_line" ]; then
            bad; echo "      THE E-STOP SEALED AFTER THE BRAIN'S REKEY NEVER REACHED THE"
            echo "      TCP HANDLER: the peer sent it and kept driving, and the kernel"
            echo "      neither latched nor refused the session."
            echo "      logs kept: $log $blog"; return
        fi
        local drove_l drove_r
        drove_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        drove_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null \
                  | grep -v "duty=0$" | awk -F: -v n="$estop_line" '$1 < n' | grep -c .)
        if [ "$drove_l" -lt 1 ] || [ "$drove_r" -lt 1 ]; then
            bad; echo "      the sealed drive frames never moved the wheels before the"
            echo "      e-stop (left=$drove_l right=$drove_r), so a later duty=0 proves"
            echo "      nothing about the latch."
            grep -a -m6 "ACTSMOKE] kernel motor" "$log" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        local last_l last_r nz_l nz_r w
        last_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null | sed -n '$p')
        last_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null | sed -n '$p')
        nz_l=$(grep -an "ACTSMOKE] kernel motor id=0 duty=" "$log" 2>/dev/null \
               | grep -v "duty=0$" | sed -n '$p' | cut -d: -f1)
        nz_r=$(grep -an "ACTSMOKE] kernel motor id=1 duty=" "$log" 2>/dev/null \
               | grep -v "duty=0$" | sed -n '$p' | cut -d: -f1)
        for w in "$last_l:$nz_l" "$last_r:$nz_r"; do
            local rec nz val
            rec=${w%:*}; nz=${w##*:}; val=${rec##*duty=}
            if [ -z "$rec" ] || [ "$val" != "0" ] || [ -z "$nz" ] \
               || [ "$nz" -gt "$estop_line" ]; then
                bad; echo "      THE E-STOP SEALED AFTER THE BRAIN'S REKEY DID NOT HOLD. Each"
                echo "      wheel's last applied duty must be 0, and its last NON-ZERO duty"
                echo "      must fall before the latch; got:"
                echo "        left : ${last_l:-<none>}   (last non-zero at line ${nz_l:-<none>})"
                echo "        right: ${last_r:-<none>}   (last non-zero at line ${nz_r:-<none>})"
                echo "      e-stop at line $estop_line"
                echo "      logs kept: $log $blog"; return
            fi
        done

        # Phase 4: kernel records kept opening after the brain's REKEY, and at
        # least one kernel REKEY record arrived with records opened after it.
        local p4 krekeys
        p4=$(grep -a "\[link-peer\] phase 4 done" "$blog" 2>/dev/null | sed -n '1p')
        krekeys=$(printf '%s\n' "$p4" | sed -n 's/.*kernel_rekeys=\([0-9]*\).*/\1/p')
        if [ -z "$krekeys" ] || [ "$krekeys" -lt 1 ]; then
            bad; echo "      no kernel REKEY record followed by an opened kernel record"
            echo "      reached the peer (kernel_rekeys=${krekeys:-<none>}):"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi

        # Phase 5: a tampered frame ends the session with a close (there is no
        # REJECT frame), and the kernel's next dial completes a NEW session.
        local sid2 est
        sid2=$(grep -a "\[link-peer\] session 2 established sid=" "$blog" 2>/dev/null \
               | sed -n '1s/.*sid=//p')
        if ! grep -aq "\[link-peer\] phase 5 done" "$blog" 2>/dev/null \
           || [ -z "$sid2" ] || [ "$sid2" = "$sid1" ]; then
            bad; echo "      the tampered frame did not end in a close and"
            echo "      a second handshake with a new session id"
            echo "      (session 1: $sid1, session 2: ${sid2:-<none>}):"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed "s|^|      |"
            grep -a "encrypted-link record layer" "$log" 2>/dev/null | sed -n "1,2p" | sed "s|^|      |"
            # The kernel closes first here and redials at once; a refused
            # connect or handshake reads as a TCP-layer fault, not a link one.
            grep -a "connect failed rc\|handshake stalled\|\[BRAIN\] hs:" "$log" 2>/dev/null \
                | sed -n "1,3p" | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        est=$(grep -ac "\[BRAIN\] encrypted link established" "$log" 2>/dev/null)
        if [ "${est:-0}" -lt 2 ]; then
            bad; echo "      the peer saw two sessions but the kernel logged ${est:-0}"
            echo "      established links, want >= 2."
            echo "      logs kept: $log $blog"; return
        fi
        if [ "$camera_port" = 0 ]; then
            # Without the key the kernel creates no camera task at all.
            if grep -aq "Created camera-tx task" "$log" 2>/dev/null; then
                bad; echo "      no behavior_camera_port is set, yet the kernel created camera-tx."
                echo "      logs kept: $log $blog"; return
            fi
        else
            # C1: camera frames on a connection of their own. The peer's
            # `camera phase N done` lines carry the assertions: frames and a
            # kernel REKEY on it, closing with its control session, a new one
            # with the next session, four distinct session ids, no camera frame
            # on a control connection and nothing else on a camera one.
            if ! grep -aq "\[link-peer\] camera phase 5 done" "$blog" 2>/dev/null; then
                bad; echo "      the camera connection did not complete its phases:"
                grep -a "\[link-peer\] FAIL\|\[link-peer\] camera" "$blog" 2>/dev/null \
                    | sed -n "1,4p" | sed "s|^|      |"
                grep -a "\[CAM-TX\]" "$log" 2>/dev/null | sed -n "1,4p" | sed "s|^|      |"
                echo "      logs kept: $log $blog"; return
            fi
            # The kernel must say it closed the camera connection because its
            # control session ended (or was replaced before the task looked).
            if ! grep -aq "\[CAM-TX\] closed (Control\(Ended\|Replaced\))" "$log" 2>/dev/null; then
                bad; echo "      the peer saw the camera connection close, but the kernel never"
                echo "      logged closing it for its control session:"
                grep -a "\[CAM-TX\]" "$log" 2>/dev/null | sed -n "1,4p" | sed "s|^|      |"
                echo "      logs kept: $log $blog"; return
            fi
        fi
        if ! grep -aq "\[link-peer\] PASS" "$blog" 2>/dev/null; then
            bad; echo "      the peer did not finish its script:"
            grep -a "\[link-peer\] FAIL" "$blog" 2>/dev/null | sed "s|^|      |"
            echo "      logs kept: $log $blog"; return
        fi
        ok; mv -f "$log" "$log.green"; mv -f "$blog" "$blog.green"   # the last green pair, to diff a red one against
    }
    par_row -s link_peer_scenario "link: encrypted end to end" 0   # the peer on a host port of its own
    # C1: the same link with camera frames on a connection of their own.
    par_row -s link_peer_scenario "link: camera connection" 1   # 1: with a camera port

    # ── The userspace ELFs the gate never executed ─────────────────────
    #
    # Of eleven programs under `userspace/`, four were never run by any
    # scenario. Two of those are worth running and are added here. Of the other
    # two:
    #
    #   * `hello` is hand-written assembly (hello.S), covered by the ELF loader
    #     path the other scenarios already exercise, and stays out.
    #   * `brain_client` needed a live brain server on the host. It is booted
    #     now, against `tools/fake_brain.py`, by `userspace: ring-3 drives
    #     motors`, `userspace: ring-3 reconnects` and `userspace: ring-3 e-stop`.
    #
    # **gpio_drv is the one that matters.** It is the ring-3 driver: userspace
    # registers as the handler for DRV_KIND_GPIO and the kernel dispatches a
    # real request to it. Nothing else in the gate crosses that boundary in
    # that direction. It was built into every disk image since E11.AQ3 and made
    # the autorun of none of them, so the whole path shipped untested.
    #
    # The marker is the kernel's own confirmation of the round trip, not the
    # driver's "I started" line: a driver that registers and then answers
    # nothing would satisfy the latter.
    kbuild "qemu,use-robot"   # the bench (robot domain) and the GPIO driver row boot the robot cell
    rm -f $AZOS_OUT/build/disk-gpiodrv.img
    make_disk $AZOS_OUT/build/disk-gpiodrv.img
    # The smoke's own verdict counts here, where gpio_drv is the autorun, and
    # only here (see QEMU_FAIL_RE).
    #
    # Wave 10 (DRV2): before that line the smoke counts gpio_drv's idle
    # serve-loop passes over 3 s with no client (`[AQ3] gpio_drv idle:`).
    # Parked in DOMAIN_DRIVER_REPLY_WAIT it wakes about once a second (the
    # kernel's park bound); `[AQ3] gpio_drv idle FAIL` (above 5/s) is a
    # verdict. Canary: gpio_drv back on its 581 + yield poll measured
    # ~155 000/s. `[AQ3] proxy round trip FAIL` (more than 16 of the 32 timed
    # pings unanswered) is one too: it is what a submit that stops waking the
    # parked driver prints.
    #
    # Wave 7: the marker is the line printed AFTER the round trip, with the
    # answering driver's live priority and class read from the scheduler by
    # its registered TID. 24/best_effort is what the `GPIODRV.ELF` topology
    # row declares (`SERVICE_PRIORITY`, above the shell's 26); before the
    # topology was applied it read 16. Any other value is a verdict line that
    # only the failure prints, so it is matched as one rather than timing out.
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[AQ3\] GPIO ring-3 (round-trip FAILED|unexpected reply)|\[AQ3\] gpio_drv idle FAIL|\[AQ3\] proxy round trip FAIL|\[AQ3\] gpio_drv tid=[0-9]+ runs at priority=([^2]|2[^4]|24[0-9])|\[AQ3\] gpio_drv tid=[0-9]+ runs at priority=24 class=[^b]" \
    par_row qemu_run "userspace: ring-3 GPIO driver" "gpio_drv tid=.* runs at priority=24 class=best_effort" 180 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-gpiodrv.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # The minimal Rust ring-3 ELF (E11.AQ3 phase-1). Trivial by design, and
    # that is the point: it is the smallest thing that proves the loader, the
    # linker script and the libsys entry path still work, so when a bigger
    # program fails to start this says whether the cause is upstream of it.
    #
    # It is also the runtime proof that a call OUTSIDE a binary's seccomp
    # profile is refused. The kernel installs UHELLO.ELF's profile at exec
    # (`IMAGE_PROFILES` in crates/core/sched/src/seccomp.rs: putchar, exit, write),
    # and uhello then issues SYS_IPC_FAST_CALL_EP, which the native
    # entries send through their IPC branch (Chain E cut 7): filtered, the
    # kernel records the denial and kills it; unfiltered, its null capability
    # is refused and it prints `FAILED:`, which QEMU_FAIL_RE reports. The
    # marker is the kill line for that number, read from the ABI (it was a
    # literal, and went stale when the call was renumbered).
    # The host half — every shipped binary has a row, each row equals what its
    # source issues, everything else is refused — is `tests/host/seccomp-tests`.
    rm -f $AZOS_OUT/build/disk-uhello.img
    make_disk $AZOS_OUT/build/disk-uhello.img
    uhello_nr="$(sed -n 's/^pub const SYS_IPC_FAST_CALL_EP: u64 = \([0-9][0-9]*\);.*/\1/p' "${REPO_ROOT}/crates/core/abi/src/syscall_nr.rs")"
    par_row qemu_run "userspace: minimal Rust ELF" "killed: syscall ${uhello_nr:-SYS_IPC_FAST_CALL_EP-not-found} not in its profile" 120 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-uhello.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # ── The 41 measurements nobody was reading ─────────────────────────
    #
    # `domains/robot/bench` (10 subsystems) runs on **every** boot and emits 41
    # `[BENCH-RES]` lines: ipc, mm, sched, net, fs, crypto, cap, ota, protocol,
    # asyncrt. The gate looked at none of them. A subsystem
    # whose benchmark stopped emitting -- because it panicked, was cfg'd out,
    # or was quietly deleted -- would take its measurement with it and the gate
    # would stay green.
    #
    # **The count, not the values.** A cycle threshold in a gate measures the
    # host's load, not the kernel; this file already says so about latbench,
    # and the same reasoning applies with more force here, where the numbers
    # come from `rdcycle` under TCG SMP. What IS gate-able is that every
    # subsystem still produces its measurement, and that is what breaks
    # silently.
    #
    # 49 verified stable across five runs from different builds. If a
    # subsystem is legitimately added or removed, this number changes with it
    # -- deliberately, so the change has to be noticed. 49 -> 41 (2026-10-24),
    # each with the code it measured: ipc.signal_send/_pending (ipc::signal and
    # its retired syscalls deleted), ipc.channel_send_recv/_full_send/
    # _create_destroy (the v1 message channel deleted), ipc.lease_active_count
    # (the IPC lease table deleted), auth.envelope_wrap/_unwrap (the brain
    # link's HMAC envelope deleted: Noise only).
    #
    # Not covered, and it is worth knowing why: `tools/bench_e2e.sh` (468
    # lines) drives the throughput and latency scenarios end to end, but needs
    # a live brain server on the host. That is why nobody runs it, and why it
    # is not gated here.
    fresh_disk $AZOS_OUT/build/disk-uhello.img
    par_row qemu_run "bench: all 41 measurements" "run_all done emitted=41 " 180 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-uhello.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # ── The ring-3 driver serves a MORE urgent client on its own hart ─────
    #
    # `UserDriverProxy` used to wait for a ring-3 driver's reply with a
    # million-iteration spin: a client more urgent than the driver on the
    # driver's hart spun the whole bound and the driver never ran. It now
    # blocks (wake by TID on the reply), and for the span of the wait donates
    # its priority to the driver — the priority-donation mechanism. Blocking alone is
    # not enough: `proxy_pi_smoke` puts a prio-20 task that only yields between
    # the client (14) and gpio_drv (24) on gpio_drv's hart, so without the
    # donation the hart goes to that task and every attempt ends at the proxy's
    # 100 ms timeout. Marker: the answered call, with the driver back at its
    # base priority after it. `[PROXYPI] FAIL` (incl. `FAIL TIMEOUT`, which only
    # the timeout path prints) is a verdict. Canary: `proxy-donation-canary`
    # (never donates) fails here on `FAIL TIMEOUT`.
    #
    # Wave 9: then a client at 8 (hard-RT band) calls the same driver; the
    # donation must lend gpio_drv 12, the ring-3 floor, not 8. The marker is
    # that second verdict, printed only after the first passed. Canary:
    # `donation-floor-canary` (no floor) fails on `FAIL floor: gpio_drv was
    # lent 8, below the ring-3 floor 12`.
    #
    # Placed after the bench row and before the seccomp block, whose first act
    # is `kbuild "qemu"`: no later row inherits this kernel. Reuses the gpio_drv
    # disk the `ring-3 GPIO driver` row built.
    kbuild "qemu,proxy-pi-smoke"
    fresh_disk $AZOS_OUT/build/disk-gpiodrv.img
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[PROXYPI\] FAIL|\[AQ3\] GPIO ring-3 (round-trip FAILED|unexpected reply)" \
    par_row qemu_run "userspace: ring-3 driver serves a more urgent client on its hart" "PROXYPI] PASS floor" 180 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-gpiodrv.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0

    # ── A crashed ring-3 driver is restarted, three times and no more ─────
    #
    # The kernel stops gpio_drv (`driver_request_stop`: it exits
    # with 137 at its next driver call) four times. Kills 1-3: the supervisor
    # holds the GPIO driver-server slot, creates a successor from the same
    # image (re-read, re-hashed), hands it the slot, and the successor answers
    # a ping; the row prints death -> successor created -> registered -> first
    # reply in ms (wall clock under TCG: the cold-restart baseline a faster
    # restore would be compared against). Kill 4: the budget (3) is spent, the kind
    # must stay down for 3 s, and the flight recorder must hold exactly three
    # more restart records and one more give-up than before kill 1.
    # `[SUP] FAIL` is a verdict. Canary: `sup-canary` (supervisor off) fails
    # on `[SUP] FAIL not restarted after kill 1`, which only a driver that
    # never came back prints. Wave 12 (EXIT2): the supervisor is woken from the
    # post-teardown exit hook, and a wake while the dead driver still holds its
    # address space fails the smoke (`[SUP] FAIL the supervisor was woken N
    # time(s) while ...`); canary by hand, 2026-10-03: wake from `exit_done`
    # again -> that line, N = 4, both ISAs. Its own disk copy: the recorder count must not
    # see another boot's records, and the other gpio rows must not see these.
    # Before the seccomp block's `kbuild "qemu"`, like the row above.
    kbuild "qemu,sup-smoke"
    rm -f $AZOS_OUT/build/disk-gpiodrv-sup.img
    cp $AZOS_OUT/build/disk-gpiodrv.img $AZOS_OUT/build/disk-gpiodrv-sup.img
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[SUP\] FAIL|\[AQ3\] GPIO ring-3 (round-trip FAILED|unexpected reply)" \
    # Alone, like the restart-window row below: its restart budget is judged
    # against the clock, and with other jobs running it once read "restarted
    # past the budget" (2026-10-03).
    par_row -s qemu_run "userspace: a crashed ring-3 driver is restarted" "SUP] PASS" 240 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-gpiodrv-sup.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    rm -f $AZOS_OUT/build/disk-gpiodrv-sup.img

    # ── The supervisor's restart window and Restart=on-failure ───────────
    #
    # Owner decisions 2026-09-28 (`crates/core/sched/src/supervisor.rs`): at most
    # SUP_RESTART_BURST restarts within SUP_RESTART_INTERVAL_S (systemd's
    # StartLimitBurst/IntervalSec), and a driver that exits 0 is not restarted.
    # The row above covers the burst at the default interval (300 s). This one
    # builds with the interval set to 5 s in a copy of the primary config, so the
    # Kconfig symbol is what reaches the table: kill gpio_drv (137), wait the
    # interval out, kill it again -> restarted as restart 1 of a FRESH window;
    # then stop it with exit code 0 (the code a driver's own exit(0) passes to
    # task_exit_with_code) -> not restarted, no owner for 3 s. Canaries (by
    # hand, reverted): the window never forgets -> `[SUP] FAIL window`; exit 0
    # treated as a failure -> `[SUP] FAIL restarted after exit 0`. The plain
    # kernel is rebuilt with the primary config afterwards.
    # Absolute, under the primary column's own directory: `azos_limits`'s
    # build script resolves KCONFIG_CONFIG from its crate directory, so a
    # relative path (CI_LOG_DIR is one) builds against no config at all.
    sup_window_cfg="${PRIMARY_DIR}/sup-window.config"
    sed 's/^CONFIG_SUP_RESTART_INTERVAL_S=.*/CONFIG_SUP_RESTART_INTERVAL_S=5/' \
        "$PRIMARY_CONFIG" >"$sup_window_cfg"
    if ! ci_wants "userspace: supervisor restart window"; then
        # Skipped (CI_TIER=rows): leave what the block leaves, the plain kernel.
        ci_skip_rows "userspace: supervisor restart window"
        kbuild "qemu"
    elif ! grep -q '^CONFIG_SUP_RESTART_INTERVAL_S=5$' "$sup_window_cfg"; then
        printf "  %-26s" "userspace: supervisor restart window..."
        bad; echo "      $PRIMARY_CONFIG has no CONFIG_SUP_RESTART_INTERVAL_S to shorten"
    else
        export KCONFIG_CONFIG="$sup_window_cfg"
        kbuild "qemu,sup-window-smoke"
        rm -f $AZOS_OUT/build/disk-gpiodrv-supw.img
        cp $AZOS_OUT/build/disk-gpiodrv.img $AZOS_OUT/build/disk-gpiodrv-supw.img
        QEMU_FAIL_RE="$QEMU_FAIL_RE|\[SUP\] FAIL|\[AQ3\] GPIO ring-3 (round-trip FAILED|unexpected reply)" \
        # Alone: a 5 s window, judged by the in-kernel smoke against the clock;
        # with other jobs running it read "restarted after exit 0" before the
        # supervisor had released the driver (2026-10-03).
        par_row -s qemu_run "userspace: supervisor restart window" "SUP] PASS window" 240 \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file=$AZOS_OUT/build/disk-gpiodrv-supw.img,if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0
        rm -f $AZOS_OUT/build/disk-gpiodrv-supw.img
        export KCONFIG_CONFIG="$PRIMARY_CONFIG"
        kbuild "qemu"
    fi
    rm -f "$sup_window_cfg"


    # ── DRV1 (wave 9): the buzzer and the INA219, in ring 3 ────────────
    #
    # The functional test of the two drivers placed in user space,
    # run by a kernel task (`ring3_drv_smoke`) through the kernel API
    # the syscall handlers call, and checked against the simulated hardware
    # underneath: PWM channel 5's state for the buzzer (440 Hz on, off, a
    # 50 ms 1000 Hz tone that has ended 300 ms later), the fixed 7400 mV /
    # 1500 mA of the simulated INA219 for the power record. The same
    # assertions passed on the in-kernel drivers before they moved.
    #
    # Both drivers now run in ring 3 (`userspace/drivers/buzz_drv`, `userspace/drivers/ina_drv`),
    # started by the kernel because their topology rows say `start = true`
    # (`ring3-driver-start`, on under `qemu`), with the capabilities of those
    # rows; the kernel API is their `UserDriverProxy` client. Only
    # `build/disk-drv.img` carries the two images.
    #
    # Wave 10 (DRV2): each verdict also requires the driver to stay parked
    # while nobody calls it (idle serve-loop passes over 3 s: at most 5/s for
    # the silent buzzer, 15/s for the INA219, which samples at 10 Hz), and
    # the INA219's integrated charge over a 3 s window to be 1500 mA times the
    # measured window within 50..=150% (it is weighted by the driver's clock,
    # not by a nominal cadence). Both fail as `[DRV1] <driver> FAIL:`.
    #
    # One boot per row, one verdict per driver: `[DRV1] <driver> FAIL:` is
    # added to each row's own pattern only, so one driver's failure does not
    # turn the other's row red. The canary row below removes the flag from
    # the buzzer's row.
    kbuild "qemu,ring3-drv-smoke"
    rm -f $AZOS_OUT/build/disk-drvbase.img $AZOS_OUT/build/disk-drv.img
    make_disk $AZOS_OUT/build/disk-drv.img
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[DRV1\] buzzer FAIL" \
    par_row qemu_run "drivers: buzzer" "DRV1] buzzer PASS" 240 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-drv.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    fresh_disk $AZOS_OUT/build/disk-drv.img
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[DRV1\] ina219 FAIL" \
    par_row qemu_run "drivers: INA219 power monitor" "DRV1] ina219 PASS" 240 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-drv.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    # The canary, gated: `ring3-drv-start-canary` builds the same topology
    # with the buzzer row's `start = true` removed. The image is on the same
    # disk, so the ONLY difference is the flag, and nothing must start it:
    # the marker is the verdict only the smoke's registration timeout prints.
    # A buzzer PASS here means something other than the flag starts drivers.
    # The INA219 still starts (its row keeps the flag) and must not fail.
    kbuild "qemu,ring3-drv-start-canary"
    fresh_disk $AZOS_OUT/build/disk-drv.img
    QEMU_FAIL_RE="$QEMU_FAIL_RE|\[DRV1\] buzzer PASS|\[DRV1\] ina219 FAIL|\[compmgr\] start BUZZDRV\.ELF" \
    par_row qemu_run "drivers: no start flag, no driver" "DRV1] buzzer FAIL: no host of the Buzzer interface" 240 \
        -smp 4 -global virtio-mmio.force-legacy=false \
        -drive file=$AZOS_OUT/build/disk-drv.img,if=none,format=raw,id=hd0 \
        -device virtio-blk-device,drive=hd0
    # Wave 11: the buzzer's ring-3 host killed under the component manager's
    # supervision (`supall_row`, defined beside the aarch64 drivers row), and its canary.
    par_row supall_row "drivers: moving driver supervised" rv "" PASS
    par_row supall_row "drivers: moving driver supervised, canary" rv ",supall-canary" FAIL
    # Wave 11 (DRVPLACE): the INA219 in the kernel placement (same readings
    # as `drivers: INA219 power monitor`), its two canaries, and the topology
    # row key `restart` as the component manager reads it (`drvplace_row`,
    # defined beside the aarch64 rows).
    par_row drvplace_row "drivers: INA219 placed in kernel" rv "qemu,ring3-drv-smoke,ina219-kernel" ina-kernel
    par_row drvplace_row "drivers: INA219 placement canary" rv "qemu,ring3-drv-smoke,ina219-placement-canary" ina-canary
    ci_row "drivers: INA219 placement build canary" drvplace_build_canary_row "drivers: INA219 placement build canary" rv
    par_row drvplace_row "drivers: restart = no" rv "qemu,restart-smoke" restart
    par_row drvplace_row "drivers: restart key canary" rv "qemu,restart-canary" restart-canary
    par_row drvplace_row "drivers: buzzer placed in kernel" rv "qemu,ring3-drv-smoke,buzzer-kernel" buzz-kernel

    # ── Seccomp image binding ───────────────────────────────────────────
    #
    # Each seccomp image profile is bound to the SHA-256 of the exact ELF the
    # build ships (crates/core/sched/src/seccomp.rs, build/image_hashes.rs), never to
    # the name it is opened under (owner decision 2026-09-14). Two images from
    # the Makefile, both after `bench: all 41 measurements` so no scenario above
    # inherits the cap-deny-smoke kernel the second one builds. The host half,
    # every binary renamed and replaced, is tests/host/seccomp-tests.
    #
    # RENAMED: uhello's bytes over ABITEST.ELF. Bound by name, uhello would run
    # under ABITEST.ELF's row, which allows its probe (the fast IPC call), and
    # print `FAILED:`. Bound by digest it runs under UHELLO.ELF's row and its
    # probe is refused. Asserted:
    # the kernel's install line naming both, the refusal line, and no abitest.
    seccomp_renamed_scenario() {
        local label="seccomp: renamed image keeps its profile"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/seccomp-renamed.log"
        rm -f "$log"

        kbuild "qemu"
        rm -f $AZOS_OUT/build/disk-abitest.img $AZOS_OUT/build/disk-seccomp-renamed.img
        make_disk $AZOS_OUT/build/disk-seccomp-renamed.img
        job_disk $AZOS_OUT/build/disk-seccomp-renamed.img
        par_ready

        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$JDISK",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 240 ]; do
            grep -aqE "SECCOMP\] tid=|uhello\] FAILED" "$log" 2>/dev/null && break
            grep -aqE "AUTORUN\] REFUSED" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        if grep -aq "ABITEST]" "$log" 2>/dev/null; then
            bad; echo "      abitest ran: the image did not carry uhello's bytes. log kept: $log"; return
        fi
        if ! grep -aqF "[AUTORUN] seccomp: /fat/ABITEST.ELF runs under the UHELLO.ELF profile" "$log" 2>/dev/null; then
            bad; echo "      /fat/ABITEST.ELF was not confined to the profile its bytes are bound to:"
            grep -a -m3 "AUTORUN\] \(REFUSED\|seccomp\)" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        if grep -aq "uhello] FAILED" "$log" 2>/dev/null; then
            bad; echo "      uhello's probe was answered: the renamed binary ran under a wider profile."
            echo "      log kept: $log"; return
        fi
        if ! grep -aq "SECCOMP] tid=" "$log" 2>/dev/null; then
            bad; echo "      uhello gave no verdict. log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "seccomp: renamed image keeps its profile" seccomp_renamed_scenario

    # REPLACED: UHELLO.ELF one byte longer, still a loadable ELF. Its digest
    # matches no shipped ELF, so autorun refuses it before granting anything,
    # writes SAFETY_EXEC_REFUSED durably, and (cap-deny-smoke) reads the record
    # back off LOG00000.BIN. Asserted: the refusal line, the record, and that
    # uhello never printed a line. The kernel is rebuilt without the smoke
    # feature right after QEMU stops, pass or fail.
    seccomp_replaced_scenario() {
        local label="seccomp: replaced image is refused"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/seccomp-replaced.log"
        rm -f "$log"

        kbuild "qemu,cap-deny-smoke"
        rm -f $AZOS_OUT/build/disk-uhello.img $AZOS_OUT/build/disk-seccomp-replaced.img
        make_disk $AZOS_OUT/build/disk-seccomp-replaced.img
        job_disk $AZOS_OUT/build/disk-seccomp-replaced.img
        par_ready

        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 4 -global virtio-mmio.force-legacy=false \
            -drive file="$JDISK",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 240 ]; do
            grep -aqE "AUTORUN\] exec refusal (NOT )?RECORDED" "$log" 2>/dev/null && break
            grep -aq "uhello]" "$log" 2>/dev/null && break
            grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null

        if grep -aqiE "panic|\[FATAL\]" "$log" 2>/dev/null; then
            bad; echo "      kernel panic or fatal exception:"; grep -aiE -m3 "panic|\[FATAL\]|\[PAGE FAULT\]" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        if grep -aq "uhello]" "$log" 2>/dev/null; then
            bad; echo "      the replaced binary ran:"; grep -a -m2 "uhello]" "$log" | sed "s|^|      |"
            echo "      log kept: $log"; return
        fi
        if ! grep -aqF "[AUTORUN] REFUSED: /fat/UHELLO.ELF (" "$log" 2>/dev/null; then
            bad; echo "      autorun did not refuse the replaced image. log kept: $log"; return
        fi
        if grep -aq "exec refusal NOT RECORDED" "$log" 2>/dev/null; then
            bad; echo "      the exec was refused and its record did not reach the disk."
            echo "      log kept: $log"; return
        fi
        if ! grep -aq "exec refusal RECORDED" "$log" 2>/dev/null; then
            bad; echo "      the refusal readback gave no verdict. log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "seccomp: replaced image is refused" seccomp_replaced_scenario
    kbuild "qemu"

    # Shared verdict of the idle-wakes rows (both ISAs), on `delta` timer
    # interrupts over the 30 s window. Wave 13, owner decision round 50:
    # hart 0's idle keepalive runs only while a watchdog is armed.
    #   * no watchdog (QEMU): THRESHOLD delta <= IDLE_WAKES_MAX_30S. Measured
    #     band: 0 on every run (bench-minimal, 30 s windows, host QEMU
    #     census 1-4: riscv64 and aarch64, -smp 1 x5 and -smp 4 x3 each); the
    #     margin of 3 leaves room for the 60 s self-heal ceiling. Linux 6.4 on the same QEMU (riscv64, busybox
    #     shell idle) takes 2.3/s = 69 per 30 s; the old fixed 100 ms keepalive
    #     read 9.3-9.6/s.
    #   * `wdt` (feature `wdt-sim`: the 500 ms timeout recorded as armed): the
    #     boot prints the derived period (`[WDT] idle keepalive on hart 0 every
    #     N us`, timeout / 4 = 125 ms) and the count must sit in the band that
    #     period gives: 228-237 per 30 s on both ISAs (-smp 1 x5, -smp 4 x3; 240
    #     would be exact, the re-arm counts from each wake); THRESHOLD 210-250. A keepalive at the old fixed 100 ms
    #     (~280 per 30 s) or none (0) fails.
    IDLE_WAKES_MAX_30S=3
    idle_wakes_verdict() { # idle_wakes_verdict <mode> <delta> <log>
        local mode="$1" delta="$2" log="$3" per
        if [ "$mode" = wdt ]; then
            per="$(tr -d '\r' <"$log" | sed -n 's/^\[WDT\] idle keepalive on hart 0 every \([0-9][0-9]*\) us.*/\1/p' | sed -n 1p)"
            if [ "$per" != 125000 ]; then
                bad; echo "      the boot did not print the derived keepalive (125000 us; got '${per:-none}') — log kept: $log"; return
            fi
            if [ "$delta" -ge 210 ] && [ "$delta" -le 250 ]; then
                ok; echo "      $delta timer interrupts over 30 s at a ${per} us keepalive (band 210-250)"
                rm -f "$log"
            else
                bad; echo "      $delta timer interrupts over 30 s, outside 210-250 for a ${per} us keepalive — log kept: $log"
            fi
            return
        fi
        if ! tr -d '\r' <"$log" | qgrep -q '^\[WDT\] no watchdog armed: no idle keepalive'; then
            bad; echo "      the boot did not report 'no watchdog armed' — log kept: $log"; return
        fi
        if [ "$delta" -le "$IDLE_WAKES_MAX_30S" ]; then
            ok; echo "      $delta timer interrupts over 30 s (threshold <= $IDLE_WAKES_MAX_30S; Linux: 69)"
            rm -f "$log"
        else
            bad; echo "      $delta timer interrupts over 30 s, above $IDLE_WAKES_MAX_30S: an idle hart"
            echo "      is waking with nothing to do — log kept: $log"
        fi
    }
    # ── 2026-09-25 owner decision Q3.2: idle is truly tickless ───────────────
    #
    # `timebase::set_next_tick_smart` clamped every timer to `now + 1/sched_hz`,
    # so an idle hart woke at sched_hz forever while the scheduler's comments
    # said "tickless". Now `do_schedule()` arms the timer for the NEAREST real
    # deadline when the hart goes idle (hart 0 keeps a 100 ms keepalive for the
    # watchdog feed and the vDSO page; other harts wake by IPI).
    #
    # Measured, wall-clock, riscv64 -smp 1 bench-minimal, 30 s windows, host
    # QEMU census 0: BEFORE 81.9/80.8/81.2 wakeups/s; AFTER 43.5/45.4/41.8.
    # The dominant sleeper in both is the live shell's 20 ms UART poll, so this
    # is a conservative halving, not a zero-sleeper idle. THRESHOLD 70/s sat
    # between the two bands so a regression to the periodic clamp failed here
    # rather than sliding through on host-load noise.
    #
    # Wave 11 ONESHOT: 9/9/9 wakeups/s on c1afd98 and 9/9/9 after the one-shot
    # change (the empty-queue re-arm fix of 2026-09-26 is what took it from 74
    # to 9). THRESHOLD 20/s: twice the measured band. Canary, by hand: idle
    # harts armed with the busy cap (`set_next_tick_tickless` ignoring
    # `hart_idle`) read 73/s here and 68/s on the aarch64 row — FAIL on both.
    #
    # The number is read back, not inferred: `watchdog::TICK_COUNT` (one
    # increment per timer-ISR entry on every hart) via the ELF's symbol table
    # and a live GDB-stub attach (`-s`, never `-S`: the CPU is not halted, the
    # read is a snapshot of a running system). Wall-clock, so NOT `-icount`.
    # Wave 13 (ENERGY): the 9.3-9.6/s floor measured on 9dc76dd9 was hart 0's
    # fixed 100 ms idle keepalive. Round 50 (owner) ties it to an armed
    # watchdog; the verdict and the measured bands are `idle_wakes_verdict`'s.
    tickless_idle_wakeups_row() { # [wdt]: the simulated-watchdog build
        local mode="${1:-}" feats="qemu,bench-minimal"
        local label="riscv64: idle wakeups/s (tickless)"
        if [ "$mode" = wdt ]; then
            feats="qemu,use-robot,bench-minimal,wdt-sim"; label="riscv64: idle keepalive (simulated WDT)"
        fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        if ! command -v riscv64-elf-gdb >/dev/null 2>&1; then
            bad; echo "      riscv64-elf-gdb not installed — the row cannot read TICK_COUNT back"; return
        fi
        kbuild "$feats" || return
        local addr
        # Leading zeros stripped: nm prints 16 hex digits (000000008067d338),
        # gdb echoes the address back as 0x8067d338: — the grep in
        # read_ticks() below keys on gdb's spelling. With the zeros kept
        # both reads came back empty (hand run, 2026-09-26).
        addr=$(nm "$KERNEL" 2>/dev/null | grep "watchdog10TICK_COUNT" | sed -n '1{s/ .*//p;}' | sed 's/^0*//')
        if [ -z "$addr" ]; then
            bad; echo "      watchdog::TICK_COUNT symbol not found in $KERNEL"; return
        fi
        local log="$CI_LOG_DIR/tickless-idle${mode:+-$mode}.log"
        rm -f "$log"
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -smp 1 -m 128M -s >"$log" 2>&1 </dev/null &
        local qpid=$!
        sleep 10
        if ! kill -0 "$qpid" 2>/dev/null; then
            bad; echo "      qemu exited during boot — log kept: $log"; return
        fi
        read_ticks() {
            riscv64-elf-gdb -q -batch -ex "target remote localhost:1234" \
                -ex "x/1xg 0x${addr}" -ex "detach" 2>/dev/null \
                | grep "0x${addr}:" | grep -o "0x[0-9a-f]*$"
        }
        local t0_hex t1_hex
        t0_hex=$(read_ticks)
        if [ -z "$t0_hex" ]; then
            kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
            bad; echo "      first GDB read of TICK_COUNT (0x$addr) came back empty — log kept: $log"; return
        fi
        sleep 30
        if ! kill -0 "$qpid" 2>/dev/null; then
            bad; echo "      qemu exited mid-window — log kept: $log"; return
        fi
        t1_hex=$(read_ticks)
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        if [ -z "$t1_hex" ]; then
            bad; echo "      second GDB read of TICK_COUNT (0x$addr) came back empty — log kept: $log"; return
        fi
        local delta rate
        delta=$(( t1_hex - t0_hex ))
        rate=$(( delta / 30 ))
        if [ "$delta" -lt 0 ]; then
            bad; echo "      TICK_COUNT went backwards ($t0_hex -> $t1_hex) — log kept: $log"; return
        fi
        idle_wakes_verdict "$mode" "$delta" "$log"
    }
    par -s "riscv64: idle wakeups/s (tickless)" tickless_idle_wakeups_row   # gdb on 1234, wall clock
    par -s "riscv64: idle keepalive (simulated WDT)" tickless_idle_wakeups_row wdt   # gdb on 1234

    # ── net-poll in IRQ mode: zero idle iterations (wave 8 FORKX, wave 9) ────
    #
    # With a virtio-net-pci NIC in MSI-X mode, `net_poll_task` sleeps with no
    # timer while no TCP connection has a clock deadline (`tcp::tick_needed()`
    # false): only an RX MSI or a `tcp::set_timer_kick` wake gives it work,
    # plus a 60 s self-heal ceiling. Before that it woke 10 times a second
    # (300 in 30 s, measured wave 8); a 1 ms poll-mode timer is ~600/s.
    #
    # The numbers are read back like the tickless row's, via the ELF's symbol
    # table and a live GDB attach: `NET_POLL_ITERS` (one increment per loop
    # iteration), `NET_MSI_WAKES` (every RX MSI's wake, dispatched or stamped)
    # and `NET_TIMER_KICKS` (a TCP deadline armed elsewhere). The window
    # starts 2 s after the task's own first line and lasts 30 s, so it ends
    # before the 60 s ceiling can fire. An iteration an RX MSI or a kick
    # explains is work, not a timer: the boot's own SNTP client (Kconfig
    # NTP_CLIENT, the net-clients task, 2026-10-17) resolves its server and
    # asks it the time in the window, and slirp's two answers woke the poller
    # twice (main ac10a4be: 2 iterations, read as a timer by the old
    # `delta == 0`). The verdict is the rest — iterations minus MSI wakes
    # minus kicks — and it must be 0 or less (an MSI landing while the
    # poller runs is counted and folded into the iteration it is already
    # in). A wake neither explains is a timer, and none is tolerated: the
    # netdev runs with `ipv6=off`, so no RA reaches the guest and no SLAAC
    # address (nor its DAD timer, folded into `tcp::next_deadline`) is formed
    # in the window. Positive anchors first — IRQ mode's own NIC line and the task's
    # start — because a boot with NO NIC also reads 0 (the no-NIC mode has
    # no timer either) and must not pass this row.
    #
    # Canary (`netpoll-idle-timer-canary`): the IRQ mode keeps the poll
    # mode's period, the leftover re-arm this row is for; the row must read
    # hundreds of unexplained iterations and fail. Measured 2026-10-24 (load
    # 20-24): the row 4 iterations, 2 MSI wakes, 2 kicks, 0 on a timer; the
    # canary 14 790 iterations, 14 788 on a timer. Compile-error bucket: a
    # build failure is its own FAIL.
    netpoll_irq_idle_row() { # netpoll_irq_idle_row <features> <pass|canary>
        local feats="$1" want="$2" label="riscv64: net-poll idle (irq)"
        [ "$want" = canary ] && label="riscv64: net-poll idle canary"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        if ! command -v riscv64-elf-gdb >/dev/null 2>&1; then
            bad; echo "      riscv64-elf-gdb not installed — the row cannot read NET_POLL_ITERS back"; return
        fi
        kbuild "$feats" || return
        local addr msi kick port="${NETPOLL_GDB_PORT:-1234}"
        netpoll_sym() { nm "$KERNEL" 2>/dev/null | grep "net_poll$1" | sed -n '1{s/ .*//p;}' | sed 's/^0*//'; }
        addr=$(netpoll_sym 14NET_POLL_ITERS); msi=$(netpoll_sym 13NET_MSI_WAKES); kick=$(netpoll_sym 15NET_TIMER_KICKS)
        if [ -z "$addr" ] || [ -z "$msi" ] || [ -z "$kick" ]; then
            bad; echo "      NET_POLL_ITERS / NET_MSI_WAKES / NET_TIMER_KICKS not all found in $KERNEL"; return
        fi
        local log="$CI_LOG_DIR/netpoll-irq-idle-$want.log"
        rm -f "$log"
        "$QEMU" -machine virt,aia=aplic-imsic -nographic -bios default -kernel "$KERNEL" \
            -smp 1 -m 128M -gdb "tcp::${port}" \
            -device virtio-net-pci,netdev=n0,disable-legacy=on -netdev user,id=n0,ipv6=off >"$log" 2>&1 </dev/null &
        local qpid=$! i=0
        while [ "$i" -lt 120 ]; do
            grep -aqF "[NET-POLL] Phase U1: dedicated network polling task started" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        if ! grep -aqF "[NET-POLL] Phase U1: dedicated network polling task started" "$log" 2>/dev/null; then
            kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
            bad; echo "      net-poll never started within 60 s — log kept: $log"; return
        fi
        if ! grep -aq "\[NET\] virtio-net-pci .* mode=irq msix=y" "$log" 2>/dev/null \
           || grep -aqF "[NET-POLL] no NIC ready" "$log" 2>/dev/null; then
            kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
            bad; echo "      the NIC is not in IRQ mode, so 0 iterations would prove nothing:"
            grep -a "\[NET\] virtio-net\|\[NET\] VirtIO\|NET-POLL\]" "$log" | tr -d '\r' | sed 's/^/        /'
            echo "      log kept: $log"; return
        fi
        sleep 2
        # One attach, the three counters: prints `iters msi_stamped
        # msi_dispatched kicks` (gdb's hex), or nothing when a read failed.
        read_counts() {
            riscv64-elf-gdb -q -batch -ex "target remote localhost:${port}" \
                -ex "x/1xg 0x${addr}" -ex "x/2xw 0x${msi}" -ex "x/1xw 0x${kick}" -ex "detach" 2>/dev/null \
                | tr '\t' ' ' | awk -v a="0x${addr}:" -v m="0x${msi}:" -v k="0x${kick}:" '
                    $1 == a { i = $2 } $1 == m { s = $2; d = $3 } $1 == k { c = $2 }
                    END { if (i != "" && s != "" && d != "" && c != "") print i, s, d, c }'
        }
        local c0 c1
        c0=$(read_counts)
        if [ -z "$c0" ]; then
            kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
            bad; echo "      first GDB read of the net-poll counters came back empty — log kept: $log"; return
        fi
        sleep 30
        if ! kill -0 "$qpid" 2>/dev/null; then
            bad; echo "      qemu exited mid-window — log kept: $log"; return
        fi
        c1=$(read_counts)
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        if [ -z "$c1" ]; then
            bad; echo "      second GDB read of the net-poll counters came back empty — log kept: $log"; return
        fi
        local i0 s0 d0 k0 i1 s1 d1 k1
        read -r i0 s0 d0 k0 <<<"$c0"
        read -r i1 s1 d1 k1 <<<"$c1"
        # The task has run its first iteration (the counter is live).
        if [ $(( i0 )) -lt 1 ]; then
            bad; echo "      NET_POLL_ITERS read $(( i0 )) at the window start: the counter never moved — log kept: $log"; return
        fi
        local iters=$(( i1 - i0 )) msis=$(( s1 - s0 + d1 - d0 )) kicks=$(( k1 - k0 ))
        local timer=$(( iters - msis - kicks ))
        local line="net-poll in 30 s idle: $iters iteration(s), $msis RX MSI wake(s), $kicks kick(s): $timer on a timer"
        if [ "$want" = pass ] && [ "$timer" -le 0 ]; then
            ok; echo "      $line"; rm -f "$log"
        elif [ "$want" = canary ] && [ "$timer" -gt 0 ]; then
            ok; echo "      $line"; rm -f "$log"
        elif [ "$want" = pass ]; then
            bad; echo "      $line, expected 0:"
            echo "      the poller is waking on a timer in IRQ mode — log kept: $log"
        else
            bad; echo "      $line: the canary's poll-period timer did not show — log kept: $log"
        fi
    }
    par -s "riscv64: net-poll idle (irq)" netpoll_irq_idle_row qemu,pci pass   # gdb port, wall clock
    par -s "riscv64: net-poll idle canary" netpoll_irq_idle_row qemu,pci,netpoll-idle-timer-canary canary

    # ── RVV: the build that was compiled and never run ─────────────────
    #
    # `rvv` was in the build matrix and in NO scenario, and it was not a
    # cosmetic difference: `--features rvv` used to forward
    # `azos_sched/rvv`, which took a **different wake path** -- `saved =
    # true` unconditionally, `clear_saving_on_no_switch` a no-op, and the
    # `context_saving` spin-gate compiled out entirely (12 divergent `cfg`
    # sites in the scheduler). A build that compiles is not a build that works,
    # and this one had never executed a single instruction.
    #
    # CLOSED 2026-09-24. `context_switch_rvv.S` now clears `context_saving`
    # with the same `fence rw, w` + `sb` release tail as the scalar switch, so
    # all twelve `cfg` sites are deleted and `azos_sched/rvv` no longer
    # exists. An rvv build takes the identical scheduler path.
    #
    # **This paragraph used to claim the gap could not reach a board** --
    # "`--features k1` does NOT enable `azos_sched/rvv`, tested with a
    # temporary `compile_error!`". That was true when written and became FALSE
    # when `k1` was changed to compose `rvv` (`k1 = ["rvv", ...]`) instead of
    # hand-copying four of its five members. Cargo features are transitive, so
    # `k1` -> `rvv` -> `azos_sched/rvv`: the one board with real vector
    # hardware was selecting the undefended scheduler, for as long as this
    # comment said it was not. A negative claim about a feature's reach has to
    # be re-derived from the composition, never grepped for its name.
    #
    # Needs a V-capable CPU: QEMU's default `rv64` has the vector extension
    # off, so the kernel would take an illegal-instruction trap on its first
    # vector op. `-cpu rv64,v=true` is therefore part of the scenario, not an
    # optimisation.
    par "rvv: vector path runs" kq "qemu,rvv" "rvv: vector path runs" "Phase 11 complete" 120 \
        -smp 4 -cpu rv64,v=true,vlen=256,elen=64

    # ── rvv: vector state isolated across tasks (2026-09-26) ─────────────────
    # rvv_ctx_save/restore indexed VEC_STATES[] by Task+120 = ctx.tp (the hart
    # id), not Task.tid (offset 128); every context switch under `rvv` handed
    # one task's v0-v31 to another. Fixed by threading offset_of!(Task, tid)
    # through global_asm!. VecState was also sized for VLEN=128 while the K1
    # (X60) is 256: now sized by vlenb at boot, refused when wider. The probe
    # (`rvv-isolation-probe`): two kernel tasks pinned to hart 0 fill v0-v31
    # with distinct patterns, yield 8 times, and check; OK only if both survive.
    # Runs at vlen=256 like the row above; the old sizing page-faults there.
    QEMU_FAIL_RE="$QEMU_FAIL_RE|RVV\] ISOLATION FAILED" \
        par "rvv: vector state isolated" kq "qemu,rvv,rvv-isolation-probe" "rvv: vector state isolated" "RVV] ISOLATION OK" 60 \
            -smp 4 -cpu rv64,v=true,vlen=256,elen=64
    kbuild "qemu"
    # ── Native PCI enumeration (riscv64) ───────────
    # ECAM and the 32-bit BAR window from the DTB's `pci-host-ecam-generic`
    # node (`[PCI] host bridge: ... (dtb)`; `(built-in)` would mean the
    # kernel fell back to its constants), the PLIC from its own
    # `riscv,plic0` node; one `[PCI]` line per function,
    # keyed on the vendor:device pair QEMU itself assigns (1af4:1042 virtio-
    # blk, 1b36:0010 nvme, 1af4:1041 virtio-net). BAR addresses are 0x0 here —
    # no firmware assigns them. Plain `virt` (PLIC); the AIA machine has its
    # own rows below.
    pci_enum_row_riscv64() {
        local label="pci: bus 0 enumerates (riscv64)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        kbuild "qemu,pci" || return
        dd if=/dev/zero of="$CI_LOG_DIR/pci-blk.img" bs=1M count=8 2>/dev/null
        dd if=/dev/zero of="$CI_LOG_DIR/pci-nvme.img" bs=1M count=8 2>/dev/null
        local log="$CI_LOG_DIR/pci-enum-riscv64.log"
        rm -f "$log"
        par_ready
        "$QEMU" -machine virt -nographic -bios default -kernel "$KERNEL" \
            -drive file="$CI_LOG_DIR/pci-blk.img",if=none,format=raw,id=hd0 \
            -device virtio-blk-pci,drive=hd0,disable-legacy=on \
            -drive file="$CI_LOG_DIR/pci-nvme.img",if=none,format=raw,id=hd1 \
            -device nvme,serial=deadbeef,drive=hd1 \
            -netdev user,id=net0 -device virtio-net-pci,netdev=net0,disable-legacy=on \
            >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 60 ]; do
            grep -aq "PCI\] pci 00:03.0 1af4:1041" "$log" 2>/dev/null && break
            grep -aqE "$QEMU_FAIL_RE" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        if grep -aqE "$QEMU_FAIL_RE" "$log" 2>/dev/null; then
            bad; echo "      kernel fault during PCI enumeration — log kept: $log"; return
        fi
        if grep -aq "PCI\] pci 00:01.0 1af4:1042" "$log" \
            && grep -aq "PCI\] pci 00:02.0 1b36:0010" "$log" \
            && grep -aq "PCI\] pci 00:03.0 1af4:1041" "$log" \
            && grep -aq "msix=y" "$log" \
            && grep -aqF "[PCI] host bridge: ECAM 0x30000000 (dtb), mem32 0x40000000+0x40000000 (dtb)" "$log" \
            && grep -aqF "[DTB] UART=0x10000000, PLIC=0xc000000" "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      expected DTB-sourced ECAM/mem32 and PLIC, and virtio-blk 1af4:1042, nvme 1b36:0010, virtio-net 1af4:1041 with msix=y — log kept: $log"
        fi
    }
    par "pci: bus 0 enumerates (riscv64)" pci_enum_row_riscv64
    kbuild "qemu"

    # ── AIA (APLIC MSI mode + IMSIC) and MSI-X (riscv64) ──
    # Same kernel on `virt,aia=aplic-imsic`: no PLIC there (HEAD took a
    # Store/AMO access fault at stval 0xc000004). The kernel drives one
    # virtio-net-pci TX completion over MSI-X into the boot hart's IMSIC
    # file and prints the per-vector counts; `used=1` says the device
    # completed the frame, `vec1 ... count=N` says its MSI arrived. stdin is
    # flooded with `x` so UART RX interrupts cross APLIC -> IMSIC during boot
    # (identity 10 count at scheduler start). Canary: azos_pci's
    # `msix-enable-canary` leaves MSI-X Enable clear -> the device falls back
    # to INTx, `used` still moves, vec1 stays 0 and only then the kernel
    # prints `delivery FAILED`.
    pci_aia_boot_riscv64() { # pci_aia_boot_riscv64 <log>
        local log="$1"
        local blk="${log%.log}-blk.img" nvme="${log%.log}-nvme.img"
        dd if=/dev/zero of="$blk" bs=1M count=8 2>/dev/null
        dd if=/dev/zero of="$nvme" bs=1M count=8 2>/dev/null
        rm -f "$log"
        # PACED input, one byte per 50 ms. It was `yes x`: QEMU feeds stdin as
        # fast as the guest drains it, one RX interrupt per byte with no line
        # rate, and the boot went bimodal — 1-3 s usually, 30-120+ s sometimes,
        # on BOTH gate 187's and gate 188's kernels (5+5 hand runs). Gate 188
        # failed on that slow mode (killed at 60 s, still in boot Phase D).
        # A real UART is bounded (115200 baud ≈ 11.5 k bytes/s); a handful of
        # bytes proves the property. Paced: 5/5 delivered in ~1 s. Before
        # wave 11, no input read "delivered 0 time(s)". Since then identity 10
        # also carries the console's TX interrupt (`uart::enable_tx_irq`), so
        # the count is nonzero with no input too: the `[1-9]` check below
        # proves UART interrupts cross APLIC -> IMSIC, not RX ones in
        # particular.
        aia_paced_input() { while :; do printf x || break; sleep 0.05; done; }
        par_ready
        aia_paced_input 2>/dev/null | "$QEMU" -machine virt,aia=aplic-imsic -nographic -bios default -kernel "$KERNEL" \
            -drive file="$blk",if=none,format=raw,id=hd0 \
            -device virtio-blk-pci,drive=hd0,disable-legacy=on \
            -drive file="$nvme",if=none,format=raw,id=hd1 \
            -device nvme,serial=deadbeef,drive=hd1 \
            -netdev user,id=net0 -device virtio-net-pci,netdev=net0,disable-legacy=on \
            >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 60 ]; do
            grep -aq "IRQ\] AIA identity 10 (uart) delivered" "$log" 2>/dev/null && break
            grep -aqE "EXCEPTION\]|$QEMU_FAIL_RE" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
    }
    pci_aia_msix_row_riscv64() {
        local label="aia: msix + uart via imsic"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        kbuild "qemu,pci" || return
        local log="$CI_LOG_DIR/pci-aia-riscv64.log"
        pci_aia_boot_riscv64 "$log"
        if grep -aqE "EXCEPTION\]|$QEMU_FAIL_RE" "$log" 2>/dev/null; then
            bad; echo "      fault or FAILED line on the AIA machine — log kept: $log"; return
        fi
        # The AIA machine has no PLIC: the DTB line says so and the bus lists
        # none (a PLIC node would be `[HWBUS] plic@...`).
        if grep -aq "HWBUS\] plic@" "$log" 2>/dev/null; then
            bad; echo "      the bus listed a PLIC on the AIA machine — log kept: $log"; return
        fi
        if grep -aq "DTB\] AIA: APLIC=" "$log" \
            && grep -aqF "[DTB] UART=0x10000000, PLIC=none" "$log" \
            && grep -aqE "PCI\] msix 00:03.0 enabled=y .* tx used=1$" "$log" \
            && grep -aqE "PCI\] msix 00:03.0 vec0 id=[0-9]+ count=[0-9]+ vec1 id=[0-9]+ count=[1-9]" "$log" \
            && grep -aqE "IRQ\] AIA identity 10 \(uart\) delivered [1-9]" "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      expected AIA selected, PLIC=none, MSI-X vec1 count>0 with used=1, uart identity 10 count>0 — log kept: $log"
        fi
    }
    par "aia: msix + uart via imsic" pci_aia_msix_row_riscv64
    pci_aia_msix_canary_riscv64() {
        local label="aia: msix canary (enable off)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        kbuild "qemu,pci,azos_pci/msix-enable-canary" || return
        local log="$CI_LOG_DIR/pci-aia-canary-riscv64.log"
        pci_aia_boot_riscv64 "$log"
        # `delivery FAILED` is printed only when the completion happened
        # (used=1) and its vector count stayed 0 — the property broken.
        if grep -aq "EXCEPTION\]" "$log" 2>/dev/null; then
            bad; echo "      fault on the AIA machine — log kept: $log"
        elif grep -aqE "PCI\] msix 00:03.0 delivery FAILED: used=1 but vec1 count=0" "$log" \
            && grep -aqE "PCI\] msix 00:03.0 enabled=n " "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      canary did not bite: expected enabled=n and 'delivery FAILED: used=1' — log kept: $log"
        fi
    }
    par "aia: msix canary (enable off)" pci_aia_msix_canary_riscv64
    kbuild "qemu"

    # ── The kernel's NIC over virtio-pci + MSI-X (riscv64) ──
    # `network: DHCP lease`'s smoke with the NIC as a virtio-net-pci function
    # on `virt,aia=aplic-imsic`: the driver runs in IRQ mode (MSI-X vector 1 =
    # RX, into the boot hart's IMSIC file) and reads the RX ring only after
    # that vector fired, so a lease is proof the RX MSIs arrived. `rx=0`
    # before and `rx=[1-9]` after are the driver's own ISR-hook counts.
    # Canary: `msix-enable-canary` leaves MSI-X Enable clear. The driver still
    # runs in IRQ mode (it decides by route, never by the enable read-back),
    # no RX MSI arrives, no frame is read and the lease fails — while
    # `network: DHCP lease` (MMIO, polled) passes on the same stack.
    # [QEMU args] put an IOMMU on the bus, and the NIC then goes through it
    # (`iommu_platform=on`, as the aarch64 helper says).
    pci_net_dhcp_boot_riscv64() { # pci_net_dhcp_boot_riscv64 <log> [stop ERE] [QEMU args before the NIC...]
        local log="$1" stop="${2:-NET\] msix counts \(after dhcp\)}" nic=""
        shift; [ $# -gt 0 ] && shift
        [ $# -gt 0 ] && nic=",iommu_platform=on"
        rm -f "$log"
        par_ready
        "$QEMU" -machine virt,aia=aplic-imsic -nographic -bios default -kernel "$KERNEL" "$@" \
            -netdev user,id=net0 -device "virtio-net-pci,netdev=net0,disable-legacy=on$nic" \
            </dev/null >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 90 ]; do
            grep -aqE "$stop" "$log" 2>/dev/null && break
            grep -aqE "EXCEPTION\]|panic" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
    }
    pci_net_dhcp_row_riscv64() {
        local label="network: DHCP lease (pci)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        kbuild "qemu,pci,dhcp-smoke" || return
        local log="$CI_LOG_DIR/pci-net-dhcp-riscv64.log"
        pci_net_dhcp_boot_riscv64 "$log"
        if grep -aqE "EXCEPTION\]|panic" "$log" 2>/dev/null; then
            bad; echo "      fault on the AIA machine — log kept: $log"; return
        fi
        # tx=0 or 1 before DHCP: with VIRTIO_F_EVENT_IDX QEMU signals the first used
        # entry of a queue unconditionally (signalled_used_valid), so the TX self-check's
        # first completion interrupts once; TX completions stay off after that.
        if grep -aqE "NET\] virtio-net-pci [0-9a-f:.]+ mode=irq msix=y " "$log" \
            && grep -aqF "[PCI] host bridge: ECAM 0x30000000 (dtb), mem32 0x40000000+0x40000000 (dtb)" "$log" \
            && grep -aqE "NET\] msix counts \(before dhcp\): config=0 rx=[01] tx=[01]([^0-9]|$)" "$log" \
            && grep -aqF "[DHCPSMOKE] PASS" "$log" \
            && grep -aqE "NET\] msix counts \(after dhcp\): config=[0-9]+ rx=([2-9]|[1-9][0-9]+)" "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      expected mode=irq msix=y, DTB-sourced host bridge, rx<=1 before (the Router Advertisement), DHCPSMOKE PASS, rx>1 after — log kept: $log"
        fi
    }
    par "network: DHCP lease (pci)" pci_net_dhcp_row_riscv64
    pci_net_dhcp_canary_riscv64() {
        local label="network: pci dhcp canary"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        kbuild "qemu,pci,dhcp-smoke,azos_pci/msix-enable-canary" || return
        local log="$CI_LOG_DIR/pci-net-dhcp-canary-riscv64.log"
        pci_net_dhcp_boot_riscv64 "$log"
        # Bites only when the PCI IRQ path ran (`mode=irq msix=n` is printed
        # by nothing else) AND the lease failed with the RX count still 0.
        if grep -aqE "EXCEPTION\]|panic" "$log" 2>/dev/null; then
            bad; echo "      fault on the AIA machine — log kept: $log"
        elif grep -aqE "NET\] virtio-net-pci [0-9a-f:.]+ mode=irq msix=n " "$log" \
            && grep -aqF "[DHCPSMOKE] FAIL" "$log" \
            && grep -aqF "NET] msix counts (after dhcp): config=0 rx=0 tx=0" "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      canary did not bite: expected mode=irq msix=n, DHCPSMOKE FAIL, rx=0 — log kept: $log"
        fi
    }
    par "network: pci dhcp canary" pci_net_dhcp_canary_riscv64

    # ── IOMMU on (riscv64): the RISC-V IOMMU confines the NIC ──
    # The aarch64 rows' twin with `-device riscv-iommu-pci` (first on the bus):
    # the kernel finds the function through the hardware bus (`riscv-iommu`,
    # class 0x0806), gives virtio-net-pci a translating domain with a PSCID of
    # its own, and the lease must still come through Sv39 with the MSI-X writes
    # into the IMSIC translated too. Canary `iommu-tx-canary` as on aarch64.
    iommu_net_row_riscv64() { # iommu_net_row_riscv64 <label> <PASS|CANARY>
        local label="$1" expect="$2" feats="qemu,pci,dhcp-smoke"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        [ "$expect" = CANARY ] && feats="$feats,iommu-tx-canary"
        kbuild "$feats" || return
        local log="$CI_LOG_DIR/iommu-net-riscv64-$expect.log" stop=""
        [ "$expect" = CANARY ] && stop='IOMMU\] fault|EXCEPTION\]|panic'
        pci_net_dhcp_boot_riscv64 "$log" "$stop" -device riscv-iommu-pci
        iommu_net_verdict "$log" riscv-iommu "$expect" "EXCEPTION\]|panic"
    }
    par "iommu: riscv-iommu translates the NIC" iommu_net_row_riscv64 "iommu: riscv-iommu translates the NIC" PASS
    par "iommu: riscv-iommu refuses unmapped" iommu_net_row_riscv64 "iommu: riscv-iommu refuses unmapped" CANARY
    kbuild "qemu"
    # The runtime half, after the scheduler starts: a host datagram through a
    # UDP hostfwd reaches the NIC, and the ISR of its RX MSI must take
    # net-poll out of its timer sleep (`dispatched=[1-9]`). A missing wake
    # prints its own line ("no ISR wake dispatched"), so it reads red rather
    # than timing out.
    pci_net_rx_wake_riscv64() {
        local label="pci: rx msi wakes net-poll"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local port=47123
        if lsof -iUDP:"$port" >/dev/null 2>&1; then
            bad; echo "      host UDP port $port is in use; row not run"; return
        fi
        kbuild "qemu,pci" || return
        local log="$CI_LOG_DIR/pci-net-rxwake-riscv64.log"
        rm -f "$log"
        "$QEMU" -machine virt,aia=aplic-imsic -nographic -bios default -kernel "$KERNEL" \
            -netdev user,id=net0,hostfwd=udp:127.0.0.1:"$port"-:7777 \
            -device virtio-net-pci,netdev=net0,disable-legacy=on \
            </dev/null >"$log" 2>&1 &
        local qpid=$! i=0
        while [ "$i" -lt 60 ]; do
            grep -aqF "NET-POLL] Phase U1" "$log" 2>/dev/null && break
            grep -aqE "EXCEPTION\]|panic" "$log" 2>/dev/null && break
            kill -0 "$qpid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        sleep 3
        local n
        for n in 1 2 3; do printf 'rxwake-%s' "$n" | nc -u -w1 127.0.0.1 "$port" 2>/dev/null; done
        i=0
        while [ "$i" -lt 20 ]; do
            grep -aqE "NET-POLL\] RX MSI (woke|taken)" "$log" 2>/dev/null && break
            i=$((i + 1)); sleep 1
        done
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null
        if grep -aqE "EXCEPTION\]|panic" "$log" 2>/dev/null; then
            bad; echo "      fault on the AIA machine — log kept: $log"
        elif grep -aqE "NET-POLL\] RX MSI woke this task: rx [0-9]+ -> [0-9]+, dispatched=[1-9]" "$log"; then
            ok; rm -f "$log"
        else
            bad; echo "      no RX MSI wake of net-poll — log kept: $log"
            grep -a "NET-POLL\]" "$log" | tr -d '\r' | sed 's|^|        |'
        fi
        kbuild "qemu"
    }
    par -s "pci: rx msi wakes net-poll" pci_net_rx_wake_riscv64   # UDP host port 47123


    # riscv64 half of `behavior_arp_sleep_row` (defined with the aarch64 rows).
    par -s "network: behavior ARP sleeps" behavior_arp_sleep_row rv

    # ── Worst-case wake-up latency under load (wave 11, LAT) ──────────────
    #
    # cyclictest/timerlat in the kernel (`kernel/src/lat_smoke.rs`): a
    # priority-1 task on hart 0 sleeps to an absolute 1 ms deadline 2000
    # times while a console spammer, a disk reader and a never-blocking CPU
    # hog share the hart, and prints how late it woke (`[LAT] isa=...
    # max_ns= p99_ns=`). `-smp 1 -icount shift=0,sleep=off`: one ns of
    # virtual time per guest instruction, so the numbers do not move with
    # host load (they are not bit-exact: a virtio-blk completion lands where
    # the host thread delivers it). The verdict line is the kernel's:
    # `[LAT] PASS` when max <= BOUND_NS (100 us, both ISAs, since wave 11
    # ONESHOT; it was 12 ms, the 10 ms tick plus 20%, while a timer sleeper
    # on a busy hart waited for the next tick — `BOUND_NS`'s doc), `[LAT]
    # FAIL` (only that path prints it) otherwise. The row also requires every
    # load to have run.
    #
    # The canary row builds `lat-canary` (implies the masked-window tracer,
    # `lat-trace`): a task on the same hart masks interrupts for 20 ms three
    # times and prints its site. It must FAIL, and the tracer must name that
    # site as the worst interrupts-masked window both on the console
    # (`[LATTRACE] run irq top1`) and through the introspection tree's
    # `latency/irqsoff` (`[LATTRACE] inspect ...`). Measured by
    # hand when this landed (wave 11): plain riscv64 max 7.5-8.0 ms, aarch64
    # 9.85 ms; canary 19.8 ms / 19.7 ms with the tracer at the canary line.
    # After ONESHOT (three runs each): riscv64 max 17.9-18.4 us (Sstc),
    # aarch64 11.5-12.8 us. Wave 13, load paced by lat-rt (20 boots each):
    # riscv64 max 4.4-15.8 us, aarch64 3.6-7.3 us.
    #
    # The periodic-arm canary rows build `oneshot-canary`: the arming from
    # before ONESHOT (no reprogram at block time; aarch64's tick handler
    # programs `now + period` only). They must print `[LAT] FAIL`.
    # Wave 13: the riscv64 canary passed 9 of 20 boots while the smoke's load
    # slept on timers of its own (each such deadline made the tick handler
    # program the nearest sleeper, lat-rt's included); paced by lat-rt it
    # fails 18 of 20 (the 2: the boot's 1 ms rt-motor sleeper on hart 0) and
    # aarch64's 20 of 20. A single riscv64 canary PASS is therefore not yet
    # proof the block-time arm is gone — see kernel/src/lat_smoke.rs.
    # Compile-error bucket: a build failure is its own `FAIL` line below.
    lat_wake_row() { # lat_wake_row <label> <isa: rv|arm> <features> <expect: PASS|CANARY|PERIODIC>
        local label="$1" isa="$2" feats="$3" expect="$4"
        # `kbuild` reports its own failure (compile-error bucket) and counts it.
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log disk kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        disk="$CI_LOG_DIR/${slug}-disk.img"
        if [ "$isa" = rv ]; then
            [ -f $AZOS_OUT/build/disk-ipctest.img.pristine ] || make_disk $AZOS_OUT/build/disk-ipctest.img
            cp $AZOS_OUT/build/disk-ipctest.img.pristine "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            # The riscv64 PERIODIC canary measures on hart 1 (kernel/src/lat_smoke.rs
            # HART), away from the boot's 1 kHz sleepers on hart 0.
            local smp=1; [ "$expect" = PERIODIC ] && smp=2
            "$QEMU" -machine virt -nographic -bios default -smp "$smp" -icount shift=0,sleep=off \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
                bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
            fi
            cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 480 ]; do
            grep -aqE '\[LAT\] (PASS|FAIL) ' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$disk" "$kimg"
        # The console starts some lines with a bare CR: anchor on a copy
        # without them, never on the raw log.
        local clean="$log.txt"
        tr -d '\r' <"$log" >"$clean"
        local result load
        result="$(grep -a '^\[LAT\] isa=' "$clean" | sed -n 1p)"
        load="$(grep -a '^\[LAT\] load ' "$clean" | sed -n 1p)"
        if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      the kernel stopped:"; grep -aiE -m3 'panic|\[FATAL\]|AARCH64-TRAP' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if [ -z "$result" ]; then
            bad; echo "      no [LAT] result within the timeout — log kept: $log"; return
        fi
        # Every load ran and the disk never failed: a run with an idle hart
        # measures a different thing (an idle hart re-arms its timer). The
        # PERIODIC canary runs the CPU hog alone (kernel/src/lat_smoke.rs: the
        # paced spam and disk interrupts reprogrammed the comparator and hid
        # the missing arm in 3 boots of 5), so it must show exactly that.
        local want_load='spam_lines=[1-9][0-9]* disk_reads=[1-9][0-9]* disk_errors=0 hog_rounds=[1-9]'
        [ "$expect" = PERIODIC ] && want_load='spam_lines=0 disk_reads=0 disk_errors=0 hog_rounds=[1-9]'
        if ! printf '%s\n' "$load" | qgrep -qE "$want_load"; then
            bad; echo "      the load did not all run: ${load:-no load line}"
            echo "      log kept: $log"; return
        fi
        # Wave 15 (FM), owner rule F1: a `lat-fat` kernel counts FAT32 device
        # I/O the FAT writer issued while it held a Mutex (`[LAT] fat
        # pi_io=`; it takes none itself, so any is FAT32's own). It
        # must be 0; the PICANARY rows (a Mutex held across each FAT update,
        # the VF shape) must count some. Anchored on the whole value.
        # Wave 15 (PI): `pi_io_all` counts the same for EVERY task (the exec
        # bounce buffer and KERNEL_FD_TABLE were the last two, from
        # `behavior`'s spawn of MLSRV.ELF and from MLSRV.ELF's file opens);
        # it must be 0 too. A PISITE:<lock> canary row puts that one lock back
        # as a Mutex held across its I/O: pi_io_all > 0 and a
        # `[LAT] fat pi_io_site` line naming <lock>.
        local pi_io="" pi_io_all=""
        case "$feats" in *lat-fat*|*fat-mutate-pi-canary*)
            pi_io="$(grep -a '^\[LAT\] fat pi_io=' "$clean" | sed -n '1s/^\[LAT\] fat pi_io=\([0-9][0-9]*\) pi_io_all=[0-9][0-9]*$/\1/p')"
            pi_io_all="$(grep -a '^\[LAT\] fat pi_io=' "$clean" | sed -n '1s/^\[LAT\] fat pi_io=[0-9][0-9]* pi_io_all=\([0-9][0-9]*\)$/\1/p')"
            if [ -z "$pi_io" ] || [ -z "$pi_io_all" ]; then
                bad; echo "      no '[LAT] fat pi_io=<n> pi_io_all=<n>' line"; echo "      log kept: $log"; return
            fi ;;
        esac
        # Wave 15 (RL), owner rule F1: virtio-blk waits for a completion with
        # no driver Mutex held (`BLK_LOCK` only around submit/reap). A
        # `lat-fat` kernel prints `[LAT] blk waits=<n> waits_locked=<n>`;
        # the PASS rows need waits > 0 and waits_locked = 0, the BLKCANARY
        # rows (`BLK_LOCK` held across the wait again) waits_locked > 0.
        local blk_line="" blk_locked=""
        case "$feats" in *lat-fat*|*blk-lock-wait-canary*)
            blk_line="$(grep -a '^\[LAT\] blk waits=' "$clean" | sed -n 1p)"
            blk_locked="$(printf '%s\n' "$blk_line" | sed -n 's/^\[LAT\] blk waits=[1-9][0-9]* waits_locked=\([0-9][0-9]*\)$/\1/p')"
            if [ -z "$blk_locked" ]; then
                bad; echo "      no '[LAT] blk waits=<n> waits_locked=<n>' line: ${blk_line:-none}"; echo "      log kept: $log"; return
            fi ;;
        esac
        # Wave 15 (BR): FAT32 device I/O the FAT writer issued with
        # preemption off (`[LAT] fat preempt_off_io=`, a count: it does not
        # follow host load). Every `lat-fat` kernel these rows boot must
        # print 0; the `FAT spinlock canary` rows below must count some.
        case "$feats" in *lat-fat*|*fat-mutate-pi-canary*|*fat-mutate-spin-canary*|*blk-lock-wait-canary*)
            local np_io
            np_io="$(grep -a '^\[LAT\] fat preempt_off_io=' "$clean" | sed -n '1s/^\[LAT\] fat preempt_off_io=\([0-9][0-9]*\) preempt_off_io_all=[0-9][0-9]*$/\1/p')"
            if [ "$np_io" != 0 ]; then
                bad; echo "      FAT device I/O with preemption off, or no '[LAT] fat preempt_off_io=<n> preempt_off_io_all=<n>' line: preempt_off_io=${np_io:-none}"
                echo "      log kept: $log"; return
            fi ;;
        esac
        if [ "$expect" = BLKCANARY ]; then
            if [ "$blk_locked" != 0 ]; then
                ok; echo "      completion waits with BLK_LOCK held: ${blk_line#\[LAT\] } (canary)"; rm -f "$log" "$clean"
            else
                bad; echo "      the BLK_LOCK canary counted no locked wait: ${blk_line#\[LAT\] }"
                echo "      log kept: $log"
            fi
            return
        fi
        if [ -n "$blk_locked" ] && [ "$blk_locked" != 0 ]; then
            bad; echo "      virtio-blk waited for the device with BLK_LOCK held (F1): ${blk_line#\[LAT\] }"
            echo "      log kept: $log"; return
        fi
        case "$expect" in PISITE:*)
            local want_lock="${expect#PISITE:}"
            if [ "$pi_io_all" != 0 ] \
               && grep -aqE "^\[LAT\] fat pi_io_site tid=[0-9]+ outer=0x[0-9a-f]+\(${want_lock}\) " "$clean"; then
                ok; echo "      FAT device I/O under ${want_lock} held as a Mutex: pi_io_all=${pi_io_all} (canary)"; rm -f "$log" "$clean"
            else
                bad; echo "      the ${want_lock} canary did not show: pi_io_all=${pi_io_all}"
                grep -a '^\[LAT\] fat pi_io_site' "$clean" | sed 's/^/      /'
                echo "      log kept: $log"
            fi
            return ;;
        esac
        if [ "$expect" = PICANARY ]; then
            if [ "$pi_io" != 0 ]; then
                ok; echo "      FAT device I/O under a held Mutex: pi_io=${pi_io} (canary)"; rm -f "$log" "$clean"
            else
                bad; echo "      the Mutex canary counted no FAT I/O under it: pi_io=${pi_io}"
                echo "      log kept: $log"
            fi
            return
        fi
        if [ -n "$pi_io" ] && [ "$pi_io" != 0 ]; then
            bad; echo "      FAT device I/O under a held Mutex (F1): pi_io=${pi_io}"
            echo "      log kept: $log"; return
        fi
        if [ -n "$pi_io_all" ] && [ "$pi_io_all" != 0 ]; then
            bad; echo "      FAT device I/O under a held Mutex by some task (F1): pi_io_all=${pi_io_all}"
            grep -a '^\[LAT\] fat pi_io_site' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if [ "$expect" = PASS ]; then
            if grep -aq '^\[LAT\] PASS ' "$clean"; then
                ok; echo "      ${result#\[LAT\] }"
                [ -n "$pi_io" ] && grep -a '^\[LAT\] fat pi_io=' "$clean" | sed -n '1s/^\[LAT\] /      /p'
                grep -a '^\[LAT\] fat preempt_off_io=' "$clean" | sed -n '1s/^\[LAT\] /      /p'
                [ -n "$blk_line" ] && printf '      %s\n' "${blk_line#\[LAT\] }"
                rm -f "$log" "$clean"
            else
                bad; echo "      ${result}"; grep -a '^\[LAT\] FAIL ' "$clean" | sed 's/^/      /'
                echo "      log kept: $log"
            fi
            return
        fi
        # PERIODIC (wave 11 ONESHOT canary): the kernel built with the timer
        # arming from before the one-shot change must fail the bound. Anchored
        # on the line only the failure path prints.
        if [ "$expect" = PERIODIC ]; then
            if grep -aq '^\[LAT\] FAIL ' "$clean"; then
                ok; echo "      ${result#\[LAT\] }"; rm -f "$log" "$clean"
            else
                bad; echo "      the periodic arming did not fail the row: ${result}"
                echo "      log kept: $log"
            fi
            return
        fi
        # CANARY: the verdict is FAIL, and the tracer names the canary's own
        # site as the worst masked window, on the console and in the
        # introspection tree.
        local site
        site="$(grep -a '^\[LATCANARY\] masked ' "$clean" | sed -n 's/.* site=\([^ ]*\)$/\1/p' | sed -n 1p)"
        if [ -z "$site" ]; then
            bad; echo "      the canary task never masked (no [LATCANARY] line) — log kept: $log"; return
        fi
        if ! grep -aq '^\[LAT\] FAIL ' "$clean"; then
            bad; echo "      a ${site} masked window did not fail the row: ${result}"
            echo "      log kept: $log"; return
        fi
        if ! grep -a '^\[LATTRACE\] run irq top1 ' "$clean" | qgrep -qF " site=${site} "; then
            bad; echo "      the tracer's worst irq site is not the canary's (${site}):"
            grep -a '^\[LATTRACE\] run irq top1 ' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if ! grep -a '^\[LATTRACE\] inspect latency/irqsoff/start = ' "$clean" | qgrep -qxF "[LATTRACE] inspect latency/irqsoff/start = ${site}"; then
            bad; echo "      the introspection tree's latency/irqsoff does not name the canary site (${site}):"
            grep -a '^\[LATTRACE\] inspect latency/irqsoff' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log" "$clean"
    }
    par_row -s lat_wake_row "lat: riscv64 wake-up under load" rv "qemu,lat-smoke" PASS
    par_row -s lat_wake_row "lat: riscv64 masked-window canary" rv "qemu,lat-canary" CANARY
    par_row -s lat_wake_row "lat: aarch64 wake-up under load" arm "qemu,lat-smoke" PASS
    par_row -s lat_wake_row "lat: aarch64 masked-window canary" arm "qemu,lat-canary" CANARY
    par_row -s lat_wake_row "lat: riscv64 periodic-arm canary" rv "qemu,oneshot-canary" PERIODIC
    par_row -s lat_wake_row "lat: aarch64 periodic-arm canary" arm "qemu,oneshot-canary" PERIODIC

    # The console's interrupts-masked window (wave 13, RT7): the lat smoke's
    # load prints a ~100-byte line every other period, and with `lat-trace`
    # the tracer names the worst masked windows by site. Every window at a
    # console site (`crates/drivers/sys/src/uart.rs`) must be at most
    # 2,000 ns of -icount time. Kernel lines are formatted before the UART
    # lock (`kernel_print`) and copied into the TX ring in blocks
    # (`TxRing::put`): measured 1,800 ns riscv64, 1,935 ns aarch64, the same
    # in 5 runs each. Before, one line's hold was 9.7 us (formatting under
    # the lock), longer than the timer-ISR entry. Canary (by hand,
    # 2026-10-04): `console-format-in-lock` -> 14,800 ns riscv64, 8,774 ns
    # aarch64, red. Compile errors: the build's own FAIL line. The smoke
    # prints every site the run's tracks kept (the 64 longest), not the
    # worst five: since other sites passed 7 us (2026-10) a 2 us console
    # window ranks below the fifth and a top-5 read could not see it, so the
    # row waits for the smoke's verdict line, which follows the summary.
    console_window_row() { # console_window_row <label> <isa: rv|arm> <features>
        local label="$1" isa="$2" feats="$3"
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log disk kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        disk="$CI_LOG_DIR/${slug}-disk.img"
        if [ "$isa" = rv ]; then
            [ -f $AZOS_OUT/build/disk-ipctest.img.pristine ] || make_disk $AZOS_OUT/build/disk-ipctest.img
            cp $AZOS_OUT/build/disk-ipctest.img.pristine "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            "$QEMU" -machine virt -nographic -bios default -smp 1 -icount shift=0,sleep=off \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
                bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
            fi
            cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 480 ]; do
            grep -aqE '^\[LAT\] (PASS|FAIL) ' "$log" 2>/dev/null && break
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$disk" "$kimg"
        local clean="$log.txt" sites worst
        tr -d '\r' <"$log" >"$clean"
        sites="$(grep -a '^\[LATTRACE\] run irq top' "$clean")"
        if [ -z "$sites" ]; then
            bad; echo "      no [LATTRACE] run irq lines — log kept: $log"; return
        fi
        if ! printf '%s\n' "$sites" | qgrep -q 'site=crates/drivers/sys/src/uart.rs:'; then
            bad; echo "      no console window among the $(printf '%s\n' "$sites" | wc -l | tr -d ' ') traced sites (did the load print?); the worst five:"
            printf '%s\n' "$sites" | sed -n 1,5p | sed 's/^/      /'; echo "      log kept: $log"; return
        fi
        worst="$(printf '%s\n' "$sites" | grep 'site=crates/drivers/sys/src/uart.rs:' \
            | sed -n 's/.* max_ns=\([0-9]*\) .*/\1/p' | sort -n | sed -n '$p')"
        if [ -z "$worst" ] || [ "$worst" -gt 2000 ]; then
            bad; echo "      console masked window ${worst:-?} ns > 2000 ns:"
            printf '%s\n' "$sites" | grep uart.rs | sed 's/^/      /'; echo "      log kept: $log"; return
        fi
        ok; echo "      console masked window max ${worst} ns"; rm -f "$log" "$clean"
    }
    par_row -s console_window_row "console: masked window rv" rv "qemu,lat-smoke,lat-trace"
    par_row -s console_window_row "console: masked window arm" arm "qemu,lat-smoke,lat-trace"

    # ── Wake-up latency under FAT32 writes (wave 15, VF) ──────────────────
    #
    # The lat smoke with `lat-fat`: its disk load rewrites /fat/LATFAT.BIN
    # (6 KiB: chain allocation, free, journal barriers) every 1.37 ms, not
    # paced by lat-rt, while lat-rt (priority 1, same hart) measures its
    # wake-ups against the same 100 us bound. The cause these rows pin:
    # `FAT_MUTATE` (crates/fs/fs/src/fat32.rs) was a `SpinLock`, so the
    # allocator's FAT scan and entry writes, each a virtio-blk round trip,
    # ran with preemption off on the writer's hart — and under -icount the
    # length followed host load: one cause of the intermittent `rt7: panic
    # contain` row, whose contained panic appends CRASH.LOG on the control
    # hart. Then a `Mutex` (VF), measured (tracer on, 2026-10-09): preempt-off max riscv64
    # 9.93 ms -> 11.5 us, aarch64 1.70 ms -> 11.4 us; wake max riscv64
    # 9.79 ms -> 9.2 us, aarch64 1.25 ms -> 8.1 us. Now (FM) no lock at all
    # across the FAT update's I/O: per-FAT-sector claims (see below).
    #
    # The canary rows build `fat-mutate-spin-canary` (the `SpinLock` back,
    # with the tracer): the FAT writer issues device I/O with preemption off
    # (`[LAT] fat preempt_off_io=` > 0; the rows above require 0). Compile
    # errors: the build's own FAIL line.
    fat_lat_canary_row() { # fat_lat_canary_row <label> <isa: rv|arm> <features>
        local label="$1" isa="$2" feats="$3"
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log disk kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        disk="$CI_LOG_DIR/${slug}-disk.img"
        if [ "$isa" = rv ]; then
            [ -f $AZOS_OUT/build/disk-ipctest.img.pristine ] || make_disk $AZOS_OUT/build/disk-ipctest.img
            cp $AZOS_OUT/build/disk-ipctest.img.pristine "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            "$QEMU" -machine virt -nographic -bios default -smp 1 -icount shift=0,sleep=off \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
                bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
            fi
            cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 480 ]; do
            grep -aqE '\[LAT\] (PASS|FAIL) ' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$disk" "$kimg"
        local clean="$log.txt" result top max
        tr -d '\r' <"$log" >"$clean"
        result="$(grep -a '^\[LAT\] isa=' "$clean" | sed -n 1p)"
        if [ -z "$result" ] || grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      no [LAT] result, or the kernel stopped — log kept: $log"; return
        fi
        if ! grep -a '^\[LAT\] load ' "$clean" | qgrep -qE 'disk_reads=[1-9][0-9]* disk_errors=0 hog_rounds=[1-9]'; then
            bad; echo "      the FAT writer or the hog did not run:"; grep -a '^\[LAT\] load ' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        # The verdict is a COUNT (wave 15, BR): FAT device I/O the FAT writer
        # issued with preemption off. The window's LENGTH is not a verdict:
        # under -icount the virtual clock still runs while the host serves
        # the virtio-blk request (and jumps to the next timer when the hart
        # idles), so the same kernel measured 61 us to 3.5 ms against the
        # 100 us bound depending on host load. Length and `[LAT]` verdict
        # are printed for information only.
        local np_line np_io
        np_line="$(grep -a '^\[LAT\] fat preempt_off_io=' "$clean" | sed -n 1p)"
        np_io="$(printf '%s\n' "$np_line" | sed -n 's/^\[LAT\] fat preempt_off_io=\([0-9][0-9]*\) preempt_off_io_all=[0-9][0-9]*$/\1/p')"
        if [ -z "$np_io" ] || [ "$np_io" = 0 ]; then
            bad; echo "      the FAT spinlock canary counted no FAT I/O with preemption off: ${np_line:-no '[LAT] fat preempt_off_io=' line}"
            echo "      log kept: $log"; return
        fi
        top="$(grep -a '^\[LATTRACE\] run preempt top1 ' "$clean" | sed -n 1p)"
        max="$(printf '%s\n' "$top" | sed -n 's/.* max_ns=\([0-9]*\) .*/\1/p')"
        ok; echo "      FAT device I/O with preemption off: preempt_off_io=${np_io} (canary)"
        echo "      info: ${result#\[LAT\] }"; echo "      info: preempt-off max ${max:-?} ns at ${top##* site=}"
        rm -f "$log" "$clean"
    }
    # lat-fat counts PI across I/O for every task: the exec bounce buffer and
    # KERNEL_FD_TABLE are taken by the behavior loop's MLSRV spawn and opens,
    # robot programs, so these rows boot the robot cell.
    par_row -s lat_wake_row "lat: riscv64 wake-up, FAT writes" rv "qemu,use-robot,lat-fat" PASS
    par_row -s fat_lat_canary_row "lat: riscv64 FAT spinlock canary" rv "qemu,fat-mutate-spin-canary"
    par_row -s lat_wake_row "lat: aarch64 wake-up, FAT writes" arm "qemu,use-robot,lat-fat" PASS
    par_row -s fat_lat_canary_row "lat: aarch64 FAT spinlock canary" arm "qemu,fat-mutate-spin-canary"
    # Wave 15 (FM), owner rule F1: `FAT_MUTATE` (a Mutex held across the
    # FAT update's virtio-blk I/O) is gone; FAT-sector claims (fat32.rs
    # `fat_sector_claim`) hold nothing across I/O. The rows above require
    # `pi_io=0`; these canaries hold a Mutex across each FAT update again
    # and must count the I/O under it.
    par_row -s lat_wake_row "lat: riscv64 FAT PI-across-I/O canary" rv "qemu,fat-mutate-pi-canary" PICANARY
    par_row -s lat_wake_row "lat: aarch64 FAT PI-across-I/O canary" arm "qemu,fat-mutate-pi-canary" PICANARY
    # Wave 15 (RL), owner rule F1: virtio-blk's `BLK_LOCK` is not held
    # across the device request (submit under it, wait without it). The
    # rows above require `waits_locked=0`; these canaries hold it across
    # each wait again and must count the waits under it.
    par_row -s lat_wake_row "lat: riscv64 virtio-blk lock-across-wait canary" rv "qemu,blk-lock-wait-canary" BLKCANARY
    par_row -s lat_wake_row "lat: aarch64 virtio-blk lock-across-wait canary" arm "qemu,blk-lock-wait-canary" BLKCANARY
    # Wave 15 (PI), owner rule F1 for every task: the exec/spawn bounce
    # buffer is a claim (no Mutex held across its read) and KERNEL_FD_TABLE is never held across
    # a descriptor's device I/O. The PASS rows above require `pi_io_all=0`;
    # each canary puts one of them back and the site must name it.
    par_row -s lat_wake_row "lat: riscv64 EXEC_BOUNCE PI-across-I/O canary" rv "qemu,use-robot,lat-fat,exec-bounce-pi-canary" PISITE:EXEC_BOUNCE
    par_row -s lat_wake_row "lat: aarch64 EXEC_BOUNCE PI-across-I/O canary" arm "qemu,use-robot,lat-fat,exec-bounce-pi-canary" PISITE:EXEC_BOUNCE
    par_row -s lat_wake_row "lat: riscv64 KERNEL_FD_TABLE PI-across-I/O canary" rv "qemu,use-robot,lat-fat,fd-table-pi-canary" PISITE:KERNEL_FD_TABLE
    par_row -s lat_wake_row "lat: aarch64 KERNEL_FD_TABLE PI-across-I/O canary" arm "qemu,use-robot,lat-fat,fd-table-pi-canary" PISITE:KERNEL_FD_TABLE

    # ── aarch64: idle wakeups/s (tickless), wave 11 ONESHOT ─────────────────
    #
    # The aarch64 half of `tickless_idle_wakeups_row` (riscv64 block): the same
    # bench-minimal boot, the same 30 s wall-clock window, the same counter
    # (`watchdog::TICK_COUNT`, which the aarch64 timer handler bumps through
    # `watchdog::tick()`), read the same way over the QEMU GDB stub — with
    # lldb's `gdb-remote`, because there is no aarch64 gdb on the host. Port
    # 1236, not the riscv64 row's 1234.
    #
    # Measured (wave 11, three 30 s windows each): 9/9/9 wakeups/s on c1afd98
    # and 9/9/9 after the one-shot change — hart 0's 100 ms idle keepalive
    # plus the boot's own sleepers, the riscv64 band. THRESHOLD 20/s, as
    # there; the same canary (idle armed with the busy cap) read 68/s: FAIL.
    # Wave 13 (ENERGY): same verdict as the riscv64 row (`idle_wakes_verdict`).
    # No aarch64 Linux image on the host: the Linux figure there is riscv64's.
    tickless_idle_wakeups_row_aarch64() { # [wdt]: the simulated-watchdog build
        local mode="${1:-}" feats="qemu,bench-minimal"
        local label="aarch64: idle wakeups/s (tickless)"
        if [ "$mode" = wdt ]; then
            feats="qemu,use-robot,bench-minimal,wdt-sim"; label="aarch64: idle keepalive (simulated WDT)"
        fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        if ! command -v lldb >/dev/null 2>&1; then
            bad; echo "      lldb not installed — the row cannot read TICK_COUNT back"; return
        fi
        if ! a64_kbuild "$feats"; then
            bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
        fi
        local addr
        addr=$(nm "$A64_KERNEL" 2>/dev/null | grep "watchdog10TICK_COUNT" | sed -n '1{s/ .*//p;}' | sed 's/^0*//')
        if [ -z "$addr" ]; then
            bad; echo "      watchdog::TICK_COUNT symbol not found in $A64_KERNEL"; return
        fi
        local log="$CI_LOG_DIR/tickless-idle-aarch64${mode:+-$mode}.log" kimg="$CI_LOG_DIR/tickless-idle-aarch64.img"
        rm -f "$log"; cp "$A64_IMG" "$kimg"
        qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 -m 128M \
            -nographic -kernel "$kimg" -gdb tcp::1236 >"$log" 2>&1 </dev/null &
        local qpid=$!
        sleep 10
        if ! kill -0 "$qpid" 2>/dev/null; then
            bad; echo "      qemu exited during boot — log kept: $log"; rm -f "$kimg"; return
        fi
        read_ticks_a64() {
            lldb --batch -o "gdb-remote localhost:1236" \
                -o "memory read -s8 -fx -c1 0x${addr}" -o "process detach" 2>/dev/null \
                | grep -i "^0x0*${addr}:" | grep -o "0x[0-9a-f]*$"
        }
        local t0_hex t1_hex
        t0_hex=$(read_ticks_a64)
        if [ -z "$t0_hex" ]; then
            kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null; rm -f "$kimg"
            bad; echo "      first lldb read of TICK_COUNT (0x$addr) came back empty — log kept: $log"; return
        fi
        sleep 30
        if ! kill -0 "$qpid" 2>/dev/null; then
            rm -f "$kimg"
            bad; echo "      qemu exited mid-window — log kept: $log"; return
        fi
        t1_hex=$(read_ticks_a64)
        kill "$qpid" 2>/dev/null; wait "$qpid" 2>/dev/null; rm -f "$kimg"
        if [ -z "$t1_hex" ]; then
            bad; echo "      second lldb read of TICK_COUNT (0x$addr) came back empty — log kept: $log"; return
        fi
        local delta rate
        delta=$(( t1_hex - t0_hex ))
        rate=$(( delta / 30 ))
        if [ "$delta" -lt 0 ]; then
            bad; echo "      TICK_COUNT went backwards ($t0_hex -> $t1_hex) — log kept: $log"; return
        fi
        idle_wakes_verdict "$mode" "$delta" "$log"
    }
    par -s "aarch64: idle wakeups/s (tickless)" tickless_idle_wakeups_row_aarch64   # gdb on 1236, wall clock
    par -s "aarch64: idle keepalive (simulated WDT)" tickless_idle_wakeups_row_aarch64 wdt   # gdb on 1236

    # ── A64CLK: the aarch64 kernel runs on the VIRTUAL counter/timer (wave 11) ─
    #
    # The kernel reads `CNTVCT_EL0` and programs `CNTV_CVAL_EL0`/`CNTV_CTL_EL0`
    # (PPI 27), as Linux does at EL1, instead of `CNTPCT_EL0`/`CNTP_*` (PPI 30).
    # Ring 3's vDSO reads `CNTVCT_EL0`, so kernel stamps and ring-3 clock reads
    # share one clock even when firmware or a hypervisor leaves `CNTVOFF_EL2`
    # nonzero. Three rows:
    #   tick   — the plain kernel arms the tick on PPI 27 and five ticks arrive.
    #   canary — `a64clk-ppi-canary` programs CNTV but enables PPI 30: no tick
    #            ever arrives, the boot stops right after the svc self-test.
    #   offset — `a64clk-cntvoff-canary` drops from EL2 leaving CNTVOFF_EL2 =
    #            2_000_000 ticks (2 ms), and captest's stamped-read summary
    #            (every sensor stamp inside its own read, on the vDSO clock)
    #            must still hold. Measured by hand when this landed: the SAME
    #            canary with the kernel's clock switched back to CNTPCT_EL0
    #            printed `FAIL sensor_read_ts(IMU): acquired inside the call`
    #            (stamps 2 ms ahead of the vDSO) and no summary line.
    a64clk_boot() { # a64clk_boot <log> <mach-extra> <marker> <secs> <kernel img>
        local log="$1" mach="$2" marker="$3" secs="$4" img="$5" i=0
        cp "$A64_IMG" "$img"
        par_ready
        qemu-system-aarch64 -M "virt,gic-version=3$mach" -cpu max,pauth=on -smp 2 \
            -nographic -kernel "$img" >"$log" 2>&1 &
        local pid=$!
        while [ "$i" -lt $((secs * 2)) ]; do
            grep -aqF "$marker" "$log" 2>/dev/null && break
            grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$img"
    }
    a64clk_tick_row() {
        local label="aarch64: tick on the virtual timer"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        if ! a64_kbuild "qemu"; then
            bad; echo "      the aarch64 kernel (--features qemu) did not build"; return
        fi
        local log="$CI_LOG_DIR/a64clk-tick.log"; rm -f "$log"
        a64clk_boot "$log" "" "[TRAP] FP/SIMD survives interrupt" 30 "$CI_LOG_DIR/a64clk-tick.img"
        if ! grep -aqF "PPI 27 + SGI 0 enabled" "$log" \
            || ! grep -aqE "^\[TIMER\] ticks: 5 in [0-9]+ ms" <(tr -d '\r' <"$log") \
            || ! grep -aqF "[TRAP] FP/SIMD survives interrupt: PASS" "$log" \
            || grep -aqE "TIMER\] FAILED|AARCH64-TRAP\] unhandled" "$log"; then
            bad; echo "      no tick on PPI 27:"
            grep -aE "GIC\] dist|TIMER\]|TRAP\]" "$log" | tr -d '\r' | sed 's|^|        |'
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "aarch64: tick on the virtual timer" a64clk_tick_row
    a64clk_ppi_canary_row() {
        local label="aarch64: PPI 30 canary (no tick)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        # Compile-error bucket: its own FAIL, not a pass of the canary.
        if ! a64_kbuild "qemu,a64clk-ppi-canary"; then
            bad; echo "      the aarch64 kernel (--features qemu,a64clk-ppi-canary) did not build"; return
        fi
        local log="$CI_LOG_DIR/a64clk-ppi-canary.log"; rm -f "$log"
        a64clk_boot "$log" "" "[TIMER] ticks:" 12 "$CI_LOG_DIR/a64clk-ppi-canary.img"
        if ! grep -aqF "PPI 30 + SGI 0 enabled" "$log" \
            || ! grep -aqF "[TRAP] svc #0 self-test: PASS" "$log" \
            || grep -aqE "AARCH64-TRAP\] unhandled|panic|\[FATAL\]|FAILED" "$log"; then
            bad; echo "      the canary kernel did not park silently at the tick check (a build, boot or trap problem, not a verdict):"
            tr -d '\r' <"$log" | sed -n '$p' | sed 's|^|        |'
            echo "      log kept: $log"; return
        fi
        if grep -aqF "[TIMER] ticks:" "$log"; then
            bad; echo "      PPI 30 enabled while CNTV is programmed, and the ticks still arrived"
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "aarch64: PPI 30 canary (no tick)" a64clk_ppi_canary_row
    a64clk_cntvoff_row() {
        local label="aarch64: one clock under CNTVOFF"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        if ! a64_kbuild "qemu,a64clk-cntvoff-canary,captest-row"; then
            bad; echo "      the aarch64 kernel (--features qemu,a64clk-cntvoff-canary) did not build"; return
        fi
        if ! make $AZOS_OUT/build/disk-aarch64-captest.img >/dev/null 2>&1; then
            bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-captest.img"; return
        fi
        local log="$CI_LOG_DIR/a64clk-cntvoff.log"; rm -f "$log"
        local kimg="$CI_LOG_DIR/a64clk-cntvoff.img" disk="$CI_LOG_DIR/a64clk-cntvoff-disk.img"
        cp "$A64_IMG" "$kimg"; cp $AZOS_OUT/build/disk-aarch64-captest.img "$disk"
        # `virtualization=on`: the kernel enters at EL2 and `_azos_drop_to_el1`
        # is what leaves CNTVOFF_EL2 nonzero under the canary feature.
        par_ready
        qemu-system-aarch64 -M virt,gic-version=3,virtualization=on -cpu max,pauth=on -smp 4 -nographic \
            -kernel "$kimg" -global virtio-mmio.force-legacy=false \
            -drive file="$disk",if=none,format=raw,id=hd0 \
            -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        local pid=$! i=0
        while [ "$i" -lt 90 ]; do
            grep -aqF "CAPTEST] ALL PASSED" "$log" 2>/dev/null && break
            grep -aqE "CAPTEST\]  FAIL" "$log" 2>/dev/null && break
            grep -aq "AARCH64-TRAP\] unhandled" "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null; rm -f "$kimg" "$disk"
        if ! grep -aqF "Entered at: EL2" "$log"; then
            bad; echo "      the kernel did not enter at EL2, so the offset was never set — log kept: $log"; return
        fi
        if grep -aqE "CAPTEST\]  FAIL|AARCH64-TRAP\] unhandled" "$log" \
            || ! grep -aqF "[CAPTEST] sensorts: 5 sensors stamped on the vDSO clock, inside the call (IMU ENCODER RANGE BATTERY) or < 1 s before it (ODOM), monotonic" "$log" \
            || ! grep -aqF "[CAPTEST] ALL PASSED" "$log"; then
            bad; echo "      kernel stamps and the vDSO clock disagree under CNTVOFF_EL2 != 0:"
            grep -aE "CAPTEST\]  FAIL|CAPTEST\] sensorts" "$log" | tr -d '\r' | sed -n 1,6p | sed 's|^|        |'
            echo "      log kept: $log"; return
        fi
        ok; rm -f "$log"
    }
    par "aarch64: one clock under CNTVOFF" a64clk_cntvoff_row

    # ── SCHED-RT: RT band budget, EDF + CBS, run-time admission (wave 11) ──
    #
    # `kernel/src/rt_smoke.rs` (feature `sched-rt-smoke`) runs four checks on
    # hart 0 under `-smp 1 -icount shift=0,sleep=off` (instruction counts) and
    # prints one verdict line per check, `[SCHEDRT] <check> PASS|FAIL <isa>`,
    # FAIL only from the failure path:
    #   band  — a band task (prio 10) that never blocks runs 3 s (three 1 s
    #           windows); the non-band task beside it must get >= 2 % and the
    #           runaway <= the 95 % cap + 2 %.
    #   exempt — during that run the non-band task watches rt-motor's
    #           heartbeat while the band is throttled: the kernel safety loops
    #           are exempt from the cap, so it may stand still for at most 5 ms
    #           of the observer's running (rt-motor's period is 1 ms).
    #   edf   — two reservations from the signed topology's rows `rt-edf-a`/
    #           `rt-edf-b` (boot admission placed them on CPU 0) share level 4
    #           under a CPU hog and a console spammer; B is released first and
    #           A (deadline 3 ms) must preempt it: no job may finish late (the
    #           LAT instrument's `now - deadline`).
    #   cbs   — a hard reservation that never stops (1 ms per 10 ms) beside
    #           two that must keep their deadlines; it must be throttled.
    #   admit — run-time admission refuses a band over-subscription (sized
    #           from what the hart already holds, rt::hart_load: the IRQ
    #           thread's reservation with IRQ_THREADED) with
    #           EBUSY and a `[SCHED-RT] admission REFUSED` line, a hart
    #           over-subscription likewise, and admits a non-band
    #           reservation whose 10 ms deadline sits beside the band's 6 ms
    #           (80 % in all): the dispatch is EDF across levels, so the
    #           cross-level rule (rt_core::levels_check) does not bind.
    #   ring3 — the row lookup SYS_SPAWN_EX/autorun apply keeps a profiled
    #           band row's priority with its reservation and raises a band
    #           row without one to the ring-3 floor (12).
    # The PASS row also prints `[SCHEDRT] cost`: instructions per comparator
    # write through `arm_if_earlier`, and per call that does not write.
    # Canary rows: each breaks one property and the matching check must print
    # FAIL (`rt-band-canary` cap off, `rt-exempt-canary` no exemption: rt-motor
    # is throttled with the band, `rt-edf-canary` FIFO inside a level,
    # `rt-cbs-canary` no budget charging, `rt-admit-canary` no admission).
    # Compile-error bucket: `kbuild`/`a64_kbuild` failures are their own FAIL.
    sched_rt_row() { # sched_rt_row <label> <isa: rv|arm> <features> <expect: PASS|band|edf|cbs|admit>
        local label="$1" isa="$2" feats="$3" expect="$4"
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        if [ "$isa" = rv ]; then
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -smp 1 -icount shift=0,sleep=off \
                -kernel "$kimg" >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" >"$log" 2>&1 &
        fi
        # 900 x 0.5 s: the CBS canary alone took 111 s of host time (a task
        # that never stops leaves no idle for -icount to skip).
        local pid=$! i=0
        while [ "$i" -lt 900 ]; do
            grep -aq '\[SCHEDRT\] done ' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$kimg"
        local clean="$log.txt"
        tr -d '\r' <"$log" >"$clean"
        if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      the kernel stopped:"; grep -aiE -m3 'panic|\[FATAL\]|AARCH64-TRAP' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if ! grep -aq '^\[SCHEDRT\] done ' "$clean"; then
            bad; echo "      no [SCHEDRT] done line within the timeout — log kept: $log"; return
        fi
        local c
        if [ "$expect" = PASS ]; then
            for c in band exempt edf cbs admit ring3; do
                if ! grep -aq "^\[SCHEDRT\] $c PASS " "$clean"; then
                    bad; grep -a "^\[SCHEDRT\] $c " "$clean" | sed 's/^/      /'
                    echo "      log kept: $log"; return
                fi
            done
            ok
            for c in band exempt edf cbs admit ring3; do
                grep -a "^\[SCHEDRT\] $c PASS " "$clean" | sed 's/^\[SCHEDRT\] /      /'
            done
            grep -a "^\[SCHEDRT\] cost " "$clean" | sed 's/^\[SCHEDRT\] /      /'
            rm -f "$log" "$clean"
            return
        fi
        # Canary: the check the canary breaks fails, on the line only its
        # failure path prints.
        if grep -aq "^\[SCHEDRT\] $expect FAIL " "$clean"; then
            ok; grep -a "^\[SCHEDRT\] $expect FAIL " "$clean" | sed 's/^\[SCHEDRT\] /      /'
            rm -f "$log" "$clean"
        else
            bad; echo "      the $expect canary did not fail its check:"
            grep -a "^\[SCHEDRT\] $expect " "$clean" | sed 's/^/      /'
            echo "      log kept: $log"
        fi
    }
    par_row sched_rt_row "sched-rt: riscv64 band/edf/cbs/admit" rv "qemu,sched-rt-smoke" PASS
    par_row sched_rt_row "sched-rt: riscv64 band cap canary" rv "qemu,rt-band-canary" band
    par_row sched_rt_row "sched-rt: riscv64 EDF order canary" rv "qemu,rt-edf-canary" edf
    par_row sched_rt_row "sched-rt: riscv64 CBS canary" rv "qemu,rt-cbs-canary" cbs
    par_row sched_rt_row "sched-rt: riscv64 admission canary" rv "qemu,rt-admit-canary" admit
    par_row sched_rt_row "sched-rt: riscv64 exemption canary" rv "qemu,rt-exempt-canary" exempt
    par_row sched_rt_row "sched-rt: aarch64 band/edf/cbs/admit" arm "qemu,sched-rt-smoke" PASS
    par_row sched_rt_row "sched-rt: aarch64 band cap canary" arm "qemu,rt-band-canary" band
    par_row sched_rt_row "sched-rt: aarch64 EDF order canary" arm "qemu,rt-edf-canary" edf
    par_row sched_rt_row "sched-rt: aarch64 CBS canary" arm "qemu,rt-cbs-canary" cbs
    par_row sched_rt_row "sched-rt: aarch64 admission canary" arm "qemu,rt-admit-canary" admit
    par_row sched_rt_row "sched-rt: aarch64 exemption canary" arm "qemu,rt-exempt-canary" exempt

    # ── SCHED-RT near the admission bound (wave 15, VB) ──
    #
    # `kernel/src/rt_util_smoke.rs` (feature `sched-rt-util`) loads a hart up
    # to what run-time admission accepts and counts every late job, under
    # `-icount shift=0,sleep=off`. One verdict line per phase,
    # `[RTUTIL] <phase> PASS|FAIL <isa>`, FAIL only from the failure path.
    # `-smp 1`: `u70-h1`/`u93-h1` (four hard-CBS reservations at 70 % and
    # 93 % density, each job computing 95 % of its budget: zero misses; the
    # hart already holds the IRQ thread's band reservation with IRQ_THREADED,
    # so u93's last task and suspend's neighbour are sized from
    # rt::hart_load),
    # `overrun` (a 1/10 ms server computing 6 ms per job is throttled, the
    # others keep every deadline), `suspend` (a 50 %-density server with a
    # 2 ms deadline that computes 400 us and sleeps 20 us must not take more
    # than its density: its 40 % neighbour keeps every deadline), `mixed`
    # (two reservations at different levels, 75 % in all, the lower one's
    # 2 ms deadline beside the upper one's 5 ms: admitted, since the dispatch
    # is EDF across levels, and neither misses).
    # `-smp 2`: `u70-hart1`/`u93-hart1`, the sets on hart 1 alone: under
    # -icount both harts share one virtual clock, so two loaded harts each
    # see half of it and only one hart is loaded at a time. The riscv64
    # hart-1 row first missed 333/375 jobs at 70 % and 263/375 at 93 % with
    # the stolen-clock signature (CBS overruns on jobs that computed 95 % of
    # their budget): hart 0 was not idle but spinning, IRQs off, on the
    # global timer-sleeper lock held by hart 1, which -icount does not run
    # while hart 0 spins (up to 50 ms per tick). Every idle path halts (rv
    # and arm `wfi`, x86 `hlt`); the lock is per CPU since
    # SCHED_TIMER_HEAP_PER_CPU. Canary: that symbol off brings back 292/375
    # and 280/375 misses (riscv64, 2026-10-09); on, 0/375 at shift 0 and 1.
    # Canaries: `rt-util-cbs-canary` (no budget charging) fails `overrun`;
    # `rt-util-wake-canary` (the CBS wake rule tests q/t, the bandwidth,
    # instead of q/d, the density) fails `suspend`; the levels canary boots
    # the PASS row's kernel with `canary=sched-dl-in-level` (fixed priority
    # between levels: admission reads the same switch and refuses `mixed`'s
    # low reservation with `levels`) and fails `mixed`. Compile-error bucket:
    # a kernel that does not build is its own FAIL.
    sched_rt_util_row() { # <label> <isa: rv|arm> <smp: 1|2> <features> <expect: PASS|phase> [<cmdline>]
        local label="$1" isa="$2" smp="$3" feats="$4" expect="$5"
        local -a app=(); [ -n "${6:-}" ] && app=(-append "$6")
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        if [ "$isa" = rv ]; then
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -smp "$smp" -icount shift=0,sleep=off \
                -kernel "$kimg" ${app[@]+"${app[@]}"} >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp "$smp" \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" ${app[@]+"${app[@]}"} >"$log" 2>&1 &
        fi
        # 900 x 0.5 s: about 35 s of host time when it passes (the phases
        # leave idle time for -icount to skip); a canary's overrunner leaves
        # none.
        local pid=$! i=0
        while [ "$i" -lt 900 ]; do
            grep -aq '\[RTUTIL\] done ' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid"; wait "$pid" 2>/dev/null
        rm -f "$kimg"
        local clean="$log.txt"
        tr -d '\r' <"$log" >"$clean"
        if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      the kernel stopped:"; grep -aiE -m3 'panic|\[FATAL\]|AARCH64-TRAP' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if ! grep -aq '^\[RTUTIL\] done ' "$clean"; then
            bad; echo "      no [RTUTIL] done line within the timeout — log kept: $log"; return
        fi
        local c phases="u70-h1 u93-h1 overrun suspend mixed"
        [ "$smp" = 1 ] || phases="u70-hart1 u93-hart1"
        if [ "$expect" = PASS ]; then
            for c in $phases; do
                if ! grep -aq "^\[RTUTIL\] $c PASS " "$clean"; then
                    bad; grep -a "^\[RTUTIL\] $c \|^\[RTUTIL\] task [a-z0-9]* $c .* misses=[1-9]" "$clean" | sed -n 1,6p | sed 's/^/      /'
                    echo "      log kept: $log"; return
                fi
            done
            ok
            for c in $phases; do
                grep -a "^\[RTUTIL\] $c PASS " "$clean" | cut -d' ' -f2- | sed 's/ band_throttles=.*//; s/^/      /'
            done
            rm -f "$log" "$clean"
            return
        fi
        if grep -aq "^\[RTUTIL\] $expect FAIL " "$clean"; then
            ok; grep -a "^\[RTUTIL\] $expect FAIL " "$clean" | cut -d' ' -f2- | sed 's/^/      /'
            rm -f "$log" "$clean"
        else
            bad; echo "      the $expect canary did not fail its phase:"
            grep -a "^\[RTUTIL\] $expect " "$clean" | sed 's/^/      /'
            echo "      log kept: $log"
        fi
    }
    par_row sched_rt_util_row "sched-rt-util: riscv64 near the bound" rv 1 "qemu,sched-rt-util" PASS
    par_row sched_rt_util_row "sched-rt-util: riscv64 CBS canary" rv 1 "qemu,rt-util-cbs-canary" overrun
    par_row sched_rt_util_row "sched-rt-util: riscv64 wake rule canary" rv 1 "qemu,rt-util-wake-canary" suspend
    par_row sched_rt_util_row "sched-rt-util: riscv64 levels canary" rv 1 "qemu,sched-rt-util" mixed "canary=sched-dl-in-level"
    par_row sched_rt_util_row "sched-rt-util: aarch64 near the bound" arm 1 "qemu,sched-rt-util" PASS
    par_row sched_rt_util_row "sched-rt-util: aarch64 hart 1" arm 2 "qemu,sched-rt-util" PASS
    par_row sched_rt_util_row "sched-rt-util: aarch64 CBS canary" arm 1 "qemu,rt-util-cbs-canary" overrun
    par_row sched_rt_util_row "sched-rt-util: aarch64 wake rule canary" arm 1 "qemu,rt-util-wake-canary" suspend
    par_row sched_rt_util_row "sched-rt-util: aarch64 levels canary" arm 1 "qemu,sched-rt-util" mixed "canary=sched-dl-in-level"
    par_row sched_rt_util_row "sched-rt-util: riscv64 hart 1" rv 2 "qemu,sched-rt-util" PASS

    # ── Priority inversion through fast IPC (wave 11 PIFAST) ──
    #
    # `kernel/src/smokes/pifast_smoke.rs`: a priority-13 kernel client calls a
    # priority-24 server through SYS_IPC_FAST_CALL_EP (582, the real dispatch
    # arms) once per 1.3 ms while a priority-18 hog computes in 2 ms bursts on
    # the same hart, and times every call. `-smp 1 -icount shift=0,sleep=off`,
    # the LAT rows' setup. The kernel prints the verdict: `[PIFAST] PASS` when
    # the worst of 1000 loaded calls is <= 100 us AND the server was seen
    # serving at the client's 13 (the donation is why), `[PIFAST] FAIL`
    # otherwise — a line only that path prints.
    #
    # Measured before the donation existed (wave 11, three runs per ISA): p99
    # 1.98 ms (one hog burst), 249-250 of 1000 calls over the bound, worst
    # 1.1-1.6 s (the boot's `behavior` task, priority 14, also sits between
    # client and server while it runs its bench sweep). With it (three runs
    # per ISA): riscv64 worst 19.3-24.7 us, aarch64 16.4-16.5 us, none over.
    #
    # Canary rows build `pifast-donation-canary` (the call never donates): the
    # row must print `[PIFAST] FAIL` with `server_prio_seen=24`. A build
    # failure is its own FAIL line (compile-error bucket).
    pifast_row() { # pifast_row <label> <isa: rv|arm> <features> <expect: PASS|CANARY>
        local label="$1" isa="$2" feats="$3" expect="$4"
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log disk kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        disk="$CI_LOG_DIR/${slug}-disk.img"
        if [ "$isa" = rv ]; then
            [ -f $AZOS_OUT/build/disk-ipctest.img.pristine ] || make_disk $AZOS_OUT/build/disk-ipctest.img
            cp $AZOS_OUT/build/disk-ipctest.img.pristine "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -smp 1 -icount shift=0,sleep=off \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
                bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
            fi
            cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic -kernel "$kimg" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 480 ]; do
            grep -aqE '\[PIFAST\] (PASS|FAIL)' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$disk" "$kimg"
        # Anchor on a copy without the console's bare CRs.
        local clean="$log.txt"
        tr -d '\r' <"$log" >"$clean"
        local loaded
        loaded="$(grep -a '^\[PIFAST\] isa=[a-z0-9]* loaded calls=' "$clean" | sed -n 1p)"
        if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      the kernel stopped:"; grep -aiE -m3 'panic|\[FATAL\]|AARCH64-TRAP' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        if [ -z "$loaded" ]; then
            bad; echo "      no [PIFAST] loaded result within the timeout:"
            grep -a '^\[PIFAST\]' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        # Every loaded call ran against a running hog.
        if ! printf '%s\n' "$loaded" | qgrep -qE 'calls=1000 .* hog_bursts=[1-9][0-9]* '; then
            bad; echo "      the hog did not run: $loaded"; echo "      log kept: $log"; return
        fi
        if [ "$expect" = PASS ]; then
            if grep -aq '^\[PIFAST\] PASS ' "$clean"; then
                ok; echo "      ${loaded#\[PIFAST\] }"; rm -f "$log" "$clean"
            else
                bad; echo "      ${loaded}"; grep -a '^\[PIFAST\] FAIL ' "$clean" | sed 's/^/      /'
                echo "      log kept: $log"
            fi
            return
        fi
        # CANARY: the call without the donation fails the bound, and the
        # server was never seen above its own 24.
        if grep -aq '^\[PIFAST\] FAIL loaded .* server_prio_seen=24 ' "$clean"; then
            ok; echo "      ${loaded#\[PIFAST\] }"; rm -f "$log" "$clean"
        else
            bad; echo "      the call without a donation did not fail the row: ${loaded}"
            echo "      log kept: $log"
        fi
    }
    par_row pifast_row "pifast: riscv64 inversion" rv "qemu,pifast-smoke" PASS
    par_row pifast_row "pifast: riscv64 no-donation canary" rv "qemu,pifast-donation-canary" CANARY
    par_row pifast_row "pifast: aarch64 inversion" arm "qemu,pifast-smoke" PASS
    par_row pifast_row "pifast: aarch64 no-donation canary" arm "qemu,pifast-donation-canary" CANARY

    # ── Multi-source port wait (wave 11, PORTWAIT) ────────────────────────
    #
    # ipctest's phase P on both ISAs: a waiter binds a far timer to a port;
    # the timer, re-armed 100 ms ahead, must be the next event of
    # `SYS_PORT_WAIT` and not before its deadline; a wait with nothing armed
    # must answer 0 at its deadline; an io_ring completion must be an event;
    # a remove by key must find the ring and a second one nothing. The row
    # requires the five `ok   P/` verdicts (`P_VERDICTS`) and no `FAIL  P/`
    # line; the rest of ipctest is judged by the ipctest rows above. The
    # phase had nine verdicts while it also bound a `Cap<Channel>` (three of
    # them the relay's); the v1 channel and its port source are gone
    # (2026-10-13), and so are those four.
    #
    # Canary (`portwait-timer-canary`): a timer bind answers 0 and arms
    # nothing. The row must then read `FAIL  P/the timer source fired`
    # (printed only by the failure path), after the 5 s outer deadline of the
    # timer wait, while the io_ring verdict, which follows that wait, stays
    # `ok` (the phase ran past it). Measured when this landed (wave 11): the
    # timer 1.0 ms late, the timeout 0.9 ms late on riscv64, 1.1 / 1.9 ms on
    # aarch64; the canary's timer wait answered 0 after 5.00 s on both
    # (2026-10-24, main ac10a4be: 1.95 / 1.29 ms and 1.29 / 1.10 ms, the
    # canary 5.002 s and 5.003 s). Compile-error bucket: a build failure is
    # its own FAIL.
    portwait_row() { # portwait_row <label> <isa: rv|arm> <features> <expect: PASS|CANARY>
        local label="$1" isa="$2" feats="$3" expect="$4" P_VERDICTS=5
        if [ "$isa" = rv ]; then kbuild "$feats" || return; fi
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local slug log disk kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/${slug}.log"; rm -f "$log"
        disk="$CI_LOG_DIR/${slug}-disk.img"
        if [ "$isa" = rv ]; then
            [ -f $AZOS_OUT/build/disk-ipctest.img.pristine ] || make_disk $AZOS_OUT/build/disk-ipctest.img
            cp $AZOS_OUT/build/disk-ipctest.img.pristine "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.elf"; cp "$KERNEL" "$kimg"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -smp 4 -kernel "$kimg" \
                -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        else
            if ! a64_kbuild "$feats"; then
                bad; echo "      the aarch64 kernel (--features $feats) did not build"; return
            fi
            if ! make $AZOS_OUT/build/disk-aarch64-ipctest.img >/dev/null 2>&1; then
                bad; echo "      disk image build failed: make $AZOS_OUT/build/disk-aarch64-ipctest.img"; return
            fi
            cp $AZOS_OUT/build/disk-aarch64-ipctest.img "$disk"
            kimg="$CI_LOG_DIR/${slug}-kernel.img"; cp "$A64_IMG" "$kimg"
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 2 -nographic \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$disk",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 >"$log" 2>&1 &
        fi
        local pid=$! i=0
        # ipctest's own budget is 20 s of guest time per child verdict; the
        # ceiling sits above it so the test decides, not this loop.
        while [ "$i" -lt 200 ]; do
            grep -aqE 'IPCTEST\] [0-9]+ check\(s\) run' "$log" 2>/dev/null && { sleep 1; break; }
            grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 1
        done
        kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$disk" "$kimg"
        local clean="$log.txt"
        tr -d '\r' <"$log" >"$clean"
        if grep -aqiE 'panic|\[FATAL\]|AARCH64-TRAP\] unhandled' "$clean"; then
            bad; echo "      the kernel stopped:"; grep -aiE -m3 'panic|\[FATAL\]|AARCH64-TRAP' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"; return
        fi
        local oks fails
        oks="$(grep -ac '^\[IPCTEST\]   ok   P/' "$clean")"
        fails="$(grep -a '^\[IPCTEST\]  FAIL  P/' "$clean")"
        if [ "$expect" = PASS ]; then
            if [ "$oks" = "$P_VERDICTS" ] && [ -z "$fails" ]; then
                ok; grep -a '^\[IPCTEST\] P: \(timer\|timeout\) wait' "$clean" | sed 's/^\[IPCTEST\] /      /'
                rm -f "$log" "$clean"
            else
                bad; echo "      phase P: ${oks} of ${P_VERDICTS} verdicts ok"
                printf '%s\n' "$fails" | sed '/^$/d; s/^/      /'
                grep -a '^\[IPCTEST\] P: ' "$clean" | sed 's/^/      /'
                echo "      log kept: $log"
            fi
            return
        fi
        # CANARY: the timer verdict fails, and the phase ran past the timer
        # wait (the io_ring verdict, judged after it, is ok).
        if ! grep -aq '^\[IPCTEST\]   ok   P/an io_ring completion is an event' "$clean"; then
            bad; echo "      the canary run did not reach phase P's io_ring wait — log kept: $log"; return
        fi
        if grep -aq '^\[IPCTEST\]  FAIL  P/the timer source fired' "$clean"; then
            ok; grep -a '^\[IPCTEST\] P: timer wait' "$clean" | sed 's/^\[IPCTEST\] /      /'
            rm -f "$log" "$clean"
        else
            bad; echo "      an unarmed timer did not fail the timer verdict:"
            grep -a '^\[IPCTEST\] P: timer wait\|P/the timer' "$clean" | sed 's/^/      /'
            echo "      log kept: $log"
        fi
    }
    par_row portwait_row "portwait: riscv64 ring-3 wait" rv "qemu" PASS
    par_row portwait_row "portwait: riscv64 timer canary" rv "qemu,portwait-timer-canary" CANARY
    par_row portwait_row "portwait: aarch64 ring-3 wait" arm "qemu" PASS
    par_row portwait_row "portwait: aarch64 timer canary" arm "qemu,portwait-timer-canary" CANARY

    # Leave the tree on the default build: every scenario above rebuilds for
    # itself, but nothing after this one does, and a stale `rvv` kernel in
    # target/ is exactly the kind of thing that gets measured by accident.
    kbuild "qemu"

    # Two guests on one link: both ends are our stack, so this is the only
    # scenario that covers TCP handshake and RX checksum validation in both
    # directions. Has its own harness because it drives two QEMU processes.
    # vsbench: the same ring-3 work on both kernels, and the check that step 9
    # actually names. Until 2026-09-07 the parity claim rested on one manual
    # run recorded by hand; nothing re-ran it, and the Linux half
    # was not built by `make userspace` — long enough for that lane to grow a
    # comment saying the reap "should be taken back in" and dead code marked
    # "kept for when this lane measures the full life cycle again".
    #
    # It asserts what SURVIVES the instrument, not speed, on the gate column —
    # AzOS built `qemu,bench-minimal`, refused unless its log shows the
    # bench-minimal banner: it completes, reports no lane failure, and every
    # lane has a Linux counterpart. The AzOS product column (`qemu`, full
    # daemon set) and Linux+seccomp are printed beside it and do not decide
    # the result. The script builds both kernels into target/vsbench-compare/,
    # never into the default target/ release directory. No thresholds — see
    # the script's header for the measurement that settles why.
    #
    # The ring lanes (`ring-*`, `ioring-*`) are measured a second time on the
    # gate kernel and on Linux under `-accel tcg,thread=single -icount
    # shift=0,sleep=off` (owner decision 2026-09-28): under MTTCG a parked
    # gate column's ring exchange waits on a halted vCPU's host-thread wake,
    # which scales with host load. That pass prints its own table in
    # instructions per op and must pass assertions 1-3 as well; see
    # VSBENCH_RING_DET in the script.
    vsbench_row() {
        printf "  %-26s" "bench: vsbench vs Linux..."
        if QEMU="$QEMU" WAIT_SECS=90 VSBENCH_SECCOMP=1 bash "${REPO_ROOT}/tools/vsbench_compare.sh"; then
            ok
        else
            bad; echo "      logs in $AZOS_OUT/build/vsbench-compare/"
        fi
    }
    par -s "bench: vsbench vs Linux" vsbench_row   # wall-clock lanes, two kernels

    # Receipts default (owner 2026-10-22): DECISION_RECORDS_DEV, the decision
    # ring and every record site, is on in every preset but HWCLASS_EMBEDDED on
    # the condition that it costs at most 1% (10 per mille). The gate kernel is
    # built with it off and on from the same qemu.config and both boot the ipc
    # and shell lanes (ipc-roundtrip, the rings, chan-call, file-ord 64B,
    # pipe, file-dup, spawn+wait) under -icount at one hart, and compares the
    # retired instructions per op where both columns print them, else the
    # guest ns/op (tools/vsbench_cost.sh, which prints the per-lane table;
    # measured 2026-10-22: at most 6 per mille, spawn+wait, whose instruction
    # count moves ~1 per mille between two runs of one kernel). At one hart a
    # wake never lands on another CPU, so the migrating-wake record does not
    # fire here: the row bounds the record sites the lanes pass on one CPU.
    # The canary builds the on column with `lockdep` too and must be over
    # (2026-10-22: drv-call +13 per mille, the one lane over; a thin margin).
    receipts_cost_row() {
        printf "  %-26s" "bench: receipts cost <= 1%..."
        local out
        if out="$(QEMU="$QEMU" bash "${REPO_ROOT}/tools/vsbench_cost.sh" DECISION_RECORDS_DEV 10 ipc,shell 2>&1)"; then
            ok; printf '%s\n' "$out" | sed -n '/^lane /,$p' | sed 's/^/      /'
        else
            bad; printf '%s\n' "$out" | sed -n '/^lane /,$p;/^vsbench-cost: .*\(fail\|did not\|no lane\|different\|changes nothing\)/p' | sed 's/^/      /'
        fi
    }
    par -s "bench: receipts cost <= 1%" receipts_cost_row
    receipts_cost_canary_row() {
        printf "  %-26s" "bench: receipts cost canary..."
        local out rc=0
        out="$(QEMU="$QEMU" VSBENCH_COST_ON_FEATURES=lockdep bash "${REPO_ROOT}/tools/vsbench_cost.sh" DECISION_RECORDS_DEV 10 ipc,shell 2>&1)" || rc=$?
        if [ "$rc" -eq 1 ] && printf '%s\n' "$out" | qgrep -q '^vsbench-cost: DECISION_RECORDS_DEV is over 10 per mille'; then
            ok
        else
            bad; echo "      CANARY: lockdep in the on column was not over 1% (rc=$rc); the row cannot fail:"
            printf '%s\n' "$out" | sed -n '/^lane /,$p' | sed 's/^/      /'
        fi
    }
    par -s "bench: receipts cost canary" receipts_cost_canary_row

    # Besides the round trip, the script requires both ends to report
    # `opts wscale=1/1 sack=1 ts=1 ecn=1`: this is the only boot where both SYNs come
    # from this stack, since slirp parses nothing but the MSS.
    net_pair_row() {
        printf "  %-26s" "network: two-node TCP..."
        kbuild "qemu,net-smoke"
        if QEMU="$QEMU" WAIT_SECS=90 bash "${REPO_ROOT}/tools/net_pair_smoke.sh" >/dev/null 2>&1; then
            ok
        else
            bad; echo "      re-run 'make qemu-net-pair' to see the logs"
        fi
    }
    par -s -n 2 "network: two-node TCP" net_pair_row   # two QEMUs on one link

    # ── Wave 15 (FIX1): a loopback delivery survives a preemption inside it ──
    #
    # The product column's `udp-roundtrip` (vsbench, -icount) lost a reply:
    # the loopback recursion guard in `ip::send_flags` was ONE global flag,
    # held across `handle` with preemption on (syscalls run with interrupts
    # enabled). A wake-up that preempted the vsbench client between
    # delivering its datagram and dropping the flag made the echo's reply
    # send return -1, and the client waited out its poll budget. The flag is
    # per hart now and the delivery runs with preemption off
    # (`ip::loopback_deliver`). `loopback-preempt-probe` asks for a
    # reschedule inside that window on EVERY delivery, as a tick landing there
    # would; the row boots the product kernel (`qemu`, full daemon set) with
    # the vsbench volume, `net` lanes only, `-smp 1 -icount`, and needs the
    # udp-roundtrip number. Canary: `loopback-guard-canary` puts the old
    # global flag back without the guard, and the lane must report the lost
    # round trip (only the failure prints `udp-rt: ...`). Compile-error
    # bucket: a build failure is its own FAIL. 2026-10-24: both rv rows hung
    # in boot — the probe's reschedule inside the boot network self-test
    # (Kconfig BOOT_SELFTESTS, which the gate turns on) switched away from
    # `kernel_main`, so `arch_enter_scheduler` never set `sie.STIE`; the
    # deferred-preemption callback now waits for the scheduler's gate
    # (`boot::sched::preempt_deferred`). A red row says when the
    # "Starting scheduler" line is missing.
    loopback_preempt_row() { # loopback_preempt_row <rv|arm> <features> <pass|canary>
        local isa="$1" feats="$2" want="$3"
        local label="net: loopback preempted ($isa)"
        [ "$want" = canary ] && label="net: loopback canary ($isa)"
        printf "  %-26s" "${label}..."
        mkdir -p "$CI_LOG_DIR"
        local log="$CI_LOG_DIR/loopback-$want-$isa.log" kimg="$CI_LOG_DIR/kernel-loopback-$want-$isa"
        local disk="$CI_LOG_DIR/loopback-$want-$isa.img" src
        rm -f "$log" "$kimg" "$disk" "$disk.lanes"
        make_disk $AZOS_OUT/build/disk-vsbench.img $AZOS_OUT/build/disk-aarch64-vsbench.img || { bad; return; }
        if [ "$isa" = rv ]; then
            kbuild "$feats" || { bad; echo "      riscv64 --features $feats did not build"; return; }
            cp "$KERNEL" "$kimg"; src="$AZOS_OUT/build/disk-vsbench.img"
        else
            a64_kbuild "$feats" || { bad; echo "      aarch64 --features $feats did not build"; return; }
            cp "$A64_IMG" "$kimg"; src="$AZOS_OUT/build/disk-aarch64-vsbench.img"
        fi
        cp "$src" "$disk" && printf 'net\n' >"$disk.lanes" \
            && mcopy -o -i "$disk" "$disk.lanes" ::VSBLANES.TXT \
            || { bad; echo "      could not prepare $disk"; return; }
        par_ready
        while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
        if [ "$isa" = rv ]; then
            "$QEMU" -machine virt -nographic -bios default -smp 1 -icount shift=0,sleep=off \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive "file=$disk,if=none,format=raw,id=hd0" \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        else
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 1 \
                -icount shift=0,sleep=off -nographic \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive "file=$disk,if=none,format=raw,id=hd0" \
                -device virtio-blk-device,drive=hd0 </dev/null >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 360 ]; do
            grep -aq '\[VSBENCH\] side=azos done' "$log" 2>/dev/null && break
            grep -aqE '\[FATAL\]|KERNEL PANIC|AARCH64-TRAP\] unhandled' "$log" 2>/dev/null && break
            kill -0 "$pid" 2>/dev/null || break
            i=$((i + 1)); sleep 0.5
        done
        sleep 1
        kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$kimg" "$disk" "$disk.lanes"
        tr -d '\r' <"$log" >"$log.t" && mv "$log.t" "$log"
        local measured=0 lost=0
        grep -aqE '^\[VSBENCH\] azos udp-roundtrip = [0-9]+ ns/op' "$log" && measured=1
        grep -aqE '^\[VSBENCH\] udp-rt: (a round trip never came back|the peer never answered)' "$log" && lost=1
        if [ "$want" = pass ] && [ "$measured" = 1 ] && [ "$lost" = 0 ]; then
            ok; grep -a 'udp-roundtrip =' "$log" | sed 's/^/      /'; rm -f "$log"; return
        fi
        if [ "$want" = canary ] && [ "$lost" = 1 ] && [ "$measured" = 0 ]; then
            ok; rm -f "$log"; return
        fi
        bad; grep -aE 'udp|VSBENCH\] side|PANIC|FATAL' "$log" | sed -n '1,6p' | sed 's/^/      /'
        grep -aqF '[SCHED] Starting scheduler' "$log" \
            || echo "      no \"[SCHED] Starting scheduler\": kernel_main was switched away from before its end"
        echo "      log kept: $log"
    }
    par -s "net: loopback preempted (rv)" loopback_preempt_row rv qemu,loopback-preempt-probe pass
    par -s "net: loopback preempted (arm)" loopback_preempt_row arm qemu,loopback-preempt-probe pass
    par -s "net: loopback canary (rv)" loopback_preempt_row rv qemu,loopback-preempt-probe,loopback-guard-canary canary
    par -s "net: loopback canary (arm)" loopback_preempt_row arm qemu,loopback-preempt-probe,loopback-guard-canary canary

    # ── The user shell (wave 11), both ISAs ──────────────────────
    #
    # These rows TYPE. Each boots the gate kernel with `build/disk-sh.img` /
    # `build/disk-aarch64-sh.img` (the drivers base plus SH.ELF and
    # TOOLBOX.ELF: the only volumes that carry the shell), waits for the user
    # shell's `azos$ ` prompt, types a script one line per prompt (paced,
    # one byte per 20 ms, on both ISAs), and then requires every marker. A
    # line `^C` sends 0x03 and waits for the prompt to come back; `#wait RE`
    # waits for an extended regex in the log; `#sleep N` waits N seconds;
    # `#intr` sends 0x03 without waiting for anything (wave 13: `^C` to a
    # Linux job reading the console, which the shell's prompt never follows);
    # `!line` is typed without waiting for a prompt after it. `USH_FAULTS=N` requires exactly N
    # deliberate user-fault kills (see the check below). `USH_FORBID` is an extended
    # regex that must NOT appear: `USH_SMP` overrides the hart count (rv 4,
    # arm 2 otherwise), `USH_KERNEL` boots that kernel image instead of
    # building `<features>`; `USH_QEMU_EXTRA` is added to the QEMU command
    # line (`-icount shift=0,sleep=off` for a row whose verdict must not
    # depend on the host's load); rows that are about exclusive console input
    # forbid the recovery console's `robot> ` prompt, which only the kernel
    # shell prints; `USH_IMG=<path>` boots that volume, kept after the row (a
    # pristine copy when it does not exist yet), so a second row boots what
    # the first left on it; `USH_DISK=lxabi` boots `build/disk-lxabi.img` /
    # `build/disk-aarch64-lxabi.img` (the shell volume plus the static Linux
    # binary `LXHELLO.ELF`) instead; the prompt row then waits past `SH_START_TIMEOUT_S` (10 s)
    # so a recovery console that should not start has had the time to. The QEMU stdin is a fifo held open on fd 8 (fd 9 is the
    # help row's), as `shell_help_row` does. `expect` FAIL is a canary build:
    # the row passes when the property is missing.
    # `USH_VKBD=1` (virtio-input, Kconfig DRV_VIRTIO_INPUT): the guest gets a
    # `-device virtio-keyboard-device` and a QEMU monitor on a unix socket
    # (a RELATIVE path: a unix socket path is limited to 103 bytes), and every
    # script line is typed through the monitor's `sendkey`
    # (tools/qemu_sendkeys.py) instead of the serial fifo, which stays open and
    # silent. Whatever the shell reads then came from the virtio keyboard.
    # Build the third-party BusyBox once per gate run (the three
    # ISAs), in a config of its own with USERSPACE_GPL + BUSYBOX: the gate's
    # own configs keep both off. 0 when build/disk-busybox.img and its
    # aarch64 twin exist afterwards; LX_BUSYBOX_X86=yes when the x86_64
    # rows can run too (LX_BUSYBOX_X86_WHY says why not).
    lx_busybox_ready() {
        if [ -z "${LX_BUSYBOX_STATE:-}" ]; then
            LX_BUSYBOX_STATE=no
            mkdir -p "$CI_LOG_DIR"
            local cfg="$AZOS_OUT/target/linux-busybox.config"
            sed -e 's/^# CONFIG_USERSPACE_GPL is not set$/CONFIG_USERSPACE_GPL=y/' "$PRIMARY_CONFIG" >"$cfg"
            (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1)
            sed -i '' -e 's/^# CONFIG_BUSYBOX is not set$/CONFIG_BUSYBOX=y/' "$cfg"
            (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1)
            if grep -q '^CONFIG_BUSYBOX=y$' "$cfg" \
               && make -s busybox KCONFIG_CONFIG="$cfg" >"$CI_LOG_DIR/busybox-build.log" 2>&1 \
               && make_disk $AZOS_OUT/build/disk-busybox.img $AZOS_OUT/build/disk-aarch64-busybox.img; then
                LX_BUSYBOX_STATE=yes
                # x86_64's volume needs the x86_64 userspace: without it only
                # the x86 rows are skipped (make_disk would end the gate).
                rm -f $AZOS_OUT/build/disk-x86_64-busybox.img*
                LX_BUSYBOX_X86_WHY="no x86_64 volume (see $CI_LOG_DIR/busybox-x86-disk.log)"
                if make $AZOS_OUT/build/disk-x86_64-busybox.img >"$CI_LOG_DIR/busybox-x86-disk.log" 2>&1; then
                    cp -p $AZOS_OUT/build/disk-x86_64-busybox.img $AZOS_OUT/build/disk-x86_64-busybox.img.pristine
                    LX_BUSYBOX_X86=yes
                fi
            fi
        fi
        [ "$LX_BUSYBOX_STATE" = yes ]
    }
    # Wave 13: `LXTHR.ELF` built (`make lxthreads`, zig) and its volumes made.
    lx_threads_ready() {
        if [ -z "${LX_THREADS_STATE:-}" ]; then
            LX_THREADS_STATE=no
            mkdir -p "$CI_LOG_DIR"
            if make -s lxthreads >"$CI_LOG_DIR/lxthreads-build.log" 2>&1 \
               && make_disk $AZOS_OUT/build/disk-lxthr.img $AZOS_OUT/build/disk-aarch64-lxthr.img; then
                LX_THREADS_STATE=yes
            fi
        fi
        [ "$LX_THREADS_STATE" = yes ]
    }
    # x86 (`ushell_row ... x86 ...`): x86_64 hosts a Linux task only in the
    # ring-3 runtime, so its kernel is built from `USH_X86_DEFCONFIG` (default:
    # the QEMU defconfig plus LINUX_RUNTIME) into an image of its own, and
    # boots on microvm with one CPU (`USH_SMP` does not apply); `USH_DISK=sh`
    # and `lxabi` are build/disk-x86_64.img (it carries LXHELLO.ELF), any
    # other volume build/disk-x86_64-<name>.img.
    ushell_row() { # ushell_row <label> <rv|arm|x86> <features> <PASS|FAIL> <script> <limit-s> <marker>...
        local label="$1" isa="$2" feats="$3" expect="$4" script="$5" limit="$6"; shift 6
        printf "  %-26s" "${label}..."
        local slug log fifo img kimg
        slug="$(printf '%s' "$label" | tr -c 'A-Za-z0-9' '-' | sed 's/--*/-/g; s/^-//; s/-$//')"
        log="$CI_LOG_DIR/ush-${slug}.log"; fifo="$CI_LOG_DIR/ush-${slug}.fifo"
        img="${USH_IMG:-$CI_LOG_DIR/ush-${slug}.img}"; kimg="$CI_LOG_DIR/ush-${slug}-kernel"
        mkdir -p "$CI_LOG_DIR"; rm -f "$log" "$fifo" "$kimg"; [ -n "${USH_IMG:-}" ] || rm -f "$img"
        local dsk="${USH_DISK:-sh}" vkbd=() vsock="$CI_LOG_DIR/ush-${slug}.mon"
        if [ -n "${USH_VKBD:-}" ]; then
            rm -f "$vsock"
            vkbd=(-device virtio-keyboard-device -chardev "socket,id=mon0,path=$vsock,server=on,wait=off" -mon chardev=mon0,mode=readline)
        elif [ -n "${USH_MON:-}" ]; then
            # `USH_MON=1`: the monitor alone, for the script's `#mon` lines. A
            # unix socket path is limited to 103 bytes, which a long label's
            # slug overruns: the socket is named by the slug's checksum.
            vsock="$CI_LOG_DIR/ush-$(printf '%s' "$slug" | cksum | cut -d' ' -f1).mon"
            rm -f "$vsock"
            vkbd=(-chardev "socket,id=mon0,path=$vsock,server=on,wait=off" -mon chardev=mon0,mode=readline)
        fi
        if [ "$isa" = rv ]; then
            if [ -z "${USH_KERNEL:-}" ] && ! kbuild "$feats"; then bad; echo "      riscv64 kernel ($feats) did not build"; return; fi
            if [ ! -f "$AZOS_OUT/build/disk-$dsk.img.pristine" ]; then
                rm -f $AZOS_OUT/build/disk-drvbase.img $AZOS_OUT/build/disk-sh.img "$AZOS_OUT/build/disk-$dsk.img"; make_disk "$AZOS_OUT/build/disk-$dsk.img"
            fi
            [ -f "$img" ] || cp "$AZOS_OUT/build/disk-$dsk.img.pristine" "$img"; cp "${USH_KERNEL:-$KERNEL}" "$kimg"
        elif [ "$isa" = x86 ]; then
            local xdef="${USH_X86_DEFCONFIG:-$CI_LOG_DIR/ush-x86-lxrt.defconfig}" xt xvol
            [ -n "${USH_X86_DEFCONFIG:-}" ] || { cat config/defconfigs/${GATE_DEFC_X86}.config; echo "CONFIG_LINUX_RUNTIME=y"; } >"$xdef"
            xt="$(basename "$xdef" .defconfig)"
            if [ -n "${USH_KERNEL:-}" ]; then cp "$USH_KERNEL" "$kimg"
            elif ! X86_KBUILD_OUT="$AZOS_OUT/build/kernel-x86_64-$xt.elf" \
                 X86_KBUILD_ARGS="X86_64_DEFCONFIG=$xdef X86_64_KCONFIG=$AZOS_OUT/build/x86_64-$xt.config X86_64_TARGET_DIR=$AZOS_OUT/target/x86_64-$xt X86_64_IMG=$AZOS_OUT/build/kernel-x86_64-$xt.elf" \
                 x86_kbuild "$feats" "$kimg"; then
                bad; echo "      x86_64 kernel ($feats, $xt) did not build"; return
            fi
            x86_kernel_check "$kimg" || { rm -f "$kimg" "$kimg.features"; return; }
            case "$dsk" in sh|lxabi) xvol=x86_64 ;; *) xvol="x86_64-$dsk" ;; esac
            if [ ! -f "$AZOS_OUT/build/disk-$xvol.img.pristine" ]; then
                rm -f "$AZOS_OUT/build/disk-$xvol.img"; make_disk "$AZOS_OUT/build/disk-$xvol.img"
            fi
            [ -f "$img" ] || cp "$AZOS_OUT/build/disk-$xvol.img.pristine" "$img"
        else
            if [ -z "${USH_KERNEL:-}" ] && ! a64_kbuild "$feats"; then bad; echo "      aarch64 kernel ($feats) did not build"; return; fi
            if [ ! -f "$AZOS_OUT/build/disk-aarch64-$dsk.img.pristine" ]; then
                rm -f $AZOS_OUT/build/disk-aarch64-drvbase.img $AZOS_OUT/build/disk-aarch64-sh.img "$AZOS_OUT/build/disk-aarch64-$dsk.img"
                make_disk "$AZOS_OUT/build/disk-aarch64-$dsk.img"
            fi
            [ -f "$img" ] || cp "$AZOS_OUT/build/disk-aarch64-$dsk.img.pristine" "$img"; cp "${USH_KERNEL:-$A64_IMG}" "$kimg"
        fi
        if ! mkfifo "$fifo"; then bad; echo "      mkfifo failed: $fifo"; return; fi
        par_ready   # the wait below happens in the job, not in the gate
        while [ $(( $(pgrep -x qemu-system-riscv64 | wc -l) + $(pgrep -x qemu-system-aarch64 | wc -l) + $(pgrep -x qemu-system-x86_64 | wc -l) )) -ge 4 ]; do sleep 2; done
        if [ "$isa" = x86 ]; then
            par_ready
            qemu-system-x86_64 -M microvm -cpu max -m 256M -nographic -no-reboot ${USH_QEMU_EXTRA:-} \
                -device isa-debug-exit,iobase=0xf4,iosize=0x04 \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 -kernel "$kimg" <"$fifo" >"$log" 2>&1 &
        elif [ "$isa" = rv ]; then
            par_ready
            "$QEMU" -machine virt -nographic -bios default -kernel "$kimg" -smp "${USH_SMP:-4}" ${USH_QEMU_EXTRA:-} \
                -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 -device virtio-rng-device ${vkbd[@]+"${vkbd[@]}"} <"$fifo" >"$log" 2>&1 &
        else
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp "${USH_SMP:-2}" ${USH_QEMU_EXTRA:-} -nographic \
                -kernel "$kimg" -global virtio-mmio.force-legacy=false \
                -drive file="$img",if=none,format=raw,id=hd0 \
                -device virtio-blk-device,drive=hd0 -device virtio-rng-device ${vkbd[@]+"${vkbd[@]}"} <"$fifo" >"$log" 2>&1 &
        fi
        local pid=$! t0 prompts verdict="" line
        exec 8>"$fifo"
        t0=$(date +%s)
        ush_prompts() { grep -ao 'azos\$ ' "$log" 2>/dev/null | wc -l | tr -d ' '; }
        ush_alive() {
            kill -0 "$pid" 2>/dev/null || { verdict=exited; return 1; }
            if grep -aqiE "panic|\[FATAL\]|AARCH64-TRAP\] unhandled" "$log" 2>/dev/null; then verdict=crash; return 1; fi
            [ $(( $(date +%s) - t0 )) -lt "$limit" ] || { verdict=timeout; return 1; }
        }
        ush_type() { local b i; for ((i = 0; i < ${#1}; i++)); do printf '%s' "${1:i:1}" >&8; sleep 0.02; done; }
        while ush_alive && [ "$(ush_prompts)" -lt 1 ]; do sleep 0.5; done
        if [ -z "$verdict" ]; then
            while IFS= read -r line; do
                [ -z "$line" ] && continue
                if [ "${line#\#wait }" != "$line" ]; then
                    while ush_alive && ! grep -aqE "${line#\#wait }" "$log"; do sleep 0.5; done
                    [ -n "$verdict" ] && break; continue
                fi
                if [ "${line#!}" != "$line" ]; then ush_type "${line#!}"; printf '\r' >&8; continue; fi
                if [ "$line" = "#intr" ]; then printf '\003' >&8; continue; fi
                # `#key NAME...`: raw key presses through the monitor (USH_VKBD),
                # for a task that reads the events and not the typed line.
                if [ "${line#\#key }" != "$line" ]; then python3 tools/qemu_sendkeys.py --raw "$vsock" ${line#\#key }; continue; fi
                # `#mon COMMAND`: one monitor command (USH_MON or USH_VKBD).
                if [ "${line#\#mon }" != "$line" ]; then python3 tools/qemu_sendkeys.py --command "$vsock" "${line#\#mon }"; continue; fi
                if [ "${line#\#sleep }" != "$line" ]; then sleep "${line#\#sleep }"; continue; fi
                prompts=$(ush_prompts)
                if [ "$line" = "^C" ]; then printf '\003' >&8
                elif [ -n "${USH_VKBD:-}" ]; then python3 tools/qemu_sendkeys.py "$vsock" "$line"
                else ush_type "$line"; printf '\r' >&8; fi
                while ush_alive && [ "$(ush_prompts)" -le "$prompts" ]; do sleep 0.5; done
                [ -n "$verdict" ] && break
            done <<< "$script"
            sleep 1
        fi
        # QEMU under `-icount` may ignore SIGTERM: escalate after 2 s at most.
        kill "$pid" 2>/dev/null
        local k; for k in $(seq 1 20); do kill -0 "$pid" 2>/dev/null || break; sleep 0.1; done
        kill -0 "$pid" 2>/dev/null && kill -9 "$pid" 2>/dev/null
        wait "$pid" 2>/dev/null
        exec 8>&-
        rm -f "$fifo" "$kimg" "$kimg.features" "$vsock"; [ -n "${USH_IMG:-}" ] || rm -f "$img"
        local missing="" m
        for m in "$@"; do grep -aqF -- "$m" "$log" || missing="$missing [$m]"; done
        local forbidden=""
        if [ -n "${USH_FORBID:-}" ] && grep -aqE -- "$USH_FORBID" "$log"; then
            forbidden="$(grep -aE -m1 -- "$USH_FORBID" "$log" | tr -d '\r')"
        fi
        # `USH_FAULTS=N`: the scenario faults on purpose N times (LXHELLO's
        # `mprot:` checks fork a child that stores to read-only memory: a
        # PROT_READ mapping, an mprotect(PROT_READ) page and the vDSO page,
        # three per LXHELLO run).
        # Exactly N kills and 2N `PAGE FAULT` lines, compared as strings
        # (`grep -c` into `-eq` skips the check on a grep error).
        if [ -n "${USH_FAULTS:-}" ]; then
            local kills faults
            kills="$(grep -a 'PAGE FAULT\] Killing user task' "$log" | wc -l | tr -d ' ')"
            faults="$(grep -a 'PAGE FAULT' "$log" | wc -l | tr -d ' ')"
            if [ "$kills" != "$USH_FAULTS" ] || [ "$faults" != "$((USH_FAULTS * 2))" ]; then
                missing="$missing [expected $USH_FAULTS fault kill(s) / $((USH_FAULTS * 2)) PAGE FAULT lines, saw $kills / $faults]"
            fi
        fi
        if [ "$verdict" = crash ]; then missing="$missing [kernel crash]"; fi
        if [ "$expect" = FAIL ]; then
            if [ -n "$missing" ] || [ -n "$forbidden" ]; then
                ok; echo "      canary failed as it must:${missing}${forbidden:+ forbidden: $forbidden}"; rm -f "$log"
            else
                bad; echo "      the canary build passed: the row does not discriminate"; echo "      log kept: $log"
            fi
            return
        fi
        if [ -z "$missing" ] && [ -z "$forbidden" ] && [ "$verdict" != crash ]; then
            ok; rm -f "$log"
        else
            bad
            [ -n "$missing" ] && echo "      missing:$missing (stopped: ${verdict:-script done})"
            [ -n "$forbidden" ] && echo "      forbidden line printed: $forbidden"
            echo "      log kept: $log"
        fi
    }
    # Wave 15 (TRACE, static keys): the W^X canary. `trace-wx-canary` makes
    # the static-key patcher write a site through the EXECUTABLE text
    # mapping instead of its never-executable alias (azos_mm::text_poke).
    # W^X must refuse it: the boot dies on a kernel store fault, and the
    # fault names exactly the address the canary printed. A pass here is the
    # evidence that the read-execute mapping is not a writable path, so the
    # alias is the only one; the normal boot's `[TRACE] static keys: ...
    # text RX at N/N sites; alias ... mapped=false` line is its other half.
    trace_wx_row() { # trace_wx_row <label> <rv|arm>
        local label="$1" isa="$2"
        printf "  %-26s" "${label}..."
        local log="$CI_LOG_DIR/trace-wx-$isa.log" kimg="$CI_LOG_DIR/trace-wx-$isa.kernel" addr fault
        mkdir -p "$CI_LOG_DIR"; rm -f "$log" "$kimg"
        if [ "$isa" = rv ]; then
            kbuild "qemu,trace-wx-canary" || { bad; echo "      riscv64 canary kernel did not build"; return; }
            cp "$KERNEL" "$kimg"
            par_ready
            "$QEMU" -machine virt -nographic -bios default -smp 4 -kernel "$kimg" </dev/null >"$log" 2>&1 &
        else
            a64_kbuild "qemu,trace-wx-canary" || { bad; echo "      aarch64 canary kernel did not build"; return; }
            cp "$A64_IMG" "$kimg"
            par_ready
            qemu-system-aarch64 -M virt,gic-version=3 -cpu max,pauth=on -smp 4 -nographic -kernel "$kimg" </dev/null >"$log" 2>&1 &
        fi
        local pid=$! i=0
        while [ "$i" -lt 90 ] && ! grep -aq "FATAL" "$log" 2>/dev/null && kill -0 "$pid" 2>/dev/null; do
            i=$((i + 1)); sleep 1
        done
        sleep 1
        kill "$pid" 2>/dev/null; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
        rm -f "$kimg"
        addr="$(grep -a 'static-key W^X canary: writing ' "$log" | sed -n 's/.*writing \(0x[0-9a-f]*\) through the executable mapping.*/\1/p' | head -1 | tr -d '\r')"
        if [ "$isa" = rv ]; then
            fault="$(grep -a 'Store/AMO page fault at ' "$log" | sed -n 's/.*page fault at \(0x[0-9a-f]*\).*/\1/p' | head -1 | tr -d '\r')"
        else
            fault="$(grep -a 'aarch64 kernel page fault: write at ' "$log" | sed -n 's/.*write at \(0x[0-9a-f]*\).*/\1/p' | head -1 | tr -d '\r')"
        fi
        if [ -n "$addr" ] && [ "$addr" = "$fault" ] && grep -aq "FATAL" "$log" && ! grep -aq "\[TRACE\] static keys: " "$log"; then
            ok; echo "      the write through the executable mapping faulted at $addr"; rm -f "$log"
        else
            bad; echo "      canary write ${addr:-not printed}, store fault ${fault:-none}; log kept: $log"
        fi
    }
    # The shell volumes, rebuilt once per run, here. The first row that needs
    # one only builds it when no `.pristine` exists, so a snapshot left by an
    # earlier run on an older tree was booted as-is (2026-10-03: LXHELLO.ELF
    # "not permitted" after a merge changed the image's rows). Not FATAL here:
    # a volume that does not build is reported by the rows that use it.
    # USB mass storage with its volume (Kconfig USB_STORAGE_VOLUME): a stick on
    # QEMU's xHCI (a PCI function: the rows build `pci`), served Bulk-Only by
    # `usb-storage`. The stick is an image made here: 64 MiB, an MBR with one
    # FAT32 partition (type 0x0C) at LBA 2048, the given files in its root.
    # The kernel mounts it at /usb when it is ready (`[USB] volume mounted
    # at`), the shell's row holds /usb read-write (crash-log export), every
    # row reads it through its root directory (the package tool), an orderly
    # power-off ejects it (`[ORDERLY] usb volume:`), a `device_del` on the
    # monitor pulls it out (`[USB] volume at /usb retired`).
    usb_stick_image() { # usb_stick_image <img> <file>...
        local img="$1" f; shift
        rm -f "$img"
        python3 - "$img" <<'PY' || return 1
import sys
SECT, START, TOTAL = 512, 2048, 64 * 1024 * 1024 // 512
with open(sys.argv[1], 'wb') as f:
    f.truncate(TOTAL * SECT)
    mbr = bytearray(SECT)
    mbr[446 + 4] = 0x0C
    mbr[446 + 8:446 + 12] = START.to_bytes(4, 'little')
    mbr[446 + 12:446 + 16] = (TOTAL - START).to_bytes(4, 'little')
    mbr[510], mbr[511] = 0x55, 0xAA
    f.write(mbr)
PY
        mkfs.fat -F 32 -s 1 --offset 2048 -n AZSTICK "$img" $((64 * 1024 - 1024)) >/dev/null 2>&1 || return 1
        for f in "$@"; do mcopy -i "$img@@1M" "$f" :: || return 1; done
    }
    usb_stick_args() { # usb_stick_args <img>: the QEMU arguments of the stick
        printf '%s' "-device qemu-xhci,id=xhci -drive if=none,id=stick,format=raw,file=$1 -device usb-storage,bus=xhci.0,drive=stick,id=stickdev"
    }
    # The volume mounts from the stick's partition and reads.
    usb_mount_row() { # usb_mount_row <label> <rv|arm> <features>
        local dir="$CI_LOG_DIR/usb-mount-$2" stick
        rm -rf "$dir"; mkdir -p "$dir/files"; stick="$dir/stick.img"
        printf 'stick says hello\n' >"$dir/files/HELLO.TXT"
        if ! usb_stick_image "$stick" "$dir/files/HELLO.TXT"; then printf "  %-26s" "$1..."; bad; echo "      the stick image did not build"; return; fi
        USH_QEMU_EXTRA="$(usb_stick_args "$stick")" USH_FORBID='robot> |PAGE FAULT|volume not mounted' \
            ushell_row "$1" "$2" "$3" PASS \
            "#wait \[USB\] volume (mounted|not mounted)
cat /usb/HELLO.TXT" 150 \
            "[USB] mass storage" "[USB] volume mounted at /usb: FAT32 at LBA 2048 (1 partition(s))" "stick says hello"
        rm -rf "$dir"
    }
    # Crash-log export: the shell copies CRASH.LOG and CRASH.OLD to the stick
    # through its /usb write tree; the orderly power-off ejects the volume.
    # Then, on the host: the two files are on the stick with their bytes and
    # the volume's FAT[1] says it was shut down cleanly. The records are made
    # with `echo` (a fresh volume has no crash log); the check reads them from
    # the stick image, not from the guest's output.
    usb_export_row() { # usb_export_row <label> <check label> <rv|arm> <features>
        local dir="$CI_LOG_DIR/usb-export-$3" stick got
        rm -rf "$dir"; mkdir -p "$dir/files"; stick="$dir/stick.img"
        printf 'stick says hello\n' >"$dir/files/HELLO.TXT"
        if ! usb_stick_image "$stick" "$dir/files/HELLO.TXT"; then printf "  %-26s" "$1..."; bad; echo "      the stick image did not build"; return; fi
        USH_QEMU_EXTRA="$(usb_stick_args "$stick")" USH_FORBID='robot> |PAGE FAULT|eject FAILED|volume not mounted' \
            ushell_row "$1" "$3" "$4" PASS \
            "#wait \[USB\] volume (mounted|not mounted)
echo usb-row-crash-42 > /fat/CRASH.LOG
echo usb-row-older-54 > /fat/CRASH.OLD
cat /fat/CRASH.LOG > /usb/CRASH.LOG
cat /fat/CRASH.OLD > /usb/CRASH.OLD
!power shutdown
#wait POWER\] shutdown by
#wait \[ORDERLY\] usb volume" 200 \
            "[USB] volume mounted at /usb" "[ORDERLY] usb volume: written back, marked clean, synchronize cache ok" \
            "[POWER] shutdown by tid"
        printf "  %-26s" "$2..."
        got="$(mtype -i "$stick@@1M" ::CRASH.LOG 2>&1 | tr -d '\r') / $(mtype -i "$stick@@1M" ::CRASH.OLD 2>&1 | tr -d '\r')"
        if [ "$got" = "usb-row-crash-42 / usb-row-older-54" ] && python3 - "$stick" <<'PY'
import sys
b = open(sys.argv[1], 'rb').read()
p = 2048 * 512
rsvd = int.from_bytes(b[p + 14:p + 16], 'little')
fat1 = int.from_bytes(b[p + rsvd * 512 + 4:p + rsvd * 512 + 8], 'little')
sys.exit(0 if fat1 & 0x0800_0000 else 1)
PY
        then
            ok; rm -rf "$dir"
        else
            bad; echo "      on the stick: ${got:-nothing} (or the volume is not marked clean)"; echo "      stick kept: $stick"
        fi
    }
    # A package on the stick reaches the installer: the package tool opens it
    # beneath its read-only root and hands it to PKGD.ELF, whose answer comes
    # back (these bytes are no package: refused). Without the stick the tool
    # cannot open it, which the row forbids.
    usb_pkg_row() { # usb_pkg_row <label> <rv|arm> <features>
        local dir="$CI_LOG_DIR/usb-pkg-$2" stick
        rm -rf "$dir"; mkdir -p "$dir/files"; stick="$dir/stick.img"
        python3 -c "import random; random.seed(0x55534250); open('$dir/files/ACME.PKG', 'wb').write(random.randbytes(4096))"
        if ! usb_stick_image "$stick" "$dir/files/ACME.PKG"; then printf "  %-26s" "$1..."; bad; echo "      the stick image did not build"; return; fi
        USH_QEMU_EXTRA="$(usb_stick_args "$stick")" USH_FORBID='robot> |PAGE FAULT|cannot open the package file|volume not mounted' \
            ushell_row "$1" "$2" "$3" PASS \
            "#wait \[pkgd\] AzOS package installer
#wait \[USB\] volume (mounted|not mounted)
pkg admit /usb/ACME.PKG" 200 \
            "[USB] volume mounted at /usb" "refused: "
        rm -rf "$dir"
    }
    # Pulled out with a file read from it: the volume is retired, the path
    # names nothing, the kernel goes on (no fault, the shell answers).
    usb_unplug_row() { # usb_unplug_row <label> <rv|arm> <features>
        local dir="$CI_LOG_DIR/usb-unplug-$2" stick
        rm -rf "$dir"; mkdir -p "$dir/files"; stick="$dir/stick.img"
        printf 'stick says hello\n' >"$dir/files/HELLO.TXT"
        if ! usb_stick_image "$stick" "$dir/files/HELLO.TXT"; then printf "  %-26s" "$1..."; bad; echo "      the stick image did not build"; return; fi
        USH_MON=1 USH_QEMU_EXTRA="$(usb_stick_args "$stick")" USH_FORBID='robot> |PAGE FAULT|volume not mounted' \
            ushell_row "$1" "$2" "$3" PASS \
            "#wait \[USB\] volume (mounted|not mounted)
cat /usb/HELLO.TXT
#mon device_del stickdev
#wait \[USB\] volume at /usb retired
cat /usb/HELLO.TXT
echo after-unplug-ok" 200 \
            "stick says hello" "[USB] volume at /usb retired: the stick is gone" "/usb/HELLO.TXT: no such file" \
            "after-unplug-ok"
        rm -rf "$dir"
    }
    for ush_vol in sh lxabi aarch64-sh aarch64-lxabi; do
        rm -f "$AZOS_OUT/build/disk-$ush_vol.img" "$AZOS_OUT/build/disk-$ush_vol.img.pristine"
    done
    rm -f $AZOS_OUT/build/disk-drvbase.img $AZOS_OUT/build/disk-aarch64-drvbase.img
    for ush_vol in sh lxabi aarch64-sh aarch64-lxabi; do
        if make "$AZOS_OUT/build/disk-$ush_vol.img" >/dev/null 2>&1; then
