        USH_FORBID='robot> ' par_row ushell_row "sh: two beeps without a device canary ($ush_isa)" "$ush_isa" "$ush_feat" FAIL \
            "beep 5000 &
beep 400 &
#sleep 2" 60 \
            "beep: 235 of 235 periods played" "beep: 19 of 19 periods played" ", most streams at once 2"
