ps
#sleep 2" 120 \
            "[infsrv] serving the Infer interface on endpoint.infer" " S MLSRV.ELF"
        USH_FORBID='robot> ' par_row ushell_row "sh: redirect ($ush_isa)" "$ush_isa" "$ush_feat" PASS \
