echo subdir-ok > /fat/D1/A.TXT
wc < /fat/D1/A.TXT
echo ab >> /fat/D1/A.TXT
wc < /fat/D1/A.TXT" 150 \
            "1 1 10" "2 2 13"
        USH_FORBID='robot> ' par_row ushell_row "sh: ctrl-c stops a job ($ush_isa)" "$ush_isa" "$ush_feat" PASS \
            "!spin
#wait spin: computing
^C
echo after-spin \$?
!yes
#wait ^y
^C
echo after-yes \$?" 180 \
            "stopped by an ancestor" "after-spin 130" "after-yes 130"
