            "kill 1
kill 2" 120 \
            "no such descendant"
        par_row ushell_row "sh: exit gives the console back ($ush_isa)" "$ush_isa" "$ush_feat" PASS \
            "spin &
!exit 0
#wait robot> " 150 \
            "die-with-parent" "gave up: recovery console" "robot> "
        # USHELL2. ^C on ONE hart: the console's RX interrupt delivers ^C to
