# Off compiles out: the robot QEMU config with RC_INPUT=n and GEOFENCE=n,
# cargo arguments from tools/kconfig_to_cargo.py (which must drop exactly the
# two features), into target/generic/ so no row's kernel is touched. Zero
# warnings, and `llvm-nm` finds none of the subsystems' symbols
# (rc_safety / rc_link / geofence) in the ELF — after finding them in the
# default robot kernel of the same ISA, so a query gone blind cannot pass.
rcfence_off_row() { # rcfence_off_row <label> <rv|arm>
    local label="$1" isa="$2" defc cfg args log out rc elf on_elf triple nmb n_on n_off
    # The Generic rows' target dir: same toolchain and dependencies, so cargo
    # reuses core/alloc and every crate and relinks only what the features
    # change, instead of a second build-std tree per ISA.
    local dir="$AZOS_OUT/target/generic"
    local re='rc_safety|rc_link|geofence'
    if [ "$isa" = rv ]; then
        defc="$GATE_ROBOT_DEFC_RV"; triple=riscv64imac-unknown-none-elf
        kbuild "qemu,use-robot" || return; on_elf="$KERNEL"
    else
        defc="$GATE_ROBOT_DEFC_A64"; triple=aarch64-unknown-none-softfloat
        a64_kbuild "qemu,use-robot" || { printf "  %-26s" "${label}..."; bad; echo "      aarch64 qemu kernel did not build"; return; }
        on_elf="$A64_KERNEL"
    fi
    printf "  %-26s" "${label}..."
    mkdir -p "$CI_LOG_DIR" "$dir"
    cfg="$dir/${defc}-off.config"; log="$CI_LOG_DIR/rcfence-off-${isa}.log"
    if ! sed -e 's/^CONFIG_RC_INPUT=y$/# CONFIG_RC_INPUT is not set/' \
             -e 's/^CONFIG_GEOFENCE=y$/# CONFIG_GEOFENCE is not set/' \
             "${REPO_ROOT}/config/defconfigs/${defc}.config" >"$cfg" \
       || ! printf '# CONFIG_RC_INPUT is not set\n# CONFIG_GEOFENCE is not set\n' >>"$cfg" \
       || ! (cd "$REPO_ROOT" && KCONFIG_CONFIG="$cfg" python3 -m olddefconfig >/dev/null 2>&1) \
       || ! grep -q '^CONFIG_USE_ROBOT=y$' "$cfg" || grep -q '^CONFIG_RC_INPUT=y$\|^CONFIG_GEOFENCE=y$' "$cfg"; then
        bad; echo "      could not expand a ${defc} config with RC_INPUT=n GEOFENCE=n"; return
    fi
    args="$(python3 "${REPO_ROOT}/tools/kconfig_to_cargo.py" "$cfg")"
    if printf '%s' "$args" | qgrep -qE 'rc-input|geofence' \
       || ! printf '%s' "$args" | qgrep -q 'use-robot'; then
        bad; echo "      kconfig_to_cargo did not drop exactly rc-input and geofence: $args"; return
    fi
    if [ "$isa" = rv ]; then
        # shellcheck disable=SC2086
        out="$(KCONFIG_CONFIG="$cfg" CARGO_TARGET_DIR="$dir" "$CARGO" build --release \
            -p azos_kernel $args 2>&1)"; rc=$?
    else
        # shellcheck disable=SC2086
        out="$(env -u RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS KCONFIG_CONFIG="$cfg" \
            CARGO_TARGET_DIR="$dir" "$CARGO" build --release -p azos_kernel $args \
            --config 'build.rustflags=["-C","link-arg=-Tkernel/linker-aarch64.ld"]' 2>&1)"; rc=$?
    fi
    printf '%s\n' "$out" >"$log"
    if [ "$rc" -ne 0 ]; then
        bad; grep -E "^error" "$log" | head -5 | sed 's/^/      /'; echo "      log kept: $log"; return
    fi
    if grep -E "^warning:" "$log" | qgrep -qvE "^warning: [A-Za-z0-9_-]+@[0-9]|future version of Rust"; then
        bad; grep -E "^warning:" "$log" | head -5 | sed 's/^/      /'; echo "      log kept: $log"; return
    fi
    elf="$dir/${triple}/release/kernel"
    nmb="$(rustc --print sysroot)/lib/rustlib/$(rustc -vV | sed -n 's/^host: //p')/bin/llvm-nm"
    n_on="$("$nmb" -C "$on_elf" 2>/dev/null | grep -cE "$re")"
    n_off="$("$nmb" -C "$elf" 2>/dev/null | grep -cE "$re")"
    if [ "${n_on:-0}" -eq 0 ]; then
        bad; echo "      the default robot kernel has no rc/geofence symbol: the query is blind"; return
    fi
    if [ "${n_off:-0}" -ne 0 ]; then
        bad; echo "      $n_off rc/geofence symbols in the RC_INPUT=n GEOFENCE=n kernel:"
        "$nmb" -C "$elf" | grep -E "$re" | head -5 | sed 's/^/      /'; return
    fi
    ok; echo "      default kernel: $n_on symbols; RC_INPUT=n GEOFENCE=n: 0"
    rm -f "$log"
}
par_row rcfence_off_row "rc/geofence: off compiles out (rv)"  rv
par_row rcfence_off_row "rc/geofence: off compiles out (arm)" arm
kbuild "qemu"
a64_kbuild "qemu" >/dev/null 2>&1 || true

# ── Fuzzing and bounded proofs (host) ───────────────────────────────────────
#
# cargo-fuzz (libFuzzer + AddressSanitizer) over the parsers that take bytes
# from outside the kernel: the DTB firmware hands over, FAT32 volumes,
# CONFIG.INI, SCHED/CAPS.TOML, POLICY.GGF, ELF images, the encrypted link, and
# network frames. Each row builds its target, replays every checked-in input
# (`corpus/` seeds and `regressions/`, the inputs that once failed), then
# fuzzes from them for FUZZ_SECS (default 30) seconds; see tools/fuzz.sh. New
# inputs go to target/fuzz-work, never into the tree. A missing cargo-fuzz is a
# FAIL, as a missing QEMU is; CI_SKIP_FUZZ=1 is the explicit opt-out.
par_phase_end
ci_phase "[3b/4] fuzzing + Kani"
echo ""
echo "[3b/4] Fuzzing and bounded proofs (host)..."
if [ "${CI_SKIP_FUZZ:-0}" = "1" ]; then
    echo "  fuzzing skipped (CI_SKIP_FUZZ=1)"
elif ! "$CARGO" fuzz --version >/dev/null 2>&1; then
    printf "  %-26sFAIL\n" "cargo-fuzz availability..."
    echo "      'cargo fuzz' not found. Install it (cargo install cargo-fuzz) or set"
    echo "      CI_SKIP_FUZZ=1 to accept parsers nobody fuzzed."
    FAIL=$((FAIL + 1))
else
    fuzz_row() { # fuzz_row <label> <spec>
        printf "  %-26s" "${1}..."
        local fuzz_out
        if fuzz_out="$(bash "${REPO_ROOT}/tools/fuzz.sh" check "$2" 2>&1)"; then
            ok
        else
            bad; printf '%s\n' "$fuzz_out"
        fi
    }
    for fuzz_spec in $(bash "${REPO_ROOT}/tools/fuzz.sh" list); do
        host_job fuzz_row "fuzz: ${fuzz_spec#*:}" "$fuzz_spec"
    done
fi

# Kani: the bounded proofs in crates/core/ipc/src/cap.rs and crates/core/ipc/src/objref.rs
# through tests/host/cap-tests, which pulls cap.rs in by
# `#[path]` (objref.rs is its submodule). Run from a directory OUTSIDE the
# tree: inside it, the root .cargo/config.toml's `build-std` makes Kani's own
# pinned toolchain build std from source, and that toolchain has no rust-src.
# The row passes only if Kani reports every harness the two files declare as
# verified. Not installed: a SKIP line, counted neither way.
if ci_row_begin "formal: Kani harnesses"; then
printf "  %-26s" "formal: Kani harnesses..."
if ! "$CARGO" kani --version >/dev/null 2>&1; then
    echo "SKIP (cargo kani not installed: nothing was verified)"
else
    kani_want="$(cat "${REPO_ROOT}/crates/core/ipc/src/cap.rs" "${REPO_ROOT}/crates/core/ipc/src/objref.rs" \
        | grep -c '#\[kani::proof\]')"
    kani_cwd="$(mktemp -d)"
    kani_out="$(cd "$kani_cwd" && "$CARGO" kani \
        --manifest-path "${REPO_ROOT}/tests/host/cap-tests/Cargo.toml" \
        --target-dir "$AZOS_OUT/target/kani" 2>&1)"
    rmdir "$kani_cwd" 2>/dev/null
    if [ -n "$kani_want" ] && [ "$kani_want" -gt 0 ] \
       && printf '%s\n' "$kani_out" | qgrep -qF "Complete - ${kani_want} successfully verified harnesses, 0 failures, ${kani_want} total."; then
        ok
    else
        bad; echo "      expected ${kani_want:-?} verified harnesses; Kani said:"
        printf '%s\n' "$kani_out" | grep -E "^Checking harness|VERIFICATION|^Complete|^error|FAILURE" \
            | sed -n 1,20p | sed 's/^/        /'
    fi
fi
fi; ci_row_end

par_drain
if [ "$CI_TIER" != full ] && [ "${CI_SKIP_QEMU:-0}" != 1 ]; then
    fast_missing="$(fast_unseen)"
    if [ -n "$fast_missing" ]; then
        printf "  %-26s" "${CI_TIER} tier: kept rows exist..."; bad
        echo "      the tier's row list names rows no par call used (renamed or removed?):"
        printf '%s\n' "$fast_missing" | sed 's/^/        /'
    fi
fi
echo ""
ci_phase_report
echo ""
if [ "$SKIP" -gt 0 ]; then
    echo "[4/4] Results: ${PASS} passed, ${FAIL} failed, ${SKIP} skipped (CI_TIER=${CI_TIER}; each is marked above)"
else
    echo "[4/4] Results: ${PASS} passed, ${FAIL} failed"
fi

if [ "$FAIL" -gt 0 ]; then
    echo "=== CI FAILED ==="
    exit 1
fi

echo "=== All checks passed ==="
